INSERT INTO `filmy` (`id`, `tytul`, `tytul_oryginalny`, `gatunek`, `rok`, `ocena`, `rezyser`, `czas_trwania`, `jezyk`, `ilosc_dostepnych`, `budzet`, `produkcja`, `nagrody`, `cena`, `opis`, `okladka`, `tmdb_id`, `imdb_id`, `typ_plyty_id`, `czy_ulubiony`) VALUES
(4, 'Ojciec chrzestny', 'The Godfather', 'Dramat, Kryminał', 1972, 8.7, 'Francis Ford Coppola', 175, 'English', 1, 6000000, 'Paramount Pictures, Alfran Productions, Albert S. Ruddy Productions', '', 5.99, 'Akcja filmu toczy się pod koniec II wojny światowej w Ameryce. Don Vito Corleone jest głową jednej z pięciu mafijnych rodzin w Nowym Jorku. Wraz z pomocą synów Sonny''ego i Freda oraz Toma Hagena -który oferuje swoje usługi w zakresie prawnym - cieszą się uznaniem wśród wielu znanych i ważnych osobistości. Wszystko zaczyna się komplikować, gdy Don Vito odmawia współpracy w handlu narkotykami.', 'https://image.tmdb.org/t/p/w500/g1BqW6xfiztwUVSQY9hevjtYyMr.jpg', 238, 'tt0068646', 2, 0),
(5, 'Skazani na Shawshank', 'The Shawshank Redemption', 'Dramat, Kryminał', 1994, 8.7, 'Frank Darabont', 144, 'English', 2, 25000000, 'Castle Rock Entertainment', '', 12.99, 'Adaptacja powieści Stephena Kinga. Nominowany  Andy Dufresne w 1995 roku do Oscara w 7 kategoriach!  Andy Dufresne jest młodym, obiecującym bankierem. Jego życie zmienia się drastycznie, kiedy zostaje niesłusznie oskarżony o zamordowanie swojej żony i jej kochanka. Skazany na dożywocie, trafia do więzienia Shawshank, gdzie rządy sprawują sadystyczni strażnicy oraz dyrektor hipokryta i oszust. Andy żeby przeżyć lata, jakie przyjdzie mu spędzić w celi, Andy będzie musiał wykazać się sprytem i wolą przetrwania. Przygotowuje również misterny plan zemsty - tak zaskakujący, że zmyli nawet najbliższych współwięźniów.', 'https://image.tmdb.org/t/p/w500/u7ZPMXKASlgW0TOonZlP8PAt7Oi.jpg', 278, 'tt0111161', 2, 0),
(8, 'Mroczny Rycerz', 'The Dark Knight', 'Akcja, Thriller, Kryminał', 2008, 8.5, 'Christopher Nolan', 152, 'English', 3, 185000000, 'Warner Bros. Pictures, Legendary Pictures, Syncopy', '', 19.99, 'Kontynuacja filmu "Batman: Początek", "Mroczny Rycerz", to kolejne wspólne dzieło reżysera Christophera Nolana i gwiazdora Christiana Bale''a, który ponownie wciela się w postać Batmana / Bruce''a Wayne''a toczącego zażartą wojnę ze światem przestępczym. Batmanowi udaje się na dobre rozbić kryminalne podziemie Gotham z pomocą porucznika Jima Gordona (Gary Oldman) i Prokuratora Okręgowego Harveya Denta (Aaron Eckhart). Ich współpraca okazuje się niezwykle skuteczna, ale szybko trzej mężczyźni stają się celem nowego geniusza zbrodni, Jokera (Heath Ledger), którego celem jest wprowadzenie w Gotham anarchii i zmuszenie Batmana, by ten przeszedł na stronę zła, przestał być bohaterem, a stał się złoczyńcą.', 'https://image.tmdb.org/t/p/w500/gKMDmGde8aAD8M6dvm6j7wciSbJ.jpg', 155, 'tt0468569', 2, 0),
(11, 'Pulp Fiction', 'Pulp Fiction', 'Thriller, Kryminał, Komedia', 1994, 8.5, 'Quentin Tarantino', 154, 'English', 4, 8000000, 'Miramax, A Band Apart, Jersey Films', '', 11.99, 'Płatni mordercy, Jules i Vincent, dostają zlecenie, by odzyskać z rąk przypadkowych rabusiów tajemniczą walizkę bossa mafii. Nie dość tego, Vincent dostaje kolejną robotę - na czas nieobecności gangstera w mieście ma zaopiekować się jego poszukującą wrażeń żoną Mią. Vincent i Jules niespodziewanie wpadają po uszy, gdy przypadkowo zabijają zakładnika. Kłopoty ma też podupadły bokser, który otrzymał dużą sumę za przegranie swojej walki. Walkę jednak wygrywa, a Los Angeles staje się od tej chwili dla niego za małe. Specjaliści od mokrej roboty będą mieli co robić...', 'https://image.tmdb.org/t/p/w500/5Whi9po8MTPyUTxAioXfyXGHNQE.jpg', 680, 'tt0110912', 2, 0),
(12, 'Forrest Gump', 'Forrest Gump', 'Komedia, Dramat, Romans', 1994, 8.5, 'Robert Zemeckis', 142, 'English', 5, 55000000, 'Paramount Pictures, The Steve Tisch Company, Wendy Finerman Productions', '', 18.99, 'W ciągu trzech burzliwych dekad, Forrest zmienia się z lekceważonego inwalidy w gwiazdę amerykańskiego futbolu; z bohatera wojny w Wietnamie staje się królem krewetek; od honorów Białego Domu przechodzi w ramiona ukochanej. Jest odzwierciedleniem naszej epoki, ostatnim niewinnym w czasach, kiedy Ameryka utraciła swą niewinność. Serce podpowiada mu w sprawach, których nie ogarnia jego umysł. Jest człowiekiem zasad, a jego sukcesy inspirują wszystkich. "Forrest Gump". Oto historia pewnego życia.', 'https://image.tmdb.org/t/p/w500/iixrNXX79OR7knBx1i9S51PfVlz.jpg', 13, 'tt0109830', 2, 0),
(13, 'Incepcja', 'Inception', 'Akcja, Sci-Fi, Kryminał', 2010, 8.4, 'Christopher Nolan', 148, 'English', 6, 160000000, 'Warner Bros. Pictures, Legendary Pictures, Syncopy', '', 10.99, 'Dom Cobb jest niezwykle sprawnym złodziejem, mistrzem w wydobywaniu wartościowych sekretów ukrytych głęboko w świadomości podczas fazy snu, kiedy umysł jest najbardziej wrażliwy. Wyjątkowe umiejętności Cobba uczyniły z niego ważnego gracza w świecie szpiegostwa przemysłowego, ale i najbardziej poszukiwanego zbiega, a za swoją pozycję zapłacił utratą wszystkiego, co kocha. Teraz Cobb otrzymuje szansę na odkupienie. Za sprawą jednego, ostatniego zadania może odzyskać stracone życie. Musi tylko wraz ze swym zespołem dokonać rzeczy niemożliwej: zamiast skraść myśl, zaszczepić ją w śpiącym umyśle. Jeśli im się to uda, dokonają zbrodni doskonałej. Jednak nawet najbardziej precyzyjne planowanie nie jest w stanie przygotować ich na spotkanie z niezwykłym przeciwnikiem, który potrafi przewidzieć każdy ich ruch. Wróg, którego tylko Cobb mógł się spodziewać.', 'https://image.tmdb.org/t/p/w500/efvcvRgOAZgFC2hrPUa6YqrE1KG.jpg', 27205, 'tt1375666', 2, 0),
(14, 'Podziemny krąg', 'Fight Club', 'Dramat, Thriller', 1999, 8.4, 'David Fincher', 139, 'English', 7, 63000000, 'Fox 2000 Pictures, Regency Enterprises, Linson Entertainment', '', 17.99, 'Cierpiący na bezsenność mężczyzna poznaje gardzącego konsumpcyjnym stylem życia Tylera Durdena, który jest jego zupełnym przeciwieństwem.', 'https://image.tmdb.org/t/p/w500/efBb4gjjKneUoBVgfFOUu2OwihS.jpg', 550, 'tt0137523', 2, 0),
(15, 'Matrix', 'The Matrix', 'Akcja, Sci-Fi', 1999, 8.3, 'Lana Wachowski', 136, 'English', 8, 63000000, 'Village Roadshow Pictures, Groucho II Film Partnership, Silver Pictures', '', 9.99, 'Thomas Anderson wiedzie podwójne życie - na co dzień pracuje w koncernie Meta Cortechs jako programista, prywatnie jest genialnym hackerem, działającym pod nickiem Neo. Pewnego dnia nawiązuje z nim kontakt tajemniczy Morfeusz - człowiek, który obiecuje mu odkryć prawdę o rzeczywistości, w jakiej żyją. Prawdę o Matriksie. Prawdę o dwóch światach: prawdziwym i wygenerowanym, który ma tylko "udawać" rzeczywistość. Neo początkowo wbrew sobie przystaje do grupy kierowanej przez Morfeusza, stopniowo jednak sam zaczyna dostrzegać, że ze światem, w którym żył dotychczas, jest coś nie tak. Że jego życiem cały czas ktoś kierował. Kolejne stopnie wtajemniczenia stawiają przed Neo nowe pytania. Który ze światów jest prawdziwy? Czym jest Matrix i komu służy? I jaką rolę w planie Morfeusza ma do spełnienia sam Neo?', 'https://image.tmdb.org/t/p/w500/xiCMLkZOVlxFbvWJMHuf4FJvnuX.jpg', 603, 'tt0133093', 2, 0),
(16, 'Chłopcy z ferajny', 'GoodFellas', 'Dramat, Kryminał', 1990, 8.5, 'Martin Scorsese', 145, 'English', 9, 25000000, 'Winkler Films, Warner Bros. Pictures', '', 16.99, 'W filmie "Chłopcy z ferajny" w formie epizodów opowiedziana zostaje autentyczna historia kariery nowojorskiego mafiozo, Henry''ego Hilla (Ray Liotta), który w ciągu 30 lat, od popełniającego małe przestępstwa gangstera, dochodzi do kierowniczego stanowiska w mafijnej hierarchii. Na podstawie relacji jednego z wtajemniczonych w sprawy mafii, film pokazuje kompleksowy obraz życia pojedynczego mafiozo, które nacechowane jest dążeniem do władzy, śmiertelnym strachem i męskimi rytuałami.', 'https://image.tmdb.org/t/p/w500/m9taboMOrt6h7sTLkGfOBSqp3qr.jpg', 769, 'tt0099685', 2, 0),
(17, 'Siedem', 'Se7en', 'Kryminał, Tajemnica, Thriller', 1995, 8.4, 'David Fincher', 127, 'English', 10, 33000000, 'New Line Cinema, Juno Pix, Arnold Kopelson Productions', '', 8.99, 'Odchodzący na emeryturę stary policyjny wyga William Somerset ma przekazać swoje obowiązki młodemu detektywowi Davidovi Millsowi. Różni ich wszystko: spokój, rozsądek, zmęczenie życiem i zawodem Somerseta kontrastuje z energią, porywczością i młodzieńczym optymizmem Millsa. Współpraca nie układa się więc najlepiej, ale niestety jest konieczna. Miastem wstrząsa seria okrutnych zabójstw. Pierwsza ofiara to otyły mężczyzna, który zmarł z przejedzenia. Następnego dnia ginie znany z chciwości prawnik. Wygląda na to, że morderca wybiera sobie na ofiary ludzi, którzy popełnili jeden z siedmiu grzechów głównych i w wyrafinowany, perfekcyjnie przygotowany sposób przeprowadza ich egzekucję.', 'https://image.tmdb.org/t/p/w500/jKstsinBR4nXRzmOItLjmpt9CQ4.jpg', 807, 'tt0114369', 2, 0),
(18, 'Interstellar', 'Interstellar', 'Przygodowy, Dramat, Sci-Fi', 2014, 8.5, 'Christopher Nolan', 169, 'English', 1, 165000000, 'Legendary Pictures, Syncopy, Lynda Obst Productions', '', 15.99, 'Ziemia w niedalekiej przyszłości. Planeta jest sukcesywnie niszczona przez klęski suszy, a ludziom grozi wyginięcie. Nieoczekiwanie naukowcy odkrywają możliwość podróżowania poza granice Układu Słonecznego. Grupa astronautów wyrusza w najważniejszą w dziejach ludzkości podróż – muszą znaleźć miejsce, gdzie nasz gatunek będzie mógł przetrwać. Na czele załogi staje Cooper, były pilot NASA, który obecnie zajmuje się uprawą roli.', 'https://image.tmdb.org/t/p/w500/q4emCJmjNomEE2pVGgqr3nDEIzI.jpg', 157336, 'tt0816692', 2, 0),
(19, 'Władca Pierścieni: Drużyna Pierścienia', 'The Lord of the Rings: The Fellowship of the Ring', 'Przygodowy, Fantasy, Akcja', 2001, 8.5, 'Peter Jackson', 179, 'English', 2, 93000000, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '', 7.99, 'Ekranizacja pierwszej części trylogii Tolkiena, "Drużyna Pierścienia" zapoznaje widzów z czarodziejskim światem Śródziemia i jego mieszkańcami - ludźmi, hobbitami, elfami, krasnoludami, czarodziejami, trollami i orkami. W tej części trylogii młody i nieśmiały hobbit Frodo Baggins (Elijah Wood) odziedzicza pierścień - Jedyny Pierścień, narzędzie władzy absolutnej, które pozwoliłoby Sauronowi, mrocznemu Władcy Mordoru, rządzić Śródziemiem i zniewolić zamieszkujące je ludy. Frodo, wraz z lojalną kompanią hobbitów, ludzi, czarodzieja, krasnoluda i elfa, musi zabrać Pierścień do Szczelin Zagłady, gdzie został kiedyś wykuty, i zniszczyć go raz na zawsze. Taka podróż oznacza zapuszczenie się głęboko do krainy Czarnego Władcy, gdzie gromadzi on armię orków. Drużyna musi walczyć nie tylko ze złem czającym się wokół, ale i z wewnętrznymi waśniami, oraz niszczącym wpływem samego Pierścienia. Przyszłość świata i przeznaczenie drużyny są ze sobą splecione.', 'https://image.tmdb.org/t/p/w500/bjWRzhXUXTNPnwptBkXQzCflVBE.jpg', 120, 'tt0120737', 2, 0),
(20, 'Władca Pierścieni: Dwie wieże', 'The Lord of the Rings: The Two Towers', 'Przygodowy, Fantasy, Akcja', 2002, 8.4, 'Peter Jackson', 180, 'English', 3, 79000000, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '', 14.99, 'Mrok gęstnieje nad światem. Po rozpadzie drużyny cel misji staje się coraz bardziej odległy. Frodo i Sam wędrują samotnie do Mordoru. Na ich drodze staje jednak Gollum, dawny właściciel pierścienia. Gandalf zwycięża Barloga, ale to dopiero początek jego zmagań z siłami zła. Pozostała część drużyny idąc tropem orków trafia do Fangornu, gdzie spotykają Gandalfa. Nadszedł czas, aby rozprawić się Sarumanem, który opętał władcę Rohanu, królestwa ludzi. Frodo i Sam prowadzeni przez Golluma, któremu Frodo darował życie, docierają do Czarnej Bramy. Tymczasem Merry i Pippin uciekają orkom i trafiają na Drzewca, starego Enta. Kiedy wszystko zaczyna się układać, Saruman, który stworzył potężną armię, postanawia zaatakować Rohańczyków. Rozpoczyna się bitwa, która może zadecydować o losie wyprawy - bitwa o Helmowy Jar.', 'https://image.tmdb.org/t/p/w500/4oDm6P1FUAegMFfQBVhWIkNcaqk.jpg', 121, 'tt0167261', 2, 0),
(21, 'Władca Pierścieni: Powrót króla', 'The Lord of the Rings: The Return of the King', 'Przygodowy, Fantasy, Akcja', 2003, 8.5, 'Peter Jackson', 202, 'English', 4, 94000000, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '', 6.99, 'Ostateczna bitwa o Śródziemie rozpoczęła się. Frodo i Sam, prowadzeni przez Golluma, kontynuują swą niebezpieczną wyprawę w kierunku Góry Przeznaczenia, w celu zniszczenia Pierścienia Władzy. Aragorn walczy, aby wypełnić przepowiednię i poprowadzić swoich zwolenników przeciw rosnącej sile Władcy Ciemności Saurona, aby Powiernik Pierścienia mógł zakończyć swoją misję.', 'https://image.tmdb.org/t/p/w500/75KNIheWdy7eLe4RWsbJmVjvJPU.jpg', 122, 'tt0167260', 2, 0),
(22, 'Gwiezdne wojny', 'Star Wars', 'Przygodowy, Akcja, Sci-Fi', 1977, 8.2, 'George Lucas', 121, 'English', 5, 11000000, 'Lucasfilm Ltd.', '', 13.99, 'Gwiezdne wojny: Część IV - Nowa nadzieja  Rycerze Jedi zostali wytępieni, a Imperium żelazną ręka sprawuje rządy nad całą galaktyką. Mała grupa Rebeliantów podejmuje walkę kradnąc tajne plany najpotężniejszej broni Imperium - tzw. Gwiazdy Śmierci. Najbardziej zaufany sługa Imperatora - Darth Vader musi odzyskać plany i odnaleźć ukrytą bazę buntowników. Księżniczka Leia - wzięta do niewoli przywódczyni Rebeliantów, wysyła sygnał z wezwaniem pomocy, który zostaje przechwycony przez zwykłego chłopaka z farmy - Luke''a Skywalkera. Wychodząc naprzeciw swemu przeznaczeniu, Luke podejmuje wyzwanie i rusza na ratunek Księżniczce chcąc pomóc Rebeliantom w obaleniu Imperium. W misji pomagają mu niezwykli sojusznicy - mądry Obi-Wan Kenobi, nieco arogancki gwiezdny awanturnik Han Solo i jego lojalny towarzysz Chewbacca a także dwa droidy R2-D2 i C-3PO.', 'https://image.tmdb.org/t/p/w500/A9GSgK58GgzllTIi7eZ2BjqvOwF.jpg', 11, 'tt0076759', 2, 0),
(23, 'Gwiezdne wojny: Część V - Imperium kontratakuje', 'The Empire Strikes Back', 'Przygodowy, Akcja, Sci-Fi', 1980, 8.4, 'Irvin Kershner', 124, 'English', 6, 18000000, 'Lucasfilm Ltd.', '', 5.99, 'Kolejna część Gwiezdnej Sagi opowiada o wydarzeniach toczących się kilka lat po zniszczeniu pierwszej Gwiazdy Śmierci. Luke Skywalker i pozostali Rebelianci uciekają po całej Galaktyce przed zakusami okrutnego Imperium. Bezpieczną ostoję znajdują na lodowej planecie Hoth. Jednak Imperium lokalizuje tę bazę. Rebelianci muszą uciekać. Luke udaje się do układu Dagobah, żeby spotkać się z Mistrzem Jedi, Yodą i pobrać od niego nauki. Natomiast Han, Leia, Chewie i roboty uciekają na planetę Bespin, do dawnego przyjaciela Hana ― Lando Calrissiana. Nie wiedzą, że wpadli w podstępnie uknutą przez Imperium pułapkę...', 'https://image.tmdb.org/t/p/w500/rWIWEQiUVSA9JSQ8pIHkUy3Fbiq.jpg', 1891, 'tt0080684', 2, 0),
(24, 'Gwiezdne wojny: Część VI - Powrót Jedi', 'Return of the Jedi', 'Przygodowy, Akcja, Sci-Fi', 1983, 7.9, 'Richard Marquand', 134, 'English', 7, 32350000, 'Lucasfilm Ltd.', '', 12.99, 'Kolejna część wielkiej Gwiezdnej Sagi. Imperium ponownie rośnie w siły. Budowa Drugiej Gwiadzy Śmierci zbliża się ku końcowi. Rebelianci również nie próżnują. Luke Skywalker (Mark Hamill), Leia (Carrie Fisher), Lando Calrissian (Billy Dee Williams) i Chewie (Peter Mayhew) udają się na pustynną Tatooine, aby uwolnić Hana Solo (Harrison Ford) z rąk Jabby Hutta. Rebelianci chcąc jak najszybciej zakończyć rządy Imperatora (Ian McDiarmid), zamierzają nie dopuścić do ukończenia budowy Gwiazdy Śmierci. Dzielą się na dwa oddziały - jeden będzie przeprowadzał akcję dywersyjną na księżycu Endor, a drugi zaatakuje bezpośrednio bazę Imperium. Luke udaje się z Rebeliantami lecącymi na Endor. Przeczuwa, że jego przeznaczeniem jest ponowne zmierzenie się Vaderem. W międzyczasie dowiaduje się, że ma siostrę...', 'https://image.tmdb.org/t/p/w500/dBFG7daUwnkcY4nVevNhFnXBGZu.jpg', 1892, 'tt0086190', 2, 0),
(25, 'Park Jurajski', 'Jurassic Park', 'Przygodowy, Sci-Fi', 1993, 8.0, 'Steven Spielberg', 127, 'English', 8, 63000000, 'Universal Pictures, Amblin Entertainment', '', 19.99, 'John Hammond, ekscentryczny milioner, stworzył na wyspie Nublar, dwieście kilometrów na zachód od Kostaryki, niezwykły rezerwat. Jego atrakcją są przywołane do życia po stu milionach lat dinozaury. Ale, aby Park Jurajski mógł przyjąć turystów, grupa fachowców musi potwierdzić, że jest miejscem całkowicie bezpiecznym. Niestety brak pokory wobec natury musi zostać ukarany. Wyprawa naukowców do rezerwatu przeradza się w krwawy koszmar...', 'https://image.tmdb.org/t/p/w500/6PahEke329HOQx1QOqlo12e4YXa.jpg', 329, 'tt0107290', 2, 0),
(26, 'Titanic', 'Titanic', 'Dramat, Romans', 1997, 7.9, 'James Cameron', 194, 'English', 9, 200000000, 'Paramount Pictures, 20th Century Fox, Lightstorm Entertainment', '', 11.99, 'Jake i Rose, para młodych kochanków, poznają i zakochują się podczas dziewiczego rejsu "niezatapialnego" transatlantyku Titanic. Nie dane im było jednak zaznać pełni szczęścia i miłosnych uniesień. Gdy luksusowy liniowiec wpada na górę lodową, ich pełen pasji, płomienny romans przeradza się w przerażającą, mrożącą krew w żyłach walkę o przetrwanie o życie. Reżyserem "Titanica" jest prawdziwy wizjoner w świecie kina, James Cameron, wielokrotnie nagradzany reżyser. Stworzył on nieporównywalne z niczym dzieło, po mistrzowsku żonglując uczuciami swoich bohaterów, miłość przeplatając z nienawiścią, hart ducha i odwagę konfrontując z podłością i tchórzostwem w obliczu wielkiej katastrofy i sprawiając, że film "Titanic" to istny triumf kinematografii.', 'https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', 597, 'tt0120338', 2, 0),
(27, 'Avatar', 'Avatar', 'Sci-Fi, Akcja, Przygodowy', 2009, 7.6, 'James Cameron', 162, 'English', 10, 237000000, 'Dune Entertainment, Lightstorm Entertainment, 20th Century Fox', '', 18.99, 'Rok 2154. Jake Sully, sparaliżowany były żołnierz piechoty morskiej, otrzymuje szansę odzyskania zdrowego ciała. Musi jednak wziąć udział w specjalnym programie militarnym. Ma trafić na Pandorę, planetę zamieszkiwaną przez Na''vi - człekopodobną, pokrytą niebieską skórą rasę. Pandora, księżyc planety Polyphemus w układzie Alfa-Centauri, jest bogata w złoża niezwykle cennego minerału, który mógłby rozwiązać światowy kryzys energetyczny. Ponieważ ludzie nie są zdolni do oddychania na Pandorze, stworzyli specjalne hybrydy zwane avatarami, którymi mogą sterować. Umożliwia im to swobodne poruszanie się po planecie. Jake dołącza do pułkownika Milesa Quadritcha, dowodzącego tajną jednostką Secops, i rozpoczyna infiltrowanie Na''vi. Kiedy jednak poznaje Neytiri, wojowniczkę z klanu Omaticaya, która ratuje mu życie i dzięki której coraz lepiej poznaje tubylców, zaczyna wątpić w słuszność swojej misji. Staje przed trudnym wyborem: stanąć w obronie dobra czy wypełnić swoje zadanie.', 'https://image.tmdb.org/t/p/w500/6DfNtptjkIrevq4mDAB0XDXT0NO.jpg', 19995, 'tt0499549', 2, 0),
(28, 'Avengers: Wojna bez granic', 'Avengers: Infinity War', 'Przygodowy, Akcja, Sci-Fi', 2018, 8.2, 'Joe Russo', 149, 'English', 1, 300000000, 'Marvel Studios', '', 10.99, 'Po ostatnich wydarzeniach jakie zaszły między Avengersami są oni podzieleni i nie tworzą dłużej jednej zgranej grupy jak za dawnych czasów. Nadciąga jednak nowe wyzwanie. Thanos (Josh Brolin) przybywa na ziemię, a jego celem jest zebranie wszystkich 6 kamieni nieskończoności, które razem dają temu kto je posiada niewyobrażalną moc. Kapitan Ameryka (Chris Evans), Iron Man (Robert Downey Jr.) i reszta superbohaterów będą musieli zjednoczyć się po raz kolejny, aby bronić swojego świata przed zagrożeniem jakiego jeszcze nie było.  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/zLLs37yOubp9Snt5n1UE0DKvWGo.jpg', 299536, 'tt4154756', 2, 0),
(29, 'Avengers: Koniec gry', 'Avengers: Endgame', 'Przygodowy, Sci-Fi, Akcja', 2019, 8.2, 'Anthony Russo', 180, 'English', 2, 356000000, 'Marvel Studios', '', 17.99, 'Po dramatycznych wydarzeniach z filmu "Avengers: Wojna bez granic" Iron Man samotnie dryfuje po kosmosie, połowa superbohaterów przestała istnieć, a Kapitan Ameryka próbuje pogodzić się z porażką. Świat już nigdy nie będzie taki sam, a ocaleni muszą nauczyć się żyć w nowych warunkach. Nie wszyscy jednak dają za wygraną. Gdy w bazie Avengers pojawia się Ant-Man, w głowach herosów rodzi się szalony plan zmiany obecnego stanu rzeczy. Czy jest możliwe odwrócenie "Efektu Thanosa" i przywrócenie do naszego świata tych, co odeszli? Iron Man, Kapitan Ameryka, Thor, Hulk, Czarna Wdowa i pozostali zbierają się ponownie, żeby wyruszyć w pełną przygód podróż po najważniejszych momentach w historii Avengers.', 'https://image.tmdb.org/t/p/w500/7It0CFUs7MxZKzFFHQzyXeNs0C5.jpg', 299534, 'tt4154796', 2, 0),
(30, 'Iron Man', 'Iron Man', 'Akcja, Sci-Fi, Przygodowy', 2008, 7.7, 'Jon Favreau', 126, 'English', 3, 140000000, 'Marvel Studios, Marvel Entertainment, Fairview Entertainment', '', 9.99, '"Iron Man" to historia miliardera, przemysłowca i genialnego wynalazcy Tony’ego Starka (Robert Downey Jr.), szefa Stark Industries, głównego dostawcy broni dla rządu USA. Beztroski styl życia Tony’ego zmienia się na zawsze, kiedy po testach przeprowadzanych z nową bronią, jego konwój zostaje zaatakowany, a on sam porwany przez rebeliantów. Ranny od pocisku, który utkwił w pobliżu serca, Tony zostaje zmuszony do skonstruowania potężnej broni dla Razy (Faran Tahir), tajemniczego przywódcy rebeliantów. Nie zważając jednak na żądania porywaczy, Tony wykorzystuje swój intelekt i geniusz, aby skonstruować zbroję, która utrzyma go przy życiu i pomoże w ucieczce.', 'https://image.tmdb.org/t/p/w500/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', 1726, 'tt0371746', 2, 0),
(31, 'Czarna Pantera', 'Black Panther', 'Akcja, Przygodowy, Sci-Fi', 2018, 7.4, 'Ryan Coogler', 134, 'English', 4, 200000000, 'Marvel Studios', '', 16.99, 'T’Challa (Chadwick Boseman) po śmierci swojego ojca, króla Wakandy, wraca do rodzinnego kraju, by objąć tron. Wkrótce Wakanda zostaje napadnięta przez dawnego wroga. W obliczu niebezpieczeństwa młody władca zbiera sojuszników i robi wszystko, aby pokonać groźnego przeciwnika i ochronić swój dotąd pozostający w izolacji lud, jego kulturę i całą wysoce rozwiniętą technologicznie cywilizację. By udowodnić, że jest godzien miana króla, T’Challa jako Czarna Pantera staje w obronie nie tylko swojej ojczyzny, ale i całego świata.', 'https://image.tmdb.org/t/p/w500/hHR6hcnt4UQIH2306R6gYKPG6Y4.jpg', 284054, 'tt1825683', 2, 0),
(32, 'Spider-Man Uniwersum', 'Spider-Man: Into the Spider-Verse', 'Animacja, Akcja, Przygodowy, Sci-Fi', 2018, 8.4, 'Bob Persichetti', 117, 'English', 5, 90000000, 'Columbia Pictures, Lord Miller, Pascal Pictures', '', 8.99, 'Miles Morales jest nastolatkiem, który odkrywa w sobie moce podobne do tych, jakimi posługuje się Spider-Man, podobnie zresztą jak on, jest superbohaterem; nazywany jest często Ultimate Spider-Man, działa w uniwersum zwanym Ziemia-1610. Jest nadzwyczajnie silny, potrafi wdrapywać się po ścianach, ma pajęczy zmysł i umiejętność paraliżowania wroga.', 'https://image.tmdb.org/t/p/w500/grU91DJPDzJv0sqDyEhzOEgwWEH.jpg', 324857, 'tt4633694', 2, 0),
(33, 'Avengers', 'The Avengers', 'Sci-Fi, Akcja, Przygodowy', 2012, 8.1, 'Joss Whedon', 142, 'English', 6, 220000000, 'Marvel Studios', '', 15.99, 'W obliczu globalnego zagrożenia Nick Fury, szef międzynarodowej agencji S.H.I.E.L.D. czuwającej nad światowym bezpieczeństwem, musi skompletować niezwykłą drużynę, która będzie potrafiła stawić czoła bezwzględnemu wrogowi. Iron Man, Thor, Kapitan Ameryka, Hulk, Sokole Oko i Czarna Wdowa po raz pierwszy w historii łączą siły, żeby ochronić Ziemię przed inwazją obcych!', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', 24428, 'tt0848228', 2, 0),
(34, 'Strażnicy Galaktyki', 'Guardians of the Galaxy', 'Akcja, Sci-Fi, Przygodowy', 2014, 7.9, 'James Gunn', 122, 'English', 7, 170000000, 'Marvel Studios', '', 7.99, 'Zuchwały awanturnik Peter Quill (Chris Pratt) kradnie tajemniczy artefakt stanowiący obiekt pożądania złego i potężnego Ronana (Lee Pace), którego ambicje zagrażają całemu wszechświatowi. Chcąc uniknąć gniewu Ronana, Quill zmuszony jest zawrzeć niewygodny sojusz z czterema niemającymi nic do stracenia outsiderami: Rocketem (Bradley Cooper) – uzbrojonym szopem, Grootem (Vin Diesel) – drzewokształtnym humanoidem, śmiertelnie niebezpieczną i tajemniczą Gamorą (Zoe Saldana) i żądnym zemsty Draxem Niszczycielem (Dave Bautista). Kiedy główny bohater odkrywa prawdziwą moc artefaktu i zagrożenie, jakie stanowi on dla kosmosu, musi zmobilizować swoich niesubordynowanych towarzyszy do ostatniej bitwy, od której zależą losy galaktyki.', 'https://image.tmdb.org/t/p/w500/e937bcDDhgXfyXYf2RrMg2zrlll.jpg', 118340, 'tt2015381', 2, 0),
(35, 'Doktor Strange', 'Doctor Strange', 'Fantasy, Przygodowy, Akcja', 2016, 7.4, 'Scott Derrickson', 115, 'English', 8, 180000000, 'Marvel Studios', '', 14.99, '‌Stephen Strange (Benedict Cumberbatch) jest aroganckim i ambitnym neurochirurgiem. Jego życie wywraca się do góry nogami, gdy w wypadku samochodowym doznaje kontuzji rąk. Po nieudanych próbach wyleczenia szuka porady u Jonathana (Benjamin Bratt), który zdołał uleczyć się po złamaniu kręgosłupa. Zgodnie z jego wskazówkami Strange udaje się w okolice Katmandu, gdzie poznaje uczniów Wonga (Benedict Wong) i Mordo (Chiwetel Ejiofor) oraz mistrza Przedwiecznego (Tilda Swinton). Wkrótce Strange odkrywa w sobie potężną moc.', 'https://image.tmdb.org/t/p/w500/xo3HkJBvxqPUpPzTlRte7ThDBp9.jpg', 284052, 'tt1211837', 2, 0),
(36, 'Thor: Ragnarok', 'Thor: Ragnarok', 'Akcja, Przygodowy, Komedia, Sci-Fi', 2017, 7.6, 'Taika Waititi', 131, 'English', 9, 180000000, 'Marvel Studios', '', 6.99, 'Minęło trochę czasu od wydarzeń przedstawionych w filmie "Thor: Mroczny Świat". Thor (Chris Hemsworth) jest uwięziony przez wrogów jego rodzinnego Asgardu w odległej części wszechświata. Pewnego dnia gromowładny zostaje zmuszony do udziału w pojedynkach gladiatorów. Niespodziewanie okazuje się, że ma stanąć do walki z dawnym sojusznikiem, Hulkiem (Mark Ruffalo). Superbohaterowie zwierają szyki nie tylko po to, żeby odzyskać wolność. Muszą też pokonać potężną Helę (Cate Blanchett) - boginię śmierci, która zawładnęła Asgardem. Jeśli się im to nie uda, świat czeka Ragnarok - mityczny zmierzch bogów, którego nie przetrwa żaden gatunek.', 'https://image.tmdb.org/t/p/w500/2m2nF7W0Kw15R08hVXlajmLlgBZ.jpg', 284053, 'tt3501632', 2, 0),
(37, 'Kapitan Marvel', 'Captain Marvel', 'Akcja, Przygodowy, Sci-Fi', 2019, 6.8, 'Ryan Fleck', 124, 'English', 10, 152000000, 'Marvel Studios', '', 13.99, 'Bądź świadkiem narodzin superbohaterki! Kapitan Marvel z Marvel Studios zabierze cię na spektakularną przygodę w lata 90. XX wieku. Kiedy galaktyczna wojna dociera na Ziemię, Carol Danvers (Brie Larson) poznaje młodego agenta Nicka Fury''ego (Samuel L. Jackson) i trafia w sam środek zawirowań, które sprawiają, że staje się jedną z Avengersów!', 'https://image.tmdb.org/t/p/w500/n3iAFkZqMVQwC3qmJ0YyXGV867u.jpg', 299537, 'tt4154664', 2, 0),
(38, 'Kapitan Ameryka: Zimowy Żołnierz', 'Captain America: The Winter Soldier', 'Akcja, Przygodowy, Sci-Fi', 2014, 7.7, 'Joe Russo', 128, 'English', 1, 170000000, 'Marvel Studios', '', 5.99, 'Po wydarzeniach w Nowym Jorku Steve (Chris Evans), znany jako Kapitan Ameryka, razem z Natashą (Scarlett Johansson) kontynuuje współpracę z kierowaną przez Nicka Fury''ego (Samuel L. Jackson) organizacją T.A.R.C.Z.A. Po jednej z kolejnych misji Fury zaznajamia go z projektem nowego programu obronnego, który ma likwidować zagrożenia i nie dopuszczać do katastrof. Rogers uważa jednak, że wzbudzanie strachu jest sprzeczne z ideą wolności, o którą od tak dawna walczy. Tymczasem Fury także zaczyna mieć wątpliwości i prosi o swojego zwierzchnika, Alexandra (Robert Redford), o zawieszenie prac nad projektem. Wkrótce dochodzi do zamachu na Fury''ego. Sprawcą jest tajemniczy najemnik nazywany Zimowym Żołnierzem (Sebastian Stan). Na domiar złego zachodzi podejrzenie, że T.A.R.C.Z.A. jest infiltrowana od wewnątrz.', 'https://image.tmdb.org/t/p/w500/6eZ8hJDYOHiAYK2U0iNs0DSm384.jpg', 100402, 'tt1843866', 2, 0),
(39, 'Wonder Woman', 'Wonder Woman', 'Akcja, Przygodowy, Fantasy', 2017, 7.2, 'Patty Jenkins', 141, 'English', 2, 149000000, 'Atlas Entertainment, Cruel & Unusual Films, DC Films', '', 12.99, 'Księżniczka Amazonek, niezrównana wojowniczka Diana (Gal Gadot), wychowywała się na odciętej od świata rajskiej wyspie Themyscira. Pewnego dnia rozbija się tam amerykański myśliwiec. Ocalały z katastrofy pilot, Steve Trevor (Chris Pine), opowiada Dianie o straszliwym konflikcie, który toczy się na Ziemi. Poruszona jego słowami Diana porzuca dom, bo wierzy, że może zapobiec dalszemu rozlewowi krwi. W świecie ludzi księżniczka - jako Wonder Woman - odkrywa, jak wielką ma moc i jakie jest jej prawdziwe przeznaczenie...', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', 297762, 'tt0451279', 2, 0),
(40, 'Harry Potter i Kamień Filozoficzny', 'Harry Potter and the Philosopher''s Stone', 'Przygodowy, Fantasy', 2001, 7.9, 'Chris Columbus', 153, 'English', 3, 125000000, 'Warner Bros. Pictures, Heyday Films, 1492 Pictures', '', 19.99, 'Harry Potter dowiaduje się, w dniu swoich 11-tych urodzin, że jest osieroconym dzieckiem dwojga potężnych czarodziejów i sam posiada magiczne zdolności. W Szkole Magii i Czarodziejstwa w Hogwarcie przeżywa największą przygodę swojego życia. Uczy się latania na miotle i różnych pożytecznych zaklęć. Przeżywa także chwile grozy rozwiązując zagadkę tajemniczego kamienia filozoficznego i tocząc walkę z potężnym i złym czarodziejem-Lordem Voldermort.', 'https://image.tmdb.org/t/p/w500/wNRk1vec98vfAQa2YdZOt7h0DGe.jpg', 671, 'tt0241527', 2, 0),
(41, 'Harry Potter i Komnata Tajemnic', 'Harry Potter and the Chamber of Secrets', 'Przygodowy, Fantasy', 2002, 7.7, 'Chris Columbus', 161, 'English', 4, 100000000, 'Warner Bros. Pictures, Heyday Films, 1492 Pictures', '', 11.99, 'Harry powraca do Hogwartu, aby ponownie zmierzyć się z niebezpieczeństwem tym razem zagrażającym także jego najlepszej przyjaciółce. Podczas drugiego roku pobytu w Szkole Magii i Czarodziejststwa młody Potter spotyka starych wrogów, poznaje nowego nauczyciela, odkrywa w sobie nowe zdolności, unika śmierci z rąk domowego skrzata chcącego za wszelką cenę uratować mu życie i wraz z dwójką swoich przyjaciół: Ronem i Hermioną znów udaje mu się rozwiązać trudną zagadkę.', 'https://image.tmdb.org/t/p/w500/mFeZBqgKQqTuk2R67IfmfQP62nj.jpg', 672, 'tt0295297', 2, 0),
(42, 'Harry Potter i więzień Azkabanu', 'Harry Potter and the Prisoner of Azkaban', 'Przygodowy, Fantasy', 2004, 8.0, 'Alfonso Cuarón', 141, 'English', 5, 130000000, 'Warner Bros. Pictures, 1492 Pictures, Heyday Films', '', 18.99, 'Harry Potter i jego najlepsi przyjaciele Ron i Hermiona, po przerwie letniej powracają do Hogwartu, aby rozpocząć trzeci rok nauki. W tym samym czasie z pilnie strzeżonego więzienia dla czarodziejów ucieka niebezpieczny przestępca - Syriusz Black! Wszystko wskazuję na to, że Black poluje na Harrego. Cały świat czarodziejów rozpoczyna poszukiwania zbiega; z Azkabanu zostają wysłane przerażające istoty - Dementorzy, w celu zabicia przestępcy.', 'https://image.tmdb.org/t/p/w500/sR7uC42HHb7qj1ndLBgBXii0quX.jpg', 673, 'tt0304141', 2, 0),
(43, 'Harry Potter i Czara Ognia', 'Harry Potter and the Goblet of Fire', 'Przygodowy, Fantasy', 2005, 7.8, 'Mike Newell', 157, 'English', 6, 150000000, 'Warner Bros. Pictures, Heyday Films, Patalex IV Productions', '', 10.99, 'W Hogwarcie rozgrywa się Turniej Trójmagiczny, na który przybywają uczniowie szkół z Francji i Bułgarii. Zgodnie ze starą tradycją, do turnieju mają być wybrani trzej przedstawiciele, każdej ze szkół. Jednak dziwnym zbiegiem okoliczności do turnieju zostaje wybranych czterech uczestników, w tym i Harry Potter. Odtąd na głównego bohatera czekają trzy zadania, a w związku z nimi wiele niesamowitych i niebezpiecznych przygód.', 'https://image.tmdb.org/t/p/w500/kRGddmzmxXcFZsJcEqVlgXUb29S.jpg', 674, 'tt0330373', 2, 0),
(44, 'Harry Potter i Zakon Feniksa', 'Harry Potter and the Order of the Phoenix', 'Przygodowy, Fantasy', 2007, 7.7, 'David Yates', 138, 'English', 7, 150000000, 'Warner Bros. Pictures, Heyday Films', '', 17.99, 'Harry Potter tym razem nie może mieć spokojnych wakacji. Lord Voldemort powrócił, a prasa czarodziejska milczy na ten temat. Na mugolskim osiedlu Little Whinging pojawiają się Dementorzy, a zbzikowana sąsiadka Dursley''ów pani Figg jest charłakiem! W dodatku Harry staje przed całym Wizengamotem za użycie czarów przez nieletniego, a Straż Przednia zabiera go do kwatery głównej Zakonu Feniksa - organizacji powołanej przez Dumbledora do walki z Sam-Wiesz-Kim. Tymczasem w Hogwarcie rządy przejmuje sprzymierzeniec Korneliusza Knota i nauczycielka obrony przed czarną magią profesor Umbridge. Wygląda na to, że nikt nie wierzy Harry''emu i Dumbledorowi, że Lord Voldemort odrodził się na nowo. Kiedy zaatakuje wszystko wyjdzie na jaw, ale czy wtedy nie będzie już za późno?', 'https://image.tmdb.org/t/p/w500/7SusRCFTH01GtGVlKjFY0xZWCx5.jpg', 675, 'tt0373889', 2, 0),
(45, 'Harry Potter i Książę Półkrwi', 'Harry Potter and the Half-Blood Prince', 'Przygodowy, Fantasy', 2009, 7.7, 'David Yates', 153, 'English', 8, 250000000, 'Warner Bros. Pictures, Heyday Films', '', 9.99, 'Lord Voldemort zaciska swoją złowieszczą pętlę wokół świata Mugoli i czarodziejów, a Hogwart przestaje być – jak dawniej - bezpieczną przystanią. Harry podejrzewa, że niebezpieczeństwo może czaić się w samym zamku, ale Dumbledorowi zależy raczej na przygotowaniu go do ostatecznego starcia, które jego zdaniem nastąpi niebawem. Razem usiłują znaleźć broń zdolną skruszyć zapory Voldemorta. Harry’emu coraz bardziej podoba się Ginny... niestety, Dean Thomas jest nią również zainteresowany. Lavender Brown dochodzi do wniosku, że Ron jest jej przeznaczeniem, nie bierze tylko pod uwagę czekoladek Romildy Vane! No i oczywiście Hermiona, przeżywająca męki zazdrości, lecz zdecydowana nie ujawniać uczuć. Gdy romanse kwitną, tylko jeden uczeń pozostaje wyniosły i obojętny. Postanowił wywrzeć swoje niezatarte – choć mroczne – piętno na życiu Akademii. Miłość wisi w powietrzu, lecz za nią czai się dramat i Hogwart być może już nigdy nie będzie taki jak przedtem.', 'https://image.tmdb.org/t/p/w500/lRzXVktAIzOh509zALQf1Zhhsh8.jpg', 767, 'tt0417741', 2, 0),
(46, 'Harry Potter i Insygnia Śmierci: Część I', 'Harry Potter and the Deathly Hallows: Part 1', 'Przygodowy, Fantasy', 2010, 7.7, 'David Yates', 146, 'English', 9, 250000000, 'Warner Bros. Pictures, Heyday Films', '', 16.99, 'Harry, Ron i Hermiona wyruszają z niebezpieczną misją, by odnaleźć i zniszczyć horkruksy, w których tkwi tajemnica siły Voldemorta. Zdani tylko na siebie, ścigani teraz bardziej niż kiedykolwiek, mogą polegać tylko na sobie, a Siły Ciemności, które są blisko, próbują ich rozdzielić.', 'https://image.tmdb.org/t/p/w500/bx9IkD8kllIuyycE7qWw8VK4DUw.jpg', 12444, 'tt0926084', 2, 0),
(47, 'Harry Potter i Insygnia Śmierci: Część II', 'Harry Potter and the Deathly Hallows: Part 2', 'Przygodowy, Fantasy', 2011, 8.1, 'David Yates', 130, 'English', 10, 125000000, 'Warner Bros. Pictures, Heyday Films', '', 8.99, 'W drugiej części widowiskowego zakończenia serii walka sił dobra z siłami zła świata czarodziejów przeistacza się w otwartą wojnę. Stawka nigdy nie była tak wysoka; nikt nie może czuć się bezpieczny. Być może w trakcie nieuchronnie zbliżającej się ostatecznej rozgrywki z Lordem Voldemortem to Harry Potter będzie zmuszony do ostatecznego poświęcenia. Tak kończy się cała opowieść.', 'https://image.tmdb.org/t/p/w500/4cQJQz9gNvhLQaF1cXKYDmjTEUj.jpg', 12445, 'tt1201607', 2, 0),
(48, 'Igrzyska śmierci', 'The Hunger Games', 'Sci-Fi, Przygodowy, Akcja, Thriller', 2012, 7.2, 'Gary Ross', 142, 'English', 1, 75000000, 'Lionsgate, Color Force', '', 15.99, 'Katniss pochodzi z Dwunastego Dystryktu, jednego z najbiedniejszych regionów w państwie Panem. Kiedy jej młodsza siostra zostaje wylosowana do udziału w Głodowych Igrzyskach, corocznym turnieju organizowanym przez bezwzględne władze, Katniss zgłasza się by zająć jej miejsce. Musi opuścić nie tylko rodzinę, której jest żywicielką, ale i Gale’a, który zdaje się być kimś więcej niż przyjacielem. Aby ich jeszcze zobaczyć, musi zwyciężyć w transmitowanych przez telewizję Igrzyskach. Przeżyć może tylko jeden uczestnik. Pochodzący z biednego dystryktu i nie szkoleni w walce Katniss i chłopak Peeta, w oczach widzów skazani są na porażkę. Igrzyska są jednak nieprzewidywalne. Między młodymi rodzi się uczucie, a odważna szesnastolatka rozpala w ludziach nadzieję na zmiany. Staje się symbolem buntu i walki z niesprawiedliwością. Jednak jeśli kiedykolwiek ma zobaczyć jeszcze rodzinny Dystrykt 12, musi dokonać rzeczy niemożliwych...', 'https://image.tmdb.org/t/p/w500/kstugEPWNFAYucCpia16nA9vwKv.jpg', 70160, 'tt1392170', 2, 0),
(49, 'Igrzyska śmierci: W pierścieniu ognia', 'The Hunger Games: Catching Fire', 'Przygodowy, Akcja, Sci-Fi', 2013, 7.4, 'Francis Lawrence', 146, 'English', 2, 130000000, 'Lionsgate, Color Force', '', 7.99, 'Po zwycięstwie w 74. Głodowych Igrzyskach, Katniss Everdeen oraz Peeta Mellark udają się na obowiązkowe Tournee Zwycięzców. Choć zuchwale złamali reguły rozgrywki, w glorii zwycięstwa odwiedzają kolejne dystrykty. Dowiadują się o fali zamieszek, do których przyczynił się ich niebywały wyczyn. W tym samym czasie prezydent Snow przystępuje do organizacji jubileuszowych, 75. Igrzysk, w których dawni zwycięzcy będą musieli stanąć przeciw sobie. Te wydarzenia mogą zmienić państwo Panem na zawsze.', 'https://image.tmdb.org/t/p/w500/7x0RkphKSzRVZfvnJ5nH0gUvmR1.jpg', 101299, 'tt1951264', 2, 0),
(50, 'Przeminęło z wiatrem', 'Gone with the Wind', 'Dramat, Wojenny, Romans', 1939, 7.9, 'Victor Fleming', 238, 'English', 3, 4000000, 'Selznick International Pictures, Metro-Goldwyn-Mayer', '', 14.99, '"Przeminęło z wiatrem" to ekranizacja bestsellerowej powieści Margaret Mitchell, o tym samym tytule. Film opowiada o losach Scarlett O''Hara, beztroskiej, pięknej i otoczonej kawalerami dziewczyny, której przyjemne i bogate życie przerywa niosąca z sobą śmierć i zniszczenie wojna. Równocześnie spada na nią wieść o ślubie Ashleya, w którym potajemnie się kochała, z nienawistną jej Melanią. Scarlett, chcąc zrobić mu na złość, przyjmuje oświadczyny pierwszego z brzegu mężczyzny, który bardzo szybko umiera. Jako wdowa Scarlett zostaje pozbawiona wszelkich zabaw i przyjemności. Wtedy w jej życiu zjawia się awanturnik - Rhett Butler.', 'https://image.tmdb.org/t/p/w500/2iIH6q8QRsTNANcNxA2PmDcTelF.jpg', 770, 'tt0031381', 2, 0),
(51, 'Casablanca', 'Casablanca', 'Dramat, Romans', 1943, 8.1, 'Michael Curtiz', 102, 'English', 4, 878000, 'Warner Bros. Pictures', '', 6.99, 'Trwa wojna. Rick prowadzi w Casablance nocny klub. Pewnego dnia zjawia się tam Ilsa, kobieta, w której niegdyś Rick był bardzo zakochany. Planowali wspólnie wyjechać do Paryża, lecz jego ukochana nie zjawiła się w umówionym miejscu. Mroczne tajemnice i klimat wojennej okupacji stanowi tło do opowieści o głębokim i uczuciu i trudnych wyborach życiowych.', 'https://image.tmdb.org/t/p/w500/j2cdc6lJo2cqpJEfP1cxsAwgZYC.jpg', 289, 'tt0034583', 2, 0),
(52, 'Obywatel Kane', 'Citizen Kane', 'Tajemnica, Dramat', 1941, 8.0, 'Orson Welles', 119, 'English', 5, 839727, 'Mercury Productions, RKO Radio Pictures', '', 13.99, 'Kiedy 76-letni Charles Foster Kane, magnat prasowy, na łożu śmierci wypowiada jedno, jedyne słowo, "Różyczka", wszyscy zgromadzeni w ogromnym zamku Kane''a Xanadu popadają w konsternację. Nawet przeprowadzona przez grupę dziennikarzy wnikliwa analiza kronik filmowych nie daje odpowiedzi na pytanie, co oznacza owa enigmatyczna "Różyczka". Ani w życiu publicznym Kane''a, ani jego życiu towarzyskim i zawodowym nie można znaleźć rozwiązania dręczącej wszystkich zagadki. Jeden z reporterów postanawia rozszyfrować znaczenie tego słowa.', 'https://image.tmdb.org/t/p/w500/vnBwC3FxtcaTJyOvLV4lDo8ElCr.jpg', 15, 'tt0033467', 2, 0),
(53, 'Zawrót głowy', 'Vertigo', 'Tajemnica, Romans, Thriller', 1958, 8.1, 'Alfred Hitchcock', 128, 'English', 6, 2479000, 'Paramount Pictures, Alfred J. Hitchcock Productions', '', 5.99, 'Akcja filmu rozgrywa się w San Francisco. James Stewart w roli cierpiącego na lęk wysokości detektywa, wynajętego by śledzić żonę przyjaciela, która ma skłonności samobójcze. Kiedy pewnego dnia udaje mu się uratować ją przed skokiem do zatoki, uświadamia sobie, że ta piękna, tajemnicza kobieta stała się obiektem jego obsesyjnego pożądania.', 'https://image.tmdb.org/t/p/w500/t8GZJc8WQxltWiZZ8xtC1ZDVeeP.jpg', 426, 'tt0052357', 2, 0),
(54, 'Psychoza', 'Psycho', 'Horror, Thriller, Tajemnica', 1960, 8.4, 'Alfred Hitchcock', 109, 'English', 7, 806947, 'Shamley Productions', '', 12.99, 'Marion Crane jest sekretarką spotykającą się po kryjomu z Samem, drobnym handlarzem. Nie mają pieniędzy, by mogli żyć razem. Więc przy nadarzającej się okazji Marion kradnie z pracy dużą kwotę pieniędzy i ucieka z miasta. Chce pojechać do Sama. Podczas jazdy nocą zaczyna mocno padać deszcz, więc uciekinierka skręca do małego moteliku - Motelu Batesa. Motel wygląda przytulnie, do momentu, gdy Marion poznaje alter ego jego właściciela...', 'https://image.tmdb.org/t/p/w500/7ZaJxINKJz0QW0gu5CyG4k8bz6w.jpg', 539, 'tt0054215', 2, 0),
(55, 'Okno na podwórze', 'Rear Window', 'Thriller, Tajemnica, Dramat', 1954, 8.3, 'Alfred Hitchcock', 112, 'English', 8, 1000000, 'Alfred J. Hitchcock Productions', '', 19.99, 'Kiedy fotograf J.B. „Jeff” Jeffries łamie nogę i zostaje przykuty do wózka inwalidzkiego, jego obsesją staje się obserwowanie życia prywatnego sąsiadów. Podejrzewając pewnego sprzedawcę o zamordowanie żony, Jeffries prosi swoją przyjaciółkę – bywającą w towarzystwie, elegancką kobietę – aby pomogła mu ustalić rzeczywisty bieg wydarzeń. Wydarzeń, które doprowadzą do jednego z najbardziej emocjonujących zakończeń w historii filmu.', 'https://image.tmdb.org/t/p/w500/oQVvQbwMa4Td1rWWYZCjIUMgyv4.jpg', 567, 'tt0047396', 2, 0),
(56, 'Deszczowa piosenka', 'Singin'' in the Rain', 'Komedia, Romans', 1952, 8.1, 'Gene Kelly', 103, 'English', 9, 2540800, 'Metro-Goldwyn-Mayer', '', 11.99, 'Akcja filmu rozgrywa się w 1927 roku. Gdy para aktorów filmu niemego znajduje się u szczytu sławy, wypuszczony zostaje pierwszy film dźwiękowy i wszystko się zmienia. Lina Lamont nie może przestawić się na film dźwiękowy z powodu swojego głosu. Jej filmowy partner Donald Lockwood i jego nowo poznana przyjaciółka Kathy postanawiają z Kathy zrobić dublerkę słynnej Liny Lamont. Oczywiście musi to doprowadzić do zgrzytu między kobietami, gdyż obie zainteresowane są Donaldem.', 'https://image.tmdb.org/t/p/w500/c5JVSQQkyBMM43oCFQEIXLJy2td.jpg', 872, 'tt0045152', 2, 0),
(57, 'Pół żartem, pół serio', 'Some Like It Hot', 'Komedia, Romans, Kryminał', 1959, 8.1, 'Billy Wilder', 120, 'English', 10, 2900000, 'The Mirisch Company', '', 18.99, 'Pod koniec szalonych lat dwudziestych, w czasach prohibicji, początku ery swingu i kulminacji wojen gangsterskich dwaj bezrobotni muzycy, Jerry i Joe, są przypadkowo świadkami porachunków kryminalnych w dniu świętego Walentego. Wiedzą za dużo, więc nie pozostaje im nic innego, jak zwiać najdalej, jak to możliwe. Jedynym ratunkiem okazuje się ucieczka z Chicago na Florydę i to w kobiecym przebraniu. Teraz już jako Daphne i Josephine na chwilę przed odjazdem pociągu trafiają do żeńskiego zespołu jazzowego, udającego się na koncerty do Miami.', 'https://image.tmdb.org/t/p/w500/yldntxtW3Qa5FjYSG0SlUBrzuyo.jpg', 239, 'tt0053291', 2, 0),
(58, 'Czarnoksiężnik z Oz', 'The Wizard of Oz', 'Przygodowy, Fantasy, Familijny', 1939, 7.6, 'Victor Fleming', 102, 'English', 1, 2777000, 'Metro-Goldwyn-Mayer', '', 10.99, 'Tornado przenosi małą Dorotkę i dom jej wujostwa do czarodziejskiej krainy Oz. Przez przypadek jedna z czarownic zostaje przygnieciona przez lądujący budynek. Jej siostra przysięga dziewczynce zemstę. By jej uniknąć, Dorotka musi dotrzeć do czarnoksiężnika z Oz i błagać go o litość. Wraz z nią w podróż udają się jej nowi przyjaciele: strach na wróble, który martwi się, że nie ma rozumu, gdyż w głowie ma jedynie słomę, blaszany człowiek, który nie ma serca i cierpi na brak uczuć, oraz lew, którego wygnano z dżungli za brak odwagi.', 'https://image.tmdb.org/t/p/w500/adAH2gVRCfik2Xe5s2l7UGnD1Ph.jpg', 630, 'tt0032138', 2, 0),
(59, 'To wspaniałe życie', 'It''s a Wonderful Life', 'Dramat, Familijny, Fantasy', 1946, 8.3, 'Frank Capra', 130, 'English', 2, 3180000, 'Liberty Films', '', 17.99, 'George Bailey (James Stewart) wraz ze swoim wujem (Thomas Mitchell) kieruje budowlaną kasą oszczędności w małym miasteczku. Niemal całkowicie poświęca się pracy, pomagając potrzebującym w uzyskaniu własnego mieszkania. Niestety, tuż przed Bożym Narodzeniem wuj gubi osiem tysięcy dolarów, co może doprowadzić do zamknięcia kasy. Bailey załamuje się nerwowo i postanawia popełnić samobójstwo. W ostatniej chwili ocala go anioł stróż, który odsłania przed nim piękne aspekty życia... Studium człowieka, który rozstaje się ze swoimi marzeniami, godząc się z codzienną - ponurą rzeczywistością.', 'https://image.tmdb.org/t/p/w500/5CkXMVRyqlyL1DsUz1CPH4hmFGK.jpg', 1585, 'tt0038650', 2, 0),
(60, 'Bulwar Zachodzącego Słońca', 'Sunset Boulevard', 'Dramat', 1950, 8.3, 'Billy Wilder', 110, 'English', 3, 1752000, 'Paramount Pictures', '', 9.99, 'W basenie jednej z posiadłości na Sunset Boulevard w Los Angeles, odnaleziony zostaje topielec. Nieboszczyk jest głównym bohaterem filmu, który, jako narrator, od tego właśnie momentu rozpoczyna snuć historię, która wyjaśni jak doszło do jego morderstwa.', 'https://image.tmdb.org/t/p/w500/sKu867NrcWKyCW2OeEjZEPsN31J.jpg', 599, 'tt0043014', 2, 0),
(61, '12 gniewnych ludzi', '12 Angry Men', 'Dramat', 1957, 8.6, 'Sidney Lumet', 96, 'English', 4, 397751, 'Orion-Nova Productions', '', 16.99, 'Tuż po zakończonej rozprawie sądowej zaczyna się zebranie przysięgłych. Mają oni rozstrzygnąć o losie jednego imigranta, który rzekomo dopuścił się morderstwa na swoim ojcu. Obradom przewodniczy Przysięgły nr 1. Pierwsze głosowanie dla wielu ławników kończy się rozczarowaniem - jeden przysięgły nie jest przekonany, co do winy oskarżonego.', 'https://image.tmdb.org/t/p/w500/zASEq60XYKIPZ4kHOzP9f1pC06P.jpg', 389, 'tt0050083', 2, 0),
(62, 'Lot nad kukułczym gniazdem', 'One Flew Over the Cuckoo''s Nest', 'Dramat', 1975, 8.4, 'Miloš Forman', 133, 'English', 5, 3000000, 'Fantasy Films', '', 8.99, 'Wprowadzając bohatera, skierowanego wprawdzie do zakładu psychiatrycznego, ale niewydającego się ani trochę szaleńcem, reżyser sugeruje jednocześnie pytanie o granice między normalnością a obłąkaniem. Widz z przerażeniem uświadamia sobie, jak są one kruche. Oto bowiem drobny złodziejaszek i awanturnik Randall Patrick McMurphy, skazany za liczne przestępstwa, w tym także gwałt, pragnąc uniknąć obozu pracy, symuluje obłęd. Zostaje wysłany na obserwację do szpitala psychiatrycznego, gdzie trafia na oddział kierowany przez siostrę Ratched.', 'https://image.tmdb.org/t/p/w500/3ICRZ5DOBwapO25lphA8yiCWi4v.jpg', 510, 'tt0073486', 2, 0),
(63, 'Lista Schindlera', 'Schindler''s List', 'Dramat, Historyczny, Wojenny', 1993, 8.6, 'Steven Spielberg', 195, 'English', 6, 22000000, 'Amblin Entertainment', '', 15.99, 'Oskar Schindler jest poważanym niemieckim przemysłowcem, który podczas II wojny światowej jest właścicielem dużej fabryki, w której w nieludzkich warunkach pracują Żydzi. Widząc cierpienie tych ludzi zaczyna ratować ich przed śmiercią w obozach koncentracyjnych. Film oparty jest na prawdziwej historii Oskara Schindlera, który podczas wojny ocalił przed śmiercią około 1100 ludzkich istnień.', 'https://image.tmdb.org/t/p/w500/7mYojklW12jrWzvjxipWFeUnO9M.jpg', 424, 'tt0108052', 2, 0),
(64, 'Szeregowiec Ryan', 'Saving Private Ryan', 'Wojenny, Dramat, Historyczny', 1998, 8.2, 'Steven Spielberg', 169, 'English', 7, 70000000, 'DreamWorks Pictures, Paramount Pictures, Amblin Entertainment', '', 7.99, 'Czerwiec 1944 roku, właśnie ruszył tzw. drugi front w Europie. Lądujący na plaży Omaha w Normandii oddział Rangersów kapitana Millera zostaje zdziesiątkowany. Z ocalałych żołnierzy, Miller wybiera kilku do niebezpiecznej misji. Otrzymuje rozkaz przeniknięcia za linię frontu i odnalezienia szeregowca Jamesa Ryan''a, jednego z tysięcy spadochroniarzy zrzuconych w noc poprzedzającą lądowanie aliantów na tyłach niemieckiej obrony. Dowództwo traktuje akcję prestiżowo. Trzej bracia Ryana, zginęli w walce i nie można dopuścić, aby matka straciła ostatniego syna. Miller ma odnaleźć i uratować Ryana nawet za cenę śmierci swoich ludzi...', 'https://image.tmdb.org/t/p/w500/9GNCKzU8vUUMgexZ5npv08mPzKr.jpg', 857, 'tt0120815', 2, 0),
(65, 'Zielona mila', 'The Green Mile', 'Fantasy, Dramat, Kryminał', 1999, 8.5, 'Frank Darabont', 188, 'English', 8, 60000000, 'Castle Rock Entertainment, Darkwoods Productions', '', 14.99, 'Paul Edgecomb jest pensjonariuszem domu starców. Kiedy pewnego razu ogląda w telewizji przedwojenny film, wzrusza się i przypomina sobie dawne czasy. Ze wspomnień zwierza się koleżance, opowiadając historię ze swojej młodości, kiedy jako strażnik bloku śmierci w 1935 roku odprowadzał więźniów na krzesło elektryczne. Ostatnia droga skazańców wiodła przez korytarz wyłożony zielonym linoleum nazywany "zieloną milą". Pewnego razu na blok trafił ogromny czarnoskóry więzień - John Coffey, skazany za zabójstwo dwóch dziewczynek. Szybko okazało się jednak, że ma on zdolność uzdrawiania, a Edgecomb postawiony został przed decyzją, która zaważy na całym jego życiu.', 'https://image.tmdb.org/t/p/w500/9Kew65xM3Ne96vjLaoOPcNqb6Rw.jpg', 497, 'tt0120689', 2, 0),
(66, 'Prestiż', 'The Prestige', 'Dramat, Tajemnica, Sci-Fi', 2006, 8.2, 'Christopher Nolan', 130, 'English', 9, 40000000, 'Warner Bros. Pictures, Touchstone Pictures, Newmarket Films', '', 6.99, 'Tajemnicza opowieść o dwóch iluzjonistach między którymi rodzi się zażarta rywalizacja, która przeradza się w wojnę na sztuczki i nieposkromione pragnienie odkrycia tajemnic zawodowych rywala. Gdy nadchodzi chwila konfrontacji obu bohaterów - odwagi z pragnieniem, estradowego talentu z nauką i ambicji z przyjaźnią - skutki stają się śmiertelnie niebezpieczne.', 'https://image.tmdb.org/t/p/w500/osBXpsFTRtpXpnxo81XRceymWNj.jpg', 1124, 'tt0482571', 2, 0),
(67, 'Memento', 'Memento', 'Tajemnica, Thriller', 2000, 8.2, 'Christopher Nolan', 113, 'English', 10, 9000000, 'Newmarket Films, Summit Entertainment, Team Todd', '', 13.99, 'Mieszkający w San Francisco detektyw ubezpieczeniowy, Leonard Shelby, w wyniku wypadku traci tzw. pamięć krótkotrwałą. Wie, kim jest i pamięta wszystko sprzed wypadku, ale błyskawicznie zapomina o tym, co wydarzyło się przed chwilą. Nie wie gdzie był, co robił i planował. Przy dłuższej rozmowie zapomina od czego się zaczęła. Powracające wspomnienia śmierci żony powodują, że nie daje za wygraną. Notatki, zdjęcia i tatuaże zastępują mu pamięć. Jedyną motywacją do życia jest obsesyjne pragnienie zemsty na mordercy ukochanej kobiety.', 'https://image.tmdb.org/t/p/w500/cOTgIhUEmaaNu10PuaYMI7WTvfa.jpg', 77, 'tt0209144', 2, 0),
(68, 'Truman Show', 'The Truman Show', 'Komedia, Dramat', 1998, 8.2, 'Peter Weir', 103, 'English', 1, 60000000, 'Paramount Pictures, Scott Rudin Productions', '', 5.99, 'Truman Burbank mieszka w uroczym nadmorskim miasteczku i wiedzie przeciętne, raczej szczęśliwe życie u boku kochającej żony Meryl. To, co dla wielu byłoby nieziszczalnym marzeniem, Truman otrzymał bez specjalnego wysiłku. Właśnie - otrzymał, a nie zdobył. Truman jest bowiem gwiazdą telewizyjnego serialu emitowanego przez 24 godziny na dobę. O każdym jego kroku decyduje reżyser programu, od niego zależy nie tylko to, kogo Truman spotka na swej drodze, ale i to, czy danego dnia będzie świecić słońce. Jednak nawet on nie przewidział, że wykreowany przez niego bohater zacznie się domyślać istnienia innego świata.', 'https://image.tmdb.org/t/p/w500/4BuOoIULkVhVYMKGg0JISxgl34f.jpg', 37165, 'tt0120382', 2, 0),
(69, 'Zakochany bez pamięci', 'Eternal Sunshine of the Spotless Mind', 'Sci-Fi, Dramat, Romans', 2004, 8.1, 'Michel Gondry', 108, 'English', 2, 20000000, 'Focus Features, Anonymous Content, This is that', '', 12.99, 'Joel odkrywa, że jego wieloletnia dziewczyna Clementine, po rozpadnięciu się ich związku poddała się eksperymentalnej operacji doktora Howarda Mierzwiaka, polegającej na wymazaniu z pamięci wszelkich wspomnień o swoim byłym ukochanym. Sfrustrowany tym faktem, postanawia skontaktować się z tajemniczym psychiatrą, aby również poddać się kuracji i wymazać ze swojej pamięci Clementine. Jednak w trakcie zabiegu, gdy wspomnienia Joela zaczynają stopniowo zanikać, przekonuje się, że wciąż kocha Clementine i tak naprawdę nie chce wyrzucać jej ze swojego umysłu. Ponieważ doktor Mierzwiak i jego współpracownicy ani myślą przerywać operacji, Joel stara się schować wspomnienia wspólnej przeszłości z Clementine w innych zakamarkach pamięci.', 'https://image.tmdb.org/t/p/w500/n6QrMP8FjQyWOfdfJnaemhNrp6a.jpg', 38, 'tt0338013', 2, 0),
(70, 'Ona', 'Her', 'Romans, Sci-Fi, Dramat', 2013, 7.8, 'Spike Jonze', 126, 'English', 3, 23000000, 'Annapurna Pictures', '', 19.99, 'Film rozgrywa się w Los Angeles, w niedalekiej przyszłości. Theodore Twombly to pełen kompleksów, samotny, wrażliwy mężczyzna, który zarabia na życie pisząc wzruszające, osobiste listy do innych ludzi. U załamanego po zakończeniu długoletniego związku, zainteresowanie budzi nowy, zaawansowany system operacyjny, który obiecuje, jako obdarzony samodoskonalącą się inteligencją, intuicyjnie dostosowywać się do potrzeb indywidualnego użytkownika. Po uruchomieniu systemu Theodore jest zachwycony, gdy poznaje „Samanthę", ciepły, kobiecy głos, który zdaje się należeć do szalenie wrażliwej, wnikliwej i zaskakująco zabawnej „osoby". W miarę, jak jej potrzeby i pragnienia rosną, równocześnie z jego własnymi, ich przyjaźń pogłębia się i przeradza w miłość.', 'https://image.tmdb.org/t/p/w500/wM1O2jlApB8M4GJ9TjomtJdRKDy.jpg', 152601, 'tt1798709', 2, 0),
(71, 'Nowy początek', 'Arrival', 'Dramat, Sci-Fi, Tajemnica', 2016, 7.6, 'Denis Villeneuve', 116, 'English', 4, 47000000, 'FilmNation Entertainment, Lava Bear Films, 21 Laps Entertainment', '', 11.99, 'Wybitna lingwistka Louise Banks (Amy Adams) zostaje wezwana przez siły obronne kraju, by spróbować porozumieć się z wysłannikami innej cywilizacji po tym, jak gigantyczny obiekt zawisł nieruchomo tuż nad Ziemią. Nikt tak naprawdę nie wie, czy obcy przybyli na Ziemię w celach pokojowych czy może są zwiastunem inwazji. W zespole badawczym wspomagają ją pułkownik Weber (Forest Whitaker) i wybitny fizyk Ian Donnelly (Jeremy Renner). Pełna napięcia metaforyczna opowieść o płynności czasu, tajemnicy, zdarzeniach, których ludzki umysł nie potrafi objąć intelektualnie.', 'https://image.tmdb.org/t/p/w500/evHCf9GuBDc42KvW9DRhY7pKx11.jpg', 329865, 'tt2543164', 2, 0),
(72, 'Łowca androidów', 'Blade Runner', 'Sci-Fi, Dramat, Thriller', 1982, 7.9, 'Ridley Scott', 117, 'English', 5, 28000000, 'Shaw Brothers, The Ladd Company, Warner Bros. Pictures', '', 18.99, '"Blade Runner" opowiada o historii jednego z Łowców Androidów, Ricka Deckarda. Replikanci, bo tak nazwano tych androidów, byli używani do niebezpiecznych badań i kolonizacji innych planet. Po krwawym buncie zespołu androidów na pozaziemskiej kolonii, Replikanci nie mogli przebywać legalnie na Ziemi. Są oni owładnięci panicznym strachem przed nieuchronną śmiercią i za wszelką cenę starają się dotrzeć do ich konstruktorów - jedynych ludzi mogących przedłużyć ich życie. Replikanci zostali bowiem zabezpieczeni przed długotrwałym życiem ze względu na rozwijające się w nich uczucia. Specjalny oddział policji - tytułowi "Łowcy Androidów" - są detektywami, którzy mają za zadanie odnaleźć i wyeliminować zbiegłych androidów. Akcja rozgrywa się w Los Angeles w 2019 roku gdy jeden z najlepszych Łowców zostaje ranny podczas wykonywania testu Voigta-Kampffa na jednym z androidów i właśnie Deckard przejmuje jego zadanie - wyeliminowanie zbiegłych androidów typu Nexus-6.', 'https://image.tmdb.org/t/p/w500/ulibbSdDYniRyx110vhrJyNd3GL.jpg', 78, 'tt0083658', 2, 0),
(73, 'Blade Runner 2049', 'Blade Runner 2049', 'Sci-Fi, Dramat', 2017, 7.6, 'Denis Villeneuve', 164, 'English', 6, 150000000, 'Alcon Entertainment, Columbia Pictures, Scott Free Productions', '', 10.99, 'Minęło 30 lat od wydarzeń przedstawionych w filmie "Łowca androidów" Ridleya Scotta. Wtedy w 2019 roku agent Rick Deckard ścigał w Los Angeles zbuntowane androidy z serii Nexus 6. Teraz w 2049 roku do akcji wkracza nowy Blade Runner, czyli łowca - oficer K . Niespodziewanie funkcjonariusz odkrywa spisek, który może zniszczyć pozostałości dawnego porządku i społeczeństwa. Żeby uratować i tak już zrujnowany świat, K musi poprosić o pomoc Deckarda. Problem w tym, że Rick ukrywa się od czasu, gdy w 2019 roku uciekł z Los Angeles...', 'https://image.tmdb.org/t/p/w500/g3YrbSqzRXVEM74AaY8rK5OqY9u.jpg', 335984, 'tt1856101', 2, 0),
(74, 'Obcy: 8 pasażer Nostromo', 'Alien', 'Horror, Sci-Fi', 1979, 8.2, 'Ridley Scott', 117, 'English', 7, 11000000, 'Brandywine Productions, Twentieth Century-Fox Productions, Ronald Shusett Productions', '', 17.99, 'W pierwszym rozdziale przerażającej sagi "Obcy", załoga statku Nostromo odpowiada na sygnał wołania o pomoc pochodzący z opustoszałej planety i odkrywa śmiercionośną formę życia, która wykorzystuje ludzkie ciało do swego rozwoju. Teraz wszyscy na pokładzie muszą walczyć nie tylko o życie, lecz także o przetrwanie całego gatunku ludzkiego.', 'https://image.tmdb.org/t/p/w500/nJmcM3Kw0vOeaErYu9pIzKs9ZRW.jpg', 348, 'tt0078748', 2, 0),
(75, 'Obcy - decydujące starcie', 'Aliens', 'Akcja, Thriller, Sci-Fi', 1986, 8.0, 'James Cameron', 137, 'English', 8, 18500000, 'SLM Production Group, 20th Century Fox, Brandywine Productions', '', 9.99, 'Po 57 latach dryfowania w przestrzeni kosmicznej oficer Ellen Ripley (Sigourney Weaver) zostaje odnaleziona. Na stacji dowiaduje się, że "firma" wysłała dużą grupę kolonistów na planetę, z której załoga Nostromo wniosła na pokład obcego. Przerażona próbuje interweniować, jednak bez skutku, gdyż nikt jej nie wierzy. Kiedy wydaje się, że wszystko wraca do normy, z bazy osadników przestają nadchodzić wiadomości. Oficer Ripley wyrusza wraz z oddziałem komandosów i pracownikiem "firmy" na planetę. To, co tam zastają, nie śniło im się w najgorszych koszmarach...', 'https://image.tmdb.org/t/p/w500/36pLA8iRP7ROgXVCLdwByzIWZQ.jpg', 679, 'tt0090605', 2, 0),
(76, 'Elektroniczny morderca', 'The Terminator', 'Akcja, Thriller, Sci-Fi', 1984, 7.7, 'James Cameron', 108, 'English', 9, 6400000, 'Hemdale, Pacific Western', '', 16.99, 'W roku 2029 Ziemię opanowują gigantyczne super-komputery dążące do zagłady całego rodzaju ludzkiego. Wysyłają w przeszłość niezniszczalnego cyborga, - Terminatora, - by zabił Sarę Connor, kobietę której nienarodzony jeszcze syn ma stać się jedyną nadzieją na przetrwanie ludzkości. Czy Sarah zdoła uchronić się przed grożącym jej niebezpieczeństwem by ocalić życie swego syna?', 'https://image.tmdb.org/t/p/w500/ipUwhiE1gR2vZ6wmUyWd8PSWtY5.jpg', 218, 'tt0088247', 2, 0),
(77, 'Terminator 2: Dzień sądu', 'Terminator 2: Judgment Day', 'Akcja, Thriller, Sci-Fi', 1991, 8.2, 'James Cameron', 137, 'English', 10, 102000000, 'Carolco Pictures, Pacific Western, Lightstorm Entertainment', '', 8.99, 'Jeden z największych przebojów w historii kina. Wielki krok w przyszłość w dziedzinie efektów specjalnych.  W przyszłości trwa wojna ludzi z maszynami, które przejęły władzę nad światem. Jedyną nadzieją ludzkości jest charyzmatyczny przywódca Ruchu Oporu, John Connor. Obawiając się go maszyny wysyłają w przeszłość nowy prototyp cyborga T-1000 (Robert Patrick), który ma zgładzić młodego Johna Connora (Edward Furlong). W ślad za nim Ruch Oporu wysyła stary model Terminatora (Arnold Schwarzenegger) przeprogramowany tak aby bronił młodego Johna.', 'https://image.tmdb.org/t/p/w500/lHlGvqexSo5EfIsxoXapmZBAGsq.jpg', 280, 'tt0103064', 2, 0),
(78, 'Powrót do przyszłości', 'Back to the Future', 'Przygodowy, Komedia, Sci-Fi', 1985, 8.3, 'Robert Zemeckis', 116, 'English', 1, 19000000, 'Universal Pictures, Amblin Entertainment', '', 15.99, 'Połowa lat 80, miasteczko Hill Valley... Młody, sympatyczny Marty (Michael J. Fox) przyjaźni się z pewnym osobliwym, starszym człowiekiem, doktorem Emmetem Brownem (Christopher Lloyd). Kiedy Marty przenosi się w czasie za pomocą wehikułu czasu skonstruowanego przez doktora, z przerażeniem odkrywa, że cofnął się o 30 lat wstecz... Na dodatek, zaraz po przybyciu zostaje przypadkowo potrącony przez swojego dziadka, a jego matka (oczywiście 30 lat młodsza) zakochuje się w nim... Marty musi w ciągu kilku dni znaleźć sposób na to, aby jego rodzice się w sobie zakochali, poradzić sobie z bandą opryszków, którzy prześladują jego ojca i przede wszystkim wrócić do swojego domu, do roku 1985...', 'https://image.tmdb.org/t/p/w500/2fEoQxuMRzebtqwHICuyM6B0HTH.jpg', 105, 'tt0088763', 2, 0),
(79, 'Pogromcy duchów', 'Ghostbusters', 'Komedia, Fantasy', 1984, 7.5, 'Ivan Reitman', 107, 'English', 2, 30000000, 'Columbia Pictures, Delphi Films, Black Rhino Productions', '', 7.99, 'Venkman (Bill Murray), Stantz (Dan Aykroyd) i Spengler (Harold Ramis) zakładają firmę zajmującą się zwalczaniem i łapaniem duchów. Ich sukcesy nie podobają się urzędnikowi organizacji środowiskowej, Peckowi (William Atherton), który doprowadza do zamknięcia przyjaciół w areszcie. Tymczasem miasto zaczyna opanowywać starożytny duch Gozer, który dostaje się do Nowego Jorku między wymiarowym kanałem znajdującym się w mieszkaniu Dany Barrett (Sigourney Weaver). Wkrótce potwory opanowują każdy zakątek miasta. Burmistrz (David Margulies), wbrew sprzeciwom Pecka, uwalnia i wzywa do pomocy pogromców.', 'https://image.tmdb.org/t/p/w500/g6hFynqGAje8BnqdBmrEuFOdeiP.jpg', 620, 'tt0087332', 2, 0),
(80, 'Indiana Jones i poszukiwacze zaginionej Arki', 'Raiders of the Lost Ark', 'Przygodowy, Akcja', 1981, 7.9, 'Steven Spielberg', 115, 'English', 3, 18000000, 'Paramount Pictures, Lucasfilm Ltd.', '', 14.99, 'Dr. Indiana Jones (Harrison Ford) jest archeologiem, który łączy wykłady uniwersyteckie z ekspedycjami badawczymi. Właśnie powrócił z ostatniej, w trakcie której odniósł porażkę w rywalizacji z naukowcem pracującym dla nazistów. Nie dane jest mu zająć się nauczaniem. Otrzymuje bowiem tajne zadanie od służb specjalnych. Wyrusza do Egiptu, gdzie prawdopodobnie odkryto miejsce przechowywania Arki Przymierza. Nie może dopuścić, by święte trofeum znalazło się w rękach Niemców. Pomoże mu w tym jego dawna dziewczyna, Marion (Karen Allen).', 'https://image.tmdb.org/t/p/w500/bvDtNNt9skWNip11BNtHZHICDX2.jpg', 85, 'tt0082971', 2, 0),
(81, 'Indiana Jones i ostatnia krucjata', 'Indiana Jones and the Last Crusade', 'Przygodowy, Akcja', 1989, 7.9, 'Steven Spielberg', 127, 'English', 4, 48000000, 'Paramount Pictures, Lucasfilm Ltd.', '', 6.99, 'Nie ma nic bardziej ekscytującego niż staranie się dotrzymać kroku Jonesom w filmie "Indiana Jones i ostatnia krucjata". Nazistowscy wrogowie Indy''ego powracają i porywają mu ojca, profesora Henry''ego Jonesa, by pomógł  odnaleźć Świętego Grala. Od zagubionych miast, po skarby templariuszy i  podziemia Wenecji, odkryj źródło wiecznego życia i największą ekranową przygodę Indiany Jonesa!', 'https://image.tmdb.org/t/p/w500/m4FpMTE4mXp9yTVwt2aOFhewNTa.jpg', 89, 'tt0097576', 2, 0),
(82, 'Szczęki', 'Jaws', 'Horror, Thriller, Przygodowy', 1975, 7.7, 'Steven Spielberg', 124, 'English', 5, 7000000, 'The Zanuck/Brown Company, Universal Pictures', '', 13.99, 'W niewielkiej osadzie na wyspie wybucha panika po kolejnych atakach jakiegoś stworzenia na pływających w morzu. Okazuje się, że wielki biały rekin nie chce wcale stąd odpływać. Szeryf Brody z przyjaciółmi Hooper''em i Quint''em decydują się go zabić.', 'https://image.tmdb.org/t/p/w500/mW4LDGSvlqDGB5mKV2b25O3uINx.jpg', 578, 'tt0073195', 2, 0),
(83, 'Lśnienie', 'The Shining', 'Horror, Thriller', 1980, 8.2, 'Stanley Kubrick', 144, 'English', 6, 19000000, 'Warner Bros. Pictures, Peregrine, Hawk Films', '', 5.99, 'Jack Torrance (Jack Nicholson) pracuje jako dozorca hotelu Panorama w górach stanu Kolorado. Pensjonat jest zamknięty na zimę, więc Jack z rodziną są jedynymi mieszkańcami budynku. Kiedy burze śnieżne blokują familię Torrance''ów w hotelu, Danny (Danny Lloyd), syn Jacka, który ma nadprzyrodzone, telepatyczne zdolności odkrywa, że pensjonat jest nawiedzony i duchy powoli doprowadzają jego ojca do obłędu. Kiedy Jack spotyka zjawę pana Grady''ego (Philip Stone), poprzedniego dozorcy hotelu, sytuacja staje się coraz groźniejsza.', 'https://image.tmdb.org/t/p/w500/lMniGq1BYnHOdhEiLOQxGYAKATC.jpg', 694, 'tt0081505', 2, 0),
(84, 'Egzorcysta', 'The Exorcist', 'Horror', 1973, 7.8, 'William Friedkin', 122, 'English', 7, 11000000, 'Hoya Productions, Warner Bros. Pictures', '', 12.99, 'Chris jest aktorką samotnie wychowującą 12-letnią córkę. Pewnego dnia w domu zaczynają się dziać dziwne rzeczy, pojawiają się trudne do zidentyfikowania odgłosy, znaki. Regan bluźni i jest agresywna. Psychiatrzy nie potrafią znaleźć medycznego wyjaśnienia tego, co się dzieje z córką Chris. Zdesperowana kobieta szuka pomocy u księdza, ojca Karrasa, który dochodzi do wniosku, że to szatan opętał Regan. Chcąc wypędzić z niej diabła, Karras wzywa doświadczonego egzorcystę, ojca Merrina.', 'https://image.tmdb.org/t/p/w500/d2hfdz4UzOwPJ9Wd7wvqQjogmb3.jpg', 9552, 'tt0070047', 2, 0),
(85, 'Halloween', 'Halloween', 'Horror, Thriller', 1978, 7.6, 'John Carpenter', 91, 'English', 8, 325000, 'Compass International Pictures, Falcon International Productions', '', 19.99, 'Święto Halloween, 1963 roku. W miasteczku Haddonfield sześcioletni Michael Myers brutalnie zamordował swoją nastoletnią siostrę. Chłopak trafia do szpitala dla umysłowo chorych, z którego po piętnastu latach ucieka i wraca do Haddonfield. Gdy nadchodzi Halloween, Michael zaczyna prześladować niczego nieświadome licealistki. Laurie (Jamie Lee Curtis) wraz z przyjaciółkami, Annie (Nancy Kyes) i Lyndą (P.J. Soles), planują imprezę w domu jednej z nich. Wszystkie trzy stają się celem mordercy.', 'https://image.tmdb.org/t/p/w500/wijlZ3HaYMvlDTPqJoTCWKFkCPU.jpg', 948, 'tt0077651', 2, 0),
(86, 'Koszmar z Ulicy Wiązów', 'A Nightmare on Elm Street', 'Horror', 1984, 7.4, 'Wes Craven', 91, 'English', 9, 1800000, 'New Line Cinema, Smart Egg Pictures, Media Home Entertainment', '', 11.99, 'Czwórkę nastoletnich przyjaciół męczą koszmary. Pojawia się w nich ten sam facet z poparzoną twarzą w kapeluszu i rękawicy zakończonej brzytwami. Z początku nie traktują sprawy poważnie. Zmienia to się diametralnie kiedy ginie Tina. Podejrzenie spada na jej chłopaka Roda, ponieważ to on był z nią tej straszliwej nocy. Nancy wierząc w niewinność przyjaciela odkrywa przerażającą prawdę dotyczącą człowieka z jej snów.', 'https://image.tmdb.org/t/p/w500/smYGD7smBa4VYEqH2Ho87m0Fp7Q.jpg', 377, 'tt0087800', 2, 0),
(87, 'Krzyk', 'Scream', 'Kryminał, Horror, Tajemnica', 1996, 7.4, 'Wes Craven', 106, 'English', 10, 14000000, 'Dimension Films, Woods Entertainment', '', 18.99, 'Co się dzieje, gdy ktoś obejrzy o jeden horror za dużo? W małym miasteczku Woodsboro grasuje seryjny morderca. Swe ofiary wybiera spośród uczniów miejscowej szkoły. Dzwoni do nich, proponując quiz ze znajomości popularnych filmów grozy. Horror zaczyna się, gdy nieszczęśnik popełni błąd. Sidney Prescott jeszcze nie doszła do siebie po starcie matki, która została zamordowana przed rokiem. Dokładnie w rocznicę jej śmierci odbiera telefon od tajemniczego nieznajomego proponującego jej dziwną grę...', 'https://image.tmdb.org/t/p/w500/vl59nEiI4lIiNv6PKDq6JrkSrjy.jpg', 4232, 'tt0117571', 2, 0),
(88, 'Milczenie owiec', 'The Silence of the Lambs', 'Kryminał, Thriller, Dramat', 1991, 8.3, 'Jonathan Demme', 118, 'English', 1, 19000000, 'Orion Pictures, Strong Heart, A Luta Continua', '', 10.99, 'Psychopata porywa i morduje młode kobiety na środkowym zachodzie. Wierząc, że w ujęciu tego mordercy dopomoże tylko inny przestępca, F.B.I. wysyła agentkę Clarice Starling (Jodie Foster) na wywiad z obłąkanym więźniem, który może dostarczyć psychologicznych przesłanek i tropów do kolejnych działań zabójcy. Więzień, psychiatra, dr. Hannibal Lecter (Anthony Hopkins) jest genialnym mordercą-kanibalem, który pomoże Agentce Starling, jeżeli ona będzie karmić jego chorą ciekawość detalami ze swojego skomplikowanego życia. Ta pokręcona relacja zmusza Starling nie tylko do konfrontacji z jej psychicznymi demonami, ale doprowadza ją również do spotkania twarzą w twarz z szalonym, ohydnym mordercą, wcieleniem zła tak potężnym, że nie będzie miała odwagi - ani siły - by go zatrzymać!', 'https://image.tmdb.org/t/p/w500/qWG1nSFlp4oNwSSTCPk3Q3n4FlD.jpg', 274, 'tt0102926', 2, 0),
(89, 'La La Land', 'La La Land', 'Komedia, Dramat, Romans', 2016, 7.9, 'Damien Chazelle', 128, 'English', 2, 30000000, 'Summit Entertainment, Gilbert Films, Impostor Pictures', '', 17.99, 'Mia jest początkującą aktorką, która w oczekiwaniu na szansę pracuje jako kelnerka. Sebastian to muzyk jazzowy, który zamiast nagrywać płyty, gra do kotleta w podrzędnej knajpce. Gdy drogi tych dwojga przetną się, połączy ich wspólne pragnienie, by zacząć wreszcie robić to co kochają. Miłość dodaje im sił, ale gdy kariery zaczynają się wreszcie układać, coraz mniej jest czasu i sił dla siebie nawzajem. Czy uda im się ocalić uczucie, nie rezygnując z marzeń?', 'https://image.tmdb.org/t/p/w500/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', 313369, 'tt3783958', 2, 0),
(90, 'Whiplash', 'Whiplash', 'Dramat, Muzyczny, Thriller', 2014, 8.4, 'Damien Chazelle', 105, 'English', 3, 3300000, 'Bold Films, Blumhouse Productions, Right of Way Films', '', 9.99, 'Andrew (Miles Teller) jest utalentowanym młodym perkusistą, uczniem konserwatorium muzycznego na Manhattanie. Chłopak marzy o wielkiej karierze. Aby zrealizować plany, postanawia dołączyć do szkolnej orkiestry jazzowej prowadzonej przez okrutnego nauczyciela Terence''a Fletchera (J.K. Simmons), który często wyładowuje swoje frustracje na uczniach. Pod kierunkiem bezwzględnego Fletchera, Andrew zaczyna dążyć do doskonałości za wszelką cenę - nawet własnego człowieczeństwa.', 'https://image.tmdb.org/t/p/w500/4Twi6WFaiGHc0SrIhdtZRNt45xg.jpg', 244786, 'tt2582802', 2, 0),
(91, 'Grand Budapest Hotel', 'The Grand Budapest Hotel', 'Komedia, Dramat', 2014, 8.0, 'Wes Anderson', 100, 'English', 4, 30000000, 'Fox Searchlight Pictures, Studio Babelsberg, Indian Paintbrush', '', 16.99, 'W okresie międzywojennym Gustave H, konsjerż prestiżowego europejskiego hotelu, zawiera znajomość z młodym boyem imieniem Zero, który zostaje jego zaufanym protegowanym.', 'https://image.tmdb.org/t/p/w500/npptkW8LqZeIlZUDFoUuOykihlQ.jpg', 120467, 'tt2278388', 2, 0),
(92, 'Moonlight', 'Moonlight', 'Dramat', 2016, 7.4, 'Barry Jenkins', 110, 'English', 5, 4000000, 'A24, Plan B Entertainment, PASTEL', '', 8.99, 'Ponadczasowa opowieść o relacjach międzyludzkich i odkrywaniu siebie. "Moonlight" jest opowieścią o dorastaniu ubogiego, czarnego chłopca.  Dorasta on w jednej z niebezpieczniejszych dzielnic Miami i stara się znaleźć swoje miejsce w świecie. Handel narkotykami na ich osiedlu kontroluje Juan, który staje się swego rodzaju zastępczym ojcem Chirona. Czysty i widny dom, w którym Juan mieszka ze swoją dziewczyną Teresą staje się dla chłopca oazą stabilności, miejscem gorących posiłków, świeżej pościeli i swobodnych rozmów. Drugim, równie bolesnym i skomplikowanym motywem przewodnim, jest związek Chirona z jego matką, Paulą, która stacza się w wyniszczający nałóg narkotykowy, których dostarcza jej Juan.', 'https://image.tmdb.org/t/p/w500/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', 376867, 'tt4975722', 2, 0),
(93, 'Parasite', '기생충', 'Komedia, Thriller, Dramat', 2019, 8.5, '봉준호', 132, 'Korean', 6, 11363000, 'Barunson E&A', '', 15.99, 'Żywot rodziny pana Ki-taeka nie należy do najbardziej udanych. Rodzice z dwójką dorosłych dzieci żyją w nędzy, wszyscy są bezrobotni, a przyszłość rysuje się tylko w szarych barwach. Jednak pomimo niedoli, potrafią być ze sobą blisko, kochać się i trwać w zgodzie - nikt tu nie krzyczy w desperacji "Jak żyć?!". Pewnego dnia otrzymują prezent od losu, który przepełnia ich nadzieją oraz wizją stałego dochodu. Syn Ki-woo zostaje polecony przez kolegę, studenta prestiżowego uniwersytetu, na dobrze płatną posadę korepetytora. Chłopak udaje się na rozmowę kwalifikacyjną do domu rodziny Parków, żyjących w zupełnie innym świecie. Pan Park jest właścicielem międzynarodowej firmy z branży IT, ma też piękną żonę Yeon-kyo. Spotkanie dwóch jakże odmiennych rodzin prowadzi do ciągu tragikomicznych wydarzeń.', 'https://image.tmdb.org/t/p/w500/jjHccoFjbqlfr4VGLVLT7yek0Xn.jpg', 496243, 'tt6751668', 2, 0),
(94, 'Spirited Away: W krainie Bogów', '千と千尋の神隠し', 'Animacja, Familijny, Fantasy', 2001, 8.5, 'Hayao Miyazaki', 125, 'Japanese', 7, 19000000, 'Studio Ghibli, Tokuma Shoten, Nippon Television Network Corporation', '', 7.99, 'Chihiro jest kapryśną, upartą dziesięcioletnią dziewczynką, która uważa, że cały świat powinien spełniać jej zachcianki. Gdy rodzice oznajmiają jej, że trzeba będzie wyprowadzić się z domu, Chihiro jest z tego powodu zła i nie myśli tego ukrywać. Zabrnąwszy w tajemniczą ślepą uliczkę, rodzina staje nagle przed ogromnym czerwonym domem, do którego wnętrza prowadzi niekończący się tunel, rozwarty jak ogromne usta. Wkrótce okazuje się, że Chihiro i jej rodzice wtargnęli do świata zamieszkanego przez starożytnych bogów i magiczne stworzenia, świata, którym rządzi demoniczna czarownica, okrutna Yubaba.', 'https://image.tmdb.org/t/p/w500/gSqglWhte6Q3zT71ovD1Ww4ckzd.jpg', 129, 'tt0245429', 2, 0),
(95, 'Księżniczka Mononoke', 'もののけ姫', 'Przygodowy, Fantasy, Animacja', 1997, 8.3, 'Hayao Miyazaki', 134, 'Japanese', 8, 20000000, 'Studio Ghibli, dentsu, Tokuma Shoten', '', 14.99, 'Waleczny młodzieniec o imieniu Ashitaka broni swej wioski przed złym potworem. Chłopak zwycięża – ale demon rzuca na niego klątwę, której efektem jest powolna, nieunikniona śmierć. Jedynym ratunkiem może być pomoc legendarnego boga zwierząt Shishi-Gami. Ashitaka wyrusza na jego poszukiwanie. Wkrótce staje się świadkiem bitwy pomiędzy przedstawicielami cywilizacji a siłami natury, które, zagrożone przez człowieka, wypowiedziały mu wojnę. Oddziałem leśnych stworzeń dowodzi wychowana przez białą wilczycę księżniczka Mononoke.  Ashitaka musi opowiedzieć się za jedną ze stron.', 'https://image.tmdb.org/t/p/w500/tpm3eXEKqiGsMBqhp2gXqBrDEmW.jpg', 128, 'tt0119698', 2, 0),
(96, 'Mój sąsiad Totoro', 'となりのトトロ', 'Fantasy, Animacja, Familijny', 1988, 8.1, 'Hayao Miyazaki', 86, 'Japanese', 9, 3700000, 'Studio Ghibli, Tokuma Shoten', '', 6.99, 'Dwie dziewczynki, Mei i Satsuki, wraz z ojcem i zmagającą się z ciężką chorobą mamą przeprowadzają się na wieś, do opuszczonego, nieco tajemniczego domu. Szybko odkrywają, że spokojna sielska okolica przepełniona jest magią. Najpierw siostry spotykają mieszkające w ich domu tajemnicze czarne kulki, później poznają łagodne i życzliwe duchy lasu, a wśród nich niezwykłego Totoro. Kiedy młodsza dziewczynka zaginie, okaże się, jak cenna jest ta przyjaźń...', 'https://image.tmdb.org/t/p/w500/p6i0gjS4G3FogVlRVayex1SJnn8.jpg', 8392, 'tt0096283', 2, 0),
(97, 'Toy Story', 'Toy Story', 'Familijny, Komedia, Animacja, Przygodowy', 1995, 8.0, 'John Lasseter', 80, 'English', 10, 30000000, 'Pixar', '', 13.99, 'W świecie zabawek Andy''ego, których niekwestionowanym liderem był dotychczas kowboj Chudy, pojawia się nowa zabawka - astronauta Buzz.', 'https://image.tmdb.org/t/p/w500/94tkkZYlr35UC4JzrtiACfpF6Ua.jpg', 862, 'tt0114709', 2, 0),
(98, 'Toy Story 2', 'Toy Story 2', 'Animacja, Komedia, Familijny', 1999, 7.6, 'John Lasseter', 92, 'English', 1, 90000000, 'Pixar', '', 5.99, 'Kontynuacja opowieści sprzed kilku lat, zrealizowanej techniką komputerową. Akcja toczy się w domu chłopca, jego zabawki żyją własnym życiem. Jedna z figurek, kowboj, zostaje uszkodzona. Przez przypadek kowboj trafia na wyprzedaż rzeczy używanych.', 'https://image.tmdb.org/t/p/w500/156IFZshUqhYZLznowAd229QYkG.jpg', 863, 'tt0120363', 2, 0),
(99, 'Toy Story 3', 'Toy Story 3', 'Animacja, Familijny, Komedia', 2010, 7.8, 'Lee Unkrich', 103, 'English', 2, 200000000, 'Pixar', '', 12.99, 'Andy stał się już dużym chłopcem i wybiera się na studia. Pragnie zabrać wraz ze sobą swą ulubioną zabawkę z dzieciństwa Kowboja Chudego, a resztę jego podopiecznych mama chłopca postanawia oddać do miejskiego przedszkola. W obawie o los swoich przyjaciół Chudy postanawia ich nie opuszczać. W przedszkolu zabawki nawiązują nowe znajomości, oraz napotykają na niebezpieczeństwo ze strony niesfornych przedszkolaków. Od tej pory Chudy wraz z przyjaciółmi robią wszystko by się stamtąd wydostać i wrócić do domu.', 'https://image.tmdb.org/t/p/w500/WW8MbtmHDZg1g9uW3OsS4jUoJw.jpg', 10193, 'tt0435761', 2, 0),
(100, 'Gdzie jest Nemo', 'Finding Nemo', 'Animacja, Familijny, Przygodowy', 2003, 7.8, 'Andrew Stanton', 100, 'English', 3, 94000000, 'Pixar', '', 19.99, 'Wielką Rafę Koralową zamieszkują kolorowe rybki zwane błazenkami. Jedną z nich o imieniu Marlin spotyka tragedia. Drapieżna ryba pożera mu żonę - Coral i prawie wszystkie jajeczka ikry, z których miały młode błazenki. Ocalał jedynie jeden mały błazenek o imieniu Nemo, który staje się oczkiem w głowie Marlina. Gdy jednak nadopiekuńczy ojciec postanawia wysyłać go do szkoły, zdarza się kolejne nieszczęście: mały błazenek zostaje wyłowiony z oceanu przez nurka i trafia do akwarium w gabinecie dentystycznym w Sydney. Merlin, który boi się głębi oceanu, postanawia wyruszyć na ratunek synkowi. W jego wyprawie towarzyszy mu inna rybka - Dora, która jest straszliwą zapominalską.', 'https://image.tmdb.org/t/p/w500/81ULtY262mzmTR8PagVdNApcoHp.jpg', 12, 'tt0266543', 2, 0),
(101, 'Król Lew', 'The Lion King', 'Animacja, Familijny, Dramat', 1994, 8.3, 'Roger Allers', 88, 'English', 4, 45000000, 'Walt Disney Pictures, Walt Disney Feature Animation', '', 11.99, 'Opowieść o Simbie lwiątku, dziedzicu Lwiej Krainy. Za sprawą knowań złego stryja Skazy, Simba musi opuścić rodzinne strony. Samotny i porzucony, trafia pod opiekę wesołych i beztroskich kompanów Timona i Pumby. Dorasta, wiodąc wraz z nimi radosne, pełne przygód życie, zapominając o odpowiedzialności i królewskim dziedzictwie. Przeznaczenie jednak daje o sobie znać. Simba przekonuje się, że nadszedł czas powrotu i objęcia we władanie Lwiej Krainy. Musi znaleźć w sobie dość odwagi, by przeciwstawić się złemu stryjowi Skazie, stoczyć z nim zaciekłą walkę i zająć należne mu w odwiecznym „kręgu życia” miejsce.', 'https://image.tmdb.org/t/p/w500/zTnHPNgI0PnRaUe6aZPIwNn2eV4.jpg', 8587, 'tt0110357', 2, 0),
(102, 'Piękna i Bestia', 'Beauty and the Beast', 'Romans, Familijny, Animacja, Fantasy', 1991, 7.7, 'Gary Trousdale', 91, 'English', 5, 25000000, 'Silver Screen Partners IV, Walt Disney Pictures', '', 18.99, 'Córka ogrodnika sprawującego opiekę nad różami zgadza się zamieszkać w ponurym zamczysku, aby ratować życie ojca. Początkowo gospodarz budzi w niej jedynie przerażenie i wstręt, lecz z upływem czasu dziewczyna zaczyna współczuć istocie zamkniętej w odrażającym ciele. Dostrzegłszy w niej piękne cechy ukryte pod maską brzydoty, zakochuje się. Miłość zdejmuje z księcia klątwę.', 'https://image.tmdb.org/t/p/w500/l2n1QQRk2pPl7QgzrY9zw1S1ZlD.jpg', 10020, 'tt0101414', 2, 0),
(103, 'Aladyn', 'Aladdin', 'Animacja, Familijny, Przygodowy, Fantasy', 1992, 7.7, 'John Musker', 90, 'English', 6, 28000000, 'Walt Disney Feature Animation', '', 10.99, 'Ubogi Aladyn jest ulicznym złodziejaszkiem który mieszka z swoim najlepszym przyjacielem małpką Abu w wielkim mieście Agrabah. Gdy córka sułtana Dżasmina postanawia wyrwać się z pałacu, przypadkowo spotyka naszego bohatera na targowisku, okazuje się że obje świetnie się czują w swoim towarzystwie. Ku przerażeniu Dżasminy Aladyn zostaje wtrącony do lochu za drobne kradzieże które popełnił. Co gorsza księżniczka może poślubić jedynie księcia a jeśli nie wybierze szybko kandydata na męża jej ręka przypadnie Wielkiemu Wezyrowi. Wezyr Dżafar pragnie zostać sułtanem, w tym celu postanawia wykorzystać chłopca by ten zdobył magiczną lampę ukrytą w magicznej jaskini pełnej pułapek.', 'https://image.tmdb.org/t/p/w500/gy9Kvft5uBBB57CcZfU2Pur4hyL.jpg', 812, 'tt0103639', 2, 0),
(104, 'Kraina lodu', 'Frozen', 'Animacja, Familijny, Przygodowy, Fantasy', 2013, 7.2, 'Chris Buck', 102, 'English', 7, 150000000, 'Walt Disney Animation Studios', '', 17.99, 'Anna wyrusza na wielką wyprawę, by odnaleźć swoją siostrę Elsę, której magiczna moc uwięziła królestwo Arendelle w okowach wiecznej zimy. W poszukiwaniach towarzyszy jej Kristoff, przed którym górskie szlaki nie kryją żadnych tajemnic i jego lojalny renifer Sven. Podczas misji ocalenia królestwa przyjaciele zmierzą się z surową pogodą, napotkają niebotyczne góry, tajemnicze trolle i zabawnego bałwana o imieniu Olaf.', 'https://image.tmdb.org/t/p/w500/ydbRzsNjAbclgWYHDkZKlgaKZoR.jpg', 109445, 'tt2294629', 2, 0),
(105, 'Vaiana: Skarb oceanu', 'Moana', 'Przygodowy, Komedia, Familijny, Animacja', 2016, 7.6, 'Ron Clements', 107, 'English', 8, 150000000, 'Walt Disney Animation Studios', '', 9.99, 'Trzy tysiące lat temu najdzielniejsi żeglarze na świecie przemierzali wody południowego Pacyfiku i odkrywali wyspy Oceanii. Jednak w pewnym momencie ich wyprawy ustały na całe tysiąc lat – i nikt nie wie dlaczego… Walt Disney Animation Studios prezentuje film "Vaiana: Skarb oceanu". Jest to komputerowo animowana opowieść o przygodach nastolatki, która, chcąc dokończyć dzieła swych przodków, wyrusza w niebezpieczną misję. Podczas podróży poznaje potężnego niegdyś półboga Maui. Od tego momentu wspólnie żeglują przez bezmiar oceanu, który nie szczędzi im karkołomnych przygód, obfitujących w spotkania z ogromnymi potworami.', 'https://image.tmdb.org/t/p/w500/hOhxt3MZyOOmWF8tHboG9XBQUyV.jpg', 277834, 'tt3521164', 2, 0),
(106, 'Zwierzogród', 'Zootopia', 'Animacja, Przygodowy, Familijny, Komedia', 2016, 7.8, 'Byron Howard', 108, 'English', 9, 150000000, 'Walt Disney Animation Studios', '', 16.99, 'Zwierzogrodu nie można pomylić z żadnym innym miastem. Jest to jedyna w swoim rodzaju współczesna metropolia zamieszkiwana wyłącznie przez zwierzęta. W Zwierzogrodzie nie jest ważne, jakim stworzeniem jesteś – czy to największym z lwów, czy może malutką ryjówką. Możesz tam zostać kimkolwiek chcesz. Ale nie wszystkie marzenia spełniają się od razu... Gdy do miasta przybywa ambitna policjantka Judy Hopps, szybko przekonuje się, że jako pierwszy królik zatrudniony w miejscowej policji, nie będzie wcale miała łatwego życia. Robi więc wszystko, by udowodnić swoją wartość (i zdobyć upragniony awans). Na jej drodze pojawia się jednak gadatliwy i chytry lis, Nick Bajer. Chcąc wykazać się za wszelką cenę, Judy przyjmuje sprawę, w której musi rozwiązać pewną kryminalną zagadkę. Jej partnerem w śledztwie zostaje nie kto inny jak wygadany i szczwany Nick...', 'https://image.tmdb.org/t/p/w500/kTPaxxk7FlV0J77U2ztywjGf8Sb.jpg', 269149, 'tt2948356', 2, 0),
(107, 'W głowie się nie mieści', 'Inside Out', 'Animacja, Familijny, Przygodowy, Dramat', 2015, 7.9, 'Pete Docter', 94, 'English', 10, 175000000, 'Pixar', '', 8.99, 'Najnowsza produkcja studia Disney/Pixar zabierze was w szaloną podróż w głąb umysłu. W Centrum dowodzenia, znajdującym się w głowie 11-letniej Riley, praca wre w najlepsze. Dziewczynką kieruje 5 pracujących w pocie czoła emocji pod dowództwem optymistycznej Radości, która robi wszystko, by Riley pozostała szczęśliwa. Nie jest to jednak łatwe, kiedy współpracownikami w tym emocjonalnym fachu są Strach, Złość, Odraza i Smutek.', 'https://image.tmdb.org/t/p/w500/hf0z2LV69XedGf2RAGfOtgLaIo.jpg', 150540, 'tt2096673', 2, 0),
(108, 'Coco', 'Coco', 'Familijny, Animacja, Muzyczny, Przygodowy', 2017, 8.2, 'Lee Unkrich', 108, 'English', 1, 175000000, 'Pixar', '', 15.99, 'Film opowiada o historii małego chłopca - Miguela, który próbuje rozwiązać pewną tajemnicę rodzinną. Za sprawą nieoczekiwanych wydarzeń dochodzi do spotkania chłopca i rodziny, żywej jak i martwej.', 'https://image.tmdb.org/t/p/w500/yMapvyFKryN8lgR1o0wD4tsCUw3.jpg', 354912, 'tt2380307', 2, 0),
(109, 'Odlot', 'Up', 'Animacja, Komedia, Familijny, Przygodowy', 2009, 8.0, 'Pete Docter', 96, 'English', 2, 175000000, 'Pixar', '', 7.99, 'Pewnego dnia Carl Fredricksen postanawia zrealizować marzenie swego życia i wyrusza w podróż do tajemniczej krainy w Ameryce Południowej. Nie byłoby w tym nic dziwnego, gdyby nie fakt, że Carl podróżuje we własnym domu unoszonym przez setki balonów, a w wyprawie przypadkowo towarzyszy mu pewien ośmiolatek. Jednak prawdziwe przygody zaczynają się dopiero po dotarciu na miejsce, gdzie dwóch podróżników spotyka dziwacznego ptaka i mówiącego ludzkim głosem psa.', 'https://image.tmdb.org/t/p/w500/j7SZNJiHi8tKPfuit1NLEBJUfeB.jpg', 14160, 'tt1049413', 2, 0),
(110, 'WALL-E', 'WALL·E', 'Animacja, Familijny, Sci-Fi', 2008, 8.1, 'Andrew Stanton', 98, 'English', 3, 180000000, 'Pixar', '', 14.99, 'Co się stanie, jeżeli ludzie opuszczą kiedyś Ziemię i pozostanie na niej jedynie mały robot? WALL.E (Wysypiskowy Automat Likwidująco Lewarujący. E-klasa) przez siedemset lat w samotności oczyszcza Ziemię z odpadów pozostawionych przez ludzi. Pewnego dnia na planetę przybywa EVE – nowoczesna, przepiękna, myśląca maszyna. Tego dnia życie WALL.E’ego zupełnie się zmienia i nabiera nowego sensu. Jego podróż przez galaktykę, przyjaźń z EVE, zabawne przygody oraz nowi, niekiedy niezwykli przyjaciele stali się tematem najnowszej komedii Studia Pixar.', 'https://image.tmdb.org/t/p/w500/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', 10681, 'tt0910970', 2, 0);

INSERT INTO `filmy` (`id`, `tytul`, `tytul_oryginalny`, `gatunek`, `rok`, `ocena`, `rezyser`, `czas_trwania`, `jezyk`, `ilosc_dostepnych`, `budzet`, `produkcja`, `nagrody`, `cena`, `opis`, `okladka`, `tmdb_id`, `imdb_id`, `typ_plyty_id`, `czy_ulubiony`) VALUES
(111, 'Ojciec chrzestny II', 'The Godfather Part II', 'Dramat, Kryminał', 1974, 8.6, 'Francis Ford Coppola', 200, 'English', 1, 13000000, 'Paramount Pictures, The Coppola Company, American Zoetrope', '', 5.99, 'Ta mistrzowska kontynuacja "Ojca chrzestnego" opisuje losy dwóch pokoleń rodu Corleone w bezwzględnym dążeniu do władzy. Francis Ford Coppola podzielił swą powieść na dwie części: w pierwszej przedstawił losy młodego Don Vito, zagranego bezbłędnie przez Roberta De Niro, w drugiej -  przejmowanie przez Michaela (Al Pacino) władzy w mafijnej rodzinie. Ponownie, gromadząc na planie wielu znakomitych artystów, Coppola stworzył bez wątpienia najlepszy sequel w dziejach kina.', 'https://image.tmdb.org/t/p/w500/sWQjhhK9AidSLExyn7M26Tz4V6U.jpg', 240, 'tt0071562', 2, 0),
(112, 'Ojciec chrzestny III', 'The Godfather Part III', 'Kryminał, Dramat, Thriller', 1990, 7.4, 'Francis Ford Coppola', 162, 'English', 2, 54000000, 'Paramount Pictures, American Zoetrope', '', 12.99, 'Sześćdziesięcioletni Michael Corleone myśli o wyprowadzeniu swej rodziny ze świata zbrodni, a zarazem o znalezieniu właściwego następcy. Wybór pada na porywczego Vincenta, ale decyzja ta równie dobrze może przekreślić marzenia o legitymizacji i wciągnąć rodzinę w piekło mafijnej wojny.', 'https://image.tmdb.org/t/p/w500/tNQ5xf0p39kX7B6YYK9XMbQ3epU.jpg', 242, 'tt0099674', 2, 0),
(113, 'Kasyno', 'Casino', 'Kryminał, Dramat', 1995, 8.0, 'Martin Scorsese', 178, 'English', 3, 50000000, 'Universal Pictures, Syalis DA, Légende Films', '', 19.99, 'Nowoczesne, błyszczące neonami hotele, wielkie sale koncertowe i wystawne rewie to tylko przykrywka tego, co stanowi istotę Las Vegas - hazardu. Film Martina Scorsese oparty na dokumentalnej książce Nicholasa Pileggiego ujawnia, w jaki sposób mafia czerpie zyski z kasyn i salonów gier. A tam, gdzie chodzi o wielkie pieniądze, rodzą się wielkie namiętności. Ale tu, w Las Vegas, nie ma miejsca na miłość, tu toczy się brutalna, pełna przemocy gra, w której ludzkie życie nie ma żadnej wartości. Po fascynującym świecie Las Vegas, światowej stolicy hazardu i zbrodni, oprowadzą Cię Robert De Niro i Joe Pesci, a towarzyszyć im będzie Sharon Stone, laureatka Złotego Globu za rolę Ginger - dziewczyny, która mogła zostać królową Las Vegas.', 'https://image.tmdb.org/t/p/w500/mtmgLoDfFiIZ8D3TMxwBq0kA24z.jpg', 524, 'tt0112641', 2, 0),
(114, 'Infiltracja', 'The Departed', 'Dramat, Thriller, Kryminał', 2006, 8.2, 'Martin Scorsese', 151, 'English', 4, 90000000, 'Warner Bros. Pictures, Plan B Entertainment, Initial Entertainment Group', '', 11.99, 'Akcja filmu rozgrywa się w południowym Bostonie, gdzie policja stanowa toczy zażartą walkę z przestępczością zorganizowaną. Młody tajny agent policji, Billy Costigan, otrzymuje od przełożonego Olivera Queenana rozkaz przeniknięcia do struktur mafijnych, którymi rządzi Frank Costello. Podczas gdy Billy szybko zdobywa zaufanie bossa, Colin Sullivan - zatwardziały młody przestępca, który już jako kadet Akademii Policyjnej pełnił rolę mafijnego informatora - zostaje awansowany na stanowisko dowódcze w Wydziale Spraw Wewnętrznych. Każdego z nich pochłania podwójne życie. Kiedy zarówno przestępcy, jak i stróże prawa, wpadają na trop wrogiej wtyczki we własnych szeregach, obaj bohaterowie rozpoczynają wyścig o to, kto pierwszy odkryje tożsamość drugiego, by tym samym uratować własną skórę...', 'https://image.tmdb.org/t/p/w500/fENeo92FAaDPngxfI4CF4h1V0UA.jpg', 1422, 'tt0407887', 2, 0),
(115, 'Nietykalni', 'The Untouchables', 'Kryminał, Historyczny, Thriller', 1987, 7.8, 'Brian De Palma', 119, 'English', 5, 25000000, 'Paramount Pictures, Linson Entertainment', '', 18.99, 'Młody agent skarbowy Elliot Ness przyjeżdża do Chicago w celu aresztowania Al Capone''a, co okazuje się nie lada wyzwaniem, ponieważ Capone opłaca policję. Ness poznaje Jimmiego Malone- starego dzielnicowego, który w porównaniu do reszty policjantów nie jest skorumpowany. Ness prosi by pomogł mu dorwać Capone. Malone ostrzega go jednak, że zadarcie z Capone oznacza wojnę.', 'https://image.tmdb.org/t/p/w500/jSkvKknXeM4qzHZkU4CUcXaTXBw.jpg', 117, 'tt0094226', 2, 0),
(116, 'Człowiek z blizną', 'Scarface', 'Akcja, Kryminał, Dramat', 1983, 8.2, 'Brian De Palma', 170, 'English', 6, 25000000, 'Universal Pictures, Martin Bregman Productions', '', 10.99, 'Al Pacino w roli niezapomnianego Tony’ego Montany, jednego z najbardziej bezwzględnych gangsterów w historii kina. Wyreżyserowany przez Briana De Palmę i wyprodukowany przez Martina Bergmana (twórcy filmowej wersji legendarnego "Ojca chrzestnego"). "Człowiek z blizną" opowiada o błyskotliwej karierze mafijnej kubańskiego uchodźcy. Ten początkowo drobny złodziejaszek dzięki swej wyjątkowej brutalności i bezwzględności wspina się na sam szczyt kokainowego imperium. Doskonały scenariusz nagrodzonego Oscarem® Oliviera Stone’a, imponująca ścieżka dźwiękowa Georgio Morodera oraz znakomite przedstawienie stylu życia łacińskiej części Miami powodują, iż ten film zalicza się do najlepszych dramatów sensacyjnych, odsłaniających brutalne oblicze świata przestępczego i władzę ludzi amerykańskiej sceny narkotykowej.', 'https://image.tmdb.org/t/p/w500/en0c1qbCGC0WEBviAhGfmlyJjIH.jpg', 111, 'tt0086250', 2, 0),
(117, 'Dawno temu w Ameryce', 'Once Upon a Time in America', 'Dramat, Kryminał', 1984, 8.4, 'Sergio Leone', 229, 'English', 7, 30000000, 'Embassy International Pictures, PSO, The Ladd Company', '', 17.99, 'Lata 20. i 30. XX wieku. David i Max razem dorastali w żydowskim getcie w Nowym Jorku. Byli członkami gangu młodzieżowego, żyli z drobnych oszustw. Po latach przyjaciele kierują własną grupą przestępczą, mają wspólne fundusze, nad którymi pieczę sprawuje ich kompan Moe. Robią wielkie pieniądze na nielegalnym handlu alkoholem. Wraz z nadejściem końca prohibicji w 1933 roku gang przeżywa kryzys finansowy. Zgrana niegdyś paczka powoli się rozpada.', 'https://image.tmdb.org/t/p/w500/6Q9YO69pt9oxe1ygeMd2F4gjaGv.jpg', 311, 'tt0087843', 2, 0),
(118, 'Pewnego razu na Dzikim Zachodzie', 'C''era una volta il West', 'Dramat, Western', 1968, 8.3, 'Sergio Leone', 166, 'Italian', 8, 5000000, 'Paramount Pictures, Rafran Cinematografica, San Marco', '', 9.99, 'Jill McBain (Claudia Cardinale) przyjeżdża z Nowego Orleanu do swojego męża, który mieszka w małym miasteczku na Dzikim Zachodzie. Kilka dni przed jej przybyciem McBain i jego dzieci z poprzedniego małżeństwa zostają zamordowani przez bandę Franka (Henry Fonda). Jednak o zbrodnię podejrzewany jest Cheyenne (Jason Robards). W tym czasie w okolicy pojawia się tajemniczy człowiek nazywany "Harmonijką" (Charles Bronson).', 'https://image.tmdb.org/t/p/w500/1UJi76RRavosnXjLzZqItsIgcsi.jpg', 335, 'tt0064116', 2, 0),
(119, 'Dobry, zły i brzydki', 'Il buono, il brutto, il cattivo', 'Western', 1966, 8.5, 'Sergio Leone', 161, 'Italian', 9, 1200000, 'United Artists, PEA, Arturo González PC', '', 16.99, 'Obraz ten jest ostatnią częścią "dolarowej" trylogii Sergia Leone. Bohaterami filmu są trzej mężczyźni: Zły - bezwzględny łowca nagród, Brzydki - wielokrotny przestępca, Dobry - łowca głów z zasadami. Wszyscy trzej usiłują dotrzeć do ukrytego przez wojsko skarbu. Brzydki jest w posiadaniu informacji o nazwie cmentarza, na którym został on zakopany, Dobry zna nazwisko na poszukiwanym grobie. Czyni to z nich mimowolny zespół. Po piętach depcze im Zły.', 'https://image.tmdb.org/t/p/w500/48UDOsbi1D47Iu0h2JnkZU2GXna.jpg', 429, 'tt0060196', 2, 0),
(120, 'Za garść dolarów', 'Per un pugno di dollari', 'Western', 1964, 7.8, 'Sergio Leone', 99, 'Italian', 10, 200000, 'Jolly Film, Ocean Films, Constantin Film', '', 8.99, 'Samotny wędrowiec Joe przybywa do miasteczka leżącego przy granicy meksykańsko-amerykańskiej. Wpływy dzielą tu między siebie dwie rywalizujące bandy przemytników. Przebiegły Joe dostrzega szansę na zarobek, lokując się pomiędzy skonfliktowanymi stronami, co realizuje zatrudniając się raz w jednej, raz w drugiej grupie. Wkrótce wtrąca się również w losy lokalnej rodziny, rozdzielonej przez bandytów. W rezultacie ściąga na siebie wrogość jednego z rodów, doprowadzając do eskalacji trwającego konfliktu.', 'https://image.tmdb.org/t/p/w500/ol8KRvdKyh84QEER7EEZ6c2C5qW.jpg', 391, 'tt0058461', 2, 0),
(121, 'Za kilka dolarów więcej', 'Per qualche dollaro in più', 'Western', 1965, 8.0, 'Sergio Leone', 132, 'Italian', 1, 600000, 'PEA, Constantin Film, Arturo González PC', '', 15.99, 'Kiedy dwaj rywalizujący ze sobą łowcy nagród orientują się, że ścigają tego samego bandytę, łączą siły w nadziei doprowadzenia go przed oblicze sprawiedliwości. Jednak wraz z rozwojem akcji, sprawy coraz bardziej się komplikują. Zobacz mocną, drugą część sagi Sergia Leone, w której Eastwood wciela się w osławionego „Człowieka bez imienia”.', 'https://image.tmdb.org/t/p/w500/kNNMR1KxkrYrqOBLGVgMDksoFYF.jpg', 938, 'tt0059578', 2, 0),
(122, 'Big Lebowski', 'The Big Lebowski', 'Komedia, Kryminał', 1998, 7.9, 'Joel Coen', 117, 'English', 2, 15000000, 'PolyGram Filmed Entertainment, Working Title', '', 7.99, 'Historia Jeffa Lebowskiego, który padł ofiarą fatalnej pomyłki. Dwóch zbirów włamuje się do mieszkania zasiedziałego w latach 70-tych, zblazowanego, bezrobotnego Jeffa Lebowskiego, każącego się nazywać The Dude, w głębokim przekonaniu, że napadają na Jeffa Lebowskiego, milionera z Pasadeny. Ofiara pomyłki odwiedza bogatego imiennika w celu otrzymania rekompensaty za zniszczony (obsikany przez włamywaczy) dywan. The Dude oraz jego kumpel, Walter, nie dostają perskiego dywanu, po który przyszli, za to wplątują się w Coenowską czarną komedię pomyłek, wymuszeń, moralnego zdegenerowania, fałszerstw, seksu i narkotyków.', 'https://image.tmdb.org/t/p/w500/vn5eAuGyh5Ap5bqYHFe3QIsJnby.jpg', 115, 'tt0118715', 2, 0),
(123, 'To nie jest kraj dla starych ludzi', 'No Country for Old Men', 'Kryminał, Thriller, Western', 2007, 7.9, 'Joel Coen', 122, 'English', 3, 25000000, 'Miramax, Paramount Vantage, Scott Rudin Productions', '', 14.99, 'Mroczny thriller braci Coen (Ethana i Joela), rozwijający się w prawdziwy dramat egzystencjalny - na 8 nominacji do Oskara. Pewien myśliwy natrafia niedaleko granicy z Meksykiem na przedziwne znalezisko: paczki heroiny, 2 000 000 dolarów i kilka ciał. Niewiele myśląc, zabiera pieniądze - co sprowadza mu na głowę prawdziwe kłopoty, z szalonym płatnym mordercą (nagrodzony Złotym Globem oskarowy faworyt Javier Bardem) na czele.', 'https://image.tmdb.org/t/p/w500/3ep7Ot5m3qgcBubF7cxcpcc2CIY.jpg', 6977, 'tt0477348', 2, 0),
(124, 'Aż poleje się krew', 'There Will Be Blood', 'Dramat', 2007, 8.1, 'Paul Thomas Anderson', 158, 'English', 4, 25000000, 'Paramount Vantage, Miramax, JoAnne Sellar Productions', '', 6.99, 'Biznes to wojna. I to taka, w której nie bierze się jeńców. Aby zgromadzić wielki majątek, trzeba być bezwzględnym i gotowym na wszystko. Takim właśnie człowiekiem był Daniel Plainview (Daniel Day-Lewis). Na przełomie XIX i XX wieku udało mu się odkryć złoża ropy naftowej w Nowym Meksyku. Umiejętnie inwestując kapitał, Plainview dorobił się całkiem pokaźnej fortuny. Sukces miał jednak swoją cenę - Daniel stał się potworem znienawidzonym przez wszystkich. Nie cofał się przed niczym, nawet jeśli w grę wchodził szantaż czy zabójstwo. W swoim dziele reżyser (Paul Thomas Anderson) pokazał brutalne narodziny wielkiego, amerykańskiego kapitału.', 'https://image.tmdb.org/t/p/w500/nYdMNzRN8YP410P2eg4chvayDHq.jpg', 7345, 'tt0469494', 2, 0),
(125, 'American Beauty', 'American Beauty', 'Dramat', 1999, 8.0, 'Sam Mendes', 117, 'English', 5, 15000000, 'DreamWorks Pictures, Jinks/Cohen Company', '', 13.99, 'Głównym bohaterem American Beauty i narratorem zarazem jest 42-letni Lester Burnham. Oto facet, który po dwudziestu latach letargu budzi się do prawdziwego życia. Impulsem do zmian staje się koleżanka córki, w typie lolitki, rozbudzająca jego zmysły. Pod jej wpływem przewartościowuje swoje życie – ćwiczy i powraca do formy fizycznej, rzuca pracę, staje się szczery i bezkompromisowy. Powraca do marzeń z młodości, które okazują się złudzeniami, bo czy palenie trawki, jeżdżenie sportowym wozem, albo beztroska „Mc-praca” uczyni go wolnym i młodym?', 'https://image.tmdb.org/t/p/w500/d7o5PkPoBuzv8OHrFrYBMAKI2yg.jpg', 14, 'tt0169547', 2, 0),
(126, 'The Social Network', 'The Social Network', 'Dramat', 2010, 7.4, 'David Fincher', 120, 'English', 6, 40000000, 'Columbia Pictures, Relativity Media, Scott Rudin Productions', '', 5.99, 'Wyreżyserowany przez Davida Finchera film The Social Network to fascynująca historia nowego rodzaju kulturowej ewolucji. To opowieść o młodym geniuszu, który zainicjował rewolucję i zmienił oblicze ludzkich interakcji nie tylko w swoim pokoleniu, ale być może na zawsze. Przesiąknięty emocjonalną brutalnością i swoistym humorem, ten mistrzowsko zrealizowany film jest kroniką powstawania portalu Facebook oraz zapiskiem z wojny o prawo do jego własności, która rozpętała się po nieoczekiwanym, spektakularnym sukcesie nowej strony internetowej. Wybitnie przenikliwy scenariusz Aarona Sorkina i genialna obsada, wśród której znajdują się Jesse Eisenberg, Andrew Garfield i Justin Timberlake to bezdyskusyjne atuty produkcji The Social Network, dzięki której zobaczysz narodziny pomysłu, który utkał nową strukturę społeczną, rozplątując jednocześnie więzi przyjaźni między swoimi twórcami.', 'https://image.tmdb.org/t/p/w500/4UqFxN1ayyXyPI6aZim2q0HvCZs.jpg', 37799, 'tt1285016', 2, 0),
(127, 'Zaginiona dziewczyna', 'Gone Girl', 'Tajemnica, Thriller, Dramat', 2014, 7.9, 'David Fincher', 145, 'English', 7, 61000000, '20th Century Fox, Regency Enterprises, TSG Entertainment', '', 12.99, 'Po utracie pracy Nick Dunne przeprowadza się wraz z żoną, Amy, z Nowego Jorku do rodzinnej miejscowości w stanie Missouri. Tam otwiera bar, korzystając z oszczędności małżonki. Pomimo dobrze prosperującego interesu oboje zaczynają coraz bardziej się od siebie oddalać. Gdy w rocznicę ślubu Amy przepada bez śladu, Nick staje się głównym podejrzanym.', 'https://image.tmdb.org/t/p/w500/rFwfIgdxQQIA45y0hjCAIRowOhY.jpg', 210577, 'tt2267998', 2, 0),
(128, 'Zodiak', 'Zodiac', 'Kryminał, Tajemnica, Thriller', 2007, 7.5, 'David Fincher', 157, 'English', 8, 65000000, 'Paramount Pictures, Warner Bros. Pictures, Phoenix Pictures', '', 19.99, 'Thriller Finchera oparty jest na prawdziwych wydarzeniach związanych z jedną z najbardziej intrygujących, niewyjaśnionych zbrodni w historii Stanów Zjednoczonych. Seryjny zabójca terroryzuje okolice San Francisco, zwodząc policję i media wymyślnymi szyframi i tajemniczymi listami. Poszukiwaniami mordercy zajmują się funkcjonariusze śledczy z czterech okręgów sądowych oraz dociekliwy pracownik lokalnej gazety. Wkrótce sprawa ta staje się ich wspólną obsesją. Wplątani w wir niewyjaśnionych wydarzeń i wciąż nowych poszlak poddawani są nieustannej próbie, zarówno w życiu osobistym, jak i zawodowym.', 'https://image.tmdb.org/t/p/w500/2BODBRj7MCfiF3wcXaZlowFdqT4.jpg', 1949, 'tt0443706', 2, 0),
(129, 'Podejrzani', 'The Usual Suspects', 'Dramat, Kryminał, Thriller', 1995, 8.2, 'Bryan Singer', 106, 'English', 9, 6000000, 'Bad Hat Harry Productions, Blue Parrot Productions', '', 11.99, 'Tytułowi "Podejrzani" to pięciu kryminalistów – Dean Keaton (Byrne), McManus (Baldwin), Todd Hockney (Pollak), Fenster (Del Toro) i Verbal Kint (Spacey). Są zamieszani w eksplozję statku, w wyniku której zginęło 27 osób i zniknęła kokaina o wartości 91 milionów dolarów. Świadkami tego wydarzenia są: ciężko poparzony węgierski imigrant, który twierdzi, że widział Keysera Soze, czyli samego diabła, i jeden z "podejrzanych" - kaleki kryminalista Verbal Kint. Verbal decyduje się, w zamian za nietykalność, opowiedzieć policji całą historię. Wraca pamięcią do momentu, kiedy wraz z pozostałymi "podejrzanymi" został aresztowany przez nowojorską policję, a później pracował z nimi, dokonując kilku napadów.', 'https://image.tmdb.org/t/p/w500/mRRSlwhEXnmj3e8RNdd1202ZfwB.jpg', 629, 'tt0114814', 2, 0),
(130, 'Wielki sen', 'The Big Sleep', 'Tajemnica, Kryminał, Thriller', 1946, 7.6, 'Howard Hawks', 116, 'English', 10, 250000, 'Warner Bros. Pictures', '', 18.99, 'Prywatny detektyw Philip Marlowe (Humphrey Bogart) zostaje wynajęty przez bogatego dżentelmena do ochrony jego pięknej córki. Nieopatrznie sam staje się ofiarą starannie ukartowanej intrygi, której rozwiązania strzeże mroczna zasłona milczenia i zbrodni... Znakomita adaptacja debiutanckiej powieści Raymonda Chandlera.', 'https://image.tmdb.org/t/p/w500/lraHo9D8c0YWfxsKqT5P5sVqMKN.jpg', 910, 'tt0038355', 2, 0),
(131, 'Sokół maltański', 'The Maltese Falcon', 'Tajemnica, Kryminał, Thriller', 1941, 7.7, 'John Huston', 100, 'English', 1, 375000, 'Warner Bros. Pictures', '', 10.99, 'Sam Spade, prywatny detektyw, otrzymuje zlecenie odnalezienia młodszej siostry Ruth Wonderly. W miarę jak Spade zaczyna zagłębiać się w sprawie, przekonuje się, że jego prawdziwe zlecenie polega na odnalezieniu niewielkiego posągu przedstawiającego sokoła. Rzeźba ta powstała w roku 1539 i była wyrazem hołdu złożonego przez Templariuszy królowi Hiszpanii. W drodze do Hiszpanii galera, która ją przewoziła, została zatopiona przez piratów, a po posągu słuch zaginął. Rzeźba odnajduje się po latach w San Francisco, ale chętnych do jej zdobycia jest wielu.', 'https://image.tmdb.org/t/p/w500/bf4o6Uzw5wqLjdKwRuiDrN1xyvl.jpg', 963, 'tt0033870', 2, 0),
(132, 'Podwójne ubezpieczenie', 'Double Indemnity', 'Kryminał, Thriller', 1944, 8.1, 'Billy Wilder', 107, 'English', 2, 927262, 'Paramount Pictures', '', 17.99, 'Walter Neff (Fred MacMurray) jest jednym z najlepszych agentów ubezpieczeniowych. Zjawia się w domu państwa Dietrichson by odnowić polisę samochodową. W ten sposób poznaje Phyllis (Barbara Stanwyck), nieszczęśliwą młodą mężatkę. Kobieta go oczarowuje. Niedługo potem wspólnie opracowują plan "zbrodni doskonałej" - mają ubezpieczyć życie męża kobiety, aby następnie dokonać zabójstwa. Jednak nie wszystko idzie zgodnie z planem...', 'https://image.tmdb.org/t/p/w500/rVNYZZgfhwqVMMWlBmxOfWqnwCj.jpg', 996, 'tt0036775', 2, 0),
(133, 'Chinatown', 'Chinatown', 'Kryminał, Tajemnica, Thriller', 1974, 7.9, 'Roman Polański', 135, 'English', 3, 6000000, 'Paramount Pictures, Long Road Productions, Robert Evans Productions', '', 9.99, 'Pechowy prywatny detektyw, tajemnicza piękność, bezwzględny mafioso oraz skomplikowana intryga utkana ze zdrady, morderstw, korupcji, skandali i śmiertelnie niebezpiecznych układów. Wszystko to w mrocznej i stylowej opowieści o latach 30., uznawanej za pozycję wyjątkową i ponadczasową, a także za hołd Romana Polańskiego dla niezwykłego gatunku, jakim jest klasyczny czarny kryminał. Intrygujący scenariusz (Oscar dla Roberta Towne), mistrzowska reżyseria i niezapomniane kreacje.', 'https://image.tmdb.org/t/p/w500/oCa5oljQWjplvANGno9nOeZcSYz.jpg', 829, 'tt0071315', 2, 0),
(134, 'Rozmowa', 'The Conversation', 'Kryminał, Dramat, Tajemnica', 1974, 7.5, 'Francis Ford Coppola', 113, 'English', 4, 1600000, 'The Directors Company, The Coppola Company', '', 16.99, 'Harry Caul  jest specjalistą od podsłuchu. W swoim rzadkim fachu osiągnął mistrzostwo. Jest w stanie podsłuchać każdą rozmowę, niezależnie od tego, w jakim miejscu się ona odbywa. Jedną z koronnych zasad, jaką Caul kieruje się w swojej pracy, jest nieangażowanie się. Ten chłodny profesjonalizm to pancerz ochronny. Pewnego dnia inwigilując rozmowę pary młodych ludzi, Harry łamie swoją zasadę.', 'https://image.tmdb.org/t/p/w500/pNwi1Q3vw2r0lAWJD3M5zNUjkuc.jpg', 592, 'tt0071360', 2, 0),
(135, 'Taksówkarz', 'Taxi Driver', 'Kryminał, Dramat', 1976, 8.1, 'Martin Scorsese', 113, 'English', 5, 1900000, 'Bill/Phillips Productions, Columbia Pictures', '', 8.99, 'Travis, weteran wojny w Wietnamie cierpiący na bezsenność, zatrudnia się jako taksówkarz na nocnej zmianie. Jeżdżąc wieczorami po Nowym Jorku, styka się z najbardziej podejrzanymi i niebezpiecznymi ludźmi i zdaje sobie sprawę, ile otacza go przemocy i okrucieństwa. Próbuje, bezskutecznie zresztą, nawiązać znajomość z pracowniczką kampanii wyborczej, Betsy. Spotyka też młodą prostytutkę Iris, którą chce uwolnić od ciemiężyciela. Mężczyzna postanawia na własną rękę rozprawić się z całym "robactwem" tego miasta...', 'https://image.tmdb.org/t/p/w500/6vEoplgvAqgwh3TnYj8kjFsaxXu.jpg', 103, 'tt0075314', 2, 0),
(136, 'Wściekły byk', 'Raging Bull', 'Dramat, Historyczny', 1980, 7.9, 'Martin Scorsese', 129, 'English', 6, 18000000, 'United Artists, Winkler Films', '', 15.99, 'Historia amerykańskiego boksera Jake''a LaMotty. Niebywała siła i agresywny charakter przynoszą mu kolejne sukcesy w ringu. Zyskuje przydomek "wściekły byk z Bronksu". Niestety, autodestrukcyjne skłonności i presja, jaką wywiera na nim otoczenie, coraz bardziej dają mu się we znaki. W niestabilnym psychicznie i łatwo wpadającym w furię mężczyźnie narasta napięcie. Bokser popada w nałóg alkoholowy i niszczy relacje ze swoją drugą żoną Vicki i bratem Joeyem.', 'https://image.tmdb.org/t/p/w500/1WV7WlTS8LI1L5NkCgjWT9GSW3O.jpg', 1578, 'tt0081398', 2, 0),
(137, 'Król komedii', 'The King of Comedy', 'Dramat, Komedia', 1982, 7.8, 'Martin Scorsese', 109, 'English', 7, 19000000, 'Embassy International Pictures', '', 7.99, 'Pozbawiony talentu Rupert Pupkin (Robert De Niro) widzi siebie w roli komika estradowego. Próbuje przeniknąć w świat show-biznesu, na razie łowiąc autografy gwiazdorów. Jego bożyszczem jest znany telewizyjny komik, Jerry Langford. Przy pomocy znajomej, Mashy, udaje mu się zbliżyć do komika, podstępem wślizgując się do jego auta i prosząc o autograf. Uratowawszy go rzekomo przed awansami pełnej temperamentu Mashy, oczekuje wdzięczności. Od tej pory Pupkin nęka gwiazdora, prosząc o pomoc w zrobieniu kariery.', 'https://image.tmdb.org/t/p/w500/m5e6Lp1MJZPXzAhVt7AQQCy9d5E.jpg', 262, 'tt0085794', 2, 0),
(138, 'Po godzinach', 'After Hours', 'Komedia, Thriller, Dramat', 1985, 7.5, 'Martin Scorsese', 97, 'English', 8, 4500000, 'Double Play, Geffen Pictures', '', 14.99, 'Programista komputerowy przeżywa najgorszą noc swojego życia, kiedy postanawia wybrać się do Soho na randkę z dziewczyną, którą poznał w kawiarni.', 'https://image.tmdb.org/t/p/w500/xqNcD76lNgFTRBtNlAzhEP4GJly.jpg', 10843, 'tt0088680', 2, 0),
(139, 'Rób, co należy', 'Do the Right Thing', 'Dramat', 1989, 7.8, 'Spike Lee', 120, 'English', 9, 6500000, 'Universal Pictures, 40 Acres and a Mule Filmworks', '', 6.99, 'Akcja filmu rozgrywa się w czarnym gettcie nowojorskiego Brooklynu. W okolicy znajduje się sklep warzywny prowadzony prze Koreańczyków i pizzeria Sala, włoskiego emigranta. Jest najgorętszy dzień lata. Narastają napięcia pomiędzy mieszkańcami dzielnicy. Mookie, dostawca pizzy Sala, zawsze znajduje się w centrum wydarzeń.', 'https://image.tmdb.org/t/p/w500/63rmSDPahrH7C1gEFYzRuIBAN9W.jpg', 925, 'tt0097216', 2, 0),
(140, 'Malcolm X', 'Malcolm X', 'Dramat, Historyczny', 1992, 7.6, 'Spike Lee', 202, 'English', 10, 34000000, 'Warner Bros. Pictures, 40 Acres and a Mule Filmworks, Marvin Worth Productions', '', 13.99, 'Malcolm X był jedną z najbardziej kontrowersyjnych postaci Ameryki lat 60. Rywalizował z Martinem Lutherem Kingiem o rząd dusz czarnoskórych Amerykanów. Obydwu przywódcom przyświecały podobne cele: emancypacja afroamerykańskiej społeczności, walka o szacunek i równe prawa w zdominowanym przez białych kraju. Tu jednak podobieństwa się kończyły. Pastor King pragnął zrealizować swoje wizje w oparciu o zasady chrześcijańskiej moralności. Malcolm X dopuszczał do używania przemocy w walce politycznej. Zapowiadał także radykalną rewolucję społeczną.', 'https://image.tmdb.org/t/p/w500/o2s9ow0uRRm1BcF3teznk5twd90.jpg', 1883, 'tt0104797', 2, 0),
(141, 'Gorączka', 'Heat', 'Kryminał, Dramat, Akcja', 1995, 7.9, 'Michael Mann', 171, 'English', 1, 60000000, 'Warner Bros. Pictures, Regency Enterprises, Forward Pass', '', 5.99, 'Kiedy Al Pacino i Robert De Niro wyrównują rachunki, "Gorączka" gwałtownie wzrasta. Film w reżyserii i na podstawie scenariusza Michaela Manna składa się z niesamowitych ujęć, w których scenę napadu na bank Mike Clark z "USA Today" nazwał "najwspanialszą sceną akcyjną ostatnich lat". Znajdziesz tu również "najbardziej imponującą obsadę aktorską zebraną w jednym filmie" ("Newsweek"). Val Kilmer, Jon Voight, Tom Sizemore i Ashley Judd partnerują dwóm gwiazdom największego formatu - Pacino i De Niro. Vincent Hanna (Al Pacino) to genialny gliniarz z wydziału zabójstw. Neil McCauley (Robert De Niro) - niepospolity, perfekcyjny i niezwykle zuchwały przestępca. Obaj staną do pojedynku na siłę, przebiegłość i intelekt.', 'https://image.tmdb.org/t/p/w500/ksc8jAUScgrtXomBPnoXLlktEV.jpg', 949, 'tt0113277', 2, 0),
(142, 'Życie Carlita', 'Carlito''s Way', 'Kryminał, Dramat, Thriller', 1993, 7.8, 'Brian De Palma', 144, 'English', 2, 30000000, 'Universal Pictures, Epic Productions, Bregman/Baer Productions', '', 12.99, '"Życie Carlita" to gangsterski film akcji w reżyserii znakomitego Briana De Palmy. Wyróżniony nagrodą Academy Award, Al Pacino gra barona narkotykowego, który próbuje zmienić swoje życie.  Zwolniony z więzienia, dzięki pomocy swojego uzależnionego od kokainy prawnika, Carlito Brigante - były król świata narkotyków, postanawia zerwać z niechlubną przeszłością i pragnie rozpocząć normalne życie. Podejmuje pracę jako menadżer nocnego klubu i obiecując rzetelną poprawę odnawia romans ze swoją byłą dziewczyną. Wyjście na prostą nie jest jednak łatwe. Carlito na każdym kroku napotyka byłych kumpli oraz bezwzględnych młodocianych opryszków, pragnących zaistnieć na scenie czarnego półświatka. Pomimo dobrych intencji, Carlito znów uwikła się w brutalną walkę na śmierć i życie z siłami, które nie chcą pozwolić mu odejść.  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/AtUj1r3X5bv1eYOjW70h375xU98.jpg', 6075, 'tt0106519', 2, 0),
(143, 'Donnie Brasco', 'Donnie Brasco', 'Kryminał, Dramat, Thriller', 1997, 7.5, 'Mike Newell', 127, 'English', 3, 35000000, 'Mark Johnson Productions, Baltimore Pictures, Mandalay Entertainment', '', 19.99, 'Agent FBI Joseph D. Pistone, otrzymuje zadanie infiltracji mafijnej rodziny Lefty''ego Ruggiero. Podając się za młodego pasera biżuterii Donniego Brasco, Pistone zaskarbia sobie przyjaźń i zaufanie gangstera. Wkrótce okazuje się, że bardzo trudno jest pogodzić oddanemu swej pracy Pistonowi życie zawodowe i prywatne. Młody agent przeżywa wewnętrzne rozterki, jako że z biegiem czasu zaczyna coraz bardziej podziwiać i szanować Ruggiero, człowieka, którego ma wydać...', 'https://image.tmdb.org/t/p/w500/tK6SV8VlvCVOMYidp14acpGjqDW.jpg', 9366, 'tt0119008', 2, 0),
(144, 'Amerykański gangster', 'American Gangster', 'Dramat, Kryminał', 2007, 7.6, 'Ridley Scott', 157, 'English', 4, 100000000, 'Film Rites, Imagine Entertainment, Universal Pictures', '', 11.99, 'Frank Lucas człowiek, który wie czym jest poczucie honoru, ale i znający zasady ulicy, postanawia uporządkować chaotyczne podziemie narkotykowe Harlemu. Na jego drodze stanie jednak Richie Roberts, nieprzekupny gliniarz, który poprzysiągł zniszczyć warte setki milionów dolarów narkotykowe imperium. Dwie silne osobowości po dwóch stronach barykady. Oto, jak wyglądało ich legendarne starcie.', 'https://image.tmdb.org/t/p/w500/qr26554LrAlNfeYpbErrkkKXsUw.jpg', 4982, 'tt0765429', 2, 0),
(145, 'Irlandczyk', 'The Irishman', 'Kryminał, Dramat, Historyczny', 2019, 7.6, 'Martin Scorsese', 209, 'English', 5, 159000000, 'Tribeca Productions, Sikelia Productions, Winkler Films', '', 18.99, 'Osadzona w powojennej Ameryce epicka opowieść widziana oczami weterana II wojny światowej Franka Sheerana, oszusta i płatnego mordercy pracującego dla najbardziej osławionych przestępców XX wieku. Rozgrywająca się na przestrzeni kilkudziesięciu lat saga poświęcona jest jednej z największych zagadek kryminalnych w historii Stanów Zjednoczonych – tajemniczemu zaginięciu legendarnego przywódcy związków zawodowych Jimmy’ego Hoffa. Widzowie wezmą udział w brutalnej podróży, podczas której zostaną przed nimi odsłonięte kulisy funkcjonowania przestępczego półświatka, wewnętrznych walk o wpływy oraz kryminalnych powiązań ze światem polityki.', 'https://image.tmdb.org/t/p/w500/tCQVSf9EhH0XQ06x6jCyWlPMyzT.jpg', 398978, 'tt1302006', 2, 0),
(146, 'Czas krwawego księżyca', 'Killers of the Flower Moon', 'Kryminał, Historyczny, Dramat', 2023, 7.4, 'Martin Scorsese', 206, 'English', 6, 200000000, 'Apple Studios, Imperative Entertainment, Sikelia Productions', '', 10.99, 'Gdy w latach 20. XX wieku w Oklahomie zostają odkryte złoża ropy na terenie zamieszkałym przez Osedżiów, ktoś zaczyna mordować członków plemienia, aż do akcji wkracza FBI, by rozwiązać zagadkę.', 'https://image.tmdb.org/t/p/w500/oA1EDzdHhAMkslPxtiVIRW4T3I4.jpg', 466420, 'tt5537002', 2, 0),
(147, 'Wilk z Wall Street', 'The Wolf of Wall Street', 'Kryminał, Dramat, Komedia', 2013, 8.0, 'Martin Scorsese', 179, 'English', 7, 100000000, 'Red Granite Pictures, Appian Way, Sikelia Productions', '', 17.99, 'Prawdziwa historia króla Wall Street. Jordan Belfort zarabiał tysiące dolarów na minutę. Wydawał je równie szybko zaczynając od pijackiej imprezy zakończonej zatopieniem 50m jachtu, a kończąc na rachunku hotelowym na 700 tys. dolarów oraz rozbiciu prywatnego odrzutowca. W latach 90-tych były szef firmy inwestycyjnej "Stratton Oakmont" został jednym z najbardziej niesławnych rekinów amerykańskiego sektora finansowego. Oszukując klientów na korzyść własnej firmy wspiął się na szczyt. Jego hedonistyczny tryb życia nie uległ zmianie nawet, gdy FBI i komisja papierów wartościowych pukały do jego drzwi. Oto biografia człowieka, który zaczynając od sprzedawania lodów na ulicznym rogu doszedł do miliardów.', 'https://image.tmdb.org/t/p/w500/eQTzLZ8szPpQuxKsxvUDUEq74nd.jpg', 106646, 'tt0993846', 2, 0),
(148, 'Aviator', 'The Aviator', 'Dramat', 2004, 7.2, 'Martin Scorsese', 170, 'English', 8, 110000000, 'Warner Bros. Pictures, Miramax, Initial Entertainment Group', '', 9.99, 'Bohaterem projektu jest Howard Hughes, amerykański miliarder, pilot i konstruktor lotniczy, który w 1935 r. ustanowił światowy rekord prędkości - 567 km/h, a w 1938 r. wykonał etapowy lot dookoła świata. Fabuła filmu opowiada o latach młodości Howarda Hughesa. Zaczyna się, gdy bohater reżyseruje jeden z ulubionych obrazów Martina Scorsese "Aniołowie piekieł", a kończy w 1946 roku, gdy Howard romansuje z najznamienitszymi aktorkami Hollywood.', 'https://image.tmdb.org/t/p/w500/xi2H8QHLMtOcSuG5FaUL4ypVZ6q.jpg', 2567, 'tt0338751', 2, 0),
(149, 'Gangi Nowego Jorku', 'Gangs of New York', 'Dramat, Historyczny, Kryminał', 2002, 7.3, 'Martin Scorsese', 167, 'English', 9, 100000000, 'Miramax, Touchstone Pictures, Initial Entertainment Group', '', 16.99, 'XIX-wieczny Nowy Jork. Po szesnastu latach spędzonych w sierocińcu Amsterdam, syn zamordowanego przywódcy gangu irlandzkich imigrantów, wraca do Five Points, by pomścić śmierć ojca. Jego zabójca, William Cutting zwany Billem Rzeźnikiem, sprawuje rządy w dzielnicy. Chłopak postanawia zabić Rzeźnika w czasie dorocznej uroczystości, gdy Bill będzie święcił zwycięstwo nad jego ojcem. By zrealizować plan, przenika w szeregi bandy. Rzeźnik traktuje Amsterdama jak syna. A on wbrew sobie zaczyna darzyć go szacunkiem i zakochuje się w jego wychowanicy.', 'https://image.tmdb.org/t/p/w500/uMcROA58iZcLwVMyfNvDTBarImV.jpg', 3131, 'tt0217505', 2, 0),
(150, 'Wyspa tajemnic', 'Shutter Island', 'Dramat, Thriller, Tajemnica', 2010, 8.2, 'Martin Scorsese', 138, 'English', 10, 80000000, 'Paramount Pictures, Phoenix Pictures, Sikelia Productions', '', 8.99, 'Akcja filmu rozgrywa się w 1954 roku na pięknej wyspie Zatoki Bostońskiej. W tak bajecznym miejscu znajduje się szpital dla obłąkanych przestępców. Na wyspie będzie prowadzone śledztwo w sprawie tajemniczego zniknięcia jednej z pacjentek. Sprawa jest prowadzona przez federalnych szeryfów Tedda i Chucka. Kobieta zniknęła z pokoju, który był zamknięty, a w oknach były kraty. Pozostała po niej tylko zaszyfrowana wiadomość. Nad wyspę nadciąga huragan i łączność z resztą świata zostaje zerwana.', 'https://image.tmdb.org/t/p/w500/scYivmvdv2DwCfbiblEcRG4P9Me.jpg', 11324, 'tt1130884', 2, 0),
(151, 'Zjawa', 'The Revenant', 'Western, Dramat, Przygodowy', 2015, 7.5, 'Alejandro G. Iñárritu', 157, 'English', 1, 135000000, 'Monarchy Enterprises S.a.r.l., Regency Enterprises, Appian Way', '', 15.99, 'Bohaterem filmu jest legendarny odkrywca i myśliwy Hugh Glass, który zaatakowany przez niedźwiedzia, zdradzony przez jednego z członków wyprawy, ledwo żywy zostaje porzucony przez towarzyszy i pozostawiony na pewną śmierć. Wbrew wszystkiemu udaje mu się przeżyć. Zmagając się z bezlitosnymi zimowymi warunkami, wytrwale i desperacko brnie przez dzikie tereny, gnany miłością do rodziny i nieokiełznaną żądzą zemsty. Ten uznany za arcydzieło sztuki filmowej epicki obraz, jak żaden wcześniej, ukazuje niezwykłą siłę ludzkiego ducha, trzymając w napięciu i wciągając widza bez reszty.', 'https://image.tmdb.org/t/p/w500/7koZ9mAQR37eyFfT2TO9MESjs9M.jpg', 281957, 'tt1663202', 2, 0),
(152, 'Nienawistna ósemka', 'The Hateful Eight', 'Dramat, Tajemnica, Western', 2015, 7.8, 'Quentin Tarantino', 167, 'English', 2, 44000000, 'The Weinstein Company, Double Feature Films, FilmColony', '', 7.99, 'Kilka lat po wojnie secesyjnej przez wietrzne pustkowia Wyoming podróżują łowca nagród John Ruth, znany jako "Szubienica", oraz zbiegła przestępczyni Daisy Domergue. Ruth ma zamiar doprowadzić kobietę przed oblicze sprawiedliwości. Podczas podróży spotykają innego okrytego złą sławą łowcę nagród majora Marquisa Warrena, niegdyś żołnierza walczącego po stronie Unii, oraz Chrisa Mannixa, renegata z Południa i samozwańczego szeryfa miasta Red Rock, do którego zmierzają. Podróżni zbaczają jednak ze szlaku podczas zamieci śnieżnej. Schronienie znajdują w zajeździe na górskiej przełęczy, gdzie zostają powitani przez czterech nieznajomych: Boba opiekującego się lokalem, kata z Red Rock Oswaldo Mobraya, kowboja Joego Gage''a i byłego konfederackiego generała Sanforda Smithersa.', 'https://image.tmdb.org/t/p/w500/sLmii6n2CLOQm1LATwZaXZYrNwx.jpg', 273248, 'tt3460252', 2, 0),
(153, 'Django', 'Django Unchained', 'Dramat, Western', 2012, 8.2, 'Quentin Tarantino', 165, 'English', 3, 100000000, 'The Weinstein Company, Columbia Pictures', '', 14.99, 'Rok 1858, południe Stanów Zjednoczonych. Niewolnik Django spotyka na swojej drodze doktora Kinga Schultza, pochodzącego z Niemiec łowcę nagród. Ten, obiecuje mu wolność i zapłatę w zamian za pomoc w odnalezieniu poszukiwanych przez prawo braci Brittle. Django zgadza się i wkrótce obaj wykonują robotę. Po wszystkim zawiązują spółkę. Schultz wprowadza Django w tajniki zawodu łowcy nagród. Ponadto, poruszony historią swojego nowego przyjaciela, postanawia pomóc mu w odszukaniu żony Broomhildy. Okazuje się, że znajduje się ona na niesławnej plantacji należącej do Calvina Candie, odrażającego dżentelmena pasjonującego się walkami niewolników.', 'https://image.tmdb.org/t/p/w500/6UjfRbaSdpNeaJvLIPTdhCO6yzJ.jpg', 68718, 'tt1853728', 2, 0),
(154, 'Bękarty wojny', 'Inglourious Basterds', 'Dramat, Thriller, Wojenny', 2009, 8.2, 'Quentin Tarantino', 153, 'English', 4, 70000000, 'Universal Pictures, The Weinstein Company, A Band Apart', '', 6.99, 'Akcja filmu rozpoczyna się w okupowanej Francji podczas egzekucji rodziny Shosanny Dreyfus, której dziewczyna jest świadkiem. Egzekucji dokonuje nazistowski pułkownik Hans Landa. Shosannie udaje się uciec i wyjechać do Paryża, gdzie, jako właścicielka kina, przyjmuje nową tożsamość. W innym miejscu w Europie, porucznik Aldo Raine organizuje grupę żydowskich żołnierzy, którzy mają dokonywać aktów zemsty. Do oddziału Raine''a dołącza niemiecka aktorka i agentka Bridget Von Hammersmark, której misją jest pozbawienie władzy przywódców Trzeciej Rzeszy. Losy tych ludzi zbiegają się pod kinowym afiszem, gdzie Shosanna przygotowuje własny plan zemsty...', 'https://image.tmdb.org/t/p/w500/xYoYYRo0vZNa0VJAOvXtfRPCi3S.jpg', 16869, 'tt0361748', 2, 0),
(155, 'Wściekłe psy', 'Reservoir Dogs', 'Kryminał, Thriller', 1992, 8.1, 'Quentin Tarantino', 99, 'English', 5, 1200000, 'Live Entertainment, Dog Eat Dog Productions', '', 13.99, 'Po nieudanym napadzie na sklep jubilerski czterech gangsterów spotyka się w opustoszałym podmiejskim magazynie. Biały (Harvey Keitel), Pomarańczowy (Tim Roth), Blondyn (Michael Madsen) i Różowy (Steve Buscemi) zdają sobie sprawę, że wśród nich jest zdrajca odpowiedzialny za wpadkę. Ich zleceniodawca, Joe Cabot (Lawrence Tierney), domaga się zdemaskowania policyjnego konfidenta, lecz wzajemne oskarżenia, wrogość i nieufność nie sprzyjają jego wykryciu. Narastająca atmosfera podejrzliwości będzie początkiem krwawej tragedii.', 'https://image.tmdb.org/t/p/w500/elQbITBVugEJhC2o8Vq2VzhqLcr.jpg', 500, 'tt0105236', 2, 0),
(156, 'Jackie Brown', 'Jackie Brown', 'Kryminał, Dramat, Thriller', 1997, 7.4, 'Quentin Tarantino', 154, 'English', 6, 12000000, 'Miramax, A Band Apart, Mighty Mighty Afrodite Productions', '', 5.99, 'Stewardessa mieszkająca w Kalifornii przewozi nielegalnie pieniądze z Meksyku do Los Angeles - i dostarcza je handlarzowi broni, który współpracuje z gangsterami. Dwaj agenci FBI wpadają na trop jej działalności, żądają posłuszeństwa i współpracy. Ona próbuje ich przechytrzyć.', 'https://image.tmdb.org/t/p/w500/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg', 184, 'tt0119396', 2, 0),
(157, 'Kill Bill', 'Kill Bill: Vol. 1', 'Akcja, Kryminał', 2003, 8.0, 'Quentin Tarantino', 111, 'English', 7, 30000000, 'Miramax, A Band Apart, Super Cool ManChu', '', 12.99, 'Panna Młoda (Uma Thurman), należąca niegdyś do płatnych zabójców, a która obecnie spodziewa się dziecka, zostaje zdradzona w dniu swojego ślubu przez swojego szefa (David Carradine). Cudem unika śmierci, mimo iż została postrzelona w głowę. Znajduje się jednak w śpiączce. Po czterech latach budzi się ze śpiączki i postanawia krwawo zemścić się na każdym, kto miał związek z zamachem na jej życie, pozostawiając sobie zemstę na tytułowym Billu na koniec.', 'https://image.tmdb.org/t/p/w500/v7TaX8kXMXs5yFFGR41guUDNcnB.jpg', 24, 'tt0266697', 2, 0),
(158, 'Kill Bill 2', 'Kill Bill: Vol. 2', 'Akcja, Kryminał, Thriller', 2004, 7.9, 'Quentin Tarantino', 136, 'English', 8, 30000000, 'Super Cool ManChu, Miramax, A Band Apart', '', 19.99, 'Dalszy ciąg losów zdradzonej i pozostawionej na pewną śmierć panny młodej (Uma Thurman). Niegdyś należąca do elity płatnych zabójców, budzi się po 4 latach ze śpiączki. Postanawia zemścić się na "Billu" (Carradine), człowieku, który ją wystawił. Droga do słodkiej zemsty nie będzie łatwa, bo po najpierw musi "zneutralizować" bezwzględnych wspólników Billa. Po 6 latach Quentin Tarantino powraca w wielkim stylu. Jak sam twierdzi "Kill Bill" to film, o którym marzył od dawna. Akcja filmu nawiązujące do najlepszych tradycji filmów samurajskich, Kung-fu i spaghetti westernów.', 'https://image.tmdb.org/t/p/w500/2yhg0mZQMhDyvUQ4rG1IZ4oIA8L.jpg', 393, 'tt0378194', 2, 0),
(159, 'Pewnego razu… w Hollywood', 'Once Upon a Time in... Hollywood', 'Komedia, Dramat, Thriller', 2019, 7.4, 'Quentin Tarantino', 162, 'English', 9, 95000000, 'Heyday Films, Columbia Pictures, Bona Film Group', '', 11.99, 'Pełna anegdot i elektryzujących dygresji historia aktora grającego w westernach, który próbuje wrócić na szczyt, oraz jego wiernego dublera. W tle czasy kontestacji, ruch hipisów, zmierzch epoki klasycznego Hollywoodu i złotej ery telewizji. Poza tym Steve McQueen, Bruce Lee, spaghetti westerny, a także piękna Sharon Tate i Roman Polański po wielkim sukcesie “Dziecka Rosemary”.', 'https://image.tmdb.org/t/p/w500/uqYoGbriYgNOKKAYSqnF3JndrMT.jpg', 466272, 'tt7131622', 2, 0),
(160, 'Sicario', 'Sicario', 'Akcja, Kryminał, Thriller', 2015, 7.4, 'Denis Villeneuve', 121, 'English', 10, 30000000, 'Lionsgate, Black Label Media, Thunder Road', '', 18.99, 'Młoda agentka FBI Kate Macer przyłącza się do supertajnej akcji CIA mającej na celu pojmanie szefa wielkiego meksykańskiego kartelu narkotykowego. Macer stopniowo poznaje szczegóły operacji, która często ociera się o granicę prawa i moralności, prowadząc do najgłębszych czeluści przestępczego piekła. Przewodnikiem po jego kolejnych kręgach będzie dla Macer tajemniczy współpracownik CIA o meksykańskim pochodzeniu, zwany "konsultantem", który jak się okaże ma dla całej akcji kluczowe znaczenie. Jego prawdziwa tożsamość będzie dla Macer największym szokiem.', 'https://image.tmdb.org/t/p/w500/fZtSgpJ6k1wWgJ6fBNlfxew70MK.jpg', 273481, 'tt3397884', 2, 0),
(161, 'Labirynt', 'Prisoners', 'Dramat, Thriller, Kryminał', 2013, 8.1, 'Denis Villeneuve', 153, 'English', 1, 46000000, 'Alcon Entertainment, 8:38 Productions, Madhouse Entertainment', '', 10.99, 'Jak daleko można się posunąć, by chronić swoją rodzinę? Keller Dover staje twarzą w twarz z najgorszym koszmarem, który może przytrafić się każdemu rodzicowi: jego sześcioletnia córka, Anna, zostaje porwana wraz ze swą koleżanką, Joy. Minuty mijają jak godziny, powstaje panika. Pierwszy trop prowadzi do samochodu, który zaparkowano na ulicy. Prowadzący śledztwo detektyw Loki aresztuje jego kierowcę, Alexa Jonesa, wkrótce musi go wypuścić z braku dowodów. Zdeterminowany Dover świadomy, że życie jego dziecka jest w niebezpieczeństwie bierze sprawy w swoje ręce. Do czego zdoła posunąć się zrozpaczony ojciec, by ochronić swoją rodzinę?', 'https://image.tmdb.org/t/p/w500/3XUDusNMvbubbKUx1qKh456MQd3.jpg', 146233, 'tt1392214', 2, 0),
(162, 'Wróg', 'Enemy', 'Thriller, Tajemnica', 2014, 6.8, 'Denis Villeneuve', 91, 'English', 2, 3500000, 'Rhombus Media, Roxbury Pictures, Mecanismo Films', '', 17.99, 'Adam Bell jest profesorem historii. Życie, jakie prowadzi, jest nudne i zaniedbane do tego stopnia, że nie poświęca zbyt wiele uwagi nawet swojej dziewczynie, Mary. Wszystko zmienia się, gdy pewnego razu ogląda film, który polecił mu znajomy. W trakcie seansu Adam dostrzega w jednej z ról własnego sobowtóra. Zaintrygowany tym, co zobaczył, postanawia odszukać mężczyznę z filmu. Nie wie jeszcze, że decyzja, którą właśnie podjął, nieodwracalnie odmieni całe jego życie.', 'https://image.tmdb.org/t/p/w500/xdU2ErL3gjqtJDj5kbn9OmRGV67.jpg', 181886, 'tt2316411', 2, 0),
(163, 'Pogorzelisko', 'Incendies', 'Dramat, Wojenny, Tajemnica', 2010, 8.1, 'Denis Villeneuve', 131, 'French', 3, 6800000, 'TS Productions, Phi Group, micro_scope', '', 9.99, 'Podczas odczytywania testamentu zmarłej matki, bliźnięta Jeanne i Simon dowiadują się, iż mają rodzeństwo i ojca, który nadal żyje, choć za życia ich matka twierdziła coś innego. Ostatnią wolą zmarłej było, aby rodzeństwo wybrało się na Bliski Wschód aby odnaleźć rodzinę i dostarczyć im zapieczętowane listy.', 'https://image.tmdb.org/t/p/w500/n8jJREVlHUw2J90I4P3mgAEG3Yk.jpg', 46738, 'tt1255953', 2, 0),
(164, 'Pianista', 'The Pianist', 'Dramat, Wojenny', 2002, 8.4, 'Roman Polański', 150, 'English', 4, 35000000, 'R.P. Productions, Heritage Films, Studio Babelsberg', '', 16.99, 'Władysław Szpilman wraz z rodziną mieszka w Warszawie. Jest młodym, zdolnym pianistą, żydowskiego pochodzenia. Gdy do miasta wkraczają Niemcy, i wkrótce potem zakładają getta, młody Władek zarabia jako pianista w kawiarniach. Z biegiem czasu Niemcy rozpoczynają wywóz Żydów, a Szpilmanowi w ostatniej chwili udaje się uniknąć losu rodziny, którą zagnano do wagonu pociągu. Wkrótce potem Władysław ucieka z getta i dzięki polskim przyjaciołom znajduje ukrycie przed okupantami. Niestety nie zaznaje spokoju na długo. Zaraz po wybuchu Powstania Warszawskiego Szpilman musi uciekać.', 'https://image.tmdb.org/t/p/w500/zBAT1blHB2zkzWvHMQmV65qBfXM.jpg', 423, 'tt0253474', 2, 0),
(165, 'Życie na podsłuchu', 'Das Leben der Anderen', 'Dramat, Thriller', 2006, 8.0, 'Florian Henckel von Donnersmarck', 137, 'German', 5, 2000000, 'Creado Film, Wiedemann & Berg Film, ARTE', '', 8.99, 'Film porusza wciąż gorący temat służb specjalnych. Opisuje przerażającą, paranoiczną i czasami śmieszną historię systemu kontroli obywateli we wschodnich Niemczech. Historia oparta na faktach. Wczesne lata 80-te. Znany dramaturg Georg Dreyman wraz ze swoją partnerką Christą, popularną aktorką tworzą parę intelektualistów- gwiazd w socjalistycznym państwie. Ich poglądy i styl życia nie zawsze zgadzają się z doktryną partii dlatego są pod ścisłą obserwacją Agenta Stasi, którego zaczyna wciągać i fascynować ich życie...', 'https://image.tmdb.org/t/p/w500/2iwbtS6EojKx2Vpugqhuat3KS2J.jpg', 582, 'tt0405094', 2, 0),
(166, 'Upadek', 'Der Untergang', 'Dramat, Historyczny, Wojenny', 2004, 7.9, 'Oliver Hirschbiegel', 156, 'German', 6, 16000000, 'NDR, ORF, ARD Degeto', '', 15.99, 'Berlin, kwiecień 1945 roku. Na ulicach panuje chaos nie do opisania. Naród niemiecki czeka na swą nieuchronną klęskę. Adolf Hitler wraz ze swoimi najbliższymi współpracownikami ukrywa się w bunkrze w podziemiach Kancelarii Rzeszy. Wśród "świty" wodza znajduje się Traudl Junge, ostatnia sekretarka Hitlera. To jej wspomnienia posłużyły do przedstawienia ostatnich, spędzonych w izolacji, dwunastu dni życia wodza upadającej III Rzeszy. Te dramatyczne dni wzbudzają tak wiele kontrowersji i domysłów jak żaden inny etap biografii Hitlera. Co naprawdę wydarzyło się 10 metrów pod ulicami Berlina?', 'https://image.tmdb.org/t/p/w500/1NhSLg6j1wx2zfeVozmijNEuelX.jpg', 613, 'tt0363163', 2, 0),
(167, 'Głową w mur', 'Gegen die Wand', 'Dramat, Romans', 2004, 7.5, 'Fatih Akin', 122, 'German', 7, NULL, 'Corazón International, Wüste Film, ARTE', '', 7.99, '"Nie musisz umierać, żeby twoje życie się skończyło" - czterdziestoletni Cahit (Birol Ünel), który po nieudanej próbie samobójczej ląduje w szpitalu psychiatrycznym, słyszy te słowa z ust swojego lekarza. Doskonale rozumie, co to znaczy: musi zacząć żyć na nowo. Jednak jego dusza wciąż cierpi, zagłusza więc ból alkoholem i narkotykami. Sibel (Sibel Kekilli), młoda i atrakcyjna Niemka, która podobnie jak Cahit ma tureckie korzenie, kocha życie stanowczo zbyt mocno jak na pobożną Muzułmankę. Chcąc wyzwolić się spod władzy konserwatywnej rodziny, Sibel pozoruje próbę samobójczą. Zamiast spodziewanego wyzwolenia przynosi jej to jednak hańbę. Tylko małżeństwo może ją ocalić. Sibel błaga więc Cahita, aby się z nią ożenił. Ten niechętnie się zgadza. Być może chce jej pomóc, a może po prostu pragnie uczynić w życiu coś istotnego.', 'https://image.tmdb.org/t/p/w500/qasMf5ZXmEbGkBNBeqRhal5C6x9.jpg', 363, 'tt0347048', 2, 0),
(168, 'Amores perros', 'Amores perros', 'Dramat, Thriller', 2000, 7.7, 'Alejandro G. Iñárritu', 154, 'Spanish', 8, 2000000, 'Altavista Films, Zeta Film', '', 14.99, 'Uniwersalna opowieść o życiu, samotności i poszukiwaniu miłości przez mieszkańców Mexico City. Film składa się z trzech pozornie niezwiązanych ze sobą historii. Młody chłopak, Octavio, liczy na to, że wystawiając psa do walki, zdobędzie pieniądze na ucieczkę z żoną brata. Daniel jest odnoszącym sukcesy wydawcą, który porzuca żonę i dzieci dla modelki. El Chivo, buntownik z elitarnego domu, który stoczył się na dno i został płatnym zabójcą, poluje na bogatego biznesmena. Losy całej trójki krzyżują się podczas tragicznego wypadku samochodowego.', 'https://image.tmdb.org/t/p/w500/2p1vhX2c4XESRooVERcQ1kCLg5j.jpg', 55, 'tt0245712', 2, 0),
(169, 'Miasto Boga', 'Cidade de Deus', 'Dramat, Kryminał', 2002, 8.4, 'Fernando Meirelles', 130, 'Portuguese', 9, 3300000, 'O2 Filmes, VideoFilmes, Wild Bunch', '', 6.99, 'Rakietę ma 10 lat. Jego brat, noszący ksywkę Kaczor, należy do bandy o osobliwej nazwie Trio Czułość. Przez jakiś czas trio rządzi osiedlem, budząc podziw młodszych dzieciaków. O dorównaniu im marzy zwłaszcza Kostka, najbliższy przyjaciel Bene. Podsuwa on bandzie pomysł napadu na dom schadzek. W czasie akcji Kostka zabija wszystkich okradzionych wcześniej klientów domu. Następnie zabija Kaczora - dotychczasowego przywódcę i przejmuje władzę w Mieście Boga. Przybiera imię Mały Ze.', 'https://image.tmdb.org/t/p/w500/19HfNrUgf0Qe7NG7NZOEFEE8z9q.jpg', 598, 'tt0317248', 2, 0),
(170, 'Dworzec nadziei', 'Central do Brasil', 'Dramat', 1998, 8.1, 'Walter Salles', 110, 'Portuguese', 10, 2900000, 'MACT Productions, VideoFilmes, RioFilme', '', 13.99, 'Film psychologiczno-obyczajowy. Rio de Janeiro, czasy współczesne: 50-letnia kobieta przed dworcem kolejowym pisuje odpłatnie listy dla analfabetów. Pewnego dnia jej klientka, matka 9-latka, która prosi o napisanie listu do dawno niewidzianego męża, ginie w wypadku drogowym. Wzruszającą opowieść o przyjaźni emerytowanej nauczycielki z małym osieroconym chłopcem, która na zawsze odmieniła ich życie.', 'https://image.tmdb.org/t/p/w500/qfyWFhUhqeNRU9HmCaBDAxVKRZ9.jpg', 666, 'tt0140888', 2, 0),
(171, 'Sekret jej oczu', 'El secreto de sus ojos', 'Tajemnica, Thriller, Dramat', 2009, 8.0, 'Juan José Campanella', 127, 'Spanish', 1, 2000000, 'Canal+ España, 100 Bares, Tornasol Media', '', 5.99, 'Benjamin Esposito, były argentyński agent federalny, znajduje się u kresu swojej kariery. Mimo, że do emerytury pozostało niewiele czasu, ma świadomość, że nie rysuje się ona w ciepłych kolorach. Benjamin jest bowiem udręczony okropną sprawą z dawnych czasów - gwałtu i morderstwa na młodej kobiecie. Prawdziwe oblicze wydarzeń z przeszłości nigdy nie ujrzało światła dziennego, dlatego by uporać się z tym zaczyna pisać. Odgrzebywanie wspomnień i kopanie w pamięci doprowadza jednak do odkrycia zaskakujących faktów.', 'https://image.tmdb.org/t/p/w500/jpfTVo1ax5OKBh09DuMraqBuMBs.jpg', 25376, 'tt1305806', 2, 0),
(172, 'Nietykalni', 'Intouchables', 'Dramat, Komedia', 2011, 8.3, 'Éric Toledano', 112, 'French', 2, 13000000, 'Gaumont, Quad Productions, Chaocorp', '', 12.99, 'Ta historia zdarzyła się naprawdę. Sparaliżowany na skutek wypadku milioner zatrudnia do pomocy i opieki młodego chłopaka z przedmieścia, który właśnie wyszedł z więzienia. Zderzenie dwóch skrajnie różnych światów daje początek szeregowi niewiarygodnych przygód i przyjaźni, która czyni ich... nietykalnymi.', 'https://image.tmdb.org/t/p/w500/vthovD3LEV0OF1Re0rRumHHgiCA.jpg', 77338, 'tt1675434', 2, 0),
(173, 'Front of the Class', 'Front of the Class', 'Dramat', 2008, 8.1, 'Peter Werner', 95, 'English', 3, NULL, 'Hallmark Hall of Fame Productions, McGee Street Productions', '', 19.99, '', 'https://image.tmdb.org/t/p/w500/w7UolFxzPi7ZA7LkglRotQ84g1g.jpg', 63193, 'tt1292594', 2, 0),
(174, 'Rozstanie', 'جدایی نادر از سیمین', 'Dramat', 2011, 7.9, 'Asghar Farhadi', 123, 'fa', 4, 5000000, 'Asghar Farhadi Productions, Memento Production', '', 11.99, '"Rozstanie"  to okrzyknięte przez światową krytykę arcydziełem współczesnego kina i nagrodzone na festiwalu w Berlinie Złotym Niedźwiedziem za najlepszy film, a także nagrodami aktorskimi.  "Rozstanie", w reżyserii twórcy głośnego "Co wiesz o Elly", to opowieść o dwóch rodzinach, których losy w dramatyczny sposób splatają się ze sobą na skutek przypadkowego zbiegu okoliczności. Film w doskonały sposób łączy elementy thrillera i dramatu psychologicznego, trzymając w napięciu do nieoczekiwanego finału.', 'https://image.tmdb.org/t/p/w500/6dmtFT4jTajp8X9XFxxUyaYEVLx.jpg', 60243, 'tt1832382', 2, 0),
(175, 'Klient', 'فروشنده', 'Dramat, Thriller', 2016, 7.2, 'Asghar Farhadi', 125, 'fa', 5, NULL, 'Memento Production, ARTE France Cinéma, Asghar Farhadi Productions', '', 18.99, 'Młode małżeństwo musi nieoczekiwanie opuścić swoje mieszkanie. Wprowadzają się do użyczonego przez znajomego lokalu w centrum Teheranu, nie zdając sobie sprawy, kto był jego poprzednim najemcą. Gdy w nowym mieszkaniu nieznany sprawca napada na kobietę, jej mąż rozpoczyna prywatne śledztwo. Mężczyzna usiłuje za wszelką cenę, bez pomocy policji, dotrzeć do agresora, by poznać motywy jego działania. Seria nieoczekiwanych wydarzeń w dramatyczny sposób zmieni życie małżonków.', 'https://image.tmdb.org/t/p/w500/7K40OyfFyS4tsGkXzAES8yLYa6t.jpg', 375315, 'tt5186714', 2, 0),
(176, 'Smak wiśni', 'طعم گيلاس', 'Dramat', 1997, 7.7, 'عباس کیارستمی', 99, 'fa', 6, 120000, 'Kanoon, Kiarostami Foundation, CiBy 2000', '', 10.99, 'Mężczyzna jeździ samochodem po obrzeżach Teheranu, usiłując znaleźć kogoś, kto za odpowiednią opłatą pomoże mu w samobójstwie.', 'https://image.tmdb.org/t/p/w500/wWMIQoILPumz3AFMJRgDI1mEbLx.jpg', 30020, 'tt0120265', 2, 0),
(177, 'Extreme Close-Up', 'Extreme Close-Up', 'Dramat, film TV', 1990, 10.0, 'Peter Horton', 93, 'English', 7, NULL, 'MGM Television, Robert Greenwald Productions, Bedford Falls Productions', '', 17.99, '', 'https://image.tmdb.org/t/p/w500/tdqv4NB9ETduFppiqfCQJ385q4O.jpg', 769421, 'tt0099531', 2, 0),
(178, 'Dzieci niebios', 'بچه‌های آسمان', 'Dramat, Familijny', 1997, 7.9, 'مجید مجیدی', 88, 'fa', 8, 180000, 'Kanoon, Miramax', '', 9.99, 'Chłopiec gubi jedyne buty swojej młodszej siostry. Wiedząc, że w domu brakuje pieniędzy, postanawia samodzielnie zdobyć dla niej nową parę.', 'https://image.tmdb.org/t/p/w500/lMXGRG5vlXOzNv3QRA3CTy5DT5q.jpg', 21334, 'tt0118849', 2, 0),
(179, 'Timbuktu', 'Timbuktu', 'Dramat, Wojenny', 2014, 7.0, 'Abderrahmane Sissako', 96, 'French', 9, NULL, 'Les films du Worso, Orange Studio, Arches Films', '', 16.99, 'Akcja "Timbuktu" dzieje się w tytułowym mieście w Mali, nad rzeką Niger, w którym władze przejęli dżihadyści i narzucają mieszkańcom islamistyczny reżim. Nie wolno palić papierosów, tańczyć, śpiewać, ani słuchać muzyki. Zakazana jest nawet piłka nożna. Najbardziej poszkodowane są jednak kobiety, które zostają niemal całkowicie wyłączone z życia społecznego i narzuca się im przestrzeganie absurdalnych nakazów.', 'https://image.tmdb.org/t/p/w500/pG5SYVCdN22Cc10nKhW4XFugtpj.jpg', 265228, 'tt3409392', 2, 0),
(180, 'Boyhood', 'Boyhood', 'Dramat', 2014, 7.5, 'Richard Linklater', 164, 'English', 10, 4000000, 'IFC Productions, Detour Filmproduction', '', 8.99, 'Realizowany w krótkich odstępach czasu między 2002 a 2013 rokiem, "Boyhood" to przełomowe wydarzenie filmowe opowiadające o 12 latach z życia pewnej rodziny. W centrum wydarzeń znajduje się Mason, który wspólnie z siostrą Samanthą zostaje zabrany w emocjonalną, transcendentną podróż przez lata dzieciństwa aż do dorosłości.', 'https://image.tmdb.org/t/p/w500/2BvtvDUyxiMJ4dmKfiQf4qdOHQN.jpg', 85350, 'tt1065073', 2, 0),
(181, 'Przed wschodem słońca', 'Before Sunrise', 'Dramat, Romans', 1995, 8.0, 'Richard Linklater', 105, 'English', 1, 2500000, 'Castle Rock Entertainment, Detour Filmproduction, Filmhaus Films', '', 15.99, 'Francuska studentka Celine i Amerykanin Jesse poznają się w pociągu do Wiednia. Rozmowa jest tak interesująca, że postanawiają wysiąść w Wiedniu i kontynuować dyskusję. Błahe rozmowy przeradzają się w poważne tematy, a wzajemne zauroczenie w uczucie.', 'https://image.tmdb.org/t/p/w500/2900By8xztHCBeQZPaZhwRtNQJD.jpg', 76, 'tt0112471', 2, 0),
(182, 'Przed zachodem słońca', 'Before Sunset', 'Dramat, Romans', 2004, 7.8, 'Richard Linklater', 80, 'English', 2, 2700000, 'Warner Independent Pictures, Castle Rock Entertainment, Detour Filmproduction', '', 7.99, 'Jesse (Ethan Hawke) i Celine (Julie Delpy) spotkają się w pociągu i spędzają ze sobą 14-godzin w Wiedniu, gdzie rozmawiają o życiu, wartościach, rzeczach błahych i tych ważnych. Ich krótka, lecz burzliwa znajomość kończy się na peronie kolejowym, gdzie oboje przysięgają sobie, że spotkają się ponownie za sześć miesięcy. Do spotkania jednak nie dochodzi... Teraz, dziewięć lat później, niespodziewanie ich drogi ponownie się przecinają w Paryżu, gdzie Jesse promuje swoją najnowszą książkę. Na jednym ze spotkań dla czytelników pojawia się Celine... Oboje mają kilka godzin, by uporać się ze swoimi uczuciami, przeszłością i odpowiedzieć na trudne pytanie: Czy znaczą wciąż dla siebie tyle, co dziewięć lat temu?', 'https://image.tmdb.org/t/p/w500/7Hku2RhuVYKOsa8PajDTA1tJd4O.jpg', 80, 'tt0381681', 2, 0),
(183, 'Przed północą', 'Before Midnight', 'Romans, Dramat', 2013, 7.5, 'Richard Linklater', 108, 'English', 3, 3000000, 'Castle Rock Entertainment, Detour Filmproduction, Faliro House Productions', '', 14.99, 'Po raz pierwszy spotkali się prawie dwadzieścia lat temu przed wschodem słońca w pociągu do Wiednia. Spędzili ze sobą noc, by rozstać się i znów na siebie trafić po dziewięciu latach przed zachodem słońca w Paryżu. Od tamtego lata minęło kolejnych dziewięć lat. Gdzie są teraz? Czy uczucie, które ich połączyło przetrwało do dziś? Reżyser filmu "Przed wschodem słońca" i "Przed zachodem słońca" przedstawia ostatnią część trylogii okrzykniętej przez krytyków największym romansem współczesnego kina, w którym swoje życiowe role zagrali Julie Delpy i Ethan Hawke.', 'https://image.tmdb.org/t/p/w500/rrNJPxcykhxKIDwQVkhFeyRUZFR.jpg', 132344, 'tt2209418', 2, 0),
(184, 'Buntownik z wyboru', 'Good Will Hunting', 'Dramat', 1997, 8.2, 'Gus Van Sant', 126, 'English', 4, 10000000, 'Lawrence Bender Productions, Be Gentlemen Limited Partnership, Miramax', '', 6.99, 'Will Hunting to "skłócony z życiem" młody chłopak. Nie ma większych ambicji, niewiele oczekuje od losu. Pracuje dorywczo, a wieczorami włóczy się po okolicznych barach... do czasu! Zwrot w jego życiu następuje, gdy nieoczekiwanie odkryte zostają jego niezwykłe zdolności matematyczne. Will musi zdecydować, czy podjąć rzucone mu przez los wezwanie i spróbować zmienić swój stosunek do świata, czy też, dalej wieść nic nie znaczącą, lecz wygodną egzystencję na pograniczu prawa. W zmaganiach z samym sobą pomaga mu piękna studentka i psycholog, który słynie z niekonwencjonalnych metod działania. Dochodzi do starcia dwóch silnych osobowości, które przynosi zaskakujący efekt...', 'https://image.tmdb.org/t/p/w500/8SYT3PE0vT3IvEDY9xuQ9c4P5EW.jpg', 489, 'tt0119217', 2, 0),
(185, 'Łowca jeleni', 'The Deer Hunter', 'Dramat, Wojenny', 1978, 8.0, 'Michael Cimino', 183, 'English', 5, 15000000, 'Universal Pictures, EMI Films', '', 13.99, 'Michael, Steven i Nick to młodzi pracownicy fabryki w Pensylwanii. Wszyscy dostają powołanie do wojska na wojnę w Wietnamie. Jeszcze przed wyjazdem Steven poślubia ciężarną Angelę, a ich przyjęcie ślubne jest zarazem przyjęciem pożegnalnym. Po pewnym czasie spędzonym w Wietnamie przyjaciele wpadają w pułapkę Vietcongu i trafiają do obozu jenieckiego, gdzie zostają zmuszeni do gry w rosyjską ruletkę między sobą.', 'https://image.tmdb.org/t/p/w500/35ebwxRGHRcTKyC39pXufBsD4te.jpg', 11778, 'tt0077416', 2, 0),
(186, 'Czas Apokalipsy', 'Apocalypse Now', 'Dramat, Wojenny', 1979, 8.3, 'Francis Ford Coppola', 153, 'English', 6, 31500000, 'American Zoetrope', '', 5.99, 'Scenariusz oparty jest na opowiadaniu Josepha Conrada "Jądro ciemności" i relacjonuje historię wyprawy kapitana Benjamina Willarda. Bohaterowi polecono zlikwidowanie szalonego pułkownika Kurtza, który na własną rękę rozpoczął morderczą wojnę na pograniczu wietnamsko-kambodżańskim. Po odnalezieniu pułkownika Willard ma według własnego uznania go zabić bądź wezwać bombowce, które zniszczą obóz. Wraz z grupką żołnierzy kapitan rusza łodzią patrolową w górę Mekongu.', 'https://image.tmdb.org/t/p/w500/1L2mrAKFHPvj2w4Y8Wcfe06Mglx.jpg', 28, 'tt0078788', 2, 0),
(187, 'Pełny magazynek', 'Full Metal Jacket', 'Dramat, Wojenny', 1987, 8.1, 'Stanley Kubrick', 116, 'English', 7, 30000000, 'Natant, Stanley Kubrick Productions, Warner Bros. Pictures', '', 12.99, 'Epicka opowieść o oddziale marines wysłanym do Wietnamu. Wpierw poznajemy przyszłych żołnierzy jak odbywają szkolenie w specjalnym obozie. W drugiej części filmu akcja przenosi się do Wietnamu. Głównym bohaterem jest Joker, młody rekrut który pracuje jako korespondent wojenny i na własne oczy przekonuje się, czym naprawdę jest walka.', 'https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg', 600, 'tt0093058', 2, 0),
(188, 'Pluton', 'Platoon', 'Dramat, Wojenny, Akcja', 1986, 7.7, 'Oliver Stone', 120, 'English', 8, 6000000, 'Hemdale Film Corporation, Arnold Kopelson Productions', '', 19.99, 'Przybyły do Wietnamu Chris Taylor (Charlie Sheen) szybko odkrywa, że najtrudniejszą walką, którą musi stoczyć jest walka z samym sobą - z własnymi słabościami, strachem, gniewem i wycieńczeniem. Pluton to opowieść o ludziach za młodych by umierać, zbyt niedojrzałych , by ustrzec się przed spustoszeniami jakie w ich duszach dokonuje brutalna wojna. W wilgotnej, parnej dżungli szybko wyrasta się ze złudzeń.', 'https://image.tmdb.org/t/p/w500/9Ywd6XOeqpN8w5MYWwOMtF8QJzq.jpg', 792, 'tt0091763', 2, 0),
(189, 'Cienka czerwona linia', 'The Thin Red Line', 'Dramat, Historyczny, Wojenny', 1998, 7.4, 'Terrence Malick', 170, 'English', 9, 52000000, 'Fox 2000 Pictures, Phoenix Pictures, George Stevens Jr. Productions', '', 11.99, 'Zrealizowana z ogromnym rozmachem, niezwykle widowiskowa adaptacja słynnej powieści Jamesa Jonesa relacjonująca losy oddziału amerykańskich żołnierzy walczących w bitwie o Guadalcanal. Gdy żądza zwycięstwa słabnie, przeradzając się w walkę o przetrwanie i opanowanie militarnego i moralnego chaosu, wszystkich żołnierzy - od wysokich rangą oficerów aż po zwykłych szeregowców - zaczynają łączyć niezwykle silne więzi emocjonalne, które niejednokrotnie decydują o ich życiu i śmierci.', 'https://image.tmdb.org/t/p/w500/seMydAaoxQP6F0xbE1jOcTmn5Jr.jpg', 8741, 'tt0120863', 2, 0),
(190, 'Helikopter w ogniu', 'Black Hawk Down', 'Akcja, Wojenny, Historyczny', 2001, 7.4, 'Ridley Scott', 144, 'English', 10, 92000000, 'Jerry Bruckheimer Films, Revolution Studios, Scott Free Productions', '', 18.99, 'W 1993 r. do Somalii wysłano elitarne oddziały amerykańskich żołnierzy. Powierzono im kluczową misją pojmania miejscowego dygnitarza wojskowego, pod którego rządami zmarły z głodu setki tysięcy Somalijczyków. Operacja nie powiodła się i Amerykanie zmuszeni byli walczyć o życie stawiając czoła przeważającym siłom wroga.', 'https://image.tmdb.org/t/p/w500/zlBd7flRDRSS7nBl6pV4OfV4BFa.jpg', 855, 'tt0265086', 2, 0),
(191, 'Wróg numer jeden', 'Zero Dark Thirty', 'Thriller, Dramat', 2012, 7.0, 'Kathryn Bigelow', 157, 'English', 1, 40000000, 'Annapurna Pictures, First Light, Mark Boal Productions', '', 10.99, 'Polowanie na najsłynniejszego terrorystę w historii ukazane z punktu widzenia młodej agentki CIA. Pomimo braku wiary kolegów, biurokracji oraz wielu przeciwności losu, agentce udaje się w końcu przekonać Pentagon, by wkroczyć do akcji i zaatakować domniemaną kryjówkę Osamy Bin Ladena.', 'https://image.tmdb.org/t/p/w500/iSbzmT1DNQgRakAFA6yKC6NucCf.jpg', 97630, 'tt1790885', 2, 0),
(192, 'The Hurt Locker: W Pułapce Wojny', 'The Hurt Locker', 'Dramat, Thriller, Wojenny', 2008, 7.2, 'Kathryn Bigelow', 131, 'English', 2, 15000000, 'First Light, Kingsgate Films, Voltage Pictures', '', 17.99, 'Irak. Żołnierze elitarnej jednostki zmuszeni są do wzięcia udziału w niebezpiecznej grze w kotka i myszkę. Łączą swoje siły, gdyż miasto w którym się znajdują pogrąża się w coraz większym chaosie i staje się coraz bardziej niebezpieczne. Każdy może być tutaj potencjalnym wrogiem, a każda napotkana rzecz śmiertelną bombą.', 'https://image.tmdb.org/t/p/w500/dQiS6lSUzhzEVkoGIgMfOOufcO3.jpg', 12162, 'tt0887912', 2, 0),
(193, 'Snajper', 'American Sniper', 'Wojenny, Akcja', 2014, 7.4, 'Clint Eastwood', 134, 'English', 3, 58800000, 'Warner Bros. Pictures, Village Roadshow Pictures, RatPac Entertainment', '', 9.99, 'Jako wysłany do Iraku członek elitarnej jednostki Navy SEALs Chris Kyle ma tylko jedną misję - chronić swoich towarzyszy broni. Swoją precyzją ratuje niezliczoną ilość żołnierzy na polu bitwy. W miarę jak opowieści o jego czynach rozpowszechniają się, zyskuje sobie miano "legendy". Reputacja Kyle''a rośnie także za liniami wroga. Powstańcy uznają snajpera za ważny cel i wyznaczają nagrodę za jego głowę. Największym wyzwaniem w życiu Chrisa jest jednak pozostanie mężem i ojcem dla rodziny, od której dzieli go pół świata. Pomimo niebezpieczeństw i rozłąki z bliskimi, Chris odbywa cztery zmiany w Iraku. Jednak po powrocie do żony Tayi i dzieci zdaje sobie sprawę, że nie pozostawił wojny za sobą.  [opis dystrybutora Blu-ray]', 'https://image.tmdb.org/t/p/w500/8PC0mcflrlIaIO8aYlDUkbmFC9G.jpg', 190859, 'tt2179136', 2, 0),
(194, 'Wszyscy ludzie prezydenta', 'All the President''s Men', 'Dramat, Tajemnica, Thriller', 1976, 7.7, 'Alan J. Pakula', 138, 'English', 4, 8500000, 'Wildwood Enterprises', '', 16.99, 'W 1972 r. pięciu ludzi zostaje aresztowanych za włamanie do głównej siedziby demokratów w Waszyngtonie, znajdującej się w budynku Watergate. Okazuje się, że osoby te były powiązane z krajowym komitetem działającym na rzecz ponownego wyboru Nixona na prezydenta. Bob Woodward, reporter Washington Post, zbiera materiały dotyczące włamania, nie wiedząc, że znajdzie w tej sprawie coś interesującego. Wkrótce dziennikarz Carl Bernstein nawiązuje współpracę z Bobem. Mężczyzna o pseudonimie Deep Throat podpowiada Bobowi, czym warto się zainteresować.', 'https://image.tmdb.org/t/p/w500/AvFeMgHphisca4tnwZip7hhzNN2.jpg', 891, 'tt0074119', 2, 0),
(195, 'Spotlight', 'Spotlight', 'Dramat, Historyczny', 2015, 7.8, 'Tom McCarthy', 128, 'English', 5, 20000000, 'Participant, Anonymous Content, Rocklin / Faust', '', 8.99, '"Spotlight" to filmowy zapis wstrząsającej historii, która miała miejsce naprawdę. Nagrodzeni Pulitzerem dziennikarze śledczy gazety "Boston Globe" dotarli do przerażających i szokujących danych na temat konsekwentnie tuszowanej siatki pedofilskiej w Kościele katolickim, składającej się z ponad 70 księży. Historia zbulwersowała świat w 2002 roku. Ale odkrycia dziennikarzy były zaledwie wierzchołkiem góry lodowej...  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/qAjgyyTLZIzzEF5p0D3NMaO1SW0.jpg', 314365, 'tt1895587', 2, 0),
(196, 'Czwarta władza', 'The Post', 'Dramat, Historyczny', 2017, 7.0, 'Steven Spielberg', 116, 'English', 6, 50000000, '20th Century Fox, DreamWorks Pictures, Reliance Entertainment', '', 15.99, 'Dwoje wydawców dziennika „The Washington Post” Katherine Graham (Meryl Streep) i Ben Bradlee (Tom Hanks) staje na czele bezprecedensowego starcia amerykańskiej prasy z najwyższymi władzami, walcząc o prawo do ujawnienia szokujących tajemnic, przez cztery dekady ukrywanych przez najwyższe władze USA.', 'https://image.tmdb.org/t/p/w500/uEpU98NPVTkJmxXB6tbapOj6TxP.jpg', 446354, 'tt6294822', 2, 0),
(197, 'Big Short', 'The Big Short', 'Komedia, Dramat', 2015, 7.4, 'Adam McKay', 130, 'English', 7, 28000000, 'Paramount Pictures, Regency Enterprises, Plan B Entertainment', '', 7.99, 'Historia oparta na prawdziwych wydarzeniach, które stały się zarzewiem ogólnoświatowego kryzysu 2007-2010. Zadziwiające, jak zaledwie kilku mężczyzn - poprzez spekulacje, malwersacje, balansowanie na granicy prawa - doprowadziło do gigantycznej zapaści gospodarczo-ekonomicznej właściwie w każdym zakątku globu. Sensacyjne kulisy wydarzeń, które wpłynęły na każdego z nas.', 'https://image.tmdb.org/t/p/w500/wYsq819EOCMoOFVojW3YWW9XK4y.jpg', 318846, 'tt1596363', 2, 0),
(198, 'Steve Jobs', 'Steve Jobs', 'Dramat, Historyczny', 2015, 6.8, 'Danny Boyle', 122, 'English', 8, 30000000, 'Scott Rudin Productions, The Mark Gordon Company, Cloud Eight Films', '', 14.99, 'Życie Steve’a Jobsa to właściwie gotowy scenariusz filmowy. Walka o przetrwanie, wyścig z czasem, genialny umysł i pomysły, które zrewolucjonizowały rzeczywistość XX i XXI wieku. Za reżyserię filmu odpowiedzialny jest Danny Boyle, laureat Oscara za film „Slumdog. Milioner z ulicy”. Scenariuszem zajął się Aaron Sorkin, zdobywca Nagrody Akademii za „The Social Network”. Film zabierze nas w miejsca, w których tworzyły się podwaliny dzisiejszej elektroniki i technologii nowej generacji. Zobaczymy walkę z czasem, który Jobs musiał wyprzedzić, abyśmy dziś korzystali z rozwiniętej technologii komputerowej. Twórcy filmu zapowiadają, że poznamy również intymny portret geniusza, ojca rewolucji technologicznej.', 'https://image.tmdb.org/t/p/w500/iIbalCUOryjpF85VM0n2aaxMQSU.jpg', 321697, 'tt2080374', 2, 0),
(199, 'McImperium', 'The Founder', 'Dramat, Historyczny', 2016, 7.2, 'John Lee Hancock', 120, 'English', 9, 15000000, 'Speedie Distribution, FilmNation Entertainment, Faliro House Productions', '', 6.99, 'Ray Kroc to charyzmatyczny biznesman, który od lat walczy o swoje pięć minut sławy. Jednak każdy jego pomysł przeradza się w klęskę, a szanse na realizację marzeń maleją z dnia na dzień. Niespodziewanie otrzymuje zamówienie od nieznanej mu restauracji w Kalifornii. Poznaje braci McDonaldów, którzy wymyślili nowatorski system serwowania jedzenia w 30 sekund od złożenia zamówienia. Ray, zachwycony rewolucyjnym pomysłem, namawia braci do stworzenia sieci restauracji w całych Stanach Zjednoczonych. W miarę rozrastania się fastfoodowego imperium, Ray chce mieć coraz więcej władzy. Jak wiele poświęci, aby zbudować najbardziej rozpoznawalną markę na świecie i stać się jedną z największych osobowości XX wieku?', 'https://image.tmdb.org/t/p/w500/hj0Jwo5DQPOVtxiHVvO6zqHclu8.jpg', 310307, 'tt4276820', 2, 0),
(200, 'Moneyball', 'Moneyball', 'Dramat', 2011, 7.3, 'Bennett Miller', 133, 'English', 10, 50000000, 'Scott Rudin Productions, Michael De Luca Productions, Rachael Horovitz Productions', '', 13.99, 'Manager Oakland Athletics Billy Beane (Brad Pitt) rzuca wyzwanie systemowi i konwencjonalnej wiedzy. Chcąc postawić na nogi swoją mało licząca się drużynę baseballową, mimo kłopotów finansowych i sprzeciwu starej gwardii, mediów, fanów, a nawet managera boiska (Philip Seymour Hoffman), Beane – z pomocą młodego ekonomisty, absolwenta Yale (Jonah Hill) – dzięki analizom komputerowym opracowuje program i zaczyna odnosić sukcesy… a przy okazji na zawsze zmienia sposób rozgrywania meczu.', 'https://image.tmdb.org/t/p/w500/tJV1LGWpHIfAmxrTEaIe8GeuyOm.jpg', 60308, 'tt1210166', 2, 0),
(201, 'Chciwość', 'Margin Call', 'Thriller, Dramat', 2011, 6.9, 'J.C. Chandor', 105, 'English', 1, 3500000, 'Before the Door Pictures, Washington Square Films, Untitled Entertainment', '', 5.99, 'Pierwsze 24 godziny finansowego kryzysu na Wall Street. Kulisy wydarzeń, które zmieniły cały świat. Analityk pracujący dla potężnej firmy inwestycyjnej, mającej swoją siedzibę na słynnym Wall Street, odkrywa niepokojące dane. Uzyskane przez niego informacje wskazują na nieprawidłowości finansowe, które mogą doprowadzić do bankructwa całego przedsiębiorstwa. Gdy statystyki trafiają w ręce najważniejszych członków zarządu, rusza lawina krytycznych, niekoniecznie trafionych decyzji. Jeden niewłaściwy ruch może doprowadzić do finansowej katastrofy. Zagrożona jest nie tylko firma, ale i przyszłość całej globalnej gospodarki.', 'https://image.tmdb.org/t/p/w500/n9fseIJkCMIEBnGqsOezQIRFs2.jpg', 50839, 'tt1615147', 2, 0),
(202, 'Wall Street', 'Wall Street', 'Kryminał, Dramat', 1987, 7.2, 'Oliver Stone', 126, 'English', 2, 15000000, '20th Century Fox, Pressman Film', '', 12.99, 'Gordon Gekko - rekin finansjery otoczony przepychem i pięknymi kobietami, logiczny i wyrachowany, wywiera magnetyczny wpływ na Buda Foxa - młodego maklera giełdowego, marzącego o wielkiej fortunie. Bud jest gotowy zrobić wszystko dla swej kariery, również dokonywać wyborów niezgodnych z własnym sumieniem. Czy jest granica, której nie odważy się przekroczyć?', 'https://image.tmdb.org/t/p/w500/2tQYq9ntzn2dEwDIGLBSipYPenv.jpg', 10673, 'tt0094291', 2, 0),
(203, 'Klub winowajców', 'The Breakfast Club', 'Komedia, Dramat', 1985, 7.7, 'John Hughes', 97, 'English', 3, 1000000, 'Universal Pictures, A&M Films, Channel Productions', '', 19.99, 'Pewnego dnia, w jednej z amerykańskich szkół, dochodzi do bezprecedensowej sytuacji. Oto grupa uczniów, w której skład wchodzą: sportowiec, kujon, panienka z bogatego domu, łobuz oraz dziwaczka, dostają wspólną karę za złe zachowanie w trakcie lekcji. Karą jest spędzenie w sobotę 8 godzin w klasie. Grupka ponadto ma za zadanie napisać wypracowanie, zatytułowane "Kim jestem?". Wspólna kara oraz perypetie z nią związane, zbliżają do siebie obce dotychczas osoby. Zaczynają one ze sobą rozmawiać, dzielić się swoimi uczuciami, problemami i fobiami. Niektórzy, oprócz zrozumienia i braterskiej więzi, odnajdą jeszcze coś: prawdziwą miłość...', 'https://image.tmdb.org/t/p/w500/A6Bm2jWHwaZeI6AapVU6ycajc3Y.jpg', 2108, 'tt0088847', 2, 0),
(204, 'Wolny dzień Ferrisa Buellera', 'Ferris Bueller''s Day Off', 'Komedia', 1986, 7.6, 'John Hughes', 103, 'English', 4, 6000000, 'Paramount Pictures, Hughes Entertainment', '', 11.99, 'Ferris Bueller (Matthew Broderick), popularna persona w szkole średniej, postanawia zrobić sobie dzień wolny. Najpierw udaje chorego przed rodzicami, potem przed siostrą Jeanie (Jennifer Grey). Gdy zostaje w domu sam, dzwoni do swojego kumpla Camerona (Alan Ruck) i namawia na eskapadę do miasta sportowym ferrari jego ojca. Wraz z nimi jedzie dziewczyna Ferrisa, Sloane (Mia Sara). Tymczasem w szkole dyr. Rooney (Jeffrey Jones), znając swojego podopiecznego oraz obawiając się o swój autorytet, udaje się do domu Ferrisa, a gdy stwierdza, że go tam nie ma, rusza w pogoń. Tymczasem wycieczka uświadamia młodym co jest dla nich ważne i co dotąd robili źle oraz pomaga odnaleźć ich cele i pragnienia. Lecz dyr. Rooney nie rezygnuje tak łatwo...', 'https://image.tmdb.org/t/p/w500/uO9dN5Hxw4HztXwA48dXBspp4At.jpg', 9377, 'tt0091042', 2, 0),
(205, 'Dziewczyna w różowej sukience', 'Pretty in Pink', 'Romans, Dramat', 1986, 6.7, 'Howard Deutch', 97, 'English', 5, 9000000, 'Paramount Pictures, Hughes Entertainment', '', 18.99, '', 'https://image.tmdb.org/t/p/w500/jeFJyzJBufJexpOuywuPp8q2tCJ.jpg', 11522, 'tt0091790', 2, 0),
(206, 'Szesnaście świeczek', 'Sixteen Candles', 'Komedia', 1984, 6.7, 'John Hughes', 93, 'English', 6, 6500000, 'Universal Pictures, Channel Productions', '', 10.99, 'Dla Samanthy (Molly Ringwald) dzień jej szesnastych urodzin nie zaczął się dobrze. Od rana wszystko poszło nie tak, jak sobie wyobrażała. Rodzice - zaaferowani ślubem starszej siostry Ginnie (Blanche Baker), nie pamiętali nawet aby jej złożyć życzenia. Zakochała się w najprzystojniejszym chłopaku w szkole, podczas gdy w niej zakochał się „pierwszak” - Ted (Anthony Michael Hall) Jeśli dodać do tego jeszcze parę innych "nieszczęść", szesnaste urodziny mogą okazać się najokropniejszym dniem w jej życiu.', 'https://image.tmdb.org/t/p/w500/A3WGCAgJF33kZdlxUdyXHYdbYax.jpg', 15144, 'tt0088128', 2, 0),
(207, 'Beztroskie lata w Ridgemont High', 'Fast Times at Ridgemont High', 'Komedia, Romans, Dramat', 1982, 6.8, 'Amy Heckerling', 90, 'English', 7, 4500000, 'Refugee Films, Universal Pictures', '', 17.99, 'W szkole średniej w Ridgemont High w Kalifornii zaczyna się rok szkolny. 15-letnia Stacy Hamilton, która dorabia jako kelnerka w barze fast food, postanawia stracić dziewictwo. Jej starszy brat, Brad, wkrótce kończy szkołę. Pracuje w barze jako kucharz, ale marzy mu się kierownicze stanowisko. Nieśmiały Mark Ratner chodzi ze Stacy do jednej klasy, ale nie potrafi nawiązać z nią bliższej znajomości. Jedną z barwniejszych postaci w szkole jest surfer Jeff Spicoli, zawsze odurzony używkami i niekompletnie ubrany.', 'https://image.tmdb.org/t/p/w500/jA4EewziinHo0vQXJB5keT5M1fm.jpg', 13342, 'tt0083929', 2, 0),
(208, 'Menażeria', 'Animal House', 'Komedia', 1978, 6.9, 'John Landis', 109, 'English', 8, 2700000, 'Universal Pictures, Oregon Film Factory, Stage III Productions', '', 9.99, 'Dwóch studentów pierwszego roku –Larry "Pinto" Kroger (Thomas Hulce) i Kent "Flounder" Dorfman (Stephen Furst) zostaje członkami bractwa Delta Tau Chi działającego na terenie Faber College. Bractwo to pełne jest oryginałów i stawiających zabawę ponad wszystko studentów. Członkami bractwa Delta są między innymi: Eric "Otter" Stratton (Tim Matheson), John "Bluto" Blutarsky (John Belushi), Daniel "D-Day" Simpson Day (Bruce McGill) oraz Robert Hoover (James Widdoes). Sąsiadami i wrogami Delty jest ekskluzywne bractwo Omega Theta Pi pod wodzą Douga Neidermeyera. Wraz z dziekanem Vernonem Wormerem (John Vernon) najchętniej pozbyliby się kłopotliwego stowarzyszenia. Okazją jest test z psychologii, który wszyscy członkowie Delty oblewają. Tymczasem trwają przygotowania do dorocznej parady uniwersyteckiej.', 'https://image.tmdb.org/t/p/w500/fWooBbipMRIKeSRhEzmeaDV0T8H.jpg', 8469, 'tt0077975', 2, 0),
(209, 'Stowarzyszenie Umarłych Poetów', 'Dead Poets Society', 'Dramat', 1989, 8.3, 'Peter Weir', 128, 'English', 9, 16400000, 'A Steven Haft Production, Witt/Thomas Productions, Silver Screen Partners IV', '', 16.99, 'Charyzmatyczny anglista John Keating rozpoczyna pracę w ekskluzywnej szkole dla chłopców. Jego niekonwencjonalne metody nauczania wnoszą powiew świeżości do konserwatywnego programu uczelni. Niezwykły profesor rozbudza w swoich podopiecznych ciekawość świata, umiejętność samodzielnego myślenia i chęć rozwijania indywidualnych pasji, tym samym odmieniając ich życie.', 'https://image.tmdb.org/t/p/w500/obsiUYvbLORzV3PihvgyCf5fij5.jpg', 207, 'tt0097165', 2, 0),
(210, 'Stań przy mnie', 'Stand by Me', 'Dramat, Przygodowy', 1986, 7.8, 'Rob Reiner', 89, 'English', 10, 8000000, 'Act III Productions', '', 8.99, 'Czterech nastolatków: Gordie, Chris, Teddy i Vern dorasta razem w fikcyjnym miasteczku Castle Rock w Oregonie. Pewnego dnia Vern podsłuchuje rozmowę starszego brata, z której dowiaduje się, że grupa starszych dzieciaków znalazła przy torach zwłoki zaginionego chłopca, ale nie poinformowała o tym policji. Przyjaciele postanawiają samodzielnie odnaleźć ciało, przekonani że dzięki temu staną się sławni.', 'https://image.tmdb.org/t/p/w500/qYNSJmEDbaIXxPdjOboVVGbe3eu.jpg', 235, 'tt0092005', 2, 0),
(211, 'Narzeczona dla księcia', 'The Princess Bride', 'Fantasy, Komedia, Romans, Przygodowy', 1987, 7.7, 'Rob Reiner', 98, 'English', 1, 16000000, 'The Princess Bride, Buttercup Films, Act III Productions', '', 15.99, 'Łącząca pierwiastki realizmu i baśniowości opowieść o zakochanej w ubogim młodzieńcu dziewczynie. Aby zyskać prawo do ręki ukochanej, chłopak musi być bogaty. W poszukiwaniu fortuny wyrusza w daleką podróż.', 'https://image.tmdb.org/t/p/w500/fnwT16rhVMHLkuGzYoSnuaCrn3a.jpg', 2493, 'tt0093779', 2, 0),
(212, 'Goonies', 'The Goonies', 'Przygodowy, Komedia, Familijny', 1985, 7.5, 'Richard Donner', 114, 'English', 2, 19000000, 'Amblin Entertainment, Warner Bros. Pictures', '', 7.99, 'Nastolatek Mikey Walsh znajduje w teczce ojca starą mapę do skarbów. W nadziei ocalenia domu przed rozbiórką, Mikey i jego przyjaciele Data Wang, Chunk Cohen, i Mouth Deveraux uciekają ku wielkiej przygodzie by znaleźć ukryty skarb Jednookiego Willa.', 'https://image.tmdb.org/t/p/w500/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', 9340, 'tt0089218', 2, 0),
(213, 'E.T.', 'E.T. the Extra-Terrestrial', 'Przygodowy, Sci-Fi, Familijny', 1982, 7.5, 'Steven Spielberg', 115, 'English', 3, 10500000, 'Universal Pictures, Amblin Entertainment', '', 14.99, 'E.T. to historia wyjątkowej przyjaźni, która rozwija się między Elliottem, samotnym chłopcem żyjącym na jednym z kalifornijskich przedmieść, a mądrym przybyszem z obcej planety, który gubi się na Ziemi. Kiedy Elliott usiłuje pomóc przyjacielowi skontaktować się z jego planetą, obaj muszą unikać naukowców i agentów rządowych za wszelką cenę pragnących wykorzystać przybysza do swoich celów. Wszystko to prowadzi do wspaniałej przygody, większej od wszystkiego co mogli sobie wyobrazić.', 'https://image.tmdb.org/t/p/w500/ihqmwPkVp5z6rwlEfC1eU45rfFH.jpg', 601, 'tt0083866', 2, 0),
(214, 'Bliskie spotkania trzeciego stopnia', 'Close Encounters of the Third Kind', 'Sci-Fi, Dramat', 1977, 7.4, 'Steven Spielberg', 137, 'English', 4, 20000000, 'Julia Phillips and Michael Phillips Productions, Columbia Pictures, EMI Films', '', 6.99, 'W grudniu 1945 roku w pobliżu Trójkąta Bermudzkiego ginie bez śladu kilka bombowców amerykańskich. Ponad 30 lat później odnajdują się, brakuje jednak ciał pilotów. Tymczasem Ron Neary, pracownik elektrowni, ma znaleźć przyczynę zakłóceń energetycznych w stanie Indiana. Na miejscu Roy dostrzega na niebie kosmiczny pojazd. Zjawisko to również obserwuje Jillian Guiler. Wkrótce nowina o UFO dociera do wszystkich mieszkańców okolicy.', 'https://image.tmdb.org/t/p/w500/riLVcwPbvsvi2eiKlCKl4yq3CFl.jpg', 840, 'tt0075860', 2, 0),
(215, 'Kolor purpury', 'The Color Purple', 'Dramat', 1985, 7.7, 'Steven Spielberg', 154, 'English', 5, 15000000, 'Amblin Entertainment, Warner Bros. Pictures, The Guber-Peters Company', '', 13.99, 'Dwie czarnoskóre siostry, 14-letnia Celie i młodsza Nettie (Akosua Busia), żyją w patologicznej relacji z ojcem, Alphonso Harrisem. Drogi ich rozchodzą się w momencie, kiedy Celie wyjeżdża z przyszłym mężem Albertem. Po 14 latach siostry się spotykają. Celie nie jest szczęśliwa w małżeństwie, ma dość cierpień oraz upokorzeń ze strony agresywnego męża, dlatego decyduje się od niego odejść.', 'https://image.tmdb.org/t/p/w500/n3MkvpcTHEC42kaEklKZIbAubof.jpg', 873, 'tt0088939', 2, 0),
(216, 'Wożąc panią Daisy', 'Driving Miss Daisy', 'Dramat', 1989, 7.2, 'Bruce Beresford', 99, 'English', 6, 7500000, 'Warner Bros. Pictures, Majestic Films International, Allied Filmmakers', '', 5.99, 'Oto jeden z najbardziej urokliwych filmów wszech czasów! Po nieumyślnym wtargnięciu autem w ogród sąsiadów, 72-letnia Daisy Werthan traci polisę ubezpieczeniową. W trosce o nowe auto, bez zgody właścicielki syn staruszki zatrudnia Hoke''a, czarnoskórego kierowcę. Daisy nie ukrywa niezadowolenia z zaistniałej sytuacji. Nie chce jeździć z mężczyzną i krytykuje go za wszystko. Zobacz jak relacja, która nie miała miejsca bytu stopniowo zaczyna przeradzać się w prawdziwą przyjaźń...', 'https://image.tmdb.org/t/p/w500/iaCzvcY42HihFxQBTZCTKMpsI0P.jpg', 403, 'tt0097239', 2, 0),
(217, 'Służące', 'The Help', 'Dramat', 2011, 8.2, 'Tate Taylor', 146, 'English', 7, 25000000, '1492 Pictures, Harbinger Pictures, DreamWorks Pictures', '', 12.99, 'Akcja filmu toczy się w stanie Mississippi w latach 60. W roli głównej występuje Emma Stone (gwiazda hitu kinowego "Zombieland") grająca Skeeter, dziewczynę z dobrego domu z południa, która po studiach marzy o karierze pisarki. Niespodziewanie wywraca do góry nogami życie swoich przyjaciół i mieszkańców rodzinnego miasteczka, gdy postanawia przeprowadzić wywiad z czarnoskórą służącą najzamożniejszych rodzin w okolicy. Nominowana do Oscara Viola Davis w roli Albeen decyduje się ujawnić ciemne sekrety życia czarnoskórej mniejszości. Ze zwierzeń rodzi się przyjaźń. Okazuje się, że przyjaciółki mają sobie dużo do opowiedzenia. Zarówno one, jak i inni mieszkańcy miasteczka są świadkami zmieniających się czasów i obyczajów.', 'https://image.tmdb.org/t/p/w500/mrzn2rhIFzHl3UvwtVtUogGPGz8.jpg', 50014, 'tt1454029', 2, 0),
(218, 'Ukryte działania', 'Hidden Figures', 'Dramat, Historyczny', 2016, 8.1, 'Theodore Melfi', 127, 'English', 8, 25000000, 'Fox 2000 Pictures, Levantine Films, Chernin Entertainment', '', 19.99, 'Niezwykła, nieznana do tej pory prawdziwa historia trzech błyskotliwych kobiet afro-amerykańskiego pochodzenia, które na przełomie lat 50. i 60. XX wieku podjęły pracę dla NASA. Pokonując niewyobrażalne przeszkody społeczne i obyczajowe, pomogły wysłać w kosmos pierwszego Amerykanina, astronautę Johna Glenna, inicjując tym samym kosmiczny wyścig między światowymi mocarstwami. [opis dystrybutora kino]', 'https://image.tmdb.org/t/p/w500/yYiyeRGmtzR5FZueThg7j8PC6tB.jpg', 381284, 'tt4846340', 2, 0),
(219, 'Green Book', 'Green Book', 'Dramat, Komedia, Historyczny', 2018, 8.2, 'Peter Farrelly', 130, 'English', 9, 23000000, 'Participant, DreamWorks Pictures, Cinetic Media', '', 11.99, 'Tony, drobny cwaniaczek z Bronxu, z nadzieją na zgarnięcie konkretnej sumki, zatrudnia się jako szofer wybitnego, ekstrawaganckiego muzyka Dona Shirley''a. Razem wyruszają w wielotygodniowe tournée na południe Stanów Zjednoczonych. Z pozoru różni ich wszystko: od majątku i wykształcenia, przez sposób bycia, po ulubione jedzenie i rozrywki. Z czasem jednak będą mieli okazję przekonać się, że tak naprawdę więcej ich łączy, niż dzieli. Ich wspólna, pełna przygód podróż stanie się początkiem nieprawdopodobnej przyjaźni.', 'https://image.tmdb.org/t/p/w500/zxiD75A5lAja5WOxB8t81PA4n8z.jpg', 490132, 'tt6966692', 2, 0),
(220, 'Kłamstewko', 'The Farewell', 'Komedia, Dramat', 2019, 7.4, 'Lulu Wang', 100, 'English', 10, 3000000, 'Big Beach, Depth of Field, Kindred Spirit', '', 18.99, 'Urodzona w Chinach i wychowana w USA Billi wraca do rodzinnego Changchun, kiedy dowiaduje się, że jej ukochanej babci Nai Nai zostało kilka tygodni życia. Okazuje się jednak, że najbliżsi nie chcą powiedzieć staruszce, jak poważny jest jej stan i pod pozorem ślubu kuzyna, członkowie rodziny tłumnie zjeżdżają do Chin z całego świata. Billi próbuje się odnaleźć w nadmiarze oczekiwań i zwyczajów rodzinnych. W końcu uświadamia sobie, że to szansa na odkrycie rodzinnego kraju.', 'https://image.tmdb.org/t/p/w500/iBexGNd2oI2XO0ZvBlnL62hVbpt.jpg', 565310, 'tt8637428', 2, 0),
(221, 'Minari', 'Minari', 'Dramat', 2020, 7.3, 'Lee Isaac Chung', 115, 'English', 1, 2000000, 'Plan B Entertainment', '', 10.99, 'W pogoni za amerykańskim snem Jakob Yi (Steven Yeun) przeprowadza swoją rodzinę z Kalifornii do sielskiego Arkansas. Jego marzeniem jest stworzyć własną farmę, której plony mogłyby zaopatrywać okolicznych koreańskich sklepikarzy. Pozostali członkowie rodziny nie są zadowoleni z przenosin, zwłaszcza, gdy okazuje się, że ich nowy dom ma… kółka i jest tak wątły, że może sobie nie poradzić z nawiedzającymi okolicę tornadami. Jakby tego było mało, do rodziny dołącza nieco szelmowska babcia z Korei. Choć nie pachnie tak jak powinna, a jej metody wychowawcze są dość dziwaczne, na przekór wszystkiemu, nawiązuje nić porozumienia z 6-letnim niesfornym Davidem, a pozostałych członków rodziny uczy, jak tworzyć nową więź z Ameryką, pielęgnując równocześnie własną tradycję.', 'https://image.tmdb.org/t/p/w500/6mPNdmjdbVKPITv3LLCmQoKs9Zw.jpg', 615643, 'tt10633456', 2, 0),
(222, 'Nomadland', 'Nomadland', 'Dramat', 2021, 7.2, 'Chloé Zhao', 108, 'English', 2, 5000000, 'Cor Cordium Productions, Hear/Say Productions, Highwayman Films', '', 17.99, 'Fern pakuje swojego vana i wyrusza w drogę jako współczesna nomadka, po tym jak w wyniku recesji straciła właściwie cały swój dotychczasowy dobytek. "Nomadland", trzeci film fabularny reżyserki Chloé Zhao, przedstawia historię Lindy May, Swankie i Boba Wellsa, prawdziwych nomadów, którzy stają się mentorami i towarzyszami Fern podczas jej podróży po rozległym amerykańskim Zachodzie.', 'https://image.tmdb.org/t/p/w500/q3b8RNOw8blBajvtZX2I7ybDq2x.jpg', 581734, 'tt9770150', 2, 0),
(223, 'Psie pazury', 'The Power of the Dog', 'Dramat, Western', 2021, 6.7, 'Jane Campion', 127, 'English', 3, NULL, 'See-Saw Films, Max Films, Brightstar', '', 9.99, 'Władczy i charyzmatyczny ranczer nie przepuści żadnej okazji, aby dokuczyć nowej żonie brata i jej nastoletniemu synowi — do czasu gdy ktoś odkrywa jego tajemnicę.', 'https://image.tmdb.org/t/p/w500/3LVWhI1JlZ42yxPKrJXFvo17Avf.jpg', 600583, 'tt10293406', 2, 0),
(224, 'Duchy Inisherin', 'The Banshees of Inisherin', 'Dramat, Komedia', 2022, 7.5, 'Martin McDonagh', 114, 'English', 4, 20000000, 'Searchlight Pictures, Blueprint Pictures, Film4 Productions', '', 16.99, '"Duchy Inisherin" to opowieść o losach dwójki przyjaciół, którzy znają się od kołyski: Pádraica (Colin Farrell) i Colma (Brendan Gleeson). Akcja filmu rozgrywa się na malowniczej wyspie położonej na zachód od wybrzeży Irlandii. Pewnego dnia przyjaźń mężczyzn staje pod znakiem zapytania, gdy Colm niespodziewanie postanawia ją zakończyć. Zaskoczony Pádraic za wszelką cenę próbuje zrozumieć, co się stało i odzyskać kontakt z dawnym przyjacielem. W jego staraniach wspierają go siostra Siobhán (Kerry Condon) i znajomy młodzieniec o imieniu Dominik (Barry Keoghan). Niestety, wszelkie wysiłki Pádraica spełzają na niczym, a niewzruszony Colm jest coraz bardziej zdeterminowany, by zakończyć niechcianą relację. Po rzuconym w desperacji ultimatum Colma następuje seria szokujących wydarzeń, od których nie będzie już odwrotu…', 'https://image.tmdb.org/t/p/w500/ui5Gh6X8N1PGuHiYOV8Z9Te7CYj.jpg', 674324, 'tt11813216', 2, 0),
(225, 'Aftersun', 'Aftersun', 'Dramat', 2022, 7.7, 'Charlotte Wells', 101, 'English', 5, NULL, 'PASTEL, BBC Film, Tango Entertainment', '', 8.99, 'Młody ojciec Calum i jego córka Sophie wyjeżdżają razem do tureckiego kurortu. Podczas wspólnych wakacji, które nagrywają na kasecie VHS, stają się sobie bliżsi, niż kiedykolwiek.', 'https://image.tmdb.org/t/p/w500/evKz85EKouVbIr51zy5fOtpNRPg.jpg', 965150, 'tt19770238', 2, 0),
(226, 'Strefa interesów', 'The Zone of Interest', 'Dramat, Historyczny, Wojenny', 2023, 7.0, 'Jonathan Glazer', 105, 'English', 6, 15000000, 'JW Films, Extreme Emotions, Access Entertainment', '', 15.99, 'Komendant obozu koncentracyjnego Auschwitz-Birkenau Rudolf Höss i jego żona Hedwiga próbują ułożyć sobie rodzinne życie w domu z ogrodem, który znajduje się tuż obok obozu.', 'https://image.tmdb.org/t/p/w500/mjPOHmLivqBN9Aj1VDDrv5SOoIo.jpg', 467244, 'tt7160372', 2, 0),
(227, 'Anatomia upadku', 'Anatomie d''une chute', 'Thriller, Tajemnica, Kryminał', 2023, 7.5, 'Justine Triet', 151, 'French', 7, 6600000, 'Les Films de Pierre, Les Films Pelléas, France 2 Cinéma', '', 7.99, 'Gdy spokojne życie rodziny we francuskich Alpach przerywa tragedia, a żonę podejrzewa się o zabójstwo męża, ich pozornie szczęśliwy związek zostaje poddany wnikliwej - i brutalnej - wiwisekcji.', 'https://image.tmdb.org/t/p/w500/w0lVbJFCYA5Nz8rdpBIHHnZi7Xq.jpg', 915935, 'tt17009710', 2, 0),
(228, 'Poprzednie życie', 'Past Lives', 'Dramat, Romans', 2023, 7.7, 'Celine Song', 106, 'English', 8, 12000000, 'A24, Killer Films, 2AM', '', 14.99, 'Przyjaciele z dzieciństwa po 20 latach spędzają wspólnie jeden tydzień.', 'https://image.tmdb.org/t/p/w500/gmTocN1iLLDyjEJir2CBnt2EhGE.jpg', 666277, 'tt13238346', 2, 0),
(229, 'Przesilenie zimowe', 'The Holdovers', 'Dramat, Komedia', 2023, 7.7, 'Alexander Payne', 133, 'English', 9, 13000000, 'Miramax, Gran Via Productions', '', 6.99, 'Zbliżają się święta Bożego Narodzenia w 1970 roku i Paul, nie mając rodziny, nigdzie nie wyjeżdża. Nauczyciel zostaje w szkole, aby pilnować uczniów, którzy nie mogą wrócić do domu. Po kilku dniach zostaje tylko jeden uczeń - sprawiający kłopoty 15-latek o imieniu Angus, któremu grozi wydalenie za fatalne zachowanie. Do Paula i Angusa dołącza kucharka Mary, której syn niedawno zginął w Wietnamie.', 'https://image.tmdb.org/t/p/w500/Lz3x6odb4evJFFgY8qm95omgwy.jpg', 840430, 'tt14849194', 2, 0),
(230, 'Biedne istoty', 'Poor Things', 'Sci-Fi, Romans, Komedia', 2023, 7.6, 'Γιώργος Λάνθιμος', 141, 'English', 10, 35000000, 'Searchlight Pictures, Film4 Productions, TSG Entertainment', '', 13.99, '"Biedne istoty" w reżyserii Yorgosa Lanthimosa to niesamowita opowieść o ewolucji Belli Baxter (Emma Stone), młodej kobiety, która zostaje przywrócona do życia przez genialnego i niekonwencjonalnego naukowca, doktora Godwina Baxtera (Willem Dafoe). Pod jego opieką Bella chętnie uczy się wszystkiego od nowa, ale chce też doświadczyć pełni życia. W poszukiwaniu nowych doznań wyrusza w burzliwą i pełną przygód podróż przez kontynenty w towarzystwie sprytnego i rozpustnego prawnika, Duncana Wedderburna (Mark Ruffalo). Wolna od uprzedzeń swoich czasów, Bella z determinacją dąży do celu, jakim jest walka o równość i niezależność.', 'https://image.tmdb.org/t/p/w500/avGy3y80hhM9D6wfXXOuzEKIME0.jpg', 792307, 'tt14230458', 2, 0),
(231, 'Gwiezdne wojny Część VII: Przebudzenie mocy', 'Star Wars: The Force Awakens', 'Przygodowy, Akcja, Sci-Fi', 2015, 7.2, 'J.J. Abrams', 135, 'English', 1, 245000000, 'Lucasfilm Ltd., Bad Robot', '', 5.99, 'Kylo Ren i odrodzony z popiołów Imperium złowieszczy Najwyższy Porządek rosną w siłę, a Luke Skywalker przepadł bez wieści w chwili, gdy galaktyka potrzebuje go najbardziej. Rey, pustynna zbieraczka złomu, oraz Finn, dezerter z oddziału szturmowców, łączą siły z Hanem Solo i Chewbaccą w poszukiwaniu ostatniej nadziei na przywrócenie pokoju w galaktyce.', 'https://image.tmdb.org/t/p/w500/AlPO56dJEbkC7LH29XPfgke2cIn.jpg', 140607, 'tt2488496', 2, 0),
(232, 'Gwiezdne wojny Część VIII: Ostatni Jedi', 'Star Wars: The Last Jedi', 'Przygodowy, Akcja, Sci-Fi', 2017, 6.7, 'Rian Johnson', 150, 'English', 2, 300000000, 'Lucasfilm Ltd.', '', 12.99, 'Rey po odnalezieniu Luke''a Skywalkera postanawia szkolić się pod jego okiem, by zostać Mistrzem Jedi. Nie wszystko jednak układa się po jej myśli. Dodatkowo Kylo Ren kierowany rządzą zemsty staje na czele Najwyższego Porządku, by raz na zawsze unicestwić Ruch Oporu. W tej trudnej chwili Rey, Luke, Finn oraz Poe Dameron będą musieli połączyć siły, by powstrzymać ciemną stronę Mocy.', 'https://image.tmdb.org/t/p/w500/bOsCWMXewNgWkrWN7OfVAJ2z7nI.jpg', 181808, 'tt2527336', 2, 0),
(233, 'Gwiezdne wojny Część IX: Skywalker. Odrodzenie', 'Star Wars: The Rise of Skywalker', 'Przygodowy, Akcja, Sci-Fi', 2019, 6.2, 'J.J. Abrams', 141, 'English', 3, 489900000, 'Lucasfilm Ltd., Bad Robot', '', 19.99, 'Lucasfilm i reżyser J.J. Abrams raz jeszcze łączą siły, aby zabrać widzów w spektakularną podróż do odległej galaktyki w filmie Gwiezdne wojny: Skywalker. Odrodzenie. Saga rodziny Skywalkerów dobiega końca. Tego po prostu nie można przegapić! Czym zaskoczą w finale twórcy jednej z najbardziej kultowych serii w historii kina? Jaki będzie finał odwiecznej batalii pomiędzy jasną i ciemną stroną mocy?', 'https://image.tmdb.org/t/p/w500/lj3g6kzBLfrcrkfRQf8ZtRF7ZUy.jpg', 181812, 'tt2527338', 2, 0),
(234, 'Łotr 1. Gwiezdne wojny – historie', 'Rogue One: A Star Wars Story', 'Akcja, Przygodowy, Sci-Fi', 2016, 7.5, 'Gareth Edwards', 133, 'English', 4, 200000000, 'Lucasfilm Ltd.', '', 11.99, 'Grupa rebeliantów podejmuje się misji niemożliwej, próbując wykraść plany budowy Gwiazdy Śmierci, najpotężniejszej broni Imperium. Ten kluczowy dla całego uniwersum Gwiezdnych wojen moment rozpoczyna serię zdarzeń, w których zwykli ludzie dokonują niezwykłych czynów i stają się bohaterami.', 'https://image.tmdb.org/t/p/w500/q1CxmobHDVimr7IYlbZYQ6PUge1.jpg', 330459, 'tt3748528', 2, 0),
(235, 'Han Solo: Gwiezdne wojny – historie', 'Solo: A Star Wars Story', 'Sci-Fi, Przygodowy, Akcja', 2018, 6.5, 'Ron Howard', 135, 'English', 5, 250000000, 'Lucasfilm Ltd.', '', 18.99, 'Podczas szalonych eskapad po najciemniejszych i najniebezpieczniejszych zakątkach kryminalnego półświatka, Han Solo spotyka swego potężnego przyszłego drugiego pilota Chewbaccę, a także osławionego szulera Lando Calrissiana.', 'https://image.tmdb.org/t/p/w500/nCttjIMnIQ5ib0B7SxcQmxo7h9T.jpg', 348350, 'tt3778644', 2, 0),
(236, 'Star Trek', 'Star Trek', 'Sci-Fi, Akcja, Przygodowy', 2009, 7.4, 'J.J. Abrams', 127, 'English', 6, 150000000, 'Paramount Pictures, Spyglass Entertainment, Bad Robot', '', 10.99, 'Los galaktyki spoczywa w rękach dwóch rywali. Jednym z nich jest James Kirk, przestępca, szukający wrażeń chłopak ze wsi w stanie Iowa. Drugi z nich- Spock wychowywał się w tradycji vulkańskiej opartej na logicznym rozumowaniu i odrzucającej emocje. Gdy ognisty temperament ściera się ze zdrowym rozsądkiem, ich współpraca wydaje się niemożliwa. Jednak to połączenie charakterów to jedyne co pozwoli poprowadzić ich załogę przez niewyobrażalne niebezpieczeństwo i udać się tam, gdzie nikt inny nie miał odwagi.', 'https://image.tmdb.org/t/p/w500/lV5OpzAss1z06YNagOVap1I35mH.jpg', 13475, 'tt0796366', 2, 0),
(237, 'W ciemność. Star Trek', 'Star Trek Into Darkness', 'Akcja, Przygodowy, Sci-Fi', 2013, 7.3, 'J.J. Abrams', 132, 'English', 7, 190000000, 'Bad Robot, Paramount Pictures, Skydance Media', '', 17.99, 'Kiedy załoga Enterprise zostaje wezwana do domu okazuje się, że niepowstrzymana siła terroru pochodząca z ich własnej organizacji zdetonowała flotę i wszystko co ona symbolizowała, pozostawiając świat w kryzysie. Mając osobiste rachunki do wyrównania, kapitan Kirk prowadzi polowanie w świecie ogarniętym wojną mające na celu schwytanie jednego człowieka - broni masowego rażenia. W miarę jak nasi bohaterowie zostają uwikłani w niebezpieczną grę na śmierć i życie, miłość zostanie poddana próbie, przyjaźnie zerwane i ofiary poczynione w imię jedynej rodziny jaka pozostała Kirkowi: jego załogi.', 'https://image.tmdb.org/t/p/w500/8O3SxzC1BDvvsTiTylAsX69sxbC.jpg', 54138, 'tt1408101', 2, 0),
(238, 'Star Trek: W nieznane', 'Star Trek Beyond', 'Akcja, Przygodowy, Sci-Fi', 2016, 6.8, 'Justin Lin', 122, 'English', 8, 185000000, 'Skydance Media, Paramount Pictures, Bad Robot', '', 9.99, 'Kolejna odsłona kultowej serii, która wrosła w popkulturę, co więcej - współtworzyła ją. Twórcy ponownie zabiorą nas w emocjonującą międzygalaktyczną podróż. Wspólnie z bohaterami filmu znów będziemy „śmiało kroczyć tam, gdzie nie dotarł jeszcze żaden człowiek".', 'https://image.tmdb.org/t/p/w500/c11UPavheVRD2vEYODHlBiwcHym.jpg', 188927, 'tt2660888', 2, 0),
(239, 'Star Trek', 'Star Trek: The Motion Picture', 'Sci-Fi, Przygodowy, Tajemnica', 1979, 6.5, 'Robert Wise', 132, 'English', 9, 44000000, 'Paramount Pictures, Century Associates, Robert Wise Productions', '', 16.99, 'Kiedy nieznana, obca siła niszczy kilka klingońskich statków, James T. Kirk (William Shatner) powraca na kapitański mostek zmodernizowanego U.S.S. Enterprise. Leonard Nimoy, DeForest Kelley oraz załoga z oryginalnej telewizyjnej serii "Star Trek" mobilizuje siły, abo powstrzymać niszczycielskie zapedy obcego intruza nieubłaganie zmierzającego z stronę Ziemi.', 'https://image.tmdb.org/t/p/w500/wfiAfNwH6CMKxz4vRaW8CPTabtk.jpg', 152, 'tt0079945', 2, 0),
(240, 'Star Trek II: Gniew Khana', 'Star Trek II: The Wrath of Khan', 'Akcja, Przygodowy, Sci-Fi', 1982, 7.5, 'Nicholas Meyer', 113, 'English', 10, 12000000, 'Paramount Pictures', '', 8.99, 'To drugi z pełnometrażowych filmów z serii "Star Trek", nakręcony za minimalne pieniądze, z użyciem najprostszych efektów specjalnych, używający tylko starych makiet pojazdów i stacji kosmicznych...jednocześnie jeden z najlepszych i najbardziej lubianych obrazów serii. Admirał Kirk i załoga Enterprise stawiają tym razem czoła dawnemu wrogowi. Jest nim Khan Noonien Singh - kiedyś uwięziony przez Kirka na opuszczonej planecie przestępca - który pragnie zemsty. Zamierza tego dokonać przy pomocy Projektu Genesis - programu stworzonemu w celach pokojowych, który jednak może służyć również jako potężna broń. Przejmuje statek Federacji - USS Reliant i rozpoczyna realizację swojego planu.', 'https://image.tmdb.org/t/p/w500/3nMw7pO2uGhtHaAA4CB94I8MJPN.jpg', 154, 'tt0084726', 2, 0),
(241, 'Prometeusz', 'Prometheus', 'Sci-Fi, Tajemnica, Horror', 2012, 6.6, 'Ridley Scott', 124, 'English', 1, 130000000, 'Dune Entertainment, 20th Century Fox, Brandywine Productions', '', 15.99, 'Mamy rok 2089, zespół archeologów pod kierownictwem Elizabeth Shaw (Noomi Rapace) odkrywa tajemnicze piktogramy, które są według nich dziełem starożytnej cywilizacji. By dowiedzieć się więcej o autorach znaków, wyruszają supernowoczesnym statkiem kosmicznym o nazwie "Prometeusz" do odległego zakątka naszego wszechświata. Otóż całą wyprawę finansuje korporacja Weyland Industries, którą na statku reprezentuje bezwzględna Meredith Vickers (Charlize Theron). Naukowcy wierzą, że uda im się nawiązać pokojowe kontakty z Obcymi, ale okazuję się, że twórcy znaków są bardzo niebezpieczni. Shaw i jej towarzysze będą musieli stoczyć walkę o własne życie i przyszłość całej ludzkiej rasy.', 'https://image.tmdb.org/t/p/w500/rSiDg2yE4kqcBkbqJvnA9dAsjaw.jpg', 70981, 'tt1446714', 2, 0),
(242, 'Obcy: Przymierze', 'Alien: Covenant', 'Horror, Sci-Fi', 2017, 6.2, 'Ridley Scott', 122, 'English', 2, 97000000, '20th Century Fox, Brandywine Productions, Scott Free Productions', '', 7.99, '"Obcy: Przymierze" to drugi rozdział nowej trylogii, którą zapoczątkował film "Prometeusz". Statek osadniczy "Przymierze" dociera na nieznaną planetę, która wydaje się być prawdziwym rajem. Członkowie ekspedycji szybko się jednak przekonują, że trafili do mrocznego, pełnego tajemnic i niebezpieczeństw świata, którego jedynym mieszkańcem jest android David (Michael Fassbender), ocalały z katastrofy "Prometeusza".', 'https://image.tmdb.org/t/p/w500/uTEvJeGNUFmCMIhFXxOoGLEzUfp.jpg', 126889, 'tt2316204', 2, 0),
(243, 'Piąty element', 'Le Cinquième Élément', 'Sci-Fi, Akcja, Przygodowy', 1997, 7.6, 'Luc Besson', 126, 'French', 3, 90000000, 'Gaumont', '', 14.99, 'Jest wiek XXIII naszej ery. Zwiadowcze krążowniki kosmiczne wykryły tajemniczy obiekt zbliżający się do naszej galaktyki. Ziemia znalazła się w niebezpieczeństwie. Korben Dallas - były komandos, kierowca nowojorskiej taksówki otrzymuje rozkaz: odnaleźć pięć mitycznych elementów zdolnych ocalić planetę. Korben nie ma wyjścia - wraz z przybyłą z innej galaktyki piękną Leeloo wyrusza w kosmos by walczyć z kosmicznym "elementem"...', 'https://image.tmdb.org/t/p/w500/zL3pSAA0WfqfUMI7HdrBIMZoBu5.jpg', 18, 'tt0119116', 2, 0),
(244, 'Pamięć absolutna', 'Total Recall', 'Akcja, Przygodowy, Sci-Fi', 1990, 7.3, 'Paul Verhoeven', 113, 'English', 4, 65000000, 'Carolco Pictures, Ronald Shusett/Gary Goldman Productions, Estudios Churubusco Azteca', '', 6.99, 'Ekranizacja opowiadania Philipa K. Dicka. Niedaleka przyszłość. Ludzkość dynamicznie kolonizuje przestrzeń kosmiczną. Przeciętny obywatel Doug Quaid (Arnold Schwarzenegger) korzysta z oferty cybernetycznego biura podróży i wybiera się w wirtualną podróż na Marsa. W jej trakcie odkrywa w swej podświadomości wspomnienia, które ktoś wymazał z jego pamięci. Okazuje się, że jeszcze niedawno był agentem specjalnym wykonującym tajne misje w kosmosie. Doug rusza na Marsa tropem swej przeszłości.', 'https://image.tmdb.org/t/p/w500/Ak5rHycbTVFEjD75aYxdGUT4PPe.jpg', 861, 'tt0100802', 2, 0),
(245, 'Raport mniejszości', 'Minority Report', 'Sci-Fi, Akcja, Thriller', 2002, 7.4, 'Steven Spielberg', 145, 'English', 5, 102000000, 'Digital Image Associates, Cruise/Wagner Productions, Blue Tulip Productions', '', 13.99, 'Waszyngton roku 2054 - futurystyczny świat, w którym nie ma zbrodni, przyszłość można przewidzieć, a winnych ukarać, zanim popełnią planowane przestępstwo. Dowodów niedoszłych zbrodni dostarcza trójka Jasnowidzów na usługach Agencji Prewencji Departamentu Sprawiedliwości, nad której sprawnym działaniem czuwa komisarz John Anderton (Tom Cruise). Jako pierwszy ogląda obrazy przekazywane przez Jasnowidzów. Ich werdykt nie pozostawia wątpliwości - za niespełna 36 godzin John Anderton zabije człowieka, którego nawet nie zna. Rozpoczyna się szaleńczy wyścig z czasem. Anderton musi wykryć, kto go wrabia albo stanie się ofiarą "idealnego" systemu, który sam pomagał tworzyć. Aby wygrać musi odpowiedzieć sobie na pytanie, które jeszcze nie tak dawno nie przyszłoby mu nawet na myśl: czy Jasnowidze mogą się mylić?', 'https://image.tmdb.org/t/p/w500/9BtQ0dL3aVb9hQLL6dCR725FFBo.jpg', 180, 'tt0181689', 2, 0),
(246, 'A.I. Sztuczna inteligencja', 'A.I. Artificial Intelligence', 'Dramat, Sci-Fi, Przygodowy', 2001, 7.1, 'Steven Spielberg', 146, 'English', 6, 100000000, 'Amblin Entertainment, Stanley Kubrick Productions, Warner Bros. Pictures', '', 5.99, 'Kiedy prototypowy robot-dziecko o imieniu David (Haley Joel Osment) zostaje zaprogramowany, by kochać, jego ludzcy rodzice nie są na to przygotowani. Porzucony w obcym i wrogim świecie David zaprzyjaźnia się ze sprytnym robotem (Jude Law) i wyrusza w spektakularną podróż, dzięki której może odkryć prawdę o sobie samym.', 'https://image.tmdb.org/t/p/w500/crls6h5cTyztGDKvgZp1W1RMNaM.jpg', 644, 'tt0212720', 2, 0),
(247, 'Looper - Pętla czasu', 'Looper', 'Akcja, Thriller, Sci-Fi', 2012, 6.9, 'Rian Johnson', 118, 'English', 7, 30000000, 'Endgame Entertainment, DMG Entertainment, Ram Bergman Productions', '', 12.99, 'W roku 2072 podróże w czasie są już rzeczywistością. Organizacje przestępcze wykorzystują je do eliminacji niewygodnych ludzi. Wysyłają ich w przeszłość, gdzie są oni zabijani przez płatnych zabójców zwanych Loopers. W roku 2042 najlepszy z Looperów otrzymuje zadanie: zlikwidować przysłanego z przyszłości mężczyznę o imieniu Joe. Problem w tym, że rozpoznaje w nim samego siebie z przyszłości. Chwila wahania kosztuje go bardzo wiele - cel ucieka, a zleceniodawcy z przyszłości nie tolerują najmniejszej wpadki...', 'https://image.tmdb.org/t/p/w500/ciHiAkTljrufCBHN3Re1wZVF93j.jpg', 59967, 'tt1276104', 2, 0),
(248, 'Przeznaczenie', 'Predestination', 'Sci-Fi, Thriller', 2014, 7.4, 'Michael Spierig', 97, 'English', 8, 5500000, 'Screen Queensland, Screen Australia, Blacklab Entertainment', '', 19.99, 'Film opartych na motywach opowiadania „Wszyscy wy zmartwychwstali...” Roberta A. Heinleina. Jest to swoista kronika życia Agenta (Ethan Hawke) wysłanego w serię trudnych podróży w czasie, które mają zapewnić mu kontynuację kariery stróża prawa. Podczas ostatniego zadania Agent musi zwerbować młodszego siebie w pogoni za przestępcą, który wymyka się w czasie.', 'https://image.tmdb.org/t/p/w500/u0dI5bkdxBL0g8FB0ZO5xRhIUca.jpg', 206487, 'tt2397535', 2, 0),
(249, 'Wynalazek', 'Primer', 'Sci-Fi, Dramat, Thriller', 2004, 6.7, 'Shane Carruth', 77, 'English', 9, 7000, 'erbp', '', 11.99, 'Historia rozpoczyna się w garażu gdzie czterech mężczyzn konstruuje nowatorski technologicznie mechanizm. Częściowo przypadkowo a połowicznie poparty wiedzą skonstruowany wynalazek a raczej jego siła pozwala bohaterom osiągnąć prawie wszystko czego zapragną. Czy ta rewelacja technologiczna zmieni ich życie?', 'https://image.tmdb.org/t/p/w500/7aFKx0fKqeYVX1t8gaqdwELyGAm.jpg', 14337, 'tt0390384', 2, 0),
(250, 'Równoległa rzeczywistość', 'Coherence', 'Thriller, Sci-Fi', 2014, 7.2, 'James Ward Byrkit', 89, 'English', 10, 50000, 'Bellanova Films, Ugly Duckling Films', '', 18.99, 'Grupa znajomych spędza w domku weekend. W tym czasie, nad planetą, przelatuje kometa, która jest przyczyną dziwnych zjawisk. Przestają działać telefony, ich wyświetlacze pękają, a kiedy mieszkańcy wychodzą na zewnątrz, wszędzie jest ciemno. Dwóch weekendowiczów postanawia oddzielić się od grupy, jednak wracają bardzo wystraszeni i odmienieni. Nie chcą powiedzieć reszcie, co takiego zobaczyli.', 'https://image.tmdb.org/t/p/w500/gKqKa4IjucNWnk1Yj7xe0FhcHBq.jpg', 220289, 'tt2866360', 2, 0),
(251, 'Efekt motyla', 'The Butterfly Effect', 'Sci-Fi, Thriller', 2004, 7.6, 'Eric Bress', 113, 'English', 1, 13000000, 'FilmEngine, Katalyst Films, BenderSpink', '', 10.99, 'Evan Treborn jako dziecko wiele przeszedł. Wyparł jednak z pamięci te przykre zdarzenia. W dzieciństwie pozostawał pod opieką psychiatry, który zachęcał go do prowadzenia dziennika, w którym szczegółowo miał zapisywać każdy dzień swojego życia. Teraz, już jako student college''u, Evan czytając swój dziennik, w niewytłumaczalny sposób przenosi się w czasie do przeszłości. Dziennik, który trzyma pod łóżkiem, okazuje się bowiem wehikułem czasu.', 'https://image.tmdb.org/t/p/w500/mg0CoeJQcdLMoebQDT3SxvoxqBj.jpg', 1954, 'tt0289879', 2, 0),
(252, 'Kod nieśmiertelności', 'Source Code', 'Thriller, Sci-Fi, Tajemnica', 2011, 7.3, 'Duncan Jones', 93, 'English', 2, 32000000, 'The Mark Gordon Company, Summit Entertainment, Vendôme Production', '', 17.99, 'Kapitan Colter Stevens budzi się w jadącym z dużą prędkością pociągu. Nie poznaje siedzącej obok niego dziewczyny, nie wie, gdzie jest. Po 8 minutach od jego przebudzenia pociąg eksploduje. Wtedy mężczyzna przekonuje się, że bierze udział w rządowym eksperymencie o nazwie: "Kod nieśmiertelności", który pozwala na wejście w ciało innego człowieka na ostatnich 8 minut jego życia. Zadaniem Stevensa jest rozpoznanie i powstrzymanie zagrażającego całemu Chicago terrorysty podkładającego bomby. "Kod nieśmiertelności" pozwala wracać na miejsce zdarzeń wielokrotnie i żołnierz z każdym powrotem na ostatnich 8 minut życia pasażerów pociągu będzie wiedział coraz więcej. Czy uda mu się znaleźć i powstrzymać atak bombowy... który już się wydarzył?', 'https://image.tmdb.org/t/p/w500/jWLxsmoKTPGpv7mP0DTjJwDndOb.jpg', 45612, 'tt0945513', 2, 0),
(253, 'Na skraju jutra', 'Edge of Tomorrow', 'Akcja, Sci-Fi', 2014, 7.6, 'Doug Liman', 113, 'English', 3, 178000000, 'RatPac Entertainment, Village Roadshow Pictures, VIZ Media', '', 9.99, 'Niedaleka przyszłość. Nieznana rasa obcych atakuje Ziemię, niszcząc miasta i zabijając miliony ludzi. Wojska z całego świata łączą siły, by wspólnie walczyć najeźdźcą.  Podpułkownik Bill Cage, który nigdy wcześniej nie uczestniczył w prawdziwej walce, bez odpowiedniego przygotowania i słabo wyposażony, zostaje rzucony na pierwsza linię. Po kilku minutach ginie, chwilę wcześniej jednak udaje mu się zabić jednego z obcych. W niewyjaśniony sposób ożywa znów na początku owego przeklętego dnia, znowu idzie do walki, ginie, znowu ożywa... Za każdym razem Cage jest jednak mądrzejszy, bardziej doświadczony i bezwzględny dla wroga. Wraz z Ritą Vrataski, żołnierzem sił specjalnych, która zabiła więcej kosmitów, niż ktokolwiek inny, z każdą kolejną walką zbliżają się do poznania sposobu na ostateczne pokonanie wroga.', 'https://image.tmdb.org/t/p/w500/UDBE3IvoHbDB80XpWPyCmriQtt.jpg', 137113, 'tt1631867', 2, 0),
(254, 'Niepamięć', 'Oblivion', 'Akcja, Sci-Fi, Przygodowy, Tajemnica', 2013, 6.7, 'Joseph Kosinski', 126, 'English', 4, 120000000, 'Universal Pictures, Relativity Media, Monolith Pictures', '', 16.99, 'Jest rok 2077: Jack Harper (Tom Cruise) stacjonuje na ewakuowanej Ziemi, serwisując niesprawne drony. Jego misja jako część operacji mającej na celu zabezpieczenie niezbędnych surowców po dekadach wojen z obcymi dobiega końca. Za dwa tygodnie Harper dołączy do grupy ocalałych przebywających w kolonii, na księżycu Saturna - Tytanie, z dala od zniszczonego wojną świata, który kiedyś nazywał domem. Życie patrolującego niebo z wysokości tysięcy metrów Jacka ulega drastycznej zmianie, kiedy ratuje z rozbitego statku kosmicznego piękną nieznajomą. Pojawienie się kobiety daje początek łańcuchowi wydarzeń, które zmuszają Jacka do podania w wątpliwość wszystkiego, co do tej pory wiedział. Odkrywając szokującą prawdę, która łączy go z Ziemią z przeszłości, Jack zostaje zmuszony do licznych aktów odwagi. Los ludzkości spoczywa teraz w rękach człowieka, który wierzył, że nasz świat wkrótce zostanie stracony na zawsze.', 'https://image.tmdb.org/t/p/w500/gHt2PCRb56DRXHzz5lJsFFoVxOB.jpg', 75612, 'tt1483013', 2, 0),
(255, 'Ex Machina', 'Ex Machina', 'Dramat, Sci-Fi', 2015, 7.6, 'Alex Garland', 108, 'English', 5, 15000000, 'DNA Films, Film4 Productions, IAC Films', '', 8.99, 'Scenarzysta „28 dni później” i „W stronę słońca” zaprasza do świata przyszłości, która dzieje się już teraz, w laboratoriach, o których nie mamy pojęcia.  Młody informatyk Caleb wygrywa firmowy konkurs i na tydzień trafia do laboratorium, w którym pracuje szef firmy - Nathan. Caleb poznaje w nim piękną Avę - pierwszą na świecie sztuczną inteligencję pod postacią kobiety. Ava jest wynikiem eksperymentu Nathana. Czuje, myśli, wzrusza się i boi o własną przyszłość. Caleb nie wie, że sam jest częścią eksperymentu, który ma sprawdzić, jak na postać Avy zareaguje przeciętny człowiek.', 'https://image.tmdb.org/t/p/w500/lNHjfGCqV8qL6J7OsWfy9XTe2wc.jpg', 264660, 'tt0470752', 2, 0),
(256, 'Marsjanin', 'The Martian', 'Sci-Fi, Dramat, Przygodowy', 2015, 7.7, 'Ridley Scott', 141, 'English', 6, 108000000, 'Genre Films, TSG Entertainment, 20th Century Fox', '', 15.99, 'Potężna burza piaskowa sprawia, że sześcioosobowa marsjańska ekspedycja, w której skład wchodzi Mark Watney (Matt Damon), musi ratować się ucieczką z Czerwonej Planety. Kiedy ciężko ranny Mark odzyskuje przytomność, stwierdza, że został na Marsie sam w zdewastowanym przez wichurę obozie, z minimalnymi zapasami powietrza i żywności, a na dodatek bez łączności z Ziemią. Co gorsza, zarówno pozostali członkowie ekspedycji, jak i sztab w Houston uważają go za martwego, nikt więc nie zorganizuje wyprawy ratunkowej; zresztą, nawet gdyby wyruszyli po niego niemal natychmiast, dotarliby na Marsa długo po tym, jak zabraknie mu powietrza, wody i żywności. Czyżby to był koniec? Nic z tego. Mark rozpoczyna heroiczną walkę o przetrwanie, w której równie ważną rolę co naukowa wiedza, zdolności techniczne i pomysłowość odgrywają niezłomna determinacja i umiejętność zachowania dystansu wobec siebie i świata, który nie zawsze gra fair…', 'https://image.tmdb.org/t/p/w500/qS3n6AJD302spmHx5TSs88ICAMo.jpg', 286217, 'tt3659388', 2, 0),
(257, 'Grawitacja', 'Gravity', 'Sci-Fi, Thriller, Dramat', 2013, 7.2, 'Alfonso Cuarón', 91, 'English', 7, 105000000, 'Esperanto Filmoj, Warner Bros. Pictures, Heyday Films', '', 7.99, 'Dr Ryan Stone jest wybitną specjalistką od inżynierii medycznej. Zatrudniona przez NASA trafia do zespołu pracującego przy naprawie teleskopu Hubble''a. Dowódcą misji jest Matt Kowalsky, który po powrocie na Ziemię ma zakończyć karierę astronauty. Kiedy w prom kosmiczny, którym astronauci przylecieli na orbitę, uderzają szczątki starego rosyjskiego satelity, ginie większość członków misji. Przy życiu pozostają tylko dr Stone i Kowalsky. Od tej chwili są zdani tylko na siebie. Muszą dotrzeć do innego promu, ale zapas powietrza w uszkodzonych zbiornikach nieubłaganie się wyczerpuje...', 'https://image.tmdb.org/t/p/w500/uEKzNJYy3HgYbEoXYjmweD7pH9F.jpg', 49047, 'tt1454468', 2, 0),
(258, 'Apollo 13', 'Apollo 13', 'Dramat, Historyczny', 1995, 7.5, 'Ron Howard', 140, 'English', 8, 52000000, 'Imagine Entertainment, Universal Pictures', '', 14.99, 'Nie minął rok od chwili, gdy człowiek stanął na Księżycu, a już dla większości Amerykanów misja Apollo 13 była jeszcze jednym rutynowym lotem w Kosmos. Do czasu jednak, gdy ciszy przestrzeni nie rozdarły znamienne słowa: "Houston, mamy problem." Tamte ciężkie chwile z kwietnia 1970 roku przypomina Ron Howard w kosmicznym dreszczowcu z udziałem Toma Hanksa oraz innych znanych aktorów. Oto zawieszeni 400 tysięcy kilometrów nad Ziemią w uszkodzonym pojeździe kosmicznym astronauci Jim Lovell (Hanks), Fred Haise (Bill Paxton), Jack Swigert (Kevin Bacon) rozpaczliwie walczą o przetrwanie. Jednocześnie w Ośrodku Kontroli Lotów astronauta Gene Kranz (Ed Harris) na czele bohaterskiej załogi robi wszystko, aby sprowadzić ich na Ziemię. "Apollo 13" to zapierająca dech w piersiach opowieść o przygodzie, wierze i odwadze. Historia, która wydarzyła się naprawdę!', 'https://image.tmdb.org/t/p/w500/d4MoScjA752ic4EgDBdRj3s2HQr.jpg', 568, 'tt0112384', 2, 0),
(259, 'Kontakt', 'Contact', 'Dramat, Sci-Fi, Tajemnica', 1997, 7.5, 'Robert Zemeckis', 153, 'English', 9, 90000000, 'South Side Amusement Company, Warner Bros. Pictures', '', 6.99, 'Ellie Arroway przez całe swoje życie szukała odpowiedzi na temat pozaziemskiej cywilizacji. Pewnego ranka odbiera sygnał radiowy z odległej gwiazdy Vega. Zawiera on szczegółowe plany międzygalaktycznego pojazdu, mogącego przetransportować pasażerów w odległą przestrzeń kosmiczną. Ellie chce, by to właśnie ona była osobą, która samotnie opuści Ziemię, aby badać obce galaktyki w celu odnalezienia źródła tajemniczego sygnału oraz, jako pierwszy człowiek, nawiązać kontakt z jego nadawcą. Ale jej osobista podróż zaprowadzi ją poza granice teorii, wiedzy, doświadczenia, aż do uświadomienia sobie, że prawdziwa wizja jest ostatecznie połączeniem faktów i wiary.', 'https://image.tmdb.org/t/p/w500/hOra640LyI8KL9YibiYelTMHAE3.jpg', 686, 'tt0118884', 2, 0),
(260, 'Otchłań', 'The Abyss', 'Przygodowy, Thriller, Sci-Fi', 1989, 7.4, 'James Cameron', 140, 'English', 10, 43000000, '20th Century Fox, Pacific Western', '', 13.99, 'Amerykańska łódź podwodna zostaje zaatakowana i uszkodzona opada na dno oceanu. Wojsko organizuje akcję ratunkową, ale okazuje się, że armia nie jest w posiadaniu odpowiedniego sprzętu umożliwiającego prace na dużych głębokościach. Do akcji zostają zaangażowani więc cywile, pracownicy stacji badawczej. W trakcie swojej pracy nawiązują oni kontakt z Obcymi...', 'https://image.tmdb.org/t/p/w500/m6j5khshyRl1nL2M1YtmZXBJMoL.jpg', 2756, 'tt0096754', 2, 0),
(261, 'Armageddon', 'Armageddon', 'Akcja, Sci-Fi, Przygodowy', 1998, 6.8, 'Michael Bay', 151, 'English', 1, 140000000, 'Touchstone Pictures, Jerry Bruckheimer Films, Valhalla Motion Pictures', '', 5.99, 'Naukowcy NASA odkrywają, że za 18 dni zderzy się z Ziemią ogromna asteroida dorównująca wielkością stanowi Teksas. By zapobiec katastrofie, w którą stawką jest przyszłość całej planety, szef NASA Dan Truman (Billy Bob Thornton) decyduje się na wysłanie promu kosmicznego ze śmiertelnie niebezpieczną misją. Jej uczestnicy mają wywiercić w asteroidzie otwory i umieścić w nich ładunki nuklearne. Jedynym człowiekiem zdolnym do pokierowania taką misją jest Harry Stamper (Bruce Willis) - światowej klasy specjalista od wierceń naftowych. Los całej ludzkości i przyszłość Ziemi spoczywa w jego rękach...', 'https://image.tmdb.org/t/p/w500/eTM3qtGhDU8cvjpoa6KEt5E2auU.jpg', 95, 'tt0120591', 2, 0),
(262, 'Dzień Niepodległości', 'Independence Day', 'Akcja, Przygodowy, Sci-Fi', 1996, 6.9, 'Roland Emmerich', 145, 'English', 2, 75000000, '20th Century Fox, Centropolis Entertainment', '', 12.99, 'Jeden z największych przebojów filmowych, w którym ludzkość staje w obliczu zagłady, gdy tajemniczy i potężni Obcy rozpoczynają inwazję na Ziemię. Początkowy zachwyt związany z pojawieniem się na niebie niezidentyfikowanych obiektów latających szybko przeradza się w przerażenie, gdy śmiercionośne promienie wystrzeliwane z pokładów statków kosmicznych niszczą miasta na powierzchni całej planety. Jedyną nadzieją na zakończenie terroru jest zjednoczenie sił w jednym silnym ataku na najeźdźcę. Czy ludzie zdołają ocalić swój świat, zanim będzie za późno?', 'https://image.tmdb.org/t/p/w500/jK0BySE3k5tjKTmCx4BGhznNBum.jpg', 602, 'tt0116629', 2, 0),
(263, 'Wojna światów', 'War of the Worlds', 'Przygodowy, Thriller, Sci-Fi', 2005, 6.6, 'Steven Spielberg', 116, 'English', 3, 132000000, 'Paramount Pictures, DreamWorks Pictures, Amblin Entertainment', '', 19.99, 'Ray Ferrier (Tom Cruise) to rozwiedziony pracownik portowy i jednocześnie niezbyt idealny ojciec. Wkrótce po tym jak jego była żona i jej nowy małżonek wpadają do Ferriera, żeby podrzucić mu dzieciaki - nastoletniego Robbiego (Justin Chatwin) i młodszą córkę Rachel (Dakota Fanning), w mieście rozpętuje się przedziwna burza z piorunami. Chwilę później, na skrzyżowaniu nieopodal swojego domu Ray staje się świadkiem niezwykłego wydarzenia, które na zawsze odmieni życie jego samego i jego rodziny. Gigantyczna wojenna machina, osadzona na trójnogu, pojawia się nagle z głębi ziemi i zanim ktokolwiek jest w stanie zareagować, spala wszystko, co znajdzie się w zasięgu jej rażenia.', 'https://image.tmdb.org/t/p/w500/nI2yJoa2FVpTN7A3ALRlOQ7OQaV.jpg', 74, 'tt0407304', 2, 0),
(264, 'Znaki', 'Signs', 'Thriller, Sci-Fi, Horror', 2002, 6.7, 'M. Night Shyamalan', 106, 'English', 4, 72000000, 'Touchstone Pictures, Blinding Edge Pictures, The Kennedy/Marshall Company', '', 11.99, 'Graham Hess jest byłym pastorem, który po śmierci żony stracił wiarę. Razem z dwójką dzieci mieszka na farmie Bucks Country w Pensylwanii. Wiedzie spokojny żywot, zajmuje się rolnictwem i myśli, że nic już go w życiu nie czeka. Pewnego dnia na swoim polu kukurydzy odkrywa tajemnicze symbole. Początkowo bierze to za sprawkę któregoś z sąsiadów, ale szybko okazuje się, że znaki nie mogą być dziełem człowieka. W tym samym czasie telewizja podaje komunikaty o podobnych zdarzeniach w innych miejscach świata.', 'https://image.tmdb.org/t/p/w500/1c9Zh9l3QUgVQqntKfBBu8Q2DGC.jpg', 2675, 'tt0286106', 2, 0),
(265, 'Niezniszczalny', 'Unbreakable', 'Thriller, Dramat, Tajemnica', 2000, 7.1, 'M. Night Shyamalan', 106, 'English', 5, 75000000, 'Barry Mendel Productions, Blinding Edge Pictures, Touchstone Pictures', '', 18.99, 'Bruce Willis ("Szósty zmysł", "Armageddon") i Samuel L. Jackson ("Szklana pułapka 3", "Pulp Fiction") to odtwórcy głównych ról w tym trzymającym w napięciu, niezwykłym filmie sensacyjnym, który na długo pozostaje w pamięci. Film został wyreżyserowany przez M. Nighta Shyamalana - twórcę przeboju kinowego "Szósty zmysł". David Dunne (Willis) jako jedyny wychodzi cało, bez najmniejszego zadraśnięcia z potwornej katastrofy kolejowej, w której ginie 131 osób. Wkrótce po tym poznaje Elijaha Price''a (Jackson) twierdzącego, że zna wyjaśnienie jego tajemniczego ocalenia. To niezwykłe spotkanie zmusza Davida do stawienia czoła swemu przeznaczeniu w procesie odkrywania samego siebie, swych pragnień i wewnętrznej siły. "Niezniszczalny" to doskonały thriller, obfitujący w zaskakujące zwroty akcji, dający do myślenia i intrygujący.', 'https://image.tmdb.org/t/p/w500/gTJibKr1QnmfTCxaZmVlO9ITZZm.jpg', 9741, 'tt0217869', 2, 0),
(266, 'Split', 'Split', 'Horror, Thriller', 2017, 7.3, 'M. Night Shyamalan', 116, 'English', 6, 9000000, 'Blinding Edge Pictures, Blumhouse Productions', '', 10.99, 'Chociaż Kevin (James McAvoy) ujawnił swemu psychiatrze 23 różne tkwiące w nim osobowości, ciągle nie wiadomo, która z nich będzie zdolna ujawnić się i zdominować pozostałe. Zmuszony do uprowadzenia trzech nastolatek, Kevin toczy wojnę o przetrwanie z siłami naciskającymi go od wewnątrz - i wszystkim czynnikami zewnętrznymi - zanim ściany oddzielające wszystkie jego osobowości nie rozsypią się w proch.', 'https://image.tmdb.org/t/p/w500/62rCETfXaPtILmIfFtwm8mFQJMJ.jpg', 381288, 'tt4972582', 2, 0),
(267, 'Glass', 'Glass', 'Thriller, Dramat, Sci-Fi', 2019, 6.7, 'M. Night Shyamalan', 129, 'English', 7, 20000000, 'Blinding Edge Pictures, Blumhouse Productions, Perfect World Pictures', '', 17.99, 'Po wydarzeniach z filmu "Split", David Dunn (Bruce Willis) ściga nadludzkie wcielenie Kevina Wendella Crumba, znane jako Bestia (James McAvoy), w serii coraz bardziej dramatycznych starć. Okazuje się, że w sprawę jest zamieszany tajemniczy Elijah Price (Samuel L. Jackson), znany również jako Mr Glass, skrywający sekrety, które odmienią życie bohaterów na zawsze.', 'https://image.tmdb.org/t/p/w500/fFNWfVsW5e81SJ9dJpnw1IqV0SL.jpg', 450465, 'tt6823368', 2, 0),
(268, 'Szósty zmysł', 'The Sixth Sense', 'Tajemnica, Thriller, Dramat', 1999, 8.0, 'M. Night Shyamalan', 107, 'English', 8, 40000000, 'Spyglass Entertainment, The Kennedy/Marshall Company, Hollywood Pictures', '', 9.99, 'Do domu mieszkającego w Filadelfii psychiatry, dr. Malcolma Crowe’a (Bruce Willis), i jego żony Anny (Olivia Williams) włamuje się niezrównoważony psychicznie pacjent Vincent Gray (Donnie Wahlberg), który oskarża doktora o to, że nie potrafił udzielić mu pomocy. Strzela do niego, po czym odbiera sobie życie… Malcolm powoli dochodzi do siebie po zamachu. Jego uwagę zwraca przypadek Cole’a Seara (Haley Joel Osment). Psychiatra odkrywa, że ten ośmioletni chłopiec posiadł niezwykły dar, który pozwala mu komunikować się z umarłymi. Jak się wkrótce okaże, nie każdy dar natury jest błogosławieństwem…', 'https://image.tmdb.org/t/p/w500/8TIFz8j24cvDwptHJiacjCx25gT.jpg', 745, 'tt0167404', 2, 0),
(269, 'Osada', 'The Village', 'Dramat, Tajemnica, Thriller', 2004, 6.5, 'M. Night Shyamalan', 108, 'English', 9, 60000000, 'Touchstone Pictures, Blinding Edge Pictures, Scott Rudin Productions', '', 16.99, 'Jest rok 1897. Covington to mała wioska w Pensylwanii, otoczona lasami. Puszcze zamieszkują tajemnicze bestie. Pomiędzy ludźmi z Covington a mieszkańcami lasu istnieje niepisany pakt o nieagresji. Ludzie nie wchodzą do lasu, leśne stwory nie atakują wioski. Niestety, nie wszyscy są równie posłuszni w przestrzeganiu tego prawa. Młody Lucius za wszelką cenę stara się dowiedzieć, dlaczego właściwie nie wolno wejść do lasu i w końcu łamie zakaz. Następnego dnia po jego wyprawie poza granice wsi na drzwiach domów pojawiają się dziwne znaki.', 'https://image.tmdb.org/t/p/w500/hgeJnfpgwtCzwAu6fi2QtLhLGEQ.jpg', 6947, 'tt0368447', 2, 0),
(270, 'Matrix Reaktywacja', 'The Matrix Reloaded', 'Akcja, Thriller, Sci-Fi', 2003, 7.1, 'Lana Wachowski', 138, 'English', 10, 150000000, 'Village Roadshow Pictures, Silver Pictures, NPV Entertainment', '', 8.99, 'Kontynuacja kultowego "Matrixa". "Matrix Reaktywacja" zaczyna się w momencie, w którym kończyła się pierwsza część. Maszyny dokonały brzemiennego w skutkach odkrycia: poznały lokalizację Zion, ostatniego miasta ludzi, ukrytego w pobliżu jądra Ziemi. Za 72 godziny tysiące Strażników - kałamarnicowatych maszyn znanych z pierwszej części - przebiją się do miasta. Jedyną nadzieją ludzi jest odnalezienie tajemniczej postaci, znanej jako Twórca Kluczy, chronionej przez parę uzbrojonych w noże Bliźniaków, nienaturalnie białych zabójców, potrafiących znikać i pojawiać się jak duchy.', 'https://image.tmdb.org/t/p/w500/yCJHQznJDDWcf4jv2atttgBXrYa.jpg', 604, 'tt0234215', 2, 0),
(271, 'Matrix Rewolucje', 'The Matrix Revolutions', 'Akcja, Thriller, Sci-Fi', 2003, 6.8, 'Lana Wachowski', 129, 'English', 1, 150000000, 'Village Roadshow Pictures, NPV Entertainment, Silver Pictures', '', 15.99, 'W finale trylogii Matrix, Neo (Keanu Reeves) podejmuje kolejny krok w poszukiwaniu prawdy. To początek jego podróży do rzeczywistego świata i powstania Matrix. Jednak podróż miedzy światami wyczerpuje jego siły i rzuca na Ziemię Niczyją - między Świat Matrix, a Świat Maszyn. Trinity (Carrie-Ann Moss) czuwa nad Neo, który znalazł się w stanie śpiączki. W tym samym czasie Morfeusz (Laurence Fishburne) zmaga się z objawieniem, że Ten, komu zaufał, okazał się po prostu systemem sterowania wynalezionym przez architektów Matrix. Gdy Armia Maszyn próbuje zniszczyć Zion, jej obywatele organizują agresywną obronę. Czy będą w stanie prowadzić walkę z nieustraszonymi Wartownikami, aż Neo odzyska pełnię swoich mocy i zakończy wojnę?', 'https://image.tmdb.org/t/p/w500/4RPr1SWFodn1e1YL9thPGEpABOT.jpg', 605, 'tt0242653', 2, 0),
(272, 'Matrix Zmartwychwstania', 'The Matrix Resurrections', 'Sci-Fi, Akcja, Przygodowy', 2021, 6.3, 'Lana Wachowski', 148, 'English', 2, 190000000, 'Warner Bros. Pictures, Village Roadshow Pictures, Venus Castina Productions', '', 7.99, 'Podążaj za Neo, który prowadzi zwyczajne życie w San Francisco, gdzie jego terapeuta przepisuje mu niebieskie pigułki. Jednak Morfeusz oferuje mu czerwoną pigułkę i ponownie otwiera jego umysł na świat Matrix.', 'https://image.tmdb.org/t/p/w500/cS1Ka0C7cnVjfLIWv1JUeJlXUDd.jpg', 624860, 'tt10838180', 2, 0),
(273, 'Batman - Początek', 'Batman Begins', 'Dramat, Kryminał, Akcja', 2005, 7.7, 'Christopher Nolan', 140, 'English', 3, 150000000, 'Warner Bros. Pictures, DC, Syncopy', '', 14.99, '"Batman Początek", dzieło cenionego reżysera Christophera Nolana, odkrywa tajemnicę narodzin legendarnego Mrocznego Rycerza. Po tragicznej śmierci rodziców, rozczarowany życiem spadkobierca fortuny Wayne''ów, Bruce (Christian Bale), podróżuje po świecie szukając środków do walki z niesprawiedliwością po to, aby obrócić strach przeciw tym, którzy go sieją. Z pomocą zaufanego lokaja Alfreda (Michael Caine), detektywa Jima Gordona (Gary Oldman), oraz swego sprzymierzeńca Luciusa Foxa (Morgan Freeman), Wayne powraca do Gotham, aby powołać do życia swoje alter-ego: Batmana, zamaskowanego wojownika, który posługuje się siłą, intelektem i zaawansowaną bronią, aby zwalczać złowrogie siły, które zagrażają miastu.', 'https://image.tmdb.org/t/p/w500/cub46jQ4bLQYYbpbSL9Q24wofS2.jpg', 272, 'tt0372784', 2, 0),
(274, 'Mroczny Rycerz powstaje', 'The Dark Knight Rises', 'Akcja, Kryminał, Thriller', 2012, 7.8, 'Christopher Nolan', 165, 'English', 4, 250000000, 'Syncopy, Legendary Pictures, Warner Bros. Pictures', '', 6.99, 'Po upływie ośmiu lat od wydarzeń z "Mrocznego Rycerza" w Gotham panuje pokój. Dzięki Ustawie Denta udało się rozbić przestępczość zorganizowaną, a najgorszych złoczyńców osadzono w Blackgate. Mając świadomość, że stabilizacja oparta jest na kłamstwie, Bruce Wayne całkowicie wycofał się z życia publicznego. Teraz całe dnie spędza w swojej rezydencji, a Wayne Enterprises zaczyna podupadać. Uwagę Bruce''a wzbudza jednak Selina Kyle, sprytna i bezczelna włamywaczka, działająca według własnego kodeksu. Ciąg wydarzeń z jej udziałem sprawia, że komisarz Jim Gordon wpada na trop tajemniczego spisku i grupy najemników dowodzonych przez Bane''a, brutalnego terrorystę mającego powiązania z Ligą Cieni. Chcąc chronić miasto, Bruce decyduje się ponownie założyć kostium Batmana. Zagrożenie okazuje się jednak większe, niż ktokolwiek mógłby przypuszczać, a Mroczny Rycerz staje przed najtrudniejszym wyzwaniem w swoim życiu.', 'https://image.tmdb.org/t/p/w500/oWIhEWtHbSlvttp5qbBEutPOV7G.jpg', 49026, 'tt1345836', 2, 0),
(275, 'Batman', 'Batman', 'Fantasy, Akcja, Kryminał', 1989, 7.2, 'Tim Burton', 126, 'English', 5, 35000000, 'Warner Bros. Pictures, Polygram Pictures, The Guber-Peters Company', '', 13.99, 'W ponurym i ciemnym Gotham City pojawia się wielkie niebezpieczeństwo w postaci szalonego przestępcy Jokera (Jack Nicholson). Policja jest bezradna, tylko jeden człowiek może uratować miasto - kryjący się pod przebraniem nietoperza milioner Bruce Wayne (Michael Keaton). W jego staraniach pomaga mu młoda, atrakcyjna reporterka, Vicky Vale (Kim Basinger).', 'https://image.tmdb.org/t/p/w500/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', 268, 'tt0096895', 2, 0),
(276, 'Powrót Batmana', 'Batman Returns', 'Akcja, Fantasy', 1992, 7.0, 'Tim Burton', 126, 'English', 6, 80000000, 'Warner Bros. Pictures, Polygram Pictures', '', 5.99, 'Miasteczko Gotham opanowały groźne stwory: dziwaczny i zarazem przerażający Pingwin oraz zwinna i tajemnicza Kobieta-Kot. To właśnie tę parę musi pokonać Batman. Zadanie jest tym trudniejsze, iż nie sposób oprzeć się zniewalającemu urokowi Kobiety-Kota, a Pingwin wprowadza w czyn swe niecne plany.', 'https://image.tmdb.org/t/p/w500/8vf3nJzDK929Dp2du76D9FYBC0b.jpg', 364, 'tt0103776', 2, 0),
(277, 'Batman Forever', 'Batman Forever', 'Akcja, Kryminał, Fantasy', 1995, 5.5, 'Joel Schumacher', 121, 'English', 7, 100000000, 'Warner Bros. Pictures, Tim Burton Productions, Polygram Pictures', '', 12.99, '"Batman Forever" to trzecia już część przygód tajemniczego Człowieka-Nietoperza, w którego tym razem wcielił się Val Kilmer. Przed Batmanem pojawia się dość poważne wyzwanie - musi bowiem zmierzyć się z dwoma wyjątkowo niebezpiecznymi przeciwnikami. Człowiek - Dwie Twarze szukający zemsty za swoją zeszpeconą twarz, oraz jeden z najbardziej niebezpiecznych i tajemniczych przestępców - Człowiek-Zagadka połączeni są wspólnym celem zdobycia kontroli nad umysłami obywateli Gotham City i ostatecznego rozprawienia się z największym stróżem porządku.', 'https://image.tmdb.org/t/p/w500/i0fJS8M5UKoETjjJ0zwUiKaR8tr.jpg', 414, 'tt0112462', 2, 0),
(278, 'Batman i Robin', 'Batman & Robin', 'Akcja, Sci-Fi, Przygodowy', 1997, 4.4, 'Joel Schumacher', 125, 'English', 8, 125000000, 'Warner Bros. Pictures, Polygram Pictures', '', 19.99, 'Przeraźliwy chłód sparaliżował Gotham City. Znękane miasto ponownie staje w obliczu zagłady. Ostatnią nadzieją na ocalenie jest Batman. Gdy na nocnym niebie pojawia się znak nietoperza, Batman natychmiast rusza na pomoc w swoim potężnym, niesamowitym Batmobilu. Tym razem nie jest sam. Towarzyszy mu przyjaciel i pomocnik - Robin, który na swym turbo motocyklu podąża jak cień za pojazdem Batmana. To nie będzie łatwa walka. Mr Freeze ma do pomocy piękną, ale niebezpieczną istotę zadającą śmierć poprzez pocałunek - kobietę o mrożącym krew w żyłach przydomku - Trujący Bluszcz. Na szczęście naprzeciwko tej pary bezlitosnych zabójców stają Batman i Robin - teraz - uzbrojeni w nowoczesne, przemyślane, budzące respekt wroga przyrządy i pojazdy. W sukurs obrońcom przychodzi nowa postać - Batgirl - niezwykle sprawna i odważna dziewczyna. Ta wspaniała trójka bohaterów stanie w obronie Gotham City, które Mr Freeze planuje zamienić w skutą lodem pustynię...', 'https://image.tmdb.org/t/p/w500/i7hEUpDuMN2LOrCEifFyGSHZQSY.jpg', 415, 'tt0118688', 2, 0),
(279, 'Batman', 'The Batman', 'Kryminał, Tajemnica, Thriller', 2022, 7.7, 'Matt Reeves', 177, 'English', 9, 185000000, '6th & Idaho Motion Picture Company, Dylan Clark Productions, DC Films', '', 11.99, 'Dwa lata pod postacią Batmana i strach w sercach kryminalistów sprawiły, że Bruce Wayne ujrzał najmroczniejsze oblicze Gotham City. Mając u boku jedynie garstkę zaufanych sojuszników - w tym Alfreda Pennywortha i porucznika Jamesa Gordona - i występując przeciwko sitwie skorumpowanych urzędników oraz osobistości, samotny mściciel stał się w mniemaniu obywateli miasta jedynym obrońcą sprawiedliwości. Nieznany zabójca w sadystyczny i wyrachowany sposób nęka elitę Gotham. Największy Detektyw Świata, kierując się zaszyfrowanymi wiadomościami, trafia do półświatka. Tam w trakcie swojego śledztwa spotyka takie postacie jak Selina Kyle, zwana Kobietą-Kot, Oswald Cobblepot, czyli Pingwin, Carmine Falcone i Edward Nashton, aka Człowiek-Zagadka. Wreszcie dowody zaczynają się konkretyzować, a zamiary sprawcy stają się jasne. Batman zostaje zmuszony do szukania nowych sprzymierzeńców, żeby zdemaskować winowajcę i położyć kres nadużywaniu władzy i korupcji, od dawna nękających Gotham City.', 'https://image.tmdb.org/t/p/w500/qpqCvFzHH8GfAteK4pkuT4Hwlhi.jpg', 414906, 'tt1877830', 2, 0),
(280, 'Joker', 'Joker', 'Kryminał, Thriller, Dramat', 2019, 8.1, 'Todd Phillips', 122, 'English', 10, 55000000, 'Warner Bros. Pictures, Joint Effort, Village Roadshow Pictures', '', 18.99, 'Historia jednego z cieszących się najgorszą sławą super-przestępców uniwersum DC — Jokera po raz pierwszy na wielkim ekranie. Przedstawiony przez Phillipsa obraz kultowego czarnego charakteru, Arthura Flecka, człowieka zepchniętego na margines, to nie tylko kontrowersyjne studium postaci, ale także opowieść ku przestrodze w szerszym kontekście.', 'https://image.tmdb.org/t/p/w500/opwCl56Zi8mextLETtM3d0ryVFU.jpg', 475557, 'tt7286456', 2, 0),
(281, 'Legion samobójców', 'Suicide Squad', 'Akcja, Przygodowy, Fantasy', 2016, 5.9, 'David Ayer', 130, 'English', 1, 175000000, 'Warner Bros. Pictures, RatPac Entertainment, DC Films', '', 10.99, 'Jak dobrze być złym… Zebrać drużynę złożoną z najbardziej niebezpiecznych pojmanych super przestępców. Następnie przekazać im najpotężniejszą broń, jaką dysponuje rząd. Wreszcie wysłać ich na misję, której celem jest pokonanie tajemniczego, nieprzeniknionego bytu. Amanda Waller (Viola Davis), oficer amerykańskiego wywiadu, doszła do wniosku, że do takiego zadania nada się jedynie zbieranina łotrów, którzy nie mają absolutnie nic do stracenia. Co zrobi Legion Samobójców, gdy jego członkowie zorientują się, że nie zostali wybrani dlatego, iż mają szansę wygrać, ale dlatego, że nikt nie będzie ich żałował, gdy poniosą klęskę? Czy dadzą z siebie wszystko, choćby mieli zginąć, czy będą walczyć o własne przetrwanie?', 'https://image.tmdb.org/t/p/w500/bGQUfteR5CuVUdsTthlLyyKOFsO.jpg', 297761, 'tt1386697', 2, 0),
(282, 'Legion samobójców: The Suicide Squad', 'The Suicide Squad', 'Akcja, Komedia, Przygodowy', 2021, 7.4, 'James Gunn', 132, 'English', 2, 185000000, 'DC Films, Atlas Entertainment, The Safran Company', '', 17.99, 'Władze wysyłają największych superzłoczyńców świata – Bloodsporta, Peacemakera, King Sharka i Harley Quinn na odległą, pełną wrogów wyspę Corto Maltese. Wyposażeni w zaawansowaną technologicznie broń, przemierzają niebezpieczną dżunglę, by odszukać i zniszczyć cel. Grupę łotrów może ujarzmić jedynie towarzyszący im pułkownik Rick Flag. Jak zwykle, wystarczy jeden zły ruch by zginąć. Gdyby ktoś miał się zakładać, to rozsądek nakazywałby nigdy na nich nie stawiać!', 'https://image.tmdb.org/t/p/w500/f3simt2nobpDrv44MoRQSFpuyJa.jpg', 436969, 'tt6334354', 2, 0),
(283, 'Ptaki Nocy (i fantastyczna emancypacja pewnej Harley Quinn)', 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'Akcja, Kryminał', 2020, 6.9, 'Cathy Yan', 109, 'English', 3, 75000000, 'Warner Bros. Pictures, DC Films, LuckyChap Entertainment', '', 9.99, 'A znacie to o policjantce, kanarku, wariatce i mafijnej księżniczce? Ptaki Nocy (i fantastyczna emancypacja pewnej Harley Quinn) to pokręcona historia, opowiadana przez samą Harley w stylu, w jakim tylko ona może ją opowiedzieć. Kiedy najbardziej narcystyczny z bandziorów Gotham, Roman Sionis, i jego oddana prawa ręka Zsasz biorą na cel niejaką Cass, w poszukiwania dziewczyny angażuje się całe miasto. Nieprawdopodobny zbieg okoliczności krzyżuje drogi Harley, Łowczyni, Czarnego Kanarka i Renee Montoyi. Cztery diametralnie różniące się kobiety nie mają wyjścia. Muszą współpracować, żeby pokonać Romana.', 'https://image.tmdb.org/t/p/w500/l1lqkLFryH8jzJNTWOesE88tsUM.jpg', 495764, 'tt7713068', 2, 0),
(284, 'Wonder Woman 1984', 'Wonder Woman 1984', 'Akcja, Przygodowy, Fantasy', 2020, 6.3, 'Patty Jenkins', 151, 'English', 4, 200000000, 'Warner Bros. Pictures, The Stone Quarry, DC Films', '', 16.99, 'Losy świata ponownie są zagrożone i tylko Wonder Woman może je uratować. Rozpoczyna się nowy rozdział w jej historii, a tymczasem Diana Prince wiedzie spokojne życie wśród śmiertelników w latach 80. XX wieku. Chociaż główna bohaterka dysponuje już pełnią mocy, nadal pozostaje w cieniu, opiekując się starożytnymi artefaktami. Teraz jednak Diana jest zmuszona wyjść z ukrycia i wykorzystać całą swoją mądrość, aby ocalić ludzi przed światem, który sami stworzyli.', 'https://image.tmdb.org/t/p/w500/lUfpvTcfeh0FdWQoIX5ScZjkQhl.jpg', 464052, 'tt7126948', 2, 0),
(285, 'Aquaman', 'Aquaman', 'Akcja, Przygodowy, Fantasy', 2018, 6.9, 'James Wan', 143, 'English', 5, 160000000, 'The Safran Company, Warner Bros. Pictures, DC Films', '', 8.99, 'Władca jednej z siedmiu podwodnych krain – król Orm (Patrick Wilson) – chce zjednoczyć wszystkie królestwa Atlantydy, aby raz na zawsze zniszczyć ludzi żyjących na powierzchni. Obwinia ich za niszczenie środowiska naturalnego i co za tym idzie – zatruwanie niewinnych obywateli Atlantydy. Na drodze króla staje jego przyrodni brat Arthur (Jason Momoa), znany powszechnie jako Aquaman. Razem z księżniczką Merą (Amber Heard) poszukuje on niezwykłego trójzębu, który może uchronić świat przed wybuchem krwawej wojny.', 'https://image.tmdb.org/t/p/w500/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', 297802, 'tt1477834', 2, 0),
(286, 'Aquaman i Zaginione Królestwo', 'Aquaman and the Lost Kingdom', 'Akcja, Przygodowy, Fantasy', 2023, 6.5, 'James Wan', 124, 'English', 6, 205000000, 'Warner Bros. Pictures, The Safran Company, Atomic Monster', '', 15.99, 'Poprzednio Czarna Manta nie zdołał pokonać Aquamana. Wciąż jednak pragnie pomścić śmierć ojca i dlatego nie cofnie się przed niczym, żeby rozprawić się z Aquamanem raz na zawsze. Tym razem Czarna Manta jest potężniejszy niż dotąd. Posiadł moc mitycznego Czarnego Trójzęba, który kryje w sobie starożytną i złowrogą siłę. Aby go pokonać, Aquaman nieoczekiwanie prosi o pomoc Orma, swojego uwięzionego brata i poprzedniego króla Atlantydy. Obaj muszą zapomnieć o różnicach, żeby ochronić królestwo oraz ocalić rodzinę Aquamana i cały świat przed nieodwracalnym zniszczeniem.', 'https://image.tmdb.org/t/p/w500/gtSJ54lMuSf7OMAYAlnlXoBZwzm.jpg', 572802, 'tt9663764', 2, 0),
(287, 'Flash', 'The Flash', 'Akcja, Sci-Fi, Przygodowy', 2023, 6.6, 'Andy Muschietti', 144, 'English', 7, 220000000, 'Warner Bros. Pictures, Double Dream, The Disco Factory', '', 7.99, 'Barry używa swojej mocy do podróży w czasie, żeby zmienić wydarzenia z przeszłości. Kiedy jednak próbuje ocalić rodzinę, mimowolnie zmienia przyszłość. Barry zostaje więźniem rzeczywistości, w której generał Zod powraca i grozi powszechnym zniszczeniem. W tym świecie nie ma jednak żadnych superbohaterów, do których można by się zwrócić. Jedyną nadzieją Barry’ego na uratowanie świata, w którym przebywa i na powrót do przyszłości, którą zna, pozostaje wyścig o życie. Tylko czy ostateczne poświęcenie wystarczy do przywrócenia dawnego biegu wydarzeń?', 'https://image.tmdb.org/t/p/w500/3XRtipuOH8Kl25bXIoeGyzdtFfl.jpg', 298618, 'tt0439572', 2, 0),
(288, 'Shazam!', 'Shazam!', 'Akcja, Komedia, Fantasy', 2019, 7.0, 'David F. Sandberg', 132, 'English', 8, 80000000, 'New Line Cinema, The Safran Company, Seven Bucks Productions', '', 14.99, 'Każdy ma w sobie superbohatera. Potrzeba jedynie odrobinę magii, aby go wydobyć. W przypadku Billy’ego Batsona (Asher Angel) wystarczy wypowiedzieć jedno słowo — SHAZAM. Wówczas ten cwany 14-letni sierota zmienia się w dorosłego superbohatera Shazama (Zachary Levi), a wszystko za sprawą starożytnego czarodzieja. Shazam, który w głębi duszy nadal jest dzieckiem — choć zamkniętym w umięśnionym ciele herosa — wykorzystuje swoją dorosłą powłokę tak, jak zrobiłby to każdy nastolatek z supermocami — do zabawy! Czy umie latać? Czy może prześwietlać wzrokiem? Czy potrafi ciskać piorunami? Czy może się nie pojawić na sprawdzianie z WOS-u? Shazam poznaje swoje możliwości i ograniczenia z radosnym nieskrępowaniem dziecka. Jednak będzie zmuszony szybko okiełznać supermoce, aby stawić czoła zabójczym siłom zła kontrolowanym przez dr Thaddeusa Sivanę (Mark Strong).', 'https://image.tmdb.org/t/p/w500/sDS1bkrQSnrHGFk4fYMkTgH1IrC.jpg', 287947, 'tt0448115', 2, 0),
(289, 'Shazam! Gniew bogów', 'Shazam! Fury of the Gods', 'Komedia, Akcja, Fantasy', 2023, 6.4, 'David F. Sandberg', 130, 'English', 9, 110000000, 'The Safran Company, New Line Cinema, DC Films', '', 6.99, 'Billy Batson, który staje się superbohaterem po wypowiedzeniu słowa "Shazam!", razem z przybranym rodzeństwem próbuje powstrzymać trzy boginie przed użyciem artefaktu zdolnego zniszczyć świat.', 'https://image.tmdb.org/t/p/w500/dLHr6H7r4vCXvCCLNgBYt70HD2f.jpg', 594767, 'tt10151854', 2, 0),
(290, 'Black Adam', 'Black Adam', 'Akcja, Przygodowy, Sci-Fi', 2022, 6.7, 'Jaume Collet Serra', 125, 'English', 10, 200000000, 'New Line Cinema, Flynn Picture Company, DC Films', '', 13.99, 'Prawie 5000 lat po otrzymaniu olbrzymich mocy starożytnych bogów – i prawie równoczesnym uwięzieniu - Black Adam (Dwayne Johnson) zostaje uwolniony z ziemskiego grobowca. Teraz jest gotów wymierzyć współczesnemu światu osobliwie pojmowaną sprawiedliwość.', 'https://image.tmdb.org/t/p/w500/grWtpyxmIVv5HY0ZXt233OrbHW.jpg', 436270, 'tt6443346', 2, 0),
(291, 'Logan: Wolverine', 'Logan', 'Akcja, Dramat, Sci-Fi', 2017, 7.8, 'James Mangold', 137, 'English', 1, 97000000, 'Hutch Parker Entertainment, The Donners'' Company, Genre Films', '', 5.99, 'Niedaleka przyszłość. Populacja mutantów skurczyła do kilku osobników. Zmęczony życiem Logan (Hugh Jackman) opiekuje się schorowanym Profesorem X (Patrick Stewart) w kryjówce przy granicy meksykańskiej. Pewnego dnia nieznajoma prosi by zaopiekował się Laurą (Dafne Keen) - młodą mutantką ściganą przez tajemniczą organizację. Czy Logan da radę ochronić dziewczynę, z którą ma więcej wspólnego niż mu się wydaje?', 'https://image.tmdb.org/t/p/w500/ip5AqhwGwejycet34T7I6lTPp88.jpg', 263115, 'tt3315342', 2, 0),
(292, 'X-Men', 'X-Men', 'Przygodowy, Akcja, Sci-Fi', 2000, 7.0, 'Bryan Singer', 104, 'English', 2, 75000000, 'The Donners'' Company, Bad Hat Harry Productions, 20th Century Fox', '', 12.99, 'Przyszli na świat w świecie pełnym uprzedzeń i nienawiści. Na skutek mutacji genetycznej posiadają niezwykłe zdolności i potężną moc. Cyklop może emitować wiązki energii o ogromnej sile rażenia. Sztorm może kontrolować warunki pogodowe i zmieniać klimat. Ruda pochłania siły życiowe i wspomnienia każdego, kogo dotknie. W szkole profesora Xaviera - potężnego telepaty uczą się jak kontrolować i wykorzystywać swoje moce dla dobra całej ludzkości. Teraz muszą stawić czoła największemu wrogowi - Magneto, który dysponując ogromną mocą odwrócił się od społeczeństwa, wierząc, że niemożliwe jest pokojowe współistnienie ludzi i mutantów. Magneto nie cofnie się przed niczym, by dowieść słuszności swoich przekonań, nawet, gdy zagrożona zostanie przyszłość całego rodzaju ludzkiego... i nie tylko ludzkiego.', 'https://image.tmdb.org/t/p/w500/bRDAc4GogyS9ci3ow7UnInOcriN.jpg', 36657, 'tt0120903', 2, 0),
(293, 'X-Men 2', 'X2', 'Przygodowy, Akcja, Sci-Fi', 2003, 7.0, 'Bryan Singer', 133, 'English', 3, 110000000, 'The Donners'' Company, Bad Hat Harry Productions, 20th Century Fox', '', 19.99, 'Wzrasta napięcie w stosunkach pomiędzy mutantami, a ludźmi. Do zaostrzenia konfliktu przyczynia się bezprecedensowy atak mutanta na Prezydenta Stanów Zjednoczonych. W jego wyniku Prezydent udziela specjalnych uprawnień generałowi Williamowi Strykerowi (Brian Cox), który wypowiada wojnę mutantom; wojnę, którą przetrwać może tylko jedna rasa... zwycięzców. Xavier (Patrick Stewart), Wolverine (Hugh Jackman), Storm (Halle Berry) i inni X-Meni muszą zjednoczyć siły ze swym starym wrogiem – Magneto (Ian McKellen), aby zapobiec niebezpiecznej konfrontacji, która może doprowadzić do zniszczenia wszystkich.', 'https://image.tmdb.org/t/p/w500/bst4alFUXCxISwdRUKSMhhkrX1M.jpg', 36658, 'tt0290334', 2, 0),
(294, 'X-Men: Pierwsza klasa', 'X-Men: First Class', 'Akcja, Sci-Fi, Przygodowy', 2011, 7.3, 'Matthew Vaughn', 132, 'English', 4, 160000000, 'The Donners'' Company, Bad Hat Harry Productions, 20th Century Fox', '', 11.99, 'Widowiskowy film akcji, ukazujący początki epickiej sagi X-Men. Zanim Charles Xavier (James McAvoy) i Erik Lensherr (Michael Fassbender) przybrali imiona Profesor X i Magneto, byli młodymi ludźmi, którzy odkryli w sobie niezwykłe moce. Nim zostali zaciętymi wrogami, byli bliskimi przyjaciółmi, którzy połączyli swe siły z innymi Mutantami, aby zapobiec największemu zagrożeniu, przed którym stanął świat. Wkrótce jednak rozdzielił ich konflikt, który doprowadził do wybuchu wiecznej wojny między Bractwem skupionym wokół Magneto a grupą X-Men, której przewodził Profesor X.', 'https://image.tmdb.org/t/p/w500/tsSfNhNcAMfdYomg4zAIFQl4RG5.jpg', 49538, 'tt1270798', 2, 0),
(295, 'X-Men: Przeszłość, która nadejdzie', 'X-Men: Days of Future Past', 'Akcja, Przygodowy, Sci-Fi', 2014, 7.5, 'Bryan Singer', 131, 'English', 5, 250000000, 'Bad Hat Harry Productions, The Donners'' Company, 20th Century Fox', '', 18.99, 'W niedalekiej przyszłości pozostali przy życiu mutanci są nieustannie tropieni przez Strażników. Zdesperowani profesor X (Patrick Stewart) i Magneto (Ian McKellen) układają desperacki plan zakończenia wojny jeszcze przed jej wybuchem. Przy pomocy mutantki Kitty (Ellen Page) świadomość Wolverine''a (Hugh Jackman) zostaje przeniesiona do jego młodszego ciała w 1973 roku. Logan ma powstrzymać Mystique (Jennifer Lawrence) przed zabiciem doktora Bolivara Traska (Peter Dinklage), którego śmierć spowodowała wdrożenie programu Strażników. Aby tego dokonać, Wolverine musi namówić pogrążonego w bólu po stracie najbliższych młodego Charlesa Xaviera (James McAvoy) do podjęcia współpracy z Erikiem Lehnsherrem (Michael Fassbender), który obecnie, skazany za zabójstwo prezydenta, jest więziony w najpilniej strzeżonym budynku na świecie.', 'https://image.tmdb.org/t/p/w500/zetFjQcXe9iwGOvQDVHgICrtk7o.jpg', 127585, 'tt1877832', 2, 0),
(296, 'Deadpool 2', 'Deadpool 2', 'Akcja, Komedia, Przygodowy', 2018, 7.5, 'David Leitch', 119, 'English', 6, 110000000, 'Maximum Effort, Genre Films, 20th Century Fox', '', 10.99, 'Oszpecony w wyniku śmiertelnie groźnego ataku bydła podkuchenny ze stołówki zakładowej Wade Wilson (Ryan Reynolds) nie cofnie się przed niczym, by spełnić największe marzenie swego życia – chce zostać wybrany najseksowniejszym barmanem miejscowej sieci barów mlecznych i udowodnić, że jeszcze się taki nie narodził, który mógłby mu nadmuchać w kakao. Walczy przy tym o odzyskanie utraconego poczucia smaku i skradzionego kondensatora strumienia, stawiając czoło wojownikom ninja, japońskim gangsterom spod znaku Yakuzy i sforze agresywnych seksualnie czworonogów. Przemierzając kulę ziemską, odkrywa siłę rodziny, przyjaźni i pikantny smak przygody, a przy okazji zdobywa pożądany puchar dla Najlepszego Kochanka Świata.', 'https://image.tmdb.org/t/p/w500/gyfPKfFYcVW54MoqhYlwwDDIfJR.jpg', 383498, 'tt5463162', 2, 0),
(297, 'Deadpool & Wolverine', 'Deadpool & Wolverine', 'Akcja, Komedia, Sci-Fi', 2024, 7.6, 'Shawn Levy', 128, 'English', 7, 556800000, 'Marvel Studios, Maximum Effort, 21 Laps Entertainment', '', 17.99, 'Dochodzacy do siebie Wolverine spotyka pyskatego Deadpoola, z którym łączy siły, by stawić czoła wspólnemu wrogowi.', 'https://image.tmdb.org/t/p/w500/7Hi6mRLsQtTaEtKiHqSeRFR1TQ2.jpg', 533535, 'tt6263850', 2, 0),
(298, 'Superman', 'Superman', 'Sci-Fi, Akcja, Przygodowy', 1978, 7.2, 'Richard Donner', 143, 'English', 8, 55000000, 'Dovemead Films, Alexander and Ilya Salkind Productions, International Film Production', '', 9.99, 'Superman jest obdarzony nadludzkimi mocami przybyszem z planety Krypton, który na co dzień wciela się w Clarka Kenta, skromnego dziennikarza z popularnej gazety. Nadchodzi jednak czas, gdy musi zmierzyć się ze swym największym wrogiem - Lexem Luthorem, złoczyńcą, który pragnie przejąć władzę nad światem.', 'https://image.tmdb.org/t/p/w500/d7px1FQxW4tngdACVRsCSaZq0Xl.jpg', 1924, 'tt0078346', 2, 0),
(299, 'Człowiek ze stali', 'Man of Steel', 'Akcja, Przygodowy, Sci-Fi', 2013, 6.7, 'Zack Snyder', 143, 'English', 9, 225000000, 'Syncopy, Peters Entertainment, Warner Bros. Pictures', '', 16.99, 'W wyniku poszukiwań zastępczych źródeł energii jądro planet Krypton ulega destabilizacji. Świat zostaje skazany na zagładę. Świadomy tego naukowiec Jor-El (Russell Crowe) chce za wszelką cenę zapewnić przetrwanie swojemu ludowi. Wbrew woli prowadzącego właśnie wojnę domową generała Zoda (Michael Shannon) umieszcza swojego nowo narodzonego synka Kal-Ela w statku ratunkowym i wysyła go na odległą Ziemię. Chłopiec trafia na farmę w Kansas, gdzie przygarniają go Jonathan (Kevin Costner) i Martha (Diane Lane) Kentowie. Po wielu latach dorosły już Clark (Henry Cavill) opuszcza dom przybranych rodziców i rusza na poszukiwania swojej tożsamości. Kiedy ścigający go Zod przybywa na Ziemię, Clark musi dokonać wyboru - pozostać w ukryciu, czy też ujawnić swoje nadzwyczajne moce i stać się symbolem nadziei dla całej ludzkości.', 'https://image.tmdb.org/t/p/w500/qj40hZtRF8T98NANC9zsrDQHf3v.jpg', 49521, 'tt0770828', 2, 0),
(300, 'Batman v Superman: Świt sprawiedliwości', 'Batman v Superman: Dawn of Justice', 'Akcja, Przygodowy, Fantasy', 2016, 6.0, 'Zack Snyder', 151, 'English', 10, 250000000, 'Warner Bros. Pictures, RatPac Entertainment, Atlas Entertainment', '', 8.99, 'W obawie przed poczynaniami nieposkromionego superbohatera o boskich rysach i zdolnościach, najznamienitszy obywatel Gotham City, a zarazem zaciekły strażnik porządku, staje do walki z otaczanym czcią współczesnym wybawcą Metropolis, podczas gdy świat usiłuje ustalić, jakiego bohatera naprawdę potrzebuje. Wobec konfliktu, który rozgorzał między Batmanem i Supermanem, na horyzoncie szybko pojawia się nowy wróg, stawiając ludzkość w obliczu śmiertelnego niebezpieczeństwa, z jakim jeszcze nigdy nie musiała się mierzyć.', 'https://image.tmdb.org/t/p/w500/qWbkT5MJc5NuwZq96OAUmDq5SM2.jpg', 209112, 'tt2975590', 2, 0),
(301, 'Hobbit: Niezwykła podróż', 'The Hobbit: An Unexpected Journey', 'Przygodowy, Fantasy, Akcja', 2012, 7.4, 'Peter Jackson', 169, 'English', 1, 250000000, 'New Line Cinema, Metro-Goldwyn-Mayer, WingNut Films', '', 15.99, 'Akcja rozgrywa się na 77 lat przed wydarzeniami z "Władcy Pierścieni", opowiada historię niziołka Bilba Bagginsa, który za namową czarodzieja Gandalfa i krasnoluda Thorina Dębowej Tarczy wyrusza, aby pomóc w znalezieniu Arcykamienia Thraina, starożytnego skarbu krasnoludzkich władców. Towarzyszy im kompania Thorina składająca się z dwunastu przedstawicieli jego rasy. Cała drużyna przemierza Mgliste Góry, gdzie Bilbo wchodzi w posiadanie tajemniczego artefaktu, stacza niezliczoną ilość bitew ze stworami Śródziemia, by w końcu dotrzeć do celu, Samotnej Góry, w której Arcykamienia, jak i innych skarbów, broni Smaug, największy smok swoich czasów.', 'https://image.tmdb.org/t/p/w500/z8QVNWqPxJQtOUIz5zEZBIJ28cF.jpg', 49051, 'tt0903624', 2, 0),
(302, 'Hobbit: Pustkowie Smauga', 'The Hobbit: The Desolation of Smaug', 'Fantasy, Przygodowy, Akcja', 2013, 7.6, 'Peter Jackson', 161, 'English', 2, 250000000, 'New Line Cinema, Metro-Goldwyn-Mayer, WingNut Films', '', 7.99, 'Hobbit Bilbo Baggins, Czarodziej Gandalf i Trzynastu Krasnoludów pod wodzą Thorina Dębowej Tarczy, kontynuują wyprawę, której celem jest odzyskanie Ereboru - Królestwa Krasnoludów. W czasie podróży spotkają niedźwiedzia-wojownika Beorna, gigantyczne Pająki z Mrocznej Puszczy, Leśne Elfy dowodzone przez Legolasa, Taurielę i Króla Thranduila oraz tajemniczego łucznika zwanego Bardem, który przemyca ich do Miasta Na Jeziorze. Kiedy wreszcie ujrzą Samotną Górę staną twarzą w twarz z największym niebezpieczeństwem - Smokiem Smaugiem.', 'https://image.tmdb.org/t/p/w500/5w2MGDc5lX3jCqfD11hXkqLLcqQ.jpg', 57158, 'tt1170358', 2, 0),
(303, 'Hobbit: Bitwa Pięciu Armii', 'The Hobbit: The Battle of the Five Armies', 'Akcja, Przygodowy, Fantasy', 2014, 7.3, 'Peter Jackson', 144, 'English', 3, 250000000, 'New Line Cinema, Metro-Goldwyn-Mayer, WingNut Films', '', 14.99, 'Filmowa adaptacja książki J.R.R. Tolkiena, będącej wstępem do słynnego "Władcy Pierścieni", to opowieść pełna niesamowitych wydarzeń i magicznych postaci. Przedstawia odwieczną walkę dobra ze złem. Po wielkim sukcesie pierwszych dwóch części trylogii – "Hobbit: Niezwykła podróż" oraz "Hobbit: Pustkowie Smauga", nadszedł czas na film zamykający niezwykłe dzieło Petera Jacksona: "Hobbit: Bitwa Pięciu Armii". Drużyna dowodzona przez Thorina Dębową Tarczę dotarła do Samotnej Góry, której skarbu strzeże potężny Smaug. Czy Bilbo i jego towarzysze pokonają smoka i odzyskają legendarny Erebor?', 'https://image.tmdb.org/t/p/w500/m3Lfi8084o3oGrbJ3oGJvToM2no.jpg', 122917, 'tt2310332', 2, 0),
(304, 'Fantastyczne zwierzęta i jak je znaleźć', 'Fantastic Beasts and Where to Find Them', 'Fantasy, Przygodowy', 2016, 7.3, 'David Yates', 133, 'English', 4, 180000000, 'Heyday Films, Warner Bros. Pictures', '', 6.99, 'Akcja filmu Fantastyczne zwierzęta i jak je znaleźć rozpoczyna się w 1926 roku. Newt Scamander wraca z wielkiej wyprawy, której celem było odnalezienie i opisanie szeregu fantastycznych zwierząt. Jego krótki pobyt w Nowym Jorku mógłby przejść niezauważony, gdyby nie pewien nie-czar (tj. amerykański mugol) o imieniu Jakub, źle skierowany magiczny przypadek oraz ucieczka kilku fantastycznych zwierząt Newta. Wszystko to może spowodować nie lada kłopoty, zarówno dla świata magicznego, jak i nie-czarów.', 'https://image.tmdb.org/t/p/w500/oAIktujv5vc76oNX3VVxt9Ep9O2.jpg', 259316, 'tt3183660', 2, 0),
(305, 'Fantastyczne zwierzęta: Zbrodnie Grindelwalda', 'Fantastic Beasts: The Crimes of Grindelwald', 'Fantasy, Przygodowy', 2018, 6.8, 'David Yates', 134, 'English', 5, 200000000, 'Warner Bros. Pictures, Heyday Films', '', 13.99, 'Akcja filmu, do którego scenariusz napisała J.K. Rowling, rozpoczyna się w 1927 r., kilka miesięcy po tym, jak Newt pomógł zdemaskować i schwytać niesławnego czarnoksiężnika Gellerta Grindelwalda. Ten dotrzymał danego wcześniej słowa i uciekł w dramatycznych okolicznościach. Cały czas gromadzi nowych zwolenników swojej sprawy — wyniesienia czarodziejów ponad wszystkie niemagiczne istoty. Jedyną osobą będącą w stanie go powstrzymać jest czarodziej, którego niegdyś uważał za swojego najlepszego przyjaciela — Albus Dumbledore. Jednak Dumbledore nie obejdzie się bez pomocy swojego byłego ucznia Newta Scamandera, któremu już raz udało się pokrzyżować plany Grindelwaldowi. Przygoda ponownie splata losy Newta, Tiny, Queenie i Jacoba. Jednak misja ta będzie także sprawdzianem ich lojalności, kiedy będą stawiali czoła nowym zagrożeniom w coraz bardziej niebezpiecznym i podzielonym świecie czarodziejów.', 'https://image.tmdb.org/t/p/w500/bumdgx8EeG8wTB0ZDLmt06rrcBB.jpg', 338952, 'tt4123430', 2, 0),
(306, 'Fantastyczne zwierzęta: Tajemnice Dumbledore''a', 'Fantastic Beasts: The Secrets of Dumbledore', 'Fantasy, Przygodowy', 2022, 6.6, 'David Yates', 142, 'English', 6, 200000000, 'Warner Bros. Pictures, Heyday Films', '', 5.99, 'Profesor Albus Dumbledore wie, że potężny i zły czarodziej Gellert Grindelwald zamierza zawładnąć światem czarodziejów. Nie mogąc powstrzymać go w pojedynkę, powierza to zadanie magizoologowi Newtowi Skamanderowi. Staje on na czele nieustraszonej drużyny, złożonej z czarodziejów, czarodziejek i jednego dzielnego mugolskiego piekarza. W niebezpiecznej misji natkną się oni na znane już i nowe zwierzęta oraz staną do walki z coraz liczniejszymi zastępami zwolenników Grindelwalda. Ale jak długo Dumbledore będzie trzymał się z boku, skoro stawka jest tak wielka?', 'https://image.tmdb.org/t/p/w500/ge05wzFdHFBfiqCV6F5SVbx3aZ5.jpg', 338953, 'tt4123432', 2, 0),
(307, 'Piraci z Karaibów. Klątwa Czarnej Perły', 'Pirates of the Caribbean: The Curse of the Black Pearl', 'Przygodowy, Fantasy, Akcja', 2003, 7.8, 'Gore Verbinski', 143, 'English', 7, 140000000, 'Walt Disney Pictures, Jerry Bruckheimer Films', '', 12.99, 'Karaiby, wiek XVIII. Beztroskie, wręcz idylliczne, pirackie życie pełnego zawadiackiego wdzięku Kapitana Jacka Sparrowa (Johnny Depp), wali się w gruzy, gdy dosięga go ręka Nemesis w osobie przebiegłego i podstępnego Kapitana Barbossy (Geoffrey Rush), który ukradł wcześniej jego statek Czarną Perłę. Barbossa atakuje miasto Port Royal i porywa córkę gubernatora, piękną Elizabeth (Keira Knightley). Sparrow zawiera sojusz z Willem Turnerem (Orlando Bloom), zdeterminowanym, by uratować ukochaną i razem ruszają w pościg za Czarną Perłą na skradzionym, najszybszym okręcie brytyjskiej floty. Will nie wie jednak, że na kapitanie Barbossie i całej jego załodze ciąży straszliwa klątwa związana z ukrytym skarbem.', 'https://image.tmdb.org/t/p/w500/uqReraSvOaQXLkFp3TjqQQT2daf.jpg', 22, 'tt0325980', 2, 0),
(308, 'Piraci z Karaibów. Skrzynia umarlaka', 'Pirates of the Caribbean: Dead Man''s Chest', 'Przygodowy, Fantasy, Akcja', 2006, 7.4, 'Gore Verbinski', 150, 'English', 8, 200000000, 'Walt Disney Pictures, Jerry Bruckheimer Films, Second Mate Productions', '', 19.99, 'Jedyny w swoim rodzaju pirat - kapitan Jack Sparrow (Johnny Depp) powraca z kolejnym krwawym długiem do spłacenia. Ofiarował bowiem swoją duszę legendarnemu Davy Jonesowi (Bill Nighy), niesamowitemu władcy podmorskich głębin, który teraz domaga się swej własności. Jack krzyżuje matrymonialne plany Willa Turnera (Orlando Bloom) i jego pięknej narzeczonej Elizabeth Swann (Keira Knightley), którzy za sprawą nieszczęśliwych zbiegów okoliczności zostają rzuceni w wir przerażającej przygody. Sparrow naraża życie swoich przyjaciół, aby odzyskać klucz i znaleźć skrzynię umarlaka w której ukryte jest coś, co ma uratować życie kapitana. Nie jest to jednak proste zadanie, gdyż cały czas ściga ich Kraken - legendarny potwór zamieszkujący oceany.', 'https://image.tmdb.org/t/p/w500/bzxQf3bPoEbPjsBj6MTSOjM7zxz.jpg', 58, 'tt0383574', 2, 0),
(309, 'Piraci z Karaibów. Na krańcu świata', 'Pirates of the Caribbean: At World''s End', 'Przygodowy, Fantasy, Akcja', 2007, 7.3, 'Gore Verbinski', 169, 'English', 9, 300000000, 'Jerry Bruckheimer Films, Second Mate Productions, Walt Disney Pictures', '', 11.99, 'Zawadiacki błysk w oku nie pomoże szarmanckiemu kapitanowi Jackowi Sparrowowi (Johnny Depp) wydostać się z pułapki Davy''ego Jonesa (Bill Nighy) kryjącej się na krańcu świata. Tym razem nie ucieknie stamtąd przy pomocy rumu, czy związanych lianami żółwi. By wyzwolić pirata, Will Turner (Orlando Bloom), Elizabeth Swann (Keira Knightley) i kapitan Barbossa (Geoffrey Rush) zawiązują sojusz i wypływają na najdalsze wody, bowiem tylko gotowi na wszystko śmiałkowie mogą dołączyć do Jacka. W tym czasie, posługując się Latającym Holendrem, Kompania Wschodnioindyjska realizuje plan oczyszczenia mórz z wszelkich korsarzy.', 'https://image.tmdb.org/t/p/w500/1c4zYjZdZxiBA3tPRmUpWZnUSIi.jpg', 285, 'tt0449088', 2, 0),
(310, 'Piraci z Karaibów. Na nieznanych wodach', 'Pirates of the Caribbean: On Stranger Tides', 'Przygodowy, Akcja, Fantasy', 2011, 6.6, 'Rob Marshall', 137, 'English', 10, 379000000, 'Walt Disney Pictures, Jerry Bruckheimer Films, Moving Picture Company', '', 18.99, 'Ścieżki kapitana Jacka Sparrowa (Johnny Depp) tym razem skrzyżują się ze ścieżkami pewnej kobiety z jego przeszłości (Penelope Cruz). Sparrow będzie zastanawiał się czy połączyła ich miłość, czy wyłącznie pragnienie odnalezienie osławionego Źródła Młodości, którego Jack poszukuje wraz ze swym dawnym przeciwnikiem kpt. Barbossą (Geoffrey Rush). Kiedy kobieta zmusza go do wejścia na pokład statku pirackiego "Zemsta Królowej Anny" pod dowództwem osławionego Czarnobrodego (Ian McShane), Jack nie wie kogo winien się lękać bardziej – uwodzicielskiej Angeliki czy Czarnobrodego.', 'https://image.tmdb.org/t/p/w500/yO3WUzGhp4xNpFCq5sUBNN7gE7.jpg', 1865, 'tt1298650', 2, 0),
(311, 'Zmierzch', 'Twilight', 'Fantasy, Dramat, Romans', 2008, 6.3, 'Catherine Hardwicke', 122, 'English', 1, 37000000, 'Summit Entertainment, Temple Hill Entertainment, Maverick Films', '', 10.99, 'Ekranizacja bestsellerowej powieści Stephenie Meyer. 17-letnia Bella Swan (Kristen Stewart), przeprowadza się do Forks, miasteczka w deszczowym stanie Waszyngton, by zamieszkać ze swoim ojcem (Billy Burke). Kiedy poznaje tajemniczego i niezwykle ponętnego Edwarda Cullena (Robert Pattinson), jej przeciętne dotychczas życie zupełnie się odmienia. Zachwycona jego złotymi oczami, hipnotyzującym głosem i nadprzyrodzonymi umiejętnościami, kompletnie traci dla niego głowę. Nie mogąc mu się oprzeć, nie zdaje sobie sprawy, na jakie niebezpieczeństwo naraża siebie i swoich najbliższych...', 'https://image.tmdb.org/t/p/w500/4F1VuNijOZsY4sGjWSdianHYcOQ.jpg', 8966, 'tt1099212', 2, 0),
(312, 'Saga „Zmierzch”: Zaćmienie', 'The Twilight Saga: Eclipse', 'Przygodowy, Fantasy, Dramat, Romans', 2010, 6.2, 'David Slade', 124, 'English', 2, 68000000, 'Summit Entertainment, Temple Hill Entertainment, Imprint Entertainment', '', 17.99, 'Edward (Robert Pattinson) zgadza się zamienić Bellę (Kristen Stewart) w wampira – pod warunkiem jednak, że wezmą ślub. Ten pomysł nie podoba się zazdrosnemu o dziewczynę Jacobowi (Taylor Lautner). Zgodnie z zasadami swojego plemienia, młody wilkołak wraz ze swoimi towarzyszami ma za zadanie bronić okolic Forks przed wampirami. Jacob oferuje Belli coś, czego Edward nigdy nie będzie w stanie jej zapewnić – normalne życie bez konieczności picia krwi i ukrywania swojej tożsamości przed światem.  Tymczasem do mieszkańców miasteczka dochodzą niepokojące wieści o zniknięciach kolejnych osób. Rodzina Cullenów wkrótce odkrywa, że nie są jedynymi wampirami zamieszkującymi okolice stanu Waszyngton. Na domiar złego w lasach ukrywa się czyhająca na życie Belli Victoria (Bryce Dallas Howard), która chce pomścić śmierć swojego przyjaciela – Jamesa. Rodzina wampirów i plemię wilkołaków będzie musiało załagodzić spór i nauczyć się współpracować, aby oddalić zbliżające się niebezpieczeństwo.', 'https://image.tmdb.org/t/p/w500/mDw2UjTZ5pDqdL3kHUaQ0kr4N3j.jpg', 24021, 'tt1325004', 2, 0),
(313, 'Igrzyska śmierci: Kosogłos. Część 1', 'The Hunger Games: Mockingjay - Part 1', 'Sci-Fi, Przygodowy, Thriller', 2014, 6.8, 'Francis Lawrence', 123, 'English', 3, 125000000, 'Lionsgate, Color Force', '', 9.99, 'Katniss wraz z matką i siostrą mieszka w legendarnym, podziemnym dystrykcie trzynastym, który, wbrew kłamliwej propagandzie, przetrwał zemstę Kapitolu. Z nowymi przywódcami na czele, rebelianci przygotowują się do rozprawy z dyktatorską władzą. Katniss, mimo początkowych wahań, zgadza się wziąć udział w walce. Staje się symbolem oporu przeciw tyranii prezydenta Snowa.', 'https://image.tmdb.org/t/p/w500/k9iXGTuhAEpjcM5nX8qTvLlyPJh.jpg', 131631, 'tt1951265', 2, 0),
(314, 'Igrzyska śmierci: Kosogłos. Część 2', 'The Hunger Games: Mockingjay - Part 2', 'Akcja, Przygodowy, Sci-Fi', 2015, 6.9, 'Francis Lawrence', 136, 'English', 4, 160000000, 'Lionsgate, Color Force, Studio Babelsberg', '', 16.99, 'Katniss Everdeen i przywódcy Dystryktu 13 rozpoczynają wielką ofensywą przeciwko Kapitolowi. Walka toczy się już nie tylko o przetrwanie, ale o przyszłość całego narodu. Katniss wspierana przez Gale''a, Finnicka oraz Peetę planuje zamach na prezydenta Snowa. Bezwzględni wrogowie i moralne wybory, przed którymi stanie Katniss, będą dla niej większym wyzwaniem niż cokolwiek, co wcześniej przeżyła na arenach Głodowych Igrzysk.', 'https://image.tmdb.org/t/p/w500/zGKieogKfrNidF8o9dSGKyZ6U16.jpg', 131634, 'tt1951266', 2, 0),
(315, 'Więzień labiryntu', 'The Maze Runner', 'Akcja, Tajemnica, Sci-Fi, Thriller', 2014, 7.2, 'Wes Ball', 113, 'English', 5, 34000000, 'Ingenious Media, The Gotham Group, Dayday Films', '', 8.99, 'Thriller science fiction, którego akcja toczy się w świecie dotkniętym wielkim kataklizmem. Thomas (Dylan O''Brien) budzi się w windzie, która powoli jedzie w górę. Kiedy w końcu się zatrzymuje i otwierają właz, dowiaduje się, że trafił do Strefy zamieszkałej przez Streferów. To ogromna polana ogrodzona wysokim, betonowym murem. Chłopak niczego nie pamięta – kim jest, skąd pochodzi, jak się tam znalazł. Nie wie, kim są jego rodzice i jak ma na imię.', 'https://image.tmdb.org/t/p/w500/wtX28KahKyNcLddLZhDGiHylcKy.jpg', 198663, 'tt1790864', 2, 0),
(316, 'Gwiazd naszych wina', 'The Fault in Our Stars', 'Romans, Dramat', 2014, 7.6, 'Josh Boone', 125, 'English', 6, 14000000, 'TSG Entertainment, Fox 2000 Pictures, Temple Hill Entertainment', '', 15.99, 'Hazel i Gus to para nastolatków, których połączyła błyskotliwość, niechęć do tego, co przeciętne i wielka miłość. Ich związek jest wyjątkowy - poznali się na spotkaniu grupy wsparcia dla osób chorych na raka. Hazel ma 17 lat i nadopiekuńczych rodziców, których bardzo kocha, mimo że czasem ją irytują. Z Gusem łączą ją nie tylko podobne doświadczenia związane z chorobą, ale także miłość do książek. Dziewczyna marzy, aby poznać autora ulubionej powieści, Petera van Houtena. Wielokrotnie próbowała nawiązać z nim kontakt, ale bezskutecznie. Wytrwałość Gusa zostaje nagrodzona. Udaje mu się dotrzeć do pisarza i zostaje zaproszony na spotkanie w Amsterdamie. Postanawia zabrać ze sobą Hazel...', 'https://image.tmdb.org/t/p/w500/n1ofwUyb9lqx0Rz7aQ9MhGy5iWI.jpg', 222935, 'tt2582846', 2, 0),
(317, 'Koralina i tajemnicze drzwi', 'Coraline', 'Animacja, Familijny, Fantasy, Horror', 2009, 8.0, 'Henry Selick', 100, 'English', 7, 60000000, 'LAIKA, Pandemonium', '', 7.99, 'Film zrealizowany na podstawie książki Neila Gaimana „Koralina”. Pewnego dnia, kiedy Koralina zwiedza nowy dom, odkrywa, że jej mieszkanie ma 14 drzwi. 13 drzwi otwiera się bez problemu i prowadzi do rzeczywistych miejsc w mieszkaniu. Czternaste drzwi znajdują się w odległym kącie pracowni i są zamknięte. Drzwi prowadzą do ciemnego przejścia, a stąd do niespokojnego miejsca spowitego mgłą i zamieszkałego przez alternatywną wersję jej sąsiadów i rodziców. Ci rodzice, jej druga mama i drugi tata, chcą by została z nimi. Zapewniają ją że będzie kochana bardziej, niż w rzeczywistości, że jedzenie będzie o wiele lepsze, niż w rzeczywistym świecie. I wszystko początkowo jest lepsze aż do chwili gdy jej druga mama chce zatrzymać Koralinę na zawsze, używając do tego magii i przemocy, i porywa jej prawdziwych rodziców. Koralina musi stawić czoło własnemu strachowi i uwolnić rodziców i dusze trzech martwych dzieci. Na szczęście znajduje w tym pomocnika-czarnego, mówiącego kota', 'https://image.tmdb.org/t/p/w500/qA6GwcREVpAY6Ky3rZHbTfbAMhC.jpg', 14836, 'tt0327597', 2, 0),
(318, 'Miasteczko Halloween', 'The Nightmare Before Christmas', 'Fantasy, Animacja, Familijny', 1993, 7.9, 'Henry Selick', 76, 'English', 8, 18000000, 'Touchstone Pictures, Skellington Productions', '', 14.99, 'Wzruszająco-przerażająca opowieść o Jacku Szkieletonie, Dyniowym Królu Halloween, który razem z upiornymi mieszkańcami miasteczka chce przejąć Boże Narodzenie i urządzić je po swojemu.', 'https://image.tmdb.org/t/p/w500/tRuNcKYde78DOGjpbkBZBwWeTYI.jpg', 9479, 'tt0107688', 2, 0),
(319, 'Sok z żuka', 'Beetlejuice', 'Fantasy, Komedia', 1988, 7.4, 'Tim Burton', 92, 'English', 9, 15000000, 'Geffen Pictures, Warner Bros. Pictures', '', 6.99, 'Co ma zrobić para sympatycznych, kochających spokój duchów, kiedy ich dom w Nowej Anglii zostaje zajęty przez młodych nowojorczyków? "Wezwijmy tego Beetlejuice" - decydują. Tak więc kontaktują się z niezależnym pośmiertnym bio-egzorcystą, aby wystraszyć rodzinę. I każdy dostaje więcej niż mógłby się spodziewać.', 'https://image.tmdb.org/t/p/w500/rD36yxmak3b5VSnnpPoXG8P1D3M.jpg', 4011, 'tt0094721', 2, 0),
(320, 'Edward Nożycoręki', 'Edward Scissorhands', 'Fantasy, Dramat, Romans', 1990, 7.7, 'Tim Burton', 105, 'English', 10, 20000000, '20th Century Fox', '', 13.99, 'Dawno, dawno temu, w zamku wysoko na wzgórzu, mieszkał niedoceniony wynalazca. Swe największe dzieło nazwał imieniem Edward. Mimo, że Edward posiadał nieodparty urok, nie był w pełni doskonały. Nagła śmierć twórcy, przerwała prace, a Edward pozostał z ostrymi jak brzytwa nożycami zamiast dłoni. Młodzieniec, żył samotnie w swoim odciętym od świata zamku, aż do czasu, gdy natrętna akwizytorka firmy Avon nie zabrała go do swojego domu.I tak zaczyna się fantastyczna przygoda Edwarda, jako członka społeczności małego, nieco sennego miasteczka.', 'https://image.tmdb.org/t/p/w500/xoTAH4h4S09j7Tsk2S88PG6p0np.jpg', 162, 'tt0099487', 2, 0),
(321, 'Rodzina Addamsów', 'The Addams Family', 'Komedia, Fantasy', 1991, 7.1, 'Barry Sonnenfeld', 100, 'English', 1, 30000000, 'Paramount Pictures, Orion Pictures, Scott Rudin Productions', '', 5.99, 'Rodzina Addamsów to zbiór niesamowitych postaci, żyjących w starym, na wpół zdewastowanym pałacu. Głową rodziny jest Gomez Addams oraz jego żona Morticia. Rodzina Addamsów charakteryzuje się bardzo czarnym poczuciem humoru.', 'https://image.tmdb.org/t/p/w500/klFZRMea2DLmNYnNtwIoOh0qd9o.jpg', 2907, 'tt0101272', 2, 0),
(322, 'Hokus Pokus', 'Hocus Pocus', 'Fantasy, Komedia, Familijny', 1993, 7.0, 'Kenny Ortega', 96, 'English', 2, 28000000, 'Walt Disney Pictures, Touchwood Pacific Partners 1, David Kirschner Productions', '', 12.99, 'Akcja filmu toczy się w miasteczku Salem. Trzy wiedźmy, siostry Sanderson (Bette Midler, Sarah Jessica Parker i Kathy Najimy), porywały dzieci i zabierały im energię życiową, aby pozostać nieśmiertelnymi i młodymi. Mieszkańcy Salem w końcu zorientowali się, kto stoi za śmiercią ich potomstwa i postanowili powiesić czarownice. Przed egzekucją jedna z sióstr rzuciła zaklęcie, które ma przywrócić je do życia w dzień Halloween. 300 lat później do miasta wprowadza się Max Dennison (Omri Katz) wraz z rodziną. W noc wigilii Wszystkich Świętych zapala czarną świecę i przywraca do życia siostry Sanderson. Teraz czarownice muszą zdobyć jak najwięcej dzieci, w przeciwnym wypadku zamienią się w pył, gdy wzejdzie słońce. Max z siostrą i przyjaciółką starają się im w tym przeszkodzić...', 'https://image.tmdb.org/t/p/w500/by4D4Q9NlUjFSEUA1yrxq6ksXmk.jpg', 10439, 'tt0107120', 2, 0),
(323, 'Jumanji', 'Jumanji', 'Przygodowy, Fantasy, Familijny', 1995, 7.2, 'Joe Johnston', 104, 'English', 3, 65000000, 'TriStar Pictures, Interscope Communications, Teitler Film', '', 19.99, 'Młody Alan Parish znajduje tajemniczą grę planszową, za której sprawą przenosi się do magicznej, dzikiej dżungli. Dopiero po 26 latach zostaje z niej przypadkowo uwolniony przez nieświadome niczego dzieci - Judy (Kristen Dunst) i Petera (Bradley Pierce). Teraz, jako dorosły mężczyzna, Alan (Robin Williams), razem ze swoją przyjaciółką z dzieciństwa Sarah, (Bonnie Hunt), Judy i Peterem starają się przechytrzyć potężne moce i wygrać z niebezpieczną, żyjącą własnym życiem grą.
 Jumanji to doskonała, poruszająca wyobraźnię przygoda. Oszałamiające efekty specjalne, humor, magia i napięcie gwarantują pierwszorzędną zabawę dla całej rodziny.  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/neJlktDIg9viYaO2uqyMhNO3B1W.jpg', 8844, 'tt0113497', 2, 0),
(324, 'Jumanji: Przygoda w dżungli', 'Jumanji: Welcome to the Jungle', 'Przygodowy, Komedia, Fantasy', 2017, 6.8, 'Jake Kasdan', 119, 'English', 4, 90000000, 'Matt Tolmach Productions, Seven Bucks Productions, Columbia Pictures', '', 11.99, 'Czwórka licealistów podczas odbywania szkolnej kary znajduje starą konsolę do gier wideo z nieznaną grą, o której nigdy nawet nie słyszeli. Po jej uruchomieniu zostają natychmiast wciągnięci do dżungli z wirtualnego świata Jumanji w ciałach swoich awatarów (Dwayne Johnson, Jack Black, Kevin Hart i Karen Gillan). Szybko się orientują, że to nie oni grają w Jumanji, lecz Jumanji gra nimi. Przeżywają emocjonującą przygodę życia, pełną zabawy, ale i całkiem realnych zagrożeń i niebezpieczeństw. Muszą doprowadzić grę do końca, bo w przeciwnym razie utkną w niej na zawsze!', 'https://image.tmdb.org/t/p/w500/7qYiXYyNdUkY7bmPKf6269rZNG7.jpg', 353486, 'tt2283362', 2, 0),
(325, 'Pogromcy duchów 2', 'Ghostbusters II', 'Komedia, Fantasy', 1989, 6.6, 'Ivan Reitman', 102, 'English', 5, 37000000, 'Columbia Pictures', '', 18.99, 'Minęło pięć lat, od czasu, gdy pogromcy duchów ocalili Nowy Jork przed atakiem sił zła. W tym czasie związek Dany i Petera rozpadł się. On i jego wspólnicy - Raymond i Egon - otrzymali zakaz uprawiania swojej działalności. Dana, która jest konserwatorką w muzeum, odnawia właśnie portret XVI-wiecznego rumuńskiego czarnoksiężnika Vigo. W trakcie prac okazuje się, że jego duch pragnie wrócić do życia, wykorzystując ciało jej dziecka. Pogromcy znów wkraczają do akcji.', 'https://image.tmdb.org/t/p/w500/qJQr4cuZ2NsL5YOmwEtTJMpMnXt.jpg', 2978, 'tt0097428', 2, 0),
(326, 'Pogromcy duchów. Dziedzictwo', 'Ghostbusters: Afterlife', 'Fantasy, Komedia, Przygodowy', 2021, 7.3, 'Jason Reitman', 124, 'English', 6, 75000000, 'Columbia Pictures, Bron Studios, The Montecito Picture Company', '', 10.99, 'Kolejny rozdział oryginalnego uniwersum Ghostbusters. Samotna matka i jej dwoje dzieci przybywają do małego miasteczka, gdzie odkrywają tajemnicze połączenie z oryginalnymi pogromcami duchów oraz sekretny spadek, który pozostawił im dziadek.', 'https://image.tmdb.org/t/p/w500/6wJxXHotlRQXXSG3hSr7NDM70Ai.jpg', 425909, 'tt4513678', 2, 0),
(327, 'Niekończąca się opowieść', 'Die unendliche Geschichte', 'Przygodowy, Fantasy, Familijny', 1984, 7.2, 'Wolfgang Petersen', 102, 'German', 7, 27000000, 'Constantin Film, Bavaria Film', '', 17.99, 'Mały chłopiec po śmierci matki zamyka się w sobie. Zaczyna mieć kłopoty w szkole, nie potrafi znaleźć wspólnego języka ze swoim ojcem. Pewnego dnia, uciekając przed prześladującymi go starszymi chłopcami, Bastian trafia do pewnej księgarni, skąd wykrada (właściwie to jedynie pożycza) tajemniczą książkę, dzięki której przeżyje najwspanialszą przygodę w swoim życiu. Nie jest to bowiem zwykła książka, ale pełna magii brama do innego świata. Dzięki niej Bastian przenosi się w krainę wyobraźni, której właśnie grozi zagłada... Mały chłopiec okaże się wkrótce jedyną osobą, która może uratować piękną księżniczkę...', 'https://image.tmdb.org/t/p/w500/o92dpEtcoBo5pmpyZZ129ezXDkH.jpg', 34584, 'tt0088323', 2, 0),
(328, 'Labirynt', 'Labyrinth', 'Przygodowy, Familijny, Fantasy', 1986, 7.3, 'Jim Henson', 101, 'English', 8, 25000000, 'Henson Associates, Lucasfilm Ltd.', '', 9.99, 'Znudzona kolejnym weekendem, spędzanym na opiece nad młodszym, przyrodnim braciszkiem, Sarah - nastolatka o żywej wyobraźni - wzywa gobliny ze swojej ulubionej książki „Labirynt", by zabrały jej brata. Kiedy okazuje się, że życzenie się spełniło i mały Tobey faktycznie zniknął, Sarah podąża za nim do świata baśni, by wyrwać go z łap złośliwego króla goblinów (Bowie), którego strzeże sam zamek - prawdziwy labirynt oszustw i złudzeń, zamieszkały przez niezwykłe stwory i pełen nieznanych niebezpieczeństw. Aby go przejść i zdążyć na czas, by uratować Tobey''a, Sara musi przechytrzyć króla, zaprzyjaźnić się ze strzegącymi go goblinami i mieć nadzieje, że ich lojalność nie jest jeszcze jedną iluzją w miejscu, gdzie nic nie jest takie, na jakie wygląda.', 'https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', 13597, 'tt0091369', 2, 0),
(329, 'Labirynt fauna', 'El laberinto del fauno', 'Fantasy, Dramat, Wojenny', 2006, 7.8, 'Guillermo del Toro', 118, 'Spanish', 9, 19000000, 'Estudios Picasso, Esperanto Filmoj, Tequila Gang', '', 16.99, 'Mała Ofelia przybywa do domu nowego męża jej matki, kapitana Vidala. Dziewczynce trudno znieść surowość ojczyma. Przez przypadek Ofelia odkrywa w ogrodzie tajemniczy labirynt. Tam spotka Fauna, baśniowego stwora, który rozpozna w niej księżniczkę magicznej krainy, której grozi zagłada. Przed dziewczynką stoją jednak 3 mordercze zadania, które sprawdzą jej nieśmiertelność. Z czasem okrucieństwo zapanuje nad całym rzeczywistym światem.', 'https://image.tmdb.org/t/p/w500/7iYVYtSIUHnH4FN2x5TzgOFFVHC.jpg', 1417, 'tt0457430', 2, 0),
(330, 'Kształt wody', 'The Shape of Water', 'Dramat, Fantasy, Romans', 2017, 7.2, 'Guillermo del Toro', 123, 'English', 10, 19500000, 'Double Dare You, Fox Searchlight Pictures, Bull Productions', '', 8.99, 'Elisa nie miała łatwego życia. Jest sierotą, która nigdy nie poznała swoich rodziców. Jest niema, co oznacza, że automatycznie skazywana na bycie gorszą. W świecie, w którym żeby coś osiągnąć, trzeba przepychać się łokciami, jest skazana na życie z miesiąca na miesiąc i usługiwanie bardziej przebojowym ludziom. Elisa ma jednak coś, czego inni nie mają: ogromną empatię i jeszcze większą wyobraźnię. Cechy te przydadzą jej się w laboratorium rządowym, w którym pracuje jako sprzątaczka, a w którym spotyka pewnego dnia uwięzionego przez wojsko stwora rodem z hollywoodzkich horrorów. Gdy jednak zaczyna mu się przyglądać i go poznawać, uświadamia sobie, że to nie żadna bestia, lecz wrażliwa i krucha istota, która została już w dniu urodzenia skazana na życie w cierpieniu w świecie ludzi.', 'https://image.tmdb.org/t/p/w500/sEEiHN6t4FPY73U4czYrVTIxIlU.jpg', 399055, 'tt5580390', 2, 0),
(331, 'Toy Story 4', 'Toy Story 4', 'Familijny, Komedia, Animacja, Przygodowy', 2019, 7.5, 'Josh Cooley', 100, 'English', 1, 175000000, 'Pixar', '', 15.99, 'Chudy zawsze znał swoje miejsce na świecie. Jego życie, jak na prawdziwego szeryfa przystało, kręciło się wokół opieki nad Andym, a później Bonni. Gdy pewnego dnia w pokoju Bonni pojawia się nowa zabawka, Sztuciek, nikt nawet nie przypuszcza, że to początek zaskakującej podróży. Nieoczekiwana wyprawa pozwoli Chudemu przekonać się, jak wielki może być świat dla zwykłej zabawki…', 'https://image.tmdb.org/t/p/w500/fT9rBJqGFTgKVCPFS113pBqqMrT.jpg', 301528, 'tt1979376', 2, 0),
(332, 'Potwory i spółka', 'Monsters, Inc.', 'Animacja, Komedia, Familijny, Fantasy', 2001, 7.9, 'Pete Docter', 92, 'English', 2, 130000000, 'Pixar', '', 7.99, 'Monstropolis to miasto zamieszkane przez potwory. W jego centrum znajduje się fabryka strachu Potwory i Spółka, gdzie w pocie czoła pracują: prawdziwy mistrz straszenia, James P. Sullivan, zwany Sulley, oraz jego najlepszy przyjaciel i pomocnik Mike Wazowski. Sulley i Mike co noc otwierają szafy w dziecięcych pokojach, by straszyć maluchy i przetwarzać ich krzyki na źródło energii. Wykonując swoją pracę, potwory głęboko wierzą, iż dzieci są toksyczne i niebezpieczne, a bezpośredni kontakt z nimi może mieć – nomen omen – potworne skutki. Kiedy więc mała dziewczynka o imieniu Boo trafia przypadkiem do ich świata, wybucha prawdziwa panika. Mike i Sulley robią wszystko, by odesłać Boo z powrotem do domu. Niestety okazuje się, że jest to bardziej skomplikowane, niż przypuszczali…', 'https://image.tmdb.org/t/p/w500/6Wm9FC1TuhD32hzogKik9rTbFZR.jpg', 585, 'tt0198781', 2, 0),
(333, 'Ratatuj', 'Ratatouille', 'Animacja, Komedia, Familijny, Fantasy', 2007, 7.9, 'Brad Bird', 110, 'English', 3, 150000000, 'Pixar', '', 14.99, 'Remy marzy o karierze wielkiego kucharza. Dwie rzeczy stoją mu na przeszkodzie - niechętna rodzina i fakt, iż jest szczurem. Nasz bohater jednak się tym nie zraża i dzielnie dąży do realizacji celu. Zbieg okoliczności sprawia, że trafia on do kanałów mieszczących się dokładnie pod ekskluzywną paryską restauracją. Początkowo Remy nie jest w lokalu mile widziany, ale pasja gotowania bierze górę nad różnicami gatunkowymi. Wkrótce cały kulinarny światek zostaje wywrócony do góry nogami...', 'https://image.tmdb.org/t/p/w500/v3otSJVt5jFZKhnlBGMoOfu2mo6.jpg', 2062, 'tt0382932', 2, 0),
(334, 'Auta', 'Cars', 'Animacja, Przygodowy, Komedia, Familijny', 2006, 7.1, 'John Lasseter', 117, 'English', 4, 120000000, 'Pixar', '', 6.99, 'Zygzak McQueen jest młodym i ambitnym samochodem wyścigowym, który marzy o olśniewających sukcesach i przygotowuje się do startu w wielkim wyścigu o Mistrzostwo Złotego Tłoka w Kalifornii. Zamiast na trasę wyścigu, trafia jednak do pustynnego miasteczka Chłodnica Górska przy autostradzie 66 i szybko poznaje jego ekscentrycznych mieszkańców. Są wśród nich: Sally - Porsche 2002, Wójt Hudson - stary samochód o tajemniczej przeszłości oraz Złomek, zardzewiała ciężarówka holownicza. W grupie nowych przyjaciół McQueen przekonuje się, że są w życiu ważniejsze rzeczy, niż dążenie do sukcesu za wszelką cenę oraz zdobywanie kolejnych pucharów.', 'https://image.tmdb.org/t/p/w500/xTLUx4xnZSgn0AINCJC6vo3vqld.jpg', 920, 'tt0317219', 2, 0),
(335, 'Merida Waleczna', 'Brave', 'Przygodowy, Animacja, Familijny, Fantasy', 2012, 7.0, 'Mark Andrews', 93, 'English', 5, 185000000, 'Pixar', '', 13.99, 'Doskonała łuczniczka Merida jest porywczą córką króla Fergusa i królowej Elinor. Niezależna i zdecydowana iść własną drogą, postępuje wbrew prastarym zwyczajom, narażając się na krytykę rodziców i dworu. Czyny księżniczki przypadkowo sprowadzają na królestwo chaos i zniszczenie. Merida musi się spieszyć, aby odwrócić skutki spowodowanych przez siebie zdarzeń. U kresu tej podróży ma odkryć znaczenie waleczności i swoje prawdziwe powołanie.', 'https://image.tmdb.org/t/p/w500/s79T8R2LJo6XVlgOoIgoXfXaxSL.jpg', 62177, 'tt1217209', 2, 0),
(336, 'Gdzie jest Dory', 'Finding Dory', 'Przygodowy, Animacja, Familijny', 2016, 7.0, 'Andrew Stanton', 97, 'English', 6, 200000000, 'Pixar', '', 5.99, 'Dory jest uroczą rybką, którą cierpi na pewną przypadłość - brak pamięci krótkotrwałej. Gdy była mała, kochający rodzice z całych sił starali się ustrzec ją przed niebezpieczeństwem. Pewnego dnia jednak Dory wpadła w prąd oceaniczny, który porwał ją w nieznane. Teraz próbuje przypomnieć sobie swoją przeszłość i odnaleźć rodziców. Wyrusza do Kalifornii, a pomagają jej w tym przyjaciele: błazenek Marlin i jego synek Nemo, zgryźliwa ośmiornica Hank, narwalowaty Bailey, przekonany o tym, że cierpi na zaburzenia echolokacji, i Nadzieja, rekin wielorybi z wadą wzroku.', 'https://image.tmdb.org/t/p/w500/4dUrWFhJKnMOCxlo9Hgy2Z4mmGr.jpg', 127380, 'tt2277860', 2, 0),
(337, 'Iniemamocni 2', 'Incredibles 2', 'Akcja, Przygodowy, Animacja, Familijny', 2018, 7.5, 'Brad Bird', 118, 'English', 7, 200000000, 'Pixar', '', 12.99, 'W rodzinie Iniemamocnych przyszła kolej na zmiany! Podczas gdy Helen rozwija swoją karierę zawodową, jej mąż Bob zostaje w domu z dziećmi realizując się w zaciszu domowych pieleszy. Ta nowa sytuacja jest trudna dla wszystkich, a pączkujące nadprzyrodzone zdolności małego Jack-Jacka nie czynią jej łatwiejszą. Kiedy kolejny szwarccharakter planuje genialny i niebezpieczny spisek, cała rodzina Iniemamocnych musi ponownie zjednoczyć siły, aby stawić czoła nowemu wyzwaniu. Łatwiej powiedzieć, trudniej zrobić – nawet dla Iniemamocnych.', 'https://image.tmdb.org/t/p/w500/xmLadOFQEibY0XFQ28NGf7AP76a.jpg', 260513, 'tt3606756', 2, 0),
(338, 'Co w duszy gra', 'Soul', 'Animacja, Dramat, Familijny, Muzyczny', 2020, 8.1, 'Pete Docter', 101, 'English', 8, 150000000, 'Pixar', '', 19.99, 'Joe Gardner, nauczyciel muzyki w szkole, dostaje życiową szansę, aby zagrać w najlepszym jazzowym klubie w mieście. Ale jeden nieostrożny krok sprawia, że prosto z nowojorskiej ulicy dostaje się w Przedświaty - niezwykłe miejsce, gdzie nowe dusze, zanim zejdą na Ziemię, otrzymują osobowość, dziwactwa i pasje. Zdeterminowany, żeby odzyskać swoje życie, Joe zaprzyjaźnia się z młodą duszą - 22, która nie rozumie, dlaczego doświadczenie bycia człowiekiem jest aż tak pociągające. Podczas, gdy Joe stara się przekonać 22, że życie jest wspaniałe, sam znajduje odpowiedzi na najważniejsze pytania.', 'https://image.tmdb.org/t/p/w500/Kam8jZe2hMd2IJ1JWvzxpgpI97.jpg', 508442, 'tt2948372', 2, 0),
(339, 'Luca', 'Luca', 'Animacja, Familijny, Fantasy, Dramat', 2021, 7.8, 'Enrico Casarosa', 95, 'English', 9, 200000000, 'Pixar', '', 11.99, '"Luca" to najnowsza animacja studia Disney/Pixar, której akcja rozgrywa się w pięknym nadmorskim miasteczku na Riwierze Włoskiej. Pełen niezwykłych przygód film opowiada o dorastaniu dwójki przyjaciół. Chłopcy wspólnie przeżywają niezapomniany letni czas, który upływa im na niekończących się przejażdżkach na skuterze i delektowaniu się lodami. Jednak ich beztroską zabawę może w każdej chwili zepsuć ujawnienie głęboko skrywanego sekretu. Obaj są potworami morskimi z innego świata znajdującego się tuż pod powierzchnią wody.', 'https://image.tmdb.org/t/p/w500/lDYIrLtHei2x5qW5jPNyNL4sS43.jpg', 508943, 'tt12801262', 2, 0),
(340, 'Kraina lodu II', 'Frozen II', 'Familijny, Animacja, Przygodowy, Komedia', 2019, 7.2, 'Jennifer Lee', 103, 'English', 10, 150000000, 'Walt Disney Animation Studios', '', 18.99, 'Dlaczego Elsa urodziła się obdarzona magiczną mocą? Odpowiedź na to pytanie nie daje jej spokoju i… zagraża całemu królestwu! Dlatego razem z Anną, Kristoffem, Olafem i Svenem wyruszają w niebezpieczną i niezwykłą podróż. Czy ta wyprawa odmieni życie bohaterów? Czego się podczas niej dowiedzą? Jakie przygody przeżyją? W oscarowej Krainie lodu Elsa bała się, że jej moc jest zbyt potężna i może doprowadzić do katastrofy. W drugiej części musi mieć nadzieję, że ta moc będzie wystarczająca, aby przezwyciężyć problemy, które napotka. Czy tak się stanie?', 'https://image.tmdb.org/t/p/w500/jVGafxdBZldAJfmgZujoDfBpVxd.jpg', 330457, 'tt4520988', 2, 0),
(341, 'Królewna Śnieżka i siedmiu krasnoludków', 'Snow White and the Seven Dwarfs', 'Fantasy, Animacja, Familijny', 1938, 7.1, 'David Hand', 83, 'English', 1, 1488423, 'Walt Disney Productions', '', 10.99, '"Dawno, dawno temu ..." tak rozpoczyna się czarowna baśń o ślicznej Królewnie Śnieżce, której beztroskie życie zmieniło się za sprawą złej macochy - czarownicy. Zazdrosna o urodę dziewczynki - magiczne zwierciadełko uznało Śnieżkę za najpiękniejszą na świecie - postanawia się jej pozbyć raz na zawsze. Porzucona w dzikim lesie, Śnieżka trafia do chatki siedmiu krasnoludków: Mędrka, Gapcia, Śpioszka, Wesołka, Nieśmiałka, Gburka i Apsika - najbardziej uroczych postaci jakie można sobie wyobrazić. Bawią się, śpiewają, śmieją się i gwiżdżą nawet w czasie ciężkiej pracy w kopalni. Wszyscy razem wiodą szczęśliwy żywot do czasu, gdy tajemnicza starucha podstępnie częstuje Śnieżkę zatrutym jabłkiem... ale nie bójcie się - jak to w bajkach bywa, wszystko kończy się dobrze!', 'https://image.tmdb.org/t/p/w500/X5FFkfGVxEvjYT6zL2g3UMQYXC.jpg', 408, 'tt0029583', 2, 0),
(342, 'Pinokio', 'Pinocchio', 'Animacja, Familijny, Fantasy', 1940, 7.1, 'Hamilton Luske', 88, 'English', 2, 2600000, 'Walt Disney Productions', '', 17.99, '„Pinokio” – legendarne arcydzieło Walta Disneya, które uczy, że zawsze trzeba wierzyć w swoje marzenia – powraca po całkowitej renowacji i lśni piękniej niż kiedykolwiek! Zobacz, jak po raz pierwszy bogata i szczegółowa animacja, niezapomniana, nagrodzona muzyka i wzruszająca przygoda powracają do życia, wzbogacone wyjątkowymi dodatkami specjalnymi, które przeniosą cię do fantastycznego świata Pinokia!  Dołącz do ulubionej zabawki Geppetta i gadającego świerszcza w pełnej przygód podróży, która wystawi odwagę, lojalność i szczerość Pinokia na próbę – sprawdzając, czy posiada on cnoty godne prawdziwego chłopca. Jedyny i niepowtarzalny Pinokio będzie żył wiecznie w sercach tych, którzy potrafią marzyć, spoglądając w gwiazdy!  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/m6W6OlRlirubGI1U2OLKY6w34Lm.jpg', 10895, 'tt0032910', 2, 0),
(343, 'Dumbo', 'Dumbo', 'Animacja, Familijny', 1941, 7.0, 'Ben Sharpsteen', 63, 'English', 3, 812000, 'Walt Disney Productions', '', 9.99, 'Dumbo to mały słonik o nienaturalnie wielkich uszach, który przy pomocy zaprzyjaźnionej myszki uczy się wiary w siebie.  Film otwiera sekwencja muzyczna, w której klucz bocianów zmierza na Florydę, z zawiniątkami w dziobach. Niosą one dobrą nowinę, zwiastującą macierzyństwo. W cyrku na Florydzie tej nocy wiele zwierząt świętuje narodziny.', 'https://image.tmdb.org/t/p/w500/aD62FBpCC8I1LAPWEBehqcbgcpT.jpg', 11360, 'tt0033563', 2, 0),
(344, 'Bambi', 'Bambi', 'Animacja, Dramat, Familijny', 1942, 7.0, 'David Hand', 70, 'English', 4, 858000, 'Walt Disney Productions', '', 16.99, 'Wraz z pierwszym słonecznym blaskiem poranka, oświetlającym zieloną łąkę w środku lasu nowy książę puszczy przyszedł na świat. Tak rozpoczyna się Bambi - ponadczasowa opowieść o niewinności i marzeniach, ukazująca piękno natury i nieposkromioną siłę miłości i przyjaźni.', 'https://image.tmdb.org/t/p/w500/wV9e2y4myJ4KMFsyFfWYcUOawyK.jpg', 3170, 'tt0034492', 2, 0),
(345, 'Kopciuszek', 'Cinderella', 'Familijny, Fantasy, Animacja, Romans', 1950, 7.1, 'Hamilton Luske', 75, 'English', 5, 2900000, 'Walt Disney Productions', '', 8.99, 'Osierocona dziewczyna jest wykorzystywana do ciężkiej pracy przez macochę i jej dwie córki. Sytuacja ulega zmianie, kiedy kopciuszek z pomocą wróżki udaje się na królewski bal, gdzie poznaje księcia.', 'https://image.tmdb.org/t/p/w500/5VjsXcOjh6aeKcwyBtMMlgL3Ywj.jpg', 11224, 'tt0042332', 2, 0),
(346, 'Piotruś Pan', 'Peter Pan', 'Animacja, Familijny, Przygodowy, Fantasy', 1953, 7.2, 'Clyde Geronimi', 77, 'English', 6, 4000000, 'Walt Disney Productions', '', 15.99, 'Piotruś Pan - chłopiec, który nie chciał dorosnąć - to ulubiony bohater opowieści na dobranoc Wandy, Janka i Michasia. Gdy zabiera ich do magicznej krainy Nibylandii, w której dzieciństwo trwa wiecznie, rozpoczyna się prawdziwa zabawa. Dzięki Dzwoneczkowi i cudownemu proszkowi wszyscy mogą latać i przeżywać niezapomniane przygody, których kulminacyjnym punktem jest ostateczne starcie Piotrusia z jego największym wrogiem - złym Kapitanem Hakiem.', 'https://image.tmdb.org/t/p/w500/oGlFlUvUynH2KYpSVM0eyYLEVfF.jpg', 10693, 'tt0046183', 2, 0),
(347, 'Śpiąca królewna', 'Sleeping Beauty', 'Fantasy, Animacja, Romans, Familijny', 1959, 6.9, 'Clyde Geronimi', 75, 'English', 7, 6000000, 'Walt Disney Productions', '', 7.99, 'W wielkim królestwie królewskiej parze narodziła się córeczka, której nadali imię Aurora. Radości rodziców nie było końca. Podczas balu z powodu narodzin, została wygnana zła wiedźma, która także chciała zobaczyć przyszłą królową. Upokorzona, rzuca na Aurorę klątwę - w dniu 16 urodzin ukłuje się wrzecionem i zapadnie w głęboki sen. Król i królowa nakazali spalić wszystkie wrzeciona w królestwie. Mija 16 lat. Trzy dobre wróżki chroniły Aurorę przed złą wiedźmą, ale ta ją znalazła i nakłoniła do użycia wrzeciona. Razem z całym królestwem księżniczka zapadła w głęboki sen. Przepowiednia głosi, że tylko młody książe Filip, pocałując Aurorę, złamie klątwę. Niestety, wiedźma zamyka go w lochu. Jedyną pomocą Filipa i królestwa są trzy dobre wróżki które chroniły Aurorę.', 'https://image.tmdb.org/t/p/w500/2HxDStko3zORDv6rsTXetle3lFn.jpg', 10882, 'tt0053285', 2, 0),
(348, '101 dalmatyńczyków', 'One Hundred and One Dalmatians', 'Przygodowy, Animacja, Komedia, Familijny', 1961, 7.2, 'Hamilton Luske', 79, 'English', 8, 3600000, 'Walt Disney Productions', '', 14.99, 'Dzieje się to w Londynie. Dalmatyńczyk Pongo postanowił znaleźć towarzyszkę życia dla swego pana Roberta. Po bezowocnych poszukiwaniach znajduję piękną dalmatynkę Czikę, której pani była równie piękna. Wkrótce nawiązują znajomość w parku, a potem Robert i Anita biorą ślub. Jednak przyjaciółka Anity - Cruella de Mon zapragnęła uszyć sobie futro z młodych szczeniąt. Nakazuje dwóm nieudacznikom - Nochalowi i Baryle kradziesz szczeniąt. Na ratunek swym dzieciom wyruszają Pongo i Czika. Czy uda im się uratować szczenięta?...', 'https://image.tmdb.org/t/p/w500/nGrMvAS74zNLkM0QmiohHnqUQm5.jpg', 12230, 'tt0055254', 2, 0),
(349, 'Księga dżungli', 'The Jungle Book', 'Familijny, Animacja, Przygodowy', 1967, 7.3, 'Wolfgang Reitherman', 78, 'English', 9, 4000000, 'Walt Disney Productions', '', 6.99, 'Klasyczna opowieść o małym chłopcu, który mieszka w dżungli pośród zwierząt. Mowgli, chociaż wychowywany przez wilki, pozostaje znienawidzony przez tygrysa Shere Khan, który chce go zniszczyć.  Z pomocą swoich nauczycieli, niedźwiedzia o wielkim sercu, Baloo oraz mądrej pantery, Bagheera, chłopiec uczy się języka i praw dżungli. Zyskuje on przyjaźń pytona Kaa i pomaga przechytrzyć plemię małp! Niestety Mowgli musi użyć więcej niż kilka sztuczek, żeby ochronić siebie i swoich przyjaciół przed niebezpieczeństwem, gdy Shere Khan powróci do dżungli.  Przygody zatrzymujące dech w piersiach oraz niezapomniane postaci zwierząt - Księga Dżungli to czarodziejska opowieść o honorze i szacunku do wszystkich istot.', 'https://image.tmdb.org/t/p/w500/CvWPhEMNrVOkbnhdIV9raQvoBq.jpg', 9325, 'tt0061852', 2, 0),
(350, 'Mała Syrenka', 'The Little Mermaid', 'Animacja, Familijny, Fantasy', 1989, 7.4, 'John Musker', 83, 'English', 10, 40000000, 'Silver Screen Partners IV, Walt Disney Feature Animation', '', 13.99, 'Disneyowska wersja "Małej Syrenki" przedstawia przygody niezależnej syrenki o imieniu Ariel, która za wszelką cenę chce trafić do świata ludzi. Działając pod wpływem emocji zawiera więc układ ze złą czarownicą morską Urszulą oddając swój głos i ogon w zamian za parę nóg i szansę ponownego spotkania przystojnego księcia Eryka, którego uratowała po katastrofie statku. Działając wbrew radom swojego mądrego ojca, króla Trytona i kraba Sebastiana, który miał za zadanie ją chronić, Ariel popada w nie lada tarapaty odkrywając, że milczenie wcale nie jest złotem, a korzyści, które odniosła dzięki układowi z Urszulą, są co najmniej wątpliwe...', 'https://image.tmdb.org/t/p/w500/qtmZIbsiOuvs6KKGnSKU2ECXRjR.jpg', 10144, 'tt0097757', 2, 0),
(351, 'Shrek 2', 'Shrek 2', 'Animacja, Komedia, Familijny, Fantasy', 2004, 7.3, 'Conrad Vernon', 92, 'English', 1, 150000000, 'DreamWorks Animation, Pacific Data Images', '', 5.99, 'Shrek i Fiona powracają z miesiąca miodowego i ku ich zdziwieniu znajdują zaproszenie na uroczysty obiad do rodziców Fiony. Młoda para wraz z Osłem u boku wyrusza więc do Zasiedmiogórogrodu. Wszyscy mieszkańcy królestwa gromadzą się, aby powitać księżniczkę. Z niecierpliwością na przyjazd córki i jej męża czekają również rodzice Fiony. Problemy w tym, że nikt ich nie przygotował na spotkanie z nowym zięciem. Jakież jest więc zdziwienie, kiedy ich zięć okazuje się grubym, zielonym i nie przywiązującym wagi do higieny ogrem, któremu w dodatku towarzyszy gadający Osioł. Nikt nie jest szczęśliwy, że księżniczka poślubiła ogra, a najbardziej ze wszystkich Książę z bajki, któremu obiecano rękę Fiony wiele lat temu. Król postanawia wynająć Kota w butach, który ma za zadanie... zabić Shreka.', 'https://image.tmdb.org/t/p/w500/tmNwQ4dTEeubGBrzT3dL5wvsvyF.jpg', 809, 'tt0298148', 2, 0),
(352, 'Shrek Trzeci', 'Shrek the Third', 'Fantasy, Przygodowy, Animacja, Komedia', 2007, 6.3, 'Chris Miller', 93, 'English', 2, 160000000, 'DreamWorks Animation, Pacific Data Images', '', 12.99, 'Historii zielonego ogra ciąg dalszy. Ojciec Fiony zaakceptował ostatecznie swojego zięcia, zdecydował nawet, że Shrek i Fiona mają pełnić obowiązki panującej pary królewskiej. Oboje nie czują jednak się w tej roli najlepiej, a Shrek z miłą chęcią wróciłby na swoje bagno. Król postanawia więc, że jeśli odnajdą następcę tronu, który obejmie rządy i godnie ich zastąpi, będą mogli opuścić królestwo i żyć własnym życiem. Odpowiednim kandydatem na króla jest siostrzeniec królowej Lilian, książę Artie. Shrek wyrusza, razem ze swoimi wiernymi druhami: Osiołkiem i Kotem w butach, w daleką podróż, aby odnaleźć i przekonać zbuntowanego Artiego, że powinien zasiąść na tronie. Tymczasem, podczas nieobecności Shreka w królestwie, Książę z bajki przeprowadza zamach stanu. Fiona organizuje ruch oporu, który ma przeciwstawić się uzurpatorowi do czasu, aż Shrek, Osiołek, Kot w butach i przyszły król Artur powrócą z podróży.', 'https://image.tmdb.org/t/p/w500/AglSZv6IMzWHozdzsndKMvpsI0b.jpg', 810, 'tt0413267', 2, 0),
(353, 'Shrek Forever', 'Shrek Forever After', 'Komedia, Przygodowy, Fantasy, Animacja', 2010, 6.4, 'Mike Mitchell', 93, 'English', 3, 165000000, 'DreamWorks Animation', '', 19.99, 'Czym zajmują się ogry, kiedy już rozprawią się ze straszliwym smokiem, poślubią piękną królewnę i ocalą królestwo teścia? Shrek został pantoflarzem. Małorolni nie uciekają już przed nim z krzykiem. Dziś proszą, żeby podpisał im się na widłach. Tęskniąc za czasami, kiedy "żył jak na ogra przystało", Shrek nieopatrznie zawiera pakt z podstępnym Rumplesnickim i ląduje w rządzonej przez niego, spaczonej, alternatywnej wersji Zasiedmiogórogrodu. Tu na ogry się poluje, a Shrek i Fiona nigdy się nie spotkali. Czy Shrekowi uda się odwrócić zaklęcie, uratować przyjaciół i odzyskać ukochaną?', 'https://image.tmdb.org/t/p/w500/mAn7hsIH0HgVVQOylvldl1HzySE.jpg', 10192, 'tt0892791', 2, 0),
(354, 'Madagaskar', 'Madagascar', 'Przygodowy, Animacja, Komedia, Familijny', 2005, 6.9, 'Eric Darnell', 86, 'English', 4, 75000000, 'Pacific Data Images, DreamWorks Animation', '', 11.99, 'Film opowiada o paczce zgranych przyjaciół: lwie - Alexie, zebrze - Marty''m, hipopotamicy - Glorii i żyrafie - Melmanie. Ich przygody rozpoczynają się za sprawą Marty''ego, który postanawia wydostać się z ogrodu i odnaleźć ową mityczną dla niego "Dzicz". Sam uciekając z ogrodu pociąga za sobą przyjaciół, którzy chcąc go ratować, wpadają razem w niezłe tarapaty. W rezultacie władze Ogrodu Zoologicznego postanawiając wysłać uciekinierów z powrotem do ich naturalnego środowiska - Afryki. Po drodze nasi bohaterowie wypadają ze statku i dryfując wszyscy odnajdują się u brzegów egzotycznej wyspy... Tu poznają społeczeństwo śmiesznych lemurów pod wodzą zakręconego króla. Wszystko jednak komplikuje fakt, że Alex wcale nie jest zachwycony rozpoczęciem życia z dala od wygód zoo i dodatkowo budzą się w nim prawdziwe instynkty drapieżcy...', 'https://image.tmdb.org/t/p/w500/tl6xuTAug5YCZwtfj37MYWYv7a5.jpg', 953, 'tt0351283', 2, 0),
(355, 'Kung Fu Panda', 'Kung Fu Panda', 'Akcja, Animacja, Komedia, Familijny', 2008, 7.3, 'Mark Osborne', 90, 'English', 5, 130000000, 'DreamWorks Animation', '', 18.99, 'Osadzona w legendarnym świecie starożytnych Chin, jest to opowieść o Po, bohaterze mimo woli, który wkracza w hermetyczny świat mistrzów sztuk walki ucząc się, że nie ma niczego niemożliwego, dla tego kto wierzy w sukces.', 'https://image.tmdb.org/t/p/w500/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', 9502, 'tt0441773', 2, 0),
(356, 'Kung Fu Panda 2', 'Kung Fu Panda 2', 'Animacja, Familijny, Komedia, Akcja', 2011, 7.1, 'Jennifer Yuh Nelson', 91, 'English', 6, 150000000, 'DreamWorks Animation', '', 10.99, 'Kontynuacja przygód Po i jego przyjaciół. Tym razem grupa sympatycznych adeptów kung-fu będzie musiała stawić czoła nikczemnemu lordowi Shenowi, który za cel postawił sobie podbicie Chin. Po i jego towarzysze wkrótce odkrywają, że ich wróg dysponuje potężną bronią.', 'https://image.tmdb.org/t/p/w500/mtqqD00vB4PGRt20gWtGqFhrkd0.jpg', 49444, 'tt1302011', 2, 0),
(357, 'Jak wytresować smoka', 'How to Train Your Dragon', 'Fantasy, Przygodowy, Animacja, Familijny', 2010, 7.9, 'Dean DeBlois', 98, 'English', 7, 165000000, 'DreamWorks Animation', '', 17.99, 'Producenci "Shreka", „Madagaskaru" i „Kung Fu Pandy" przedstawiają film na podstawie książki Cressidy Cowell  „Jak wytresować smoka", której akcja rozgrywa się w świecie Wikingów i dzikich smoków. Bohaterem filmu jest nastoletni Wiking mieszkający na wyspie Berk, gdzie walki ze smokami są codziennością. Zbliża się właśnie czas inicjacji i jedyna szansa na udowodnienie plemieniu i ojcu swojej wartości. Kiedy jednak okazuje się, że zamiast wytresować smoka, nastolatek zaprzyjaźnia się z nim, cały jego świat staje na głowie.', 'https://image.tmdb.org/t/p/w500/hQnJzbvV0zFLwrCgzpz3coC3sdZ.jpg', 10191, 'tt0892769', 2, 0),
(358, 'Jak wytresować smoka 2', 'How to Train Your Dragon 2', 'Fantasy, Akcja, Przygodowy, Animacja', 2014, 7.7, 'Dean DeBlois', 102, 'English', 8, 145000000, 'DreamWorks Animation', '', 9.99, 'W drugim rozdziale porywającej trylogii JAK WYTRESOWAĆ SMOKA powracamy do fantastycznego świata Czkawki i Szczerbatka w pięć lat po tym, jak udało im się zjednoczyć smoki i wikingów na wyspie Berk. Podczas gdy Astrid i pozostali biorą udział w wyścigach smoków (nowy najpopularniejszy sport zespołowy na wyspie), nierozłączna para Czkawka i Szczerbatek przemierza niebo, odkrywając nieznane ziemie i nowe światy. Gdy podczas jednej z wypraw natrafiają na tajemną lodową jaskinię, a w niej setki nowych dzikich smoków i tajemniczego Jeźdźca Smoków, dostają się w sam środek wojny o pokój. Czkawka i Szczerbatek zrobią wszystko, by stawić czoła wyzwaniu i odkryją, że tylko wspólnymi siłami mogą zmienić przyszłość zarówno ludzi, jak i smoków.', 'https://image.tmdb.org/t/p/w500/7wtG5mCra9HoNu8PWb9cAukQ03f.jpg', 82702, 'tt1646971', 2, 0),
(359, 'Jak wytresować smoka 3', 'How to Train Your Dragon: The Hidden World', 'Animacja, Familijny, Przygodowy', 2019, 7.7, 'Dean DeBlois', 104, 'English', 9, 129000000, 'DreamWorks Animation', '', 16.99, 'Co rozpoczęło się nietypową przyjaźnią między nastoletnim wikingiem a straszliwą Nocną Furią, stało się epicką trylogią, która odmieniła ich życie. W następnym rozdziale, Czkawka i Szczerbatek w końcu odkryją swoje prawdziwe przeznaczenia: wódz wioski jako władca Berk u boku Astrid, i smoczy przywódca swojej rasy. Z biegiem czasu najmroczniejsze zagrożenie, któremu stawią czoła - a także pojawienie się samicy Nocnej Furii - wystawi ich przyjaźń na próbę ciężką jak nigdy dotąd.', 'https://image.tmdb.org/t/p/w500/i2bSSOVmhJjBJt0ymResCmKoHT9.jpg', 166428, 'tt2386490', 2, 0),
(360, 'Krudowie', 'The Croods', 'Animacja, Przygodowy, Familijny, Komedia', 2013, 6.9, 'Chris Sanders', 98, 'English', 10, 135000000, 'DreamWorks Animation', '', 8.99, 'W poszukiwaniu nowego domu staromodny jaskiniowiec musi przeprowadzić rodzinę przez prehistoryczne ziemie. Olbrzymich rozmiarów flora i fauna są sporym wyzwaniem, jednak prawdziwe komplikacje pojawią się w chwili, kiedy do rodziny dołączy jaskiniowiec zatrważająco nowoczesny. Jego poszukiwanie "lepszego jutra" zupełnie nie pasuje do poglądów naszego hołdującego tradycji bohatera.', 'https://image.tmdb.org/t/p/w500/jsaiJvYcww0x2sVFJql30TurlKL.jpg', 49519, 'tt0481499', 2, 0),
(361, 'Laputa – podniebny zamek', '天空の城ラピュタ', 'Przygodowy, Fantasy, Animacja, Akcja', 1986, 8.0, 'Hayao Miyazaki', 124, 'Japanese', 1, 3000000, 'Studio Ghibli, Tokuma Shoten', '', 15.99, 'Życie Pazu, osieroconego chłopca z górniczej osady, zmienia się w jednej chwili, kiedy prosto w jego ramiona z nieba spada dziewczynka z zawieszonym na szyi jasnozielonym kamieniem. Okazuje się, że Sheeta i jej tajemniczy naszyjnik są kluczami do odnalezienia mitycznego, unoszącego się gdzieś pośród chmur, pełnego tajemnic i skarbów zamku Laputa, wedle legendy niegdyś zamieszkiwanego przez wysoko rozwiniętą cywilizację. Sheeta musi uciekać przed wojskiem oraz powietrznymi piratami, którzy za wszelką cenę chcą odnaleźć legendarny zamek…', 'https://image.tmdb.org/t/p/w500/jS50vAIVGgTAjvi92RTJ7cZoHxU.jpg', 10515, 'tt0092067', 2, 0),
(362, 'Nausicaä z Doliny Wiatru', '風の谷のナウシカ', 'Przygodowy, Animacja, Fantasy', 1984, 7.9, 'Hayao Miyazaki', 116, 'Japanese', 2, 1000000, 'Topcraft, Tokuma Shoten, Hakuhodo', '', 7.99, 'Tysiąc lat po „Siedmiu Dniach Ognia”, czyli wojnie zakończonej wielkim ekologicznym kataklizmem, Ziemia porośnięta jest toksyczną dżunglą, pełną ogromnych owadów-mutantów. Oddychanie bez maski tlenowej grozi śmiercią w ciągu kilku minut. Jedną z ostatnich zamieszkałych przez ludzi oaz jest królestwo zwane Doliną Wiatru. Wieje tam „wiatr bogów”, odpędzający trujące opary. Następczyni tronu, księżniczka Nausicaä, razem z mistrzem Yupą próbują zrozumieć mechanizmy rządzące przyrodą i znaleźć sposób, który zapewni ludziom bezpieczeństwo. Delikatna równowaga zostaje zachwiana, gdy nieopodal rozbija się samolot przewożący potężną broń. Sąsiedzi Doliny Wiatru planują użyć jej, by zniszczyć owady i dżunglę, nieświadomi, że ściągną w ten sposób zgubę na resztę ludności.', 'https://image.tmdb.org/t/p/w500/jisAAzfCMDyd9iqhlJf5sESQ5f8.jpg', 81, 'tt0087544', 2, 0),
(363, 'Ruchomy zamek Hauru', 'ハウルの動く城', 'Fantasy, Animacja, Przygodowy', 2004, 8.4, 'Hayao Miyazaki', 119, 'Japanese', 3, 24000000, 'Studio Ghibli, Tokuma Shoten, Nippon Television Network Corporation', '', 14.99, 'Sophie zostaje zamieniona przez demoniczną Czarownicę w starą kobietę. Zrozpaczona próbuje odzyskać swoje ciało i wyrusza w magiczną podróż pełną niebezpieczeństw. W poszukiwaniu samej siebie Sophie trafia do dziwnego Ruchomego Zamku należącego do czarodzieja Hauru. Spotyka w nim demona ognia - Karushifâ, który przedstawia jej propozycję. Jeśli Sophie uwolni go spod mocy Hauru, on w zamian przywróci jej 18-letnie ciało. Co stanie się z Sophie w Ruchomym Zamku? Czy wszystkie części magicznej układanki znajdą swoje miejsce?', 'https://image.tmdb.org/t/p/w500/pCHfm0Icmk0rJiBJjY1XAfYMTd7.jpg', 4935, 'tt0347149', 2, 0),
(364, 'Zrywa się wiatr', '風立ちぬ', 'Animacja, Dramat, Historyczny, Romans', 2013, 7.8, 'Hayao Miyazaki', 126, 'Japanese', 4, 30000000, 'Studio Ghibli, Nippon Television Network Corporation, dentsu', '', 6.99, 'Od najmłodszych lat Jiro zafascynowany jest samolotami zaprojektowanymi przez włoskiego inżyniera lotnictwa Gianni Caproniego. Chłopiec śni o lataniu i podniebnych przygodach. Niestety, wrodzona wada wzroku nie pozwala mu na karierę pilota. Udaje mu się jednak zostać jednym z największych i najbardziej kreatywnych konstruktorów samolotów w całej Azji.', 'https://image.tmdb.org/t/p/w500/3bIxQuItLeBAkOUBqyvaCI8emgw.jpg', 149870, 'tt2013293', 2, 0),
(365, 'O dziewczynie skaczącej przez czas', '時をかける少女', 'Fantasy, Animacja, Dramat, Sci-Fi', 2006, 7.8, '細田守', 98, 'Japanese', 5, NULL, 'Madhouse, Happinet Pictures, KADOKAWA', '', 13.99, 'Makoto jest zwyczajną nastolatką, spędzającą większość czasu z przyjaciółmi. Kiedy pewnego dnia, spiesząc się z wizytą do ciotki, cudem unika potrącenia przez pociąg – przeskakuje w czasie do momentu sprzed wypadku. Korzystając z nowo poznanych zdolności, naprawia swoje codzienne błędy – od słabych ocen na sprawdzianach po nieudane wyznania miłości. Kiedy jednak dosięgają ją konsekwencje manipulowania czasem, Makoto musi zrobić wszystko, żeby uniknąć straszliwej przyszłości, której nie da się cofnąć.', 'https://image.tmdb.org/t/p/w500/7AN1hPKpysFplXBsDqKjYvqIaBM.jpg', 14069, 'tt0808506', 2, 0),
(366, 'What''s Your Name?', 'What''s Your Name?', 'Dramat', 2016, 0.0, 'Letibeb Zelleke', 26, 'English', 6, NULL, 'N/A', '', 5.99, '', 'https://image.tmdb.org/t/p/w500/9ts87cPRdxWvXfzsbgOoqj60y0o.jpg', 777507, 'tt5586588', 2, 0),
(367, 'Tenki no Ko', '天気の子', 'Animacja, Dramat, Fantasy, Romans', 2019, 8.0, 'Makoto Shinkai', 112, 'Japanese', 7, 11100000, 'CoMix Wave Films, Story, TOHO', '', 12.99, 'Hodaka po przeprowadzce do Tokio spotyka Hinę, która ma tajemniczą zdolność kontrolowania pogody.', 'https://image.tmdb.org/t/p/w500/sGBRqb0Y3DlUpmYXPGUsy587ofd.jpg', 568160, 'tt9426210', 2, 0),
(368, 'Suzume', 'すずめの戸締まり', 'Animacja, Dramat, Przygodowy, Fantasy', 2022, 7.9, 'Makoto Shinkai', 122, 'Japanese', 8, 13000000, 'CoMix Wave Films, Story, Lawson Entertainment', '', 19.99, '„Suzume” to opowieść o dojrzewaniu 17-letniej głównej bohaterki. Animacja rozgrywa się w różnych dotkniętych katastrofą miejscach w całej Japonii.  Podróż Suzume rozpoczyna się w spokojnym miasteczku w Kyushu (południowo-zachodnia Japonia), kiedy spotyka chłopaka, który szuka tajemniczych drzwi. Suzume znajduje je zniszczone pośród ruin, jakby były osłonięte przed jakąkolwiek katastrofą. Suzume zdaje się być przyciągana przez ich moc i sięga aby je otworzyć… Drzwi zaczynają otwierać kolejne drzwi w całej Japonii, siejąc zniszczenie. Suzume musi zamknąć te portale, aby zapobiec dalszej katastrofie.', 'https://image.tmdb.org/t/p/w500/m5zCFaHhFhRGcxLbUpTodRNVaNy.jpg', 916224, 'tt16428256', 2, 0),
(369, 'Akira', 'AKIRA', 'Animacja, Sci-Fi, Akcja', 1988, 7.9, '大友克洋', 125, 'Japanese', 9, 5700000, 'MBS, Sumitomo Corporation, TOHO', '', 11.99, 'Rok 2019, blisko 30 lat po zakończeniu III Wojny Światowej. Odbudowane po ataku nuklearnym Neo-Tokio pogrąża się w coraz większej anarchii. Ulicami rządzą gangi, a grupy rebeliantów walczą z rządzącymi elitami. Dla Kanedy, młodego przywódcy gangu motocyklowego, taka sytuacja jest idealna. Do czasu, kiedy wojsko porywa jego najlepszego przyjaciela Tetsuo i wykorzystuje w tajnym eksperymencie o nazwie "Akira". Kaneda z przerażeniem odkrywa,  że jego przyjaciel nie jest już tym samym człowiekiem co kiedyś, a co gorsza dysponuje potężną mocą mogącą zniszczyć całe miasto.', 'https://image.tmdb.org/t/p/w500/dB2wgQvbu3X1vyyW2cyJaNOuTwg.jpg', 149, 'tt0094625', 2, 0),
(370, 'Ghost in the Shell', 'GHOST IN THE SHELL / 攻殻機動隊', 'Akcja, Animacja, Sci-Fi', 1995, 7.9, 'Mamoru Oshii', 82, 'Japanese', 10, 3000000, 'Bandai Visual, Production I.G, Kodansha', '', 18.99, 'Akcja rozgrywa się w roku 2029, w świecie, w którym komputery są wszechobecne. Wraz z ich ekspansją zmieniła się definicja przestępstwa. Teraz najgorszą zbrodnią jest włamywanie się do sieci. Aby temu zapobiec, powołano specjalny oddział Sekcja 9, składający się z cyborgów mających dostęp do sieci z każdego miejsca na Ziemi. "Ghost in the Shell" opowiada o poszukiwaniach przez parę agentów groźnego hakera ukrywającego się pod pseudonimem "Władca marionetek".', 'https://image.tmdb.org/t/p/w500/q9iCq0NAvOV8lMjAwTokIw1rI63.jpg', 9323, 'tt0113568', 2, 0),
(371, 'Obecność', 'The Conjuring', 'Horror, Thriller', 2013, 7.5, 'James Wan', 112, 'English', 1, 13000000, 'Evergreen Media Group, The Safran Company, New Line Cinema', '', 10.99, 'Prawdziwą historia Eda i Lorraine Warrenów, światowej sławy badaczy zjawisk paranormalnych, którzy zostali wezwani przez rodzinę terroryzowaną na odludnej farmie przez mroczną zjawę. Zmuszeni do konfrontacji z potężnym demonem, Warrenowie stają przed najbardziej przerażającym przypadkiem w ich życiu.', 'https://image.tmdb.org/t/p/w500/ymB7nzBRhjeVvOoONJbGuhWqXDQ.jpg', 138843, 'tt1457767', 2, 0),
(372, 'Obecność 2', 'The Conjuring 2', 'Horror', 2016, 7.3, 'James Wan', 134, 'English', 2, 40000000, 'New Line Cinema, The Safran Company, Atomic Monster', '', 17.99, 'Kontynuacja hitu kinowego Jamesa Wana. Nominowana do Oscara Vera Farmiga oraz Patrick Wilson ponownie wcielają się w role Lorraine i Eda Warrenów. Tym razem badacze będą chcieli pomóc samotnej matce wychowującej czwórkę dzieci w domu nawiedzanym przez duchy. Nawiedzenie z Enfield to jeden z najlepiej udokumentowanych przypadków paranormalnych. Poznaj prawdę kryjącą się za tymi wydarzeniami.', 'https://image.tmdb.org/t/p/w500/wFCMrX1l3wbm0UK3WxMpzsfCTss.jpg', 259693, 'tt3065204', 2, 0),
(373, 'Naznaczony', 'Insidious', 'Horror, Thriller', 2011, 7.0, 'James Wan', 103, 'English', 3, 1500000, 'Alliance Films, IM Global, Haunted Movies', '', 9.99, '"Naznaczony" to intrygujący i zaskakujący horror, który bez trudu znajdzie swoje miejsce obok takich klasyków gatunku jak "Egzorcysta", "Omen" czy "Duch".
 Młode małżeństwo z trójką małych dzieci kupuje wymarzony dom. Ich początkowa radość zostaje jednak przerwana przez dziwne i niewytłumaczalne zjawiska, które towarzyszą im od momentu przeprowadzki. Po upadku z drabiny ich syn zapada w tajemniczą śpiączkę. Zrozpaczeni rodzice szukają wszędzie pomocy. Wkrótce przyjdzie im zadać sobie pytanie, czy to na pewno dom jest źródłem nękających ich zjawisk…  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/mmirfFD3NMeLC4vTotbfQqcvlgF.jpg', 49018, 'tt1591095', 2, 0),
(374, 'Dziedzictwo. Hereditary', 'Hereditary', 'Horror, Tajemnica, Thriller', 2018, 7.3, 'Ari Aster', 128, 'English', 4, 10000000, 'PalmStar Media, Pulse Films, Finch Entertainment', '', 16.99, 'Śmierć Ellen, seniorki rodziny Grahamów, nie mogła być dla nikogo zaskoczeniem. Natomiast to, co nastąpiło po niej, dla wszystkich było szokiem. Rodzina Annie, córki Ellen, wkrótce po pogrzebie zaczyna doświadczać niepokojących zjawisk. Początkowo tłumaczy je sobie żałobą i przemęczeniem, ale wkrótce zdarzenia przybierają tak tragiczny i potworny obrót, że jasnym staje się, iż na rodzinie Grahamów ciąży mroczne dziedzictwo. Co takiego wydarzyło się w życiu Ellen, że teraz zapłacić musi za to jej rodzina? Odkrycie tej prawdy nikomu nie przyniesie spokoju…', 'https://image.tmdb.org/t/p/w500/22VMhUvw9D9GDVOEh1yBTemPQuy.jpg', 493922, 'tt7784604', 2, 0),
(375, 'Midsommar. W biały dzień', 'Midsommar', 'Horror, Dramat, Tajemnica', 2019, 7.1, 'Ari Aster', 148, 'English', 5, 9000000, 'B-Reel Films, Square Peg', '', 8.99, 'Dani i Christian to młodzi Amerykanie, którym nie układa się w związku i rozważają rozstanie. Niespodziewana rodzinna tragedia zbliża ich jednak do siebie, a pogrążona w żałobie Dani postanawia dołączyć do Christiana i jego przyjaciół, aby wziąć udział w wakacyjnej wyprawie na północ Skandynawii. Tam, w odciętej od świata wiosce, raz na 90 lat obchodzone jest prastare święto związane z letnim przesileniem. Jednak to, co z początku wygląda na beztroską wycieczkę do krainy niezachodzącego słońca, z czasem przybiera nieoczekiwany, przerażający obrót. Lokalni mieszkańcy zapraszają amerykańskich gości do udziału w niepokojących rytuałach. W sielskiej scenerii rozpoczyna się dziewięciodniowy festiwal coraz dziwniejszych obrzędów, których rezultat zadecyduje o życiu i śmierci biorących w nich udział.', 'https://image.tmdb.org/t/p/w500/1fLr50N1ROCFVswqb6FkS2cI7tO.jpg', 530385, 'tt8772262', 2, 0),
(376, 'Uciekaj!', 'Get Out', 'Tajemnica, Thriller, Horror', 2017, 7.6, 'Jordan Peele', 107, 'English', 6, 4500000, 'Monkeypaw Productions, Blumhouse Productions, QC Entertainment', '', 15.99, 'Wstrząsający thriller "Uciekaj!" to historia młodego czarnoskórego chłopaka, Chrisa Washingtona (Daniel Kaluuya), który wybiera się z zapoznawczą wizytą do posiadłości rodziców jego białej dziewczyny, Rose Armitage (Allison Williams). Szybko orientuje się, że atmosfera domu jest, mówiąc delikatnie, dziwna. Nie spodziewa się jednak, że powodem zaproszenia nie jest wyłącznie chęć poznania go przez rodziców Rose. Chris wierzy, że nerwowa atmosfera panująca w domu Armitage''ów wynika z przyczyn rasowych. Niedługo jednak odkryje zadziwiającą prawdę. Prawdę, jakiej nie mógł się spodziewać.', 'https://image.tmdb.org/t/p/w500/lnvWEZcADx3UvoMW6LVfDMRLv8y.jpg', 419430, 'tt5052448', 2, 0),
(377, 'To my', 'Us', 'Horror, Thriller', 2019, 6.9, 'Jordan Peele', 116, 'English', 7, 20000000, 'Monkeypaw Productions, Universal Pictures, Perfect World Pictures', '', 7.99, 'Akcja dzieje się we współczesnych czasach w południowej Kalifornii. W filmie zobaczymy m.in. Lupitę Nyong’o w roli Adelaide Wilson, kobiety, która wraca w swe rodzinne strony do domku na plaży, w którym spędziła dzieciństwo. Przyjeżdża tu z mężem oraz dziećmi, aby odnaleźć letnie wytchnienie. Ścigana przez niewyjaśnione i nierozwiązane traumy z przeszłości oraz dziwaczne zbiegi okoliczności, Adelaide czuje, że paranoja, w której się znalazła, narasta z niepohamowaną siłą. Kobieta czuje, że coś złego spotka jej rodzinę. Po relaksującym dniu na plaży, który spędza z rodziną i przyjaciółmi, Adelaide wraca do letniego domu. Kiedy nastaje zmrok, Wilsonowie odkrywają cztery sylwetki stojące na podjeździe: sobowtóry ich rodziny.', 'https://image.tmdb.org/t/p/w500/7qo0pTe8fwvljtt6jyWm9KH2fCc.jpg', 458723, 'tt6857112', 2, 0),
(378, 'Nie!', 'Nope', 'Horror, Sci-Fi, Thriller', 2022, 6.8, 'Jordan Peele', 130, 'English', 8, 68000000, 'Universal Pictures, Monkeypaw Productions', '', 14.99, 'Hollywoodzki pogromca zwierząt OJ i jego siostra Emerald mieszkają na rozległym ranczu w południowej Kalifornii. Po śmierci ojca stają się świadkami niewyjaśnionych zjawisk. Wraz z byłym dziecięcym gwiazdorem, który pracuje jako konferansjer w sąsiadującym z ranczem rodzinnym parku rozrywki, obsesyjnie próbują uchwycić ich źródło za pomocą kamer. Wkrótce ich działania przynoszą przerażające konsekwencje.', 'https://image.tmdb.org/t/p/w500/oUTQOTLcJaElkrJlEmZFwcGnaEu.jpg', 762504, 'tt10954984', 2, 0),
(379, 'To', 'It', 'Horror, Thriller, Dramat', 2017, 7.2, 'Andy Muschietti', 135, 'English', 9, 35000000, 'New Line Cinema, Vertigo Entertainment, Lin Pictures', '', 6.99, 'Kiedy w mieście Derry w stanie Maine zaczynają znikać dzieci, grupa dzieciaków musi stawić czoła swoim największym lękom. Na ich drodze staje nikczemny klaun o imieniu Pennywise, który zapisał się na kartach historii jako morderca lubujący się w zadawaniu bólu. Film oparty jest na motywach niezwykle popularnej powieści Stephena Kinga pod tym samym tytułem, która przeraża czytelników od dziesięcioleci.', 'https://image.tmdb.org/t/p/w500/jDOMQ0fm9A97gy9aD9vF7MEKzJA.jpg', 346364, 'tt1396484', 2, 0),
(380, 'To: Rozdział 2', 'It Chapter Two', 'Horror, Thriller, Dramat', 2019, 6.8, 'Andy Muschietti', 169, 'English', 10, 79000000, 'Vertigo Entertainment, Double Dream, Rideback', '', 13.99, 'Zło wkrada się do miasteczka Derry położonego w stanie Maine co 27 lat. "To: Rozdział 2" ponownie gromadzi znanych nam z części pierwszej, dorosłych już bohaterów, którzy spotykają się prawie trzydzieści lat po wydarzeniach przedstawionych w filmie "To".', 'https://image.tmdb.org/t/p/w500/qnDb7rErT7N58tScP2tiYbCC4eU.jpg', 474350, 'tt7349950', 2, 0),
(381, 'Omen', 'The Omen', 'Horror, Thriller', 1976, 7.4, 'Richard Donner', 111, 'English', 1, 2800000, 'Mace Neufeld Productions, Harvey Bernhard Productions, Twentieth Century-Fox Productions', '', 5.99, 'W rzymskiej klinice 6 czerwca o szóstej rano przychodzi na świat martwe dziecko. Ojciec, amerykański dyplomata Robert Thom, jest pogrążony w głębokim smutku. Obawia się o stan psychiczny Katherine, która tak bardzo pragnęła dać mu potomka. Za namową spotkanego w szpitalu księdza Spiletto, w tajemnicy przed żoną adoptuje niemowlę, które urodziło się w tym samym czasie. Jego matka zmarła przy porodzie, chłopczyk nie ma żadnych krewnych. Szczęście Katherine nie ma granic, nawet nie domyśla się, że słodkie maleństwo nie jest jej synkiem...', 'https://image.tmdb.org/t/p/w500/zX99thlzZu2HBRZtpWXLIIRsiJ8.jpg', 794, 'tt0075005', 2, 0),
(382, 'Duch', 'Poltergeist', 'Horror', 1982, 7.2, 'Tobe Hooper', 114, 'English', 2, 10700000, 'Metro-Goldwyn-Mayer, SLM Production Group', '', 12.99, 'Szczęśliwa rodzina przeprowadza się do wymarzonego domu. Po pewnym czasie zaczynają dziać się niezwykłe rzeczy. Upiorne drzewo stojące za oknem próbuje zjeść chłopca, a mała dziewczynka oglądając telewizję zostaje porwana przez tytułowego ducha. Rodzice dziewczynki postanawiają wezwać na pomoc parapsychologów, którzy odkrywają, że ich dom stoi na starym indiańskim cmentarzu.', 'https://image.tmdb.org/t/p/w500/9XPfrH8kbMs947bAtjXgjsIEg8C.jpg', 609, 'tt0084516', 2, 0),
(383, 'Martwe zło', 'The Evil Dead', 'Horror', 1983, 7.3, 'Sam Raimi', 85, 'English', 3, 350000, 'Renaissance Pictures', '', 19.99, 'Do opuszczonego domku w górach przybywa na weekend piątka studentów. Na miejscu znajdują "Necronomicon" - legendarną księgę zmarłych i nagraną na taśmę inwokację przywołującą demony. Ku swemu nieszczęściu odsłuchują ją i w rezultacie noc w lesie będzie dla wielu ostatnią w ich życiu.', 'https://image.tmdb.org/t/p/w500/heArjGvcPi9Wp3Y2gwF9boPcLQp.jpg', 764, 'tt0083907', 2, 0),
(384, 'Mucha', 'The Fly', 'Horror, Sci-Fi', 1986, 7.5, 'David Cronenberg', 96, 'English', 4, 15000000, 'SLM Production Group, Brooksfilms', '', 11.99, 'Naukowiec Seth Brundle prowadzi pracę nad nowym środkiem transportu - teleportacją. Postanawia pokazać swój wynalazek dziennikarce pisma naukowego Veronice, która będzie miała za zadanie dokumentować postępy jego badań. Niestety, Brundle pochopnie postanawia wypróbować swój wynalazek na samym sobie, a poprzez niedopatrzenie, do komory teleportacyjnej dostaje się mucha, w wyniku czego komputer łączy DNA muchy z kodem genetycznym Setha.', 'https://image.tmdb.org/t/p/w500/nyCLLmzXfepVYeCDYmihXBzPgNF.jpg', 9426, 'tt0091064', 2, 0),
(385, 'Coś', 'The Thing', 'Horror, Tajemnica, Sci-Fi', 1982, 8.1, 'John Carpenter', 109, 'English', 5, 15000000, 'Universal Pictures, The Turman-Foster Company', '', 18.99, 'Akcja toczy się zimą 1982 r. w odciętej od świata bazie naukowej na Antarktydzie. Śmierć sieje tam Obcy - przybysz z nieznanej planety, którego pojazd rozbił się niegdyś na Ziemi i który właśnie teraz zbudzony został z lodowego snu. Ma on umiejętność nieustannej zmiany kształtów. Ponieważ egzystuje wyłącznie we wnętrzu żywego organizmu próbuje upodobnić się do swego nosiciela. Zaczyna od psa, kończy na człowieku.', 'https://image.tmdb.org/t/p/w500/xrIcBKkSVf3F2R7DkUOBavCsDfz.jpg', 1091, 'tt0084787', 2, 0),
(386, 'Noc żywych trupów', 'Night of the Living Dead', 'Horror, Sci-Fi', 1968, 7.6, 'George A. Romero', 96, 'English', 6, 114000, 'Image Ten', '', 10.99, 'George A. Romero, mistrz kina grozy przedstawia jeden z najsłynniejszych horrorów świata! To miała być spokojna wycieczka w rodzinne strony. Barbara i Johnny nie wiedzieli jednak, że w chwili, gdy zdecydowali się odwiedzić grób rodziców Amerykę opanowały głodne ludzkiego ciała, krwiożercze zombie... Teraz jedynym ratunkiem staje się ucieczka i pomoc przypadkowych ludzi. Czy uda im się dotrwać do świtu?  Zobacz mroczny, przerażający i trzymający w napięciu jak żaden inny, horror, który na nowo zdefiniował gatunek kina grozy odkrywając przed światem nowe oblicze zombie!', 'https://image.tmdb.org/t/p/w500/yNFuM1VXNRHVjMR7UUfmuVTV4PS.jpg', 10331, 'tt0063350', 2, 0),
(387, 'Świt żywych trupów', 'Dawn of the Dead', 'Horror, Sci-Fi', 1978, 7.5, 'George A. Romero', 127, 'English', 7, 640000, 'Dawn Associates, Laurel Entertainment', '', 17.99, 'Tajemnicza epidemia zamienia ludzi w krwiożerczych zombie, a USA pogrążają się w anarchii. Nieliczni ocaleni - dwaj policjanci z elitarnej brygady SWAT, dziennikarz i jego dziewczyna - ukrywają się w opuszczonym, gigantycznym centrum handlowym. Początkowo wydaje im się, że znaleźli bezpieczny azyl, w którym spokojnie przeczekają do końca morderczej zarazy. Sytuacja zmienia się w chwili, gdy do centrum handlowego przedostaje się grupa uzbrojonych bandytów, a za nimi przerażające zombie. Rozpoczyna się dramatyczna walka o przetrwanie...', 'https://image.tmdb.org/t/p/w500/oc0fMzvUUhhDwf8GlBbvxECyJjh.jpg', 923, 'tt0077402', 2, 0),
(388, '28 dni później', '28 Days Later', 'Horror, Thriller, Sci-Fi', 2002, 7.2, 'Danny Boyle', 113, 'English', 8, 8000000, 'DNA Films', '', 9.99, 'Śmiertelnie niebezpieczny wirus wymyka się spod kontroli. Przenoszony poprzez krew powoduje u zainfekowanych morderczą agresję. W ciągu 28 dni kraj opanowuje epidemia, a nieliczni pozostali przy życiu za wszelką cenę starają się przerwać rozprzestrzenianie wirusa i ocalić przyszłość. Nie zdają sobie sprawy, że śmiertelny wirus nie jest jedynym grożącym im niebezpieczeństwem.', 'https://image.tmdb.org/t/p/w500/uqqqHwEJxzY3ksGHGmQQaotltWa.jpg', 170, 'tt0289043', 2, 0),
(389, 'Wysyp żywych trupów', 'Shaun of the Dead', 'Horror, Komedia', 2004, 7.5, 'Edgar Wright', 95, 'English', 9, 6000000, 'WT² Productions, Big Talk Studios', '', 16.99, 'Shaun ma prawie trzydziestkę i żadnego konkretnego celu w życiu. Wydaje się, że więcej uwagi poświęca swoim kumplom, nieudacznikom podobnym do niego, z którymi dzieli także mieszkanie, niż swojej narzeczonej Liz. Wkrótce nadejdzie jednak chwila, w której Shawn zrozumie jak wiele znaczy dla niego jego Liz. Stanie się tak za sprawą zombie, które pewnego dnia pojawią się w Londynie.', 'https://image.tmdb.org/t/p/w500/yw574ZEM4yGT67ogOlfLF4CcsZL.jpg', 747, 'tt0365748', 2, 0),
(390, 'Jestem legendą', 'I Am Legend', 'Dramat, Sci-Fi, Thriller', 2007, 7.2, 'Francis Lawrence', 101, 'English', 10, 150000000, 'Village Roadshow Pictures, Weed Road Pictures, Overbrook Entertainment', '', 8.99, 'Nowy Jork. Miasto opanował dziwny wirus, który spowodował zmianę ludzi w pełne agresji i szaleństwa potwory. Osoby, które były odporne na działanie wirusa, zostały zabite przez ukrywające się w mroku kreatury. Przeżył tylko jeden człowiek, Robert Neville, który wraz ze swoim psem prowadzi monotonne życie: w dzień stara się zdobyć pożywienie a w nocy ukrywa się i walczy o swoje życie. Neville postanawia odkryć szczepionkę, by odwrócić obecną sytuację. W piwnicy ma laboratorium, gdzie przeprowadza eksperymenty. Pewnego dnia traci wszelką nadzieję i rusza do bezpośredniej walki z przerażającymi potworami.', 'https://image.tmdb.org/t/p/w500/mrgYRZ46Xjo2dieHCTCWLmG5deW.jpg', 6479, 'tt0480249', 2, 0),
(391, 'Szklana pułapka', 'Die Hard', 'Akcja, Thriller', 1988, 7.8, 'John McTiernan', 131, 'English', 1, 28000000, 'Gordon Company, Silver Pictures, 20th Century Fox', '', 15.99, 'Nakatomi Plaza, Los Angeles. Trwa gwiazdkowe przyjęcie dla pracowników Nakatomi Corporation. Radosny nastrój zmienia się w paraliżujący strach, kiedy w ciągu kilku minut budynek zostaje opanowany przez grupę terrorystów z Hansem Gruberem (Alan Rickman) na czele. W „Szklanej Pułapce" tylko jedna osoba umknęła uwadze przestępców. John McClane (Bruce Willis), nowojorski detektyw, znalazł się tam właściwie przypadkowo. Jest zmęczony. Ma przy sobie tylko mały pistolet. Ale stanowi jedyną nadzieję dla sterroryzowanych zakładników, wśród których jest jego żona Holly (Bonnie Bedelia). Podejmuje samotną, nierówną i brawurową walkę.', 'https://image.tmdb.org/t/p/w500/qGQYMBuC3A6s6Jp3tHuDUCk09ZC.jpg', 562, 'tt0095016', 2, 0),
(392, 'Zabójcza broń', 'Lethal Weapon', 'Akcja, Thriller, Kryminał', 1987, 7.3, 'Richard Donner', 110, 'English', 2, 15000000, 'Silver Pictures, Warner Bros. Pictures', '', 7.99, 'Po śmierci żony policjant Martin Riggs (Mel Gibson) myśli o samobójstwie. Przełożeni przenoszą go na posterunek, gdzie jego partnerem zostaje Roger Murtaugh (Danny Glover), przykładny ojciec, człowiek o nienagannej opinii. Ich pierwszym zadaniem jest zbadanie okoliczności podejrzanego samobójstwa. Podczas śledztwa zostają wplątani w porachunki mafijne. Pomimo niechęci do pracy z partnerem będą musieli sobie zaufać.', 'https://image.tmdb.org/t/p/w500/1V3mTAf8AhHBwVY7JlVP2h8TGx6.jpg', 941, 'tt0093409', 2, 0),
(393, 'Godziny szczytu', 'Rush Hour', 'Akcja, Komedia, Kryminał', 1998, 7.1, 'Brett Ratner', 93, 'English', 3, 33000000, 'New Line Cinema, Arthur Sarkissian Productions, Roger Birnbaum Productions', '', 14.99, 'Detektyw James Carter (Chris Tucker) jest największym luzakiem w policji Los Angeles. Zawsze pracuje sam. Jednak gdy FBI prosi go o pomoc w odnalezieniu porwanej córki chińskiego konsula, zgadza się na pracę z partnerem. A jest nim detektyw Lee (Jackie Chan), duma policji Hong Kongu - oddany sprawie, nieustraszony mistrz wschodnich sztuk walki. Lee i Carter tworzą mieszankę wybuchową. Gdziekolwiek postawią stopę natychmiast coś wybucha, wali się lub w najlepszym razie płonie. Stawiając całe miasto na głowie trafiają na trop porywaczy i od tej chwili kończą się żarty... Porywaczami okazują się członkowie potężnej organizacji przestępczej. Lee i Carter muszą użyć wszystkich swoich talentów, nawet tych najbardziej ukrytych, żeby ocalić córkę konsula i własną skórę...  [opis dystrybutora dvd]', 'https://image.tmdb.org/t/p/w500/AfaugIq8xUywmradHJW0Fn0Yeez.jpg', 2109, 'tt0120812', 2, 0),
(394, 'Bad Boys', 'Bad Boys', 'Akcja, Komedia, Kryminał', 1995, 6.8, 'Michael Bay', 118, 'English', 4, 19000000, 'Columbia Pictures, Don Simpson/Jerry Bruckheimer Films', '', 6.99, 'Z Biura Dowodów przy komendzie policji w Miami ginie heroina warta 100 milionów dolarów. Zadanie jej odnalezienia spada na detektywów Marcusa Burnetta (Martin Lawrence) i Mike''a Lowrey''a (Will Smith). Jedyną osobą, która może im pomóc, jest Julie Mott (Téa Leoni) potrafiąca zidentyfikować szefa gangu. Lecz dziewczyna jest śmiertelnie przerażona i chce rozmawiać tylko z Lowrey''em. Ponieważ Mike jest nieobecny, komisarz na spotkanie wysyła Burnetta. Marcus, potulny żonkoś, wciela się więc w swego partnera - znanego playboya. Ale mistyfikacja nie na wiele się zda, kiedy gangsterzy za wszelką cenę chcą zlikwidować świadka...', 'https://image.tmdb.org/t/p/w500/x1ygBecKHfXX4M2kRhmFKWfWbJc.jpg', 9737, 'tt0112442', 2, 0),
(395, 'Ciche miejsce', 'A Quiet Place', 'Horror, Dramat, Sci-Fi', 2018, 7.4, 'John Krasinski', 90, 'English', 5, 17000000, 'Paramount Pictures, Platinum Dunes, Sunday Night Productions', '', 13.99, '"WSTRZĄSAJĄCY, ELEKTRYZUJĄCY" thriller, o rodzinie, która zmuszona jest wieść życie w całkowitej ciszy, by uniknąć ataku tajemniczych, krwiożerczych stworzeń. Zdając sobie sprawę, że każdy, nawet najlżejszy dźwięk, szept, odgłos kroków może sprowadzić na nich śmierć, Evelyn i Lee starają się za wszelką cenę ochronić swe dzieci i znaleźć sposób na pokonanie potworów. Thriller "Ciche Miejsce" okrzyknięty przez krytyków jako "REWELACYJNY, TRZYMAJĄCY W NIEUSTANNYM NAPIĘCIU" i "PRZYSPIESZAJĄCY BICIE SERCA" to film roku, który po prostu trzeba zobaczyć.', 'https://image.tmdb.org/t/p/w500/1YupNOLZYJzzcyKXAiDEVIHAZzi.jpg', 447332, 'tt6644200', 2, 0),
(396, 'Zombie Express', '부산행', 'Akcja, Horror, Thriller, Przygodowy', 2016, 7.8, '연상호', 118, 'Korean', 6, 8500000, 'Next Entertainment World, RedPeter Films, Contents Panda', '', 5.99, 'Seok Woo (Gong Yoo) jest przepracowanym menedżerem w dużej seulskiej korporacji. Odeszła od niego żona, a z córeczką ma chłodne relacje. W dniu urodzin dziewczynki, Woo wybiera się z nią do mieszkającej w Pusan matki. Wsiadają do szybkiego pociągu KTX i ruszają w drogę. Tymczasem w kraju wybucha epidemia zombie. Koreę Południową ogarnia chaos, a kolejne ofiary dołączają do hord żywych trupów. Zarażeni trafiają także do pociągu. Podróż momentalnie staje się koszmarem i dramatyczną walką o przetrwanie.', 'https://image.tmdb.org/t/p/w500/4aUOH61qczXnKEpNsSLCw2mGWyv.jpg', 396535, 'tt5700672', 2, 0),
(397, 'Pozwól mi wejść', 'Låt den rätte komma in', 'Horror, Dramat', 2008, 7.5, 'Tomas Alfredson', 115, 'Swedish', 7, 4000000, 'EFTI, Bavaria Film International, Sandrew Metronome Sverige', '', 12.99, 'Dwunastoletni Oskar nie ma przyjaciół. Każdego dnia jest nękany przez silniejszych kolegów, którym nie potrafi się przeciwstawić. Pewnego dnia spotyka tajemniczą dziewczynkę o imieniu Eli. Jej pojawienie się rozpoczyna serię śmierci i makabrycznych wydarzeń. Oskar zdaje sobie sprawę, że Eli nie jest zwyczajną istotą. Nie jest jej zimno. Nie jada słodyczy. Nie sprawia jej problemu ułożenie kostki Rubika. Z biegiem czasu chłopiec przekonuje się, że dziewczynka nie potrafi żyć bez ludzkiej krwi. Dziecięca więź okazuje się jednak silniejsza niż strach.', 'https://image.tmdb.org/t/p/w500/2UcjguOB3BeI7UD64uxxbPqP9wf.jpg', 13310, 'tt1139797', 2, 0),
(398, 'Rocky Horror Picture Show', 'The Rocky Horror Picture Show', 'Komedia, Sci-Fi, Horror', 1975, 7.4, 'Jim Sharman', 100, 'English', 8, 1400000, '20th Century Fox, Lou Adler Productions, Michael White Productions', '', 19.99, 'Do tajemniczego zamku zamieszkiwanego przez groźnego doktora Frank-N-Furtera pewnej nocy trafiają Janet i Brad, którym zepsuł się samochód. Para ta stanie się świadkiem stworzenia przez doktora idealnego kochanka Rocky''ego Horrora.', 'https://image.tmdb.org/t/p/w500/wRXCl9mgeme0GKq24DTW5DRW0O6.jpg', 36685, 'tt0073629', 2, 0),
(399, 'Wywiad z wampirem', 'Interview with the Vampire', 'Horror, Dramat, Fantasy', 1994, 7.4, 'Neil Jordan', 123, 'English', 9, 60000000, 'Geffen Pictures', '', 11.99, 'Lestat to młody wampir o niezwykłej urodzie, ale zimny i wyrachowany, z lubością zabija swe ofiary. W Nowym Orleanie poznaje śmiertelnika Louisa, którego prowadzi przez śmierć do wiecznego życia i ciemności. Dwieście lat później to właśnie Louis opowie swą historię młodemu dziennikarzowi - historię egzystencji wampira, pełnej smutku, wiecznego istnienia, pożądania, miłości i tęsknoty.', 'https://image.tmdb.org/t/p/w500/7Y73rCdiObueFUSldEBoyS5R3gT.jpg', 628, 'tt0110148', 2, 0),
(400, 'Pretty Woman', 'Pretty Woman', 'Romans, Komedia', 1990, 7.4, 'Garry Marshall', 119, 'English', 10, 14000000, 'Touchstone Pictures, Silver Screen Partners IV, Arnon Milchan Productions', '', 18.99, 'Dzieli ich wszystko, ale łączy jedno - oboje robią różne rzeczy dla pieniędzy.  Bohaterką filmu jest Vivian Ward, dziewczyna do towarzystwa, która dopiero co przyjechała do Los Angeles z prowincji. Przypadkowo spotyka bogatego i przystojnego adwokata z Wall Street, Edwarda Lewisa, którego urzeka jej spontaniczność. Proponuje więc dziewczynie korzystną transakcję: za tydzień spędzony u jego boku dostanie trzy tysiące dolarów.', 'https://image.tmdb.org/t/p/w500/oVKX1Pt1q7jXTkTk51mu2S0sAB0.jpg', 114, 'tt0100405', 2, 0),
(401, 'Notting Hill', 'Notting Hill', 'Romans, Komedia', 1999, 7.3, 'Roger Michell', 124, 'English', 1, 42000000, 'Working Title, Notting Hill Pictures, Duncan Kenworthy Productions', '', 10.99, 'William Thacker mieszka w zachodnim Londynie, w dzielnicy dla indywidualistów - Notting Hill. Jest rozwiedziony, sam myśli o sobie jako o dziwnym człowieku żyjącym na "pół gwizdka". Dzieli swoje mieszkanie z dziwacznym, nieogolonym Walijczykiem, Spikeem. Utrzymanie zapewnia mu kiepsko prosperująca księgarnia, której jest właścicielem. Pewnego dnia, przychodzi rano do swojej księgarni, wita się ze swym entuzjastycznym asystentem i gdy ten wychodzi, aby napić się cappucino, drzwi otwierają się cicho, William podnosi wzrok i jest zdumiony widząc, że jego klientką jest Anna Scott, największa współczesna gwiazda filmowa...', 'https://image.tmdb.org/t/p/w500/hHRIf2XHeQMbyRb3HUx19SF5Ujw.jpg', 509, 'tt0125439', 2, 0),
(402, 'To właśnie miłość', 'Love Actually', 'Komedia, Romans, Dramat', 2003, 7.1, 'Richard Curtis', 135, 'English', 2, 40000000, 'Working Title, DNA Films, StudioCanal', '', 17.99, 'Nadchodzi Boże Narodzenie w Londynie. Były gwiazdor rocka Billy Mack nagrywa swój przebój w bożonarodzeniowej wersji. Jamie dowiaduje się, że jego dziewczyna ma romans z jego bratem. Peter i Juliet właśnie wzięli ślub, jednak Juliet nie umie ułożyć swoich relacji z przyjacielem męża. Daniel cierpi po stracie żony, ale musi zająć się pasierbem. Karen i Harry to stabilne małżeństwo, lecz mężczyznę wodzi na pokuszenia seksowna sekretarka. Do rezydencji na Downing Street 10 właśnie wprowadza się nowo wybrany premier - młody i samotny.', 'https://image.tmdb.org/t/p/w500/oYhZ8GAf9jaB1yDJh8YjJFoxZId.jpg', 508, 'tt0314331', 2, 0),
(403, 'Pamiętnik', 'The Notebook', 'Romans, Dramat', 2004, 7.9, 'Nick Cassavetes', 123, 'English', 3, 29000000, 'New Line Cinema, Avery Pix, Gran Via Productions', '', 9.99, 'Film jest kroniką dwojga młodych kochanków, Allie Nelson i Noah Calhoun, którzy spotkali się pewnego wieczoru podczas karnawału gdzieś w Karolinie Północnej. Allie i Noah pochodzili z dwóch różnych środowisk i po zakończeniu II Wojny Światowej ich drogi rozeszły się. Siedem lat później Allie, która czekała na Noah przez kilka lat, poznaje przystojnego młodego żołnierza o imieniu Lon. Wkrótce Lon oświadcza się jej i zostaje przyjęty. Jednak niedługo potem Allie znajduje w gazecie historię o Noah. Postanawia go odwiedzić i sprawdzić jak się miewa. Okazuje się, że Noah wciąż ją kocha. Pytanie tylko czy pierwsza prawdziwa miłość pokona przeciwności zanim okaże się za późno?', 'https://image.tmdb.org/t/p/w500/yMNEfj72auMEBBeke57qrKRnmCq.jpg', 11036, 'tt0332280', 2, 0),
(404, 'Mamma Mia!', 'Mamma Mia!', 'Komedia, Romans', 2008, 7.0, 'Phyllida Lloyd', 108, 'English', 4, 52000000, 'Littlestar, Playtone, Internationale Filmproduktion Richter', '', 16.99, 'Sophie niedługo ma wyjść za mąż. Jednak zanim nadejdzie ten najważniejszy dzień w jej życiu postanawia odnaleźć swojego ojca. Jest tylko jeden problem… nie ma pojęcia kto nim jest. Kiedy wpada jej w ręce pamiętnik jej matki Donny, dziewczyna odkrywa, że jej ojcem może być jeden z trzech jej byłych kochanków. Wiedząc, że matka nie będzie z tego zadowolona, w tajemnicy przed nią Sophie zaprasza wszystkich trzech mężczyzn na swój ślub. Usiłuje utrzymać ich przyjazd w tajemnicy, ale wkrótce cała sprawa wychodzi na jaw i zaczyna się zabawa!', 'https://image.tmdb.org/t/p/w500/mugycW3U8TT2tK58rrljffjQrvz.jpg', 11631, 'tt0795421', 2, 0),
(405, 'Grease', 'Grease', 'Romans, Komedia', 1978, 7.4, 'Randal Kleiser', 110, 'English', 5, 6000000, 'Paramount Pictures, Robert Stigwood Organization, Fine Arts Films', '', 8.99, 'Występując w tej filmowej wersji przebojowego musicalu - "Grease" - John Travolta utrwala swą pozycję jako najbardziej wszechstronna i zniewalająca serca nastolatków gwiazda lat 70. Partneruje mu słynna piosenkarka Olivia Newton-John, debiutująca w amerykańskim kinie jako Sandy, naiwna ukochana Travolty. W tej fantastycznej wyprawie w lata 50. biorą także udział inne gwiazdy, które oglądamy w rolach drugoplanowych. "Grease" to nie tylko nostalgiczne spojrzenie na minioną dekadę - to także pełen wigoru i świeżości ekscytujący film muzyczny składający hołd niezapomnianej epoce narodzin rock ''n'' rolla!!!', 'https://image.tmdb.org/t/p/w500/2rM7fQKpb7cs1Iq7IBqub9LFDzJ.jpg', 621, 'tt0077631', 2, 0),
(406, 'Dirty Dancing', 'Dirty Dancing', 'Dramat, Muzyczny, Romans', 1987, 7.3, 'Emile Ardolino', 100, 'English', 6, 6000000, 'Great American Films Limited Partnership, Vestron Pictures', '', 15.99, 'Młoda dziewczyna (Jennifer Grey) spędza wakacje wraz z rodzicami i siostrą w ekskluzywnym ośrodku wypoczynkowym. To właśnie tutaj poznaje przystojnego instruktora tańca John''ego (Patrick Swayze). Między młodymi ludźmi rodzi się uczucie. Film okraszony muzyką, która w 1988 roku zdobyła Oskara i Złoty Glob.', 'https://image.tmdb.org/t/p/w500/x6PP0dUBIqGBkzAxOspzYWJd4wM.jpg', 88, 'tt0092890', 2, 0),
(407, 'Kac Vegas', 'The Hangover', 'Komedia', 2009, 7.3, 'Todd Phillips', 100, 'English', 7, 35000000, 'Legendary Pictures, Green Hat Films, Warner Bros. Pictures', '', 7.99, 'Czterech dobrych kumpli wyrusza na wieczór kawalerski do Las Vegas. Następnego ranka dopada ich kac-gigant, przyszły pan młody znika, a pozostali nie pamiętają, co się stało. Wyruszając na poszukiwanie kolegi, odkrywają, że jeden z nich poślubił striptizerkę, drugi miał doświadczenie homoseksualne, a wszystkich czterech ściga lichwiarz – bandyta.', 'https://image.tmdb.org/t/p/w500/2gUIZ1LZMCtO4zcIZC4r7c5pV6Q.jpg', 18785, 'tt1119646', 2, 0),
(408, 'Supersamiec', 'Superbad', 'Komedia', 2007, 7.3, 'Greg Mottola', 114, 'English', 8, 20000000, 'Columbia Pictures, Apatow Productions', '', 14.99, 'Ziomki, które wypacykowały Wpadkę i 40-letniego prawiczka rzucają na taśmę Supersamca! Oto Seth i jego kumpel Evan - dwie małpy czające się na skarb narodów najlepszych bioder w szkole. Z petardą niekumającym bazy przybywa Mr. McLovin rzucając na ladę lewe legity i plan operacji „podchmielona: zaliczona". Tera trzeba wyhaczyć łosia, co tylko im wosk posmaruje i browarki zapoda...', 'https://image.tmdb.org/t/p/w500/hnf3owlip5lzZnXNkG0RZjabbZn.jpg', 8363, 'tt0829482', 2, 0),
(409, 'Dzień świstaka', 'Groundhog Day', 'Romans, Fantasy, Komedia', 1993, 7.6, 'Harold Ramis', 101, 'English', 9, 14600000, 'Columbia Pictures', '', 6.99, 'Phil Connors, pyszałkowaty i cyniczny prezenter pogody, wybiera się wraz z ekipą telewizyjną do prowincjonalnego Punxsutawney na doroczny "Dzień Świstaka". Idiotyczna ceremonia przepowiadania nadejścia wiosny przepełnia go odrazą. Jedynym jaśniejszym punktem wyprawy jest śliczna producentka, Rita. Phil ma nadzieję poderwać Ritę, jednak los szykuje mu przykrą niespodziankę. Z niewiadomych przyczyn dzień świstaka zaczyna się bez końca powtarzać. Żeby wyrwać się z pętli czasu, Phil będzie musiał wiele zrozumieć i wiele w sobie zmienić.', 'https://image.tmdb.org/t/p/w500/xUdHk8kAX6Qyb12Yrg3Cs6lA3gV.jpg', 137, 'tt0107048', 2, 0),
(410, 'Polowanie na druhny', 'Wedding Crashers', 'Komedia, Romans', 2005, 6.5, 'David Dobkin', 119, 'English', 10, 40000000, 'Avery Pix, New Line Cinema, Tapestry Films', '', 13.99, 'Kierując się "kodeksem weselnych podrywaczy" John Beckwith i Jeremy Grey są w stanie wkręcić się na każde wesele i zdobyć serce każdej druhny. Jednak na największej imprezie weselnej roku John łamie zasady i zakochuje się w córce Sekretarza Skarbu USA. Konsekwencje okażą się zbyt zwariowane nawet dla tak zawodowych imprezowiczów!', 'https://image.tmdb.org/t/p/w500/uFbrVUQrNLZz0AwJlFMJx7ru4F1.jpg', 9522, 'tt0396269', 2, 0);

