UPDATE `utwory` u
JOIN (
    SELECT `album_id`, MIN(`cena`) AS `cena`
    FROM `muzyka`
    WHERE `album_id` IS NOT NULL
    GROUP BY `album_id`
) m ON m.`album_id` = u.`album_id`
SET u.`cena` = m.`cena`
WHERE u.`cena` IS NULL;
